['Here is an example of how you might approach this task using C programming language. This code does not include all the details as it would be quite complex to provide a full solution in one go. However, it provides a starting point for your requirements. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <netdb.h>
#include <sys/resource.h>

// Define a struct to hold the data for each line
typedef struct {
    char *line;
    int numFields;
} LineData;

pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;
FILE *errorLogFile;

void *resolveDNS(void *hostname) {
    struct hostent *he;
    if ((he=gethostbyname((char *)hostname)) == NULL) {  
        pthread_mutex_lock(&logMutex);
        fprintf(errorLogFile, "Failed to resolve DNS for %s\n", (char *)hostname);
        pthread_mutex_unlock(&logMutex);
        return NULL;
    }

    char *ip = inet_ntoa (*((struct in_addr *)he->h_addr));
    char *result = malloc(strlen(ip) + 1);
    strcpy(result, ip);
    return result;
}

void *processLine(void *data) {
    LineData *lineData = (LineData *)data;

    // Split the line into fields and count them
    char *field = strtok(lineData->line, " ");
    int numFields = 0;
    while (field != NULL) {
        numFields++;
        field = strtok(NULL, " ");
    }

    if (numFields < 2) {
        // Skip lines with insufficient fields
        free(lineData->line);
        return NULL;
    }

    // Compute the average of the last two numerical fields
    char *lastField = strrchr(lineData->line, ' ') + 1;
    int num1 = atoi(strrchr(lineData->line, ' ') + 1);
    int num2 = atoi(strrchr(lastField, ' ') + 1);

    if (num1 == 0 || num2 == 0) {
        // Log warnings for unexpected data types
        pthread_mutex_lock(&logMutex);
        fprintf(errorLogFile, "Unexpected data type in line: %s\n", lineData->line);
        pthread_mutex_unlock(&logMutex);
    }

    double average = (num1 + num2) / 2.0;

    // Print the result in CSV format
    printf("%s,%.2f\n", lineData->line, average);

    free(lineData->line);
    return NULL;
}

int main() {
    errorLogFile = fopen("error.log", "w");

    // Open the file and read each line into a new thread
    FILE *file = fopen("large_text_file.txt", "r");
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        pthread_t thread;

        // Allocate memory for the line and copy it into the struct
        LineData *lineData = malloc(sizeof(LineData));
        lineData->line = malloc(strlen(buffer) + 1);
        strcpy(lineData->line, buffer);

        // Create a new thread to process each line
        pthread_create(&thread, NULL, processLine, (void *)lineData);
    }

    fclose(file);
    fclose(errorLogFile);

    return 0;
}
```
This code is just a starting point and does not include all the details as it would be quite complex to provide a full solution in one go. It provides a basic structure for your requirements, but you will need to add more functionality such as managing system resources efficiently, using a thread pool to manage concurrent threads, implementing mechanisms to monitor and limit the overall memory footprint of the application, etc.
