['Here is a high level overview of how you might structure this task in Rust. This code does not include all the details mentioned in your request due to its complexity and length. However, it should give you an idea of how you could approach this problem. 

```rust
use std::fs::File;
use std::io::{self, prelude::*, BufReader};
use std::collections::HashMap;
use regex::Regex; // You would need to add the 'regex' crate to your Cargo.toml file for this to work

struct Config {
    sections: HashMap<String, HashMap<String, String>>,
}

impl Config {
    fn new(path: &str) -> io::Result<Config> {
        let file = File::open(path)?;
        let reader = BufReader::new(file);

        let mut sections = HashMap::new();
        let re = Regex::new(r"^\[([a-zA-Z0-9_]+)\]\s*$").unwrap();
        let mut current_section: Option<String> = None;

        for line in reader.lines() {
            let line = line?;
            if !line.trim().is_empty() {
                if re.is_match(&line) {
                    // New section
                    let caps = re.captures(&line).unwrap();
                    current_section = Some(caps[1].to_string());
                    sections.insert(current_section.clone().unwrap(), HashMap::new());
                } else if let Some(section) = &mut current_section {
                    // Parse key-value pair in section
                    if let Some((key, value)) = line.split_once('=') {
                        sections[section].insert(key.trim().to_string(), value.trim().to_string());
                    }
                }
            }
        }

        Ok(Config { sections })
    }
}
```
This is a simple configuration file parser that uses regular expressions to parse the file. It assumes that each section starts with `[section]` and contains key-value pairs separated by `=`. 

