```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.IO;
using System.Threading.Tasks;
using Newtonsoft.Json; // You need to install this package via NuGet

public class DatabaseManager
{
    private readonly string _configFilePath;
    private readonly List<SqlConnection> _connectionPool;
    private readonly int _timeoutDuration;

    public DatabaseManager(string configFilePath, List<SqlConnection> connectionPool, int timeoutDuration)
    {
        _configFilePath = configFilePath;
        _connectionPool = connectionPool;
        _timeoutDuration = timeoutDuration;
    }

    public async Task<List<Task<SqlDataReader>>> ExecuteCommandsAsync(List<Tuple<string, object[]>> commands)
    {
        var tasks = new List<Task<SqlDataReader>>();

        foreach (var command in commands)
        {
            var connection = GetAvailableConnection();

            if (connection == null)
                throw new Exception("No available connections");

            tasks.Add(ExecuteCommandAsync(command, connection));
        }

        return tasks;
    }

    private SqlConnection GetAvailableConnection()
    {
        // This is a simple implementation of a connection pooling mechanism. 
        // You might want to use a more sophisticated approach depending on your needs.
        foreach (var connection in _connectionPool)
        {
            if (connection.State == ConnectionState.Closed || connection.State == ConnectionState.Broken)
                return connection;
        }

        return null;
    }

    private async Task<SqlDataReader> ExecuteCommandAsync(Tuple<string, object[]> command, SqlConnection connection)
    {
        var sqlCommand = new SqlCommand(command.Item1, connection);
        sqlCommand.Parameters.AddRange(command.Item2);

        // Load external data source configuration from file
        dynamic config = JsonConvert.DeserializeObject<dynamic>(File.ReadAllText(_configFilePath));

        // Apply additional metadata from the external configuration file to the command
        sqlCommand.ApplyMetadataFromConfig(config);

        if (connection.State == ConnectionState.Closed)
            await connection.OpenAsync();

        var result = await sqlCommand.ExecuteReaderAsync();

        return result;
    }
}
```
This code assumes that you have a method `ApplyMetadataFromConfig` on the `SqlCommand` object which applies additional metadata from the external configuration file to the command. You would need to implement this method based on your specific requirements. 

Please note that error handling and logging are not included in this example, but they should be added according to your needs. Also, you might want to consider using a more sophisticated connection pooling mechanism or a library like Dapper for executing SQL commands.
']

