    private readonly List<string> subdirectoryNames;
    private static ReaderWriterLockSlim lock_ = new ReaderWriterLockSlim();

    public DirectoryManager(Configuration config)
    {
        this.baseDirectoryPath = config.BaseDirectoryPath;
        this.subdirectoryNames = config.SubdirectoryNames;
    }

    public void CreateEnvironmentVariableIfNotExists(string envVarName, string dirName)
    {
        lock_.EnterWriteLock();
        try
        {
            var envVarValue = Environment.GetEnvironmentVariable(envVarName);
            if (string.IsNullOrEmpty(envVarValue))
            {
                var newDirPath = Path.Combine(baseDirectoryPath, dirName);
                Directory.CreateDirectory(newDirPath);
                Environment.SetEnvironmentVariable(envVarName, newDirPath);
            }
        }
        finally
        {
            lock_.ExitWriteLock();
        }
    }

    public void ParseXmlConfigFile(string filePath)
