        {
            XmlDocument doc = new XmlDocument();
            doc.Load(filePath);
            // parse the XML document and update baseDirectoryPath and subdirectoryNames
        }
        catch (Exception ex) when (ex is FileNotFoundException || ex is XmlException)
        {
            Console.WriteLine("Error parsing configuration file: " + ex.Message);
        }
    }

    public List<string> GetSubdirectories()
    {
        lock_.EnterReadLock();
        try
        {
            return new List<string>(Directory.GetDirectories(baseDirectoryPath, "*", SearchOption.TopDirectoryOnly));
        }
        finally
        {
            lock_.ExitReadLock();
        }
    }
}
