["Here is an example implementation using Node.js with worker threads and async/await syntax. This code uses `fs` module for reading files and `path` module for getting file extensions. It also uses a simple retry mechanism for handling transient network issues, and logs errors to the console. 

```javascript
const fs = require('fs');
const path = require('path');
const { Worker } = require('worker_threads');

// Define supported file types
const SUPPORTED_FILE_TYPES = ['.txt', '.json', '.csv'];

// Function to read a file and return its size
async function getFileSize(filePath) {
  let retries = 0;
  while (retries < 3) { // Retry up to 3 times
    try {
      const stats = await fs.promises.stat(filePath);
      return stats.size;
    } catch (err) {
      console.error(`Error reading file ${filePath}: ${err}`);
      retries++;
      // Wait for a bit before retrying
      await new Promise(resolve => setTimeout(resolve, 1000));
    }
  }
  throw new Error(`Failed to read file ${filePath} after 3 attempts.`);
}

// Function to process files in a directory
async function processDirectoryFiles(dirPath) {
  const dirEntries = await fs.promises.readdir(dirPath, { withFileTypes: true });

  // Create an array of promises for each file
  const promises = dirEntries.map(entry => {
    if (entry.isDirectory()) return processDirectoryFiles(path.join(dirPath, entry.name));

    const ext = path.extname(entry.name);
    if (!SUPPORTED_FILE_TYPES.includes(ext)) return;

    // Use worker threads to handle each file in a separate thread
    return new Promise((resolve, reject) => {
      const worker = new Worker('./worker.js', { workerData: path.join(dirPath, entry.name) });

      worker.on('message', resolve);
      worker.on('error', reject);
      worker.on('exit', code => {
        if (code !== 0) reject(new Error(`Worker stopped with exit code ${code}`));
      });
    });
  });

  // Wait for all promises to resolve and combine results into a single object
  const result = {};
  for (const promise of promises) {
    if (!promise) continue;

    try {
      const fileData = await promise;
      result[fileData.name] = fileData.size;
    } catch (err) {
      console.error(`Error processing file: ${err}`);
    }
  }

  return result;
}
```

The `worker.js` script would look something like this:

```javascript
