const fs = require('fs');

async function getFileSize(filePath) {
  const stats = await fs.promises.stat(filePath);
  return stats.size;
}

getFileSize(workerData).then(size => {
  parentPort.postMessage({ name: workerData, size });
}).catch(err => {
  console.error(`Error reading file ${workerData}: ${err}`);
});
```

