    private static final long CLEANUP_INTERVAL = 60 * 60 * 1000; // 1 hour

    private LruCache<String, Bitmap> mMemoryCache;
    private File mDiskCacheDir;
    private ExecutorService mExecutorService;
    private Handler mHandler = new Handler(Looper.getMainLooper());

    public ThemeCacheManager() {
        // Initialize memory cache with a size based on available memory
        final int maxMemory = (int) (Runtime.getRuntime().maxMemory() / 1024);
        final int cacheSize = maxMemory / 8;

        mMemoryCache = new LruCache<String, Bitmap>(cacheSize) {
            @Override
            protected int sizeOf(String key, Bitmap bitmap) {
                // The cache size will be measured in kilobytes rather than number of items.
                return bitmap.getByteCount() / 1024;
            }
        };

        // Initialize disk cache directory
        mDiskCacheDir = new File(Environment.getExternalStorageDirectory(), "theme_cache");
        if (!mDiskCacheDir.exists()) {
            mDiskCacheDir.mkdirs();
        }

        // Initialize executor service for background tasks
        mExecutorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

    public void cacheTheme(final String themeId, final Bitmap bitmap) {
        if (bitmap == null || themeId == null) return;

        // Add the bitmap to memory cache
        mMemoryCache.put(themeId, bitmap);

        // Write the bitmap to disk in a background thread
        mExecutorService.execute(new Runnable() {
            @Override
            public void run() {
                try {
                    File file = new File(mDiskCacheDir, themeId + ".png");
                    FileOutputStream outStream = new FileOutputStream(file);
                    bitmap.compress(Bitmap.CompressFormat.PNG, 100, outStream);

                    // Clean up the output stream and update memory cache with success status
                    outStream.flush();
                    outStream.close();
                } catch (IOException e) {
                    Log.e(TAG, "Failed to cache theme: " + themeId, e);
                } finally {
                    mHandler.post(new Runnable() {
                        @Override
                        public void run() {
                            // Update UI with success status
                        }
                    });
                }
            }
        });
    }

    // Add more methods as needed...
}
```
This is a basic example and does not include all the features you requested. You would need to expand it significantly to fully implement all the features you described: permission handling, image processing service integration, background task management, cache eviction policy, concurrent caching support, logging, performance optimization under high load conditions, etc.
