const fs = require('fs');
const https = require('https');
const { promisify } = require('util');

// Promisified version of fs.readFile for better readability
const readFileAsync = promisify(fs.readFile);

async function fetchPrivateKeyAndCertificate() {
  // Fetch private key and certificate from external sources
  const privateKeyPromise = readFileAsync('path/to/privatekey', 'utf8');
  const certificatePromise = readFileAsync('https://example.com/certificate', 'utf8');

  // Wait for both promises to resolve
  const [privateKey, certificate] = await Promise.all([privateKeyPromise, certificatePromise]);

  return { privateKey, certificate };
}

async function processOAuthRequest() {
  try {
    const { privateKey, certificate } = await fetchPrivateKeyAndCertificate();

    // Merge the fetched private key and certificate into a single PEM file
    const pemContent = `${privateKey}\n${certificate}`;

    return Promise.resolve(pemContent);
  } catch (error) {
    console.log('Error processing OAuth request:', error);
    throw error;
  }
}
```
This code fetches the private key and certificate from local files and a remote API, waits for both promises to resolve using `Promise.all`, merges them into a single PEM file, and returns it as an array. It also includes basic error handling with console logging. 

