enum AttackType { BASIC, SPECIAL, ULTIMATE, REST };

struct AttackDetails {
    int damage;
    int cooldownMin;
    int cooldownMax;
};

std::map<AttackType, AttackDetails> attacks = {
    {BASIC, {5, 5, 10}},
    {SPECIAL, {20, 10, 20}},
    {ULTIMATE, {30, 20, 30}},
    {REST, {0, 10, 15}}
};

void selectAttack(int& energyLevel, AttackType lastAttack, std::map<AttackType, time_t> attackHistory) {
    // Check if the energy level is below 20% and the last attack was not a rest
    if (energyLevel < 20 && lastAttack != REST) {
        std::cout << "Selected Attack: Rest\n";
        energyLevel = 80;
        return;
    }

    // Select an attack that is not on cooldown and has enough energy to be used
    std::vector<AttackType> availableAttacks;
    for (auto& pair : attacks) {
        AttackDetails details = pair.second;
        time_t currentTime = time(0);

        // Check if the attack is on cooldown or has been used too recently
        if (attackHistory[pair.first] + details.cooldownMin <= currentTime && energyLevel >= details.damage) {
            availableAttacks.push_back(pair.first);
        }
    }

    // If no attack is available, select the rest attack
    if (availableAttacks.empty()) {
        std::cout << "Selected Attack: Rest\n";
        energyLevel = 80;
        return;
    }

    // Select a random attack from the available ones
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, availableAttacks.size() - 1);
    AttackType selectedAttack = availableAttacks[dis(gen)];

    // Update the energy level and attack history
    energyLevel -= attacks[selectedAttack].damage;
    attackHistory[selectedAttack] = time(0);

    std::cout << "Selected Attack: " << selectedAttack << "\n";
}
```
This code uses a `std::map` to store the details of each type of attack. The `selectAttack` function then selects an available attack based on these details and updates the energy level and attack history accordingly. It also handles cases where the energy level is below 20% or all attacks are on cooldown by selecting a "Rest" attack.
']

