using System;
using UnityEngine; // Assuming you're using Unity3D

public class DynamicValueGenerator
{
    private int seed;
    private Random rng;

    public DynamicValueGenerator(int seed)
    {
        this.seed = seed;
        rng = new Random(this.seed);
    }

    public int GetRandomInt(int min, int max, bool inclusive)
    {
        return inclusive ? rng.Next(min, max + 1) : rng.Next(min, max);
    }

    public float GetRandomFloat(float min, float max, bool inclusive)
    {
        double sample = rng.NextDouble();
        double scaled = sample * (max - min);
        return (float)(inclusive ? scaled + min : Math.Max(min, scaled));
    }

    public Vector3 GetRandomVector3(Vector3 min, Vector3 max, bool xInclusive, bool yInclusive, bool zInclusive)
    {
        float x = GetRandomFloat(min.x, max.x, xInclusive);
        float y = GetRandomFloat(min.y, max.y, yInclusive);
        float z = GetRandomFloat(min.z, max.z, zInclusive);
        return new Vector3(x, y, z);
    }

    public override string ToString()
    {
        return $"Seed: {seed}";
    }
}
```
This class uses the `System.Random` class for generating random numbers and vectors. The `GetRandomInt` method generates a random integer within the specified range, inclusive or exclusive based on the boolean parameter. Similarly, the `GetRandomFloat` method generates a random float number within the specified range. The `GetRandomVector3` method generates a random vector with customizable inclusion/exclusion of each axis.

