        fclose(file);
        return NULL;
    }

    unsigned char *buffer = malloc(size);
    if (buffer == NULL) {
        printf("Could not allocate memory for buffer\n");
        free(metadata);
        fclose(file);
        return NULL;
    }

    if (fread(buffer, 1, size, file) != size) {
        printf("Error reading from file %s\n", filename);
        free(buffer);
        free(metadata);
        fclose(file);
        return NULL;
    }

    // Parse TIFF metadata here...
