using System;
using System.IO;
using System.Threading;

public class WebsiteManager
{
    private readonly string _directoryPath;
    private readonly string _siteName;
    private readonly bool _startImmediately;
    private readonly object _lock = new object();

    public WebsiteManager(string directoryPath, string siteName, bool startImmediately)
    {
        if (string.IsNullOrEmpty(directoryPath)) throw new ArgumentException("Invalid directory path");
        if (string.IsNullOrEmpty(siteName)) throw new ArgumentException("Invalid site name");

        _directoryPath = directoryPath;
        _siteName = siteName;
        _startImmediately = startImmediately;
    }

    public void AddAndStartWebsite()
    {
        lock (_lock)
