import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.apache.commons.compress.utils.IOUtils;

public class BackupUtility {
    private static final String CONFIG_FILE = "config.json";
    private static final int MAX_RETRIES = 3;
    private static final ExecutorService executor = Executors.newFixedThreadPool(10);

    public void backup() throws Exception {
        for (int i = 0; i < MAX_RETRIES; i++) {
            try {
                Path configPath = fetchRemoteFile();
                if (configPath != null && Files.exists(configPath)) {
                    processBackup(configPath);
                    break;
                }
            } catch (Exception e) {
                System.err.println("Failed to backup: " + e.getMessage());
                Thread.sleep(1000); // wait for a second before retrying
            }
        }
    }

    private Path fetchRemoteFile() throws Exception {
        // Implement your logic here to fetch the file from remote repository
        return null;
    }

    private void processBackup(Path configPath) throws IOException, InterruptedException, ExecutionException {
        List<String> directories = parseConfig(configPath);

        for (String directory : directories) {
            Future<?> future = executor.submit(() -> {
                try {
                    compressDirectory(directory);
                } catch (IOException e) {
                    System.err.println("Failed to compress: " + e.getMessage());
                }
            });

            // You can add a timeout here if you want to limit the time spent on each task
            future.get(); 
        }
    }

    private List<String> parseConfig(Path configPath) throws IOException {
        // Implement your logic here to parse the configuration file and return directories list
        return null;
    }

    private void compressDirectory(String directory) throws IOException {
        Path source = Paths.get(directory);
        String tarName = source.getFileName().toString() + ".tar";

        try (TarArchiveOutputStream out = getTarArchiveOutputStream(new FileOutputStream(tarName))) {
            Files.walkFileTree(source, new SimpleFileVisitor<Path>() {
                @Override
                public FileVisitResult visitFile(Path file, BasicFileAttributes attributes) throws IOException {
                    if (!Files.isHidden(file)) {
                        addToArchiveCompressed(out, source, file);
                    }
                    return FileVisitResult.CONTINUE;
                }
            });
        }
    }

    private TarArchiveOutputStream getTarArchiveOutputStream(FileOutputStream outputStream) throws IOException {
        return new TarArchiveOutputStream(outputStream);
    }

    private void addToArchiveCompressed(TarArchiveOutputStream out, Path source, Path file) throws IOException {
        try (InputStream in = Files.newInputStream(file)) {
            TarArchiveEntry entry = new TarArchiveEntry(source.relativize(file).toString());
            entry.setSize(Files.size(file));
            out.putArchiveEntry(entry);

            IOUtils.copy(in, out);
            out.closeArchiveEntry();
        }
    }
}
```
This code is a basic example and does not cover all the points you mentioned due to its complexity but it gives an idea about how you can start implementing this task. 

