['Here is a basic implementation in C using cJSON library for parsing JSON and curl for logging to an external service. This code does not include load balancing considerations as they are highly dependent on specific use case and infrastructure setup. 

```c
#include <stdbool.h>
#include <time.h>
#include <curl/curl.h>
#include "cJSON.h"

// Function to log session validation attempts
static void log_validation(CURL *curl, const char* url, time_t timestamp, bool status) {
    // Prepare JSON payload
    cJSON *payload = cJSON_CreateObject();
    cJSON_AddNumberToObject(payload, "timestamp", (double)timestamp);
    cJSON_AddBoolToObject(payload, "status", status);

    // Convert to string and send POST request
    char *json_str = cJSON_PrintUnformatted(payload);
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_str);

    // Execute request and cleanup
    curl_easy_perform(curl); 
    cJSON_free(json_str);
    cJSON_Delete(payload);
}

bool validate_session(CURL *curl, const char* url, const char* json) {
    // Parse JSON payload
    cJSON *session = cJSON_Parse(json);

    time_t now = time(NULL);
    bool valid = true;

    // Check required fields and their types
    if(!cJSON_IsString(cJSON_GetObjectItemCaseSensitive(session, "session_id")) ||
       !cJSON_IsString(cJSON_GetObjectItemCaseSensitive(session, "user_id")) ||
       !cJSON_IsNumber(cJSON_GetObjectItemCaseSensitive(session, "expiration_time")) ||
       !cJSON_IsNumber(cJSON_GetObjectItemCaseSensitive(session, "last_activity"))) {
        valid = false;
    } else {
        // Check field values
        time_t expiration_time = cJSON_GetObjectItemCaseSensitive(session, "expiration_time")->valueint;
        time_t last_activity = cJSON_GetObjectItemCaseSensitive(session, "last_activity")->valueint;

        if(difftime(now, expiration_time) > 0 || difftime(now, last_activity) > 900) {
            valid = false;
        }
    }

    // Log validation attempt
    log_validation(curl, url, now, valid);

    // Cleanup and return result
    cJSON_Delete(session);
    return valid;
}
```
This code assumes that the JSON payload is well-formed and does not include any error handling for malformed or missing fields. It also doesn't handle network errors when logging validation attempts, which could be added with additional error checking in `log_validation` function. 

Please note that this code uses cURL library to send POST requests to an external service. You need to install and link against the cURL library for it to work. Also, you should replace "http://example.com/log" with your actual logging service URL.
']

