['Here is a basic implementation of the service in C# using .NET Core. This code does not include all the requirements mentioned above due to its complexity but it provides a good starting point for building such a service. 

```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Caching.Memory;

public class EncryptionService
{
    private readonly IMemoryCache _cache;
    private readonly string _apiEndpoint;

    public EncryptionService(IMemoryCache cache, string apiEndpoint)
    {
        _cache = cache;
        _apiEndpoint = apiEndpoint;
    }

    public (string plaintext, byte[] hmac) DecryptAndVerifyMessage(byte[] encryptedMessage, byte[] iv)
    {
        var keys = FetchKeysFromApi();

        using (var tripleDes = new TripleDESCryptoServiceProvider())
        {
            tripleDes.Key = keys.Item1;
            tripleDes.IV = iv;

            using (var decryptor = tripleDes.CreateDecryptor(tripleDes.Key, tripleDes.IV))
            {
                byte[] plaintextBytes;

                using (MemoryStream msDecrypt = new MemoryStream())
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Write))
                    {
                        csDecrypt.Write(encryptedMessage, 0, encryptedMessage.Length);
                        csDecrypt.FlushFinalBlock();

                        plaintextBytes = msDecrypt.ToArray();
                    }
                }

                string plaintext = Encoding.UTF8.GetString(plaintextBytes);
                byte[] hmac;

                using (var hmacsha256 = new HMACSHA256(keys.Item2))
                {
                    hmac = hmacsha256.ComputeHash(Encoding.UTF8.GetBytes(plaintext));
                }

                return (plaintext, hmac);
            }
        }
    }

    private Tuple<byte[], byte[]> FetchKeysFromApi()
    {
        if (!_cache.TryGetValue("keys", out Tuple<byte[], byte[]> keys))
        {
            // Call the API to fetch the latest encryption keys and IVs securely
            // For simplicity, let's assume that we get these values from a dictionary
            var response = new Dictionary<string, string>() 
            {
                {"encryptionKey", "your_encryption_key"},
                {"hmacKey", "your_hmac_key"}
            };

            keys = Tuple.Create(Encoding.UTF8.GetBytes(response["encryptionKey"]), Encoding.UTF8.GetBytes(response["hmacKey"]));

            // Cache the keys for 24 hours
            _cache.Set("keys", keys, new MemoryCacheEntryOptions().SetAbsoluteExpiration(TimeSpan.FromHours(24)));
        }

        return keys;
    }
}
```
This code uses .NET Core's built-in cryptography libraries to perform the decryption and HMAC computation. It also uses a MemoryCache object from Microsoft.Extensions.Caching.Memory to cache the encryption keys for 24 hours, reducing the number of API calls and improving performance.

Please note that this is a simplified example and does not include all the requirements mentioned above such as error handling, logging, integration with external systems, scalability considerations etc. For a production-ready solution, you would need to add these features according to your specific needs.
