#define MAX_SIZE 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int valid;
    int RNTI;
    unsigned char CRCFLAG[EVP_MAX_MD_SIZE];
} NFAPI_CRC_INDICATION_PDU_T;

