public class NetworkApp {
    private SocketAddress remote;
    private Selector selector;
    private SocketChannel channel;

    public void connect(String host, int port) throws IOException {
        remote = new InetSocketAddress(host, port);

        // Initialize the selector and register it with the channel.
        selector = Selector.open();
        channel = SocketChannel.open(remote);
        channel.configureBlocking(false);
        SelectionKey key = channel.register(selector, SelectionKey.OP_CONNECT);

        // Attempt to establish the connection.
        int retries = 0;
        while (!channel.finishConnect()) {
            if (retries++ > 3) {
                throw new IOException("Failed to connect");
            }

            try {
                Thread.sleep(1000); // Wait before retrying.
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        selector.wakeup(); // Wake up the selector to handle connection state changes.
    }

    public void manageConnection() throws IOException {
        while (true) {
            if (selector.selectNow() > 0) {
                Iterator<SelectionKey> selectedKeys = selector.selectedKeys().iterator();
                while (selectedKeys.hasNext()) {
                    SelectionKey key = selectedKeys.next();
                    selectedKeys.remove();

                    // Handle connection state changes.
