from threading import Lock

class FileHasher:
    def __init__(self):
        self.md5 = hashlib.md5()
        self.lock = Lock()

    def update(self, file_path):
        with open(file_path, 'rb') as f:
            for byte_block in iter(lambda: f.read(4096), b""):
