#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NetworkNode {
    int nodeID;
    char* location;
    int status;
} NetworkNode;

typedef struct NodeList {
    pthread_mutex_t lock;
    NetworkNode** nodes;
    size_t count;
    size_t capacity;
} NodeList;

// Initialize a new node list.
void init(NodeList* list) {
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        exit(EXIT_FAILURE);
    }
    list->nodes = malloc(sizeof(NetworkNode*) * 10);
    if (!list->nodes) {
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = 10;
}

// Add a node to the list.
void addNode(NodeList* list, NetworkNode* node) {
    pthread_mutex_lock(&list->lock);

    // Check for unique IDs.
    for (size_t i = 0; i < list->count; ++i) {
        if (node->nodeID == list->nodes[i]->nodeID) {
            exit(EXIT_FAILURE);  // Duplicate nodeID, handle error as needed.
        }
    }

    // Check for valid location format.
    if (!node->location || strlen(node->location) > 256) {
        exit(EXIT_FAILURE);  // Invalid location format, handle error as needed.
    }

    // Resize the list if necessary.
    if (list->count == list->capacity) {
        list->capacity *= 2;
        list->nodes = realloc(list->nodes, sizeof(NetworkNode*) * list->capacity);
        if (!list->nodes) {
            exit(EXIT_FAILURE);
        }
    }

    // Add the node.
    list->nodes[list->count++] = node;

    pthread_mutex_unlock(&list->lock);
}

// Remove a node from the list by its ID.
void removeNode(NodeList* list, int nodeID) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (nodeID == list->nodes[i]->nodeID) {
            free(list->nodes[i]);  // Free the memory.

            // Shift all nodes after this one to fill the gap.
            for (size_t j = i; j < list->count - 1; ++j) {
                list->nodes[j] = list->nodes[j + 1];
            }

            --list->count;
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}
```
