} Record;

void init_memory(int* keys, size_t keyCount, Record* records, size_t recordCount, int minVal, int maxVal) {
    srand((unsigned int)(time(NULL) * getpid())); // seed PRNG with time and PID

    for (size_t i = 0; i < keyCount; ++i) {
        keys[i] = rand(); // generate random number

        // check for duplicates
        for (size_t j = 0; j < i; ++j) {
            if (keys[j] == keys[i]) {
                printf("Duplicate key found: %d\n", keys[i]);
                break;
            }
        }
    }

    for (size_t i = 0; i < recordCount; ++i) {
        records[i].value = minVal + rand() % ((maxVal + 1) - minVal); // generate random number within range

        int offsetIndex = rand() % keyCount; // select a random index for the offset
        if (offsetIndex >= 0 && offsetIndex < keyCount) {
            records[i].offset = &keys[offsetIndex]; // assign valid offset
        } else {
            printf("Invalid offset: %d\n", offsetIndex);
            records[i].offset = NULL; // assign default value to record
        }
    }
}
