```java
import okhttp3.*;
import org.apache.commons.codec.digest.DigestUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.io.IOException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class UserProfileClient {
    private static final Logger logger = LoggerFactory.getLogger(UserProfileClient.class);
    private OkHttpClient client = new OkHttpClient();
    private ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private AtomicInteger apiCalls = new AtomicInteger(0);
    private AtomicInteger successfulResponses = new AtomicInteger(0);
    private AtomicInteger timeoutsOrFailures = new AtomicInteger(0);

    public String getUserProfile(String userId) {
        if (cache.containsKey(userId)) {
            return cache.get(userId);
        }

        Request request = new Request.Builder()
                .url("https://api.example.com/users/" + userId)
                .build();

        try (Response response = client.newCall(request).execute()) {
            apiCalls.incrementAndGet();
            if (!response.isSuccessful()) throw new IOException("Unexpected code " + response);

            String profile = response.body().string();
            cache.put(userId, profile);
            successfulResponses.incrementAndGet();
            return profile;
        } catch (IOException e) {
            timeoutsOrFailures.incrementAndGet();
            logger.error("Error while fetching user profile", e);
            return null;
        }
    }

    public String generateMD5Hash(String input) {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input string cannot be null or empty");
        }

        return DigestUtils.md5Hex(input);
    }

    public void logMetrics() {
        logger.info("API calls: " + apiCalls.get());
        logger.info("Successful responses: " + successfulResponses.get());
        logger.info("Timeouts or failures: " + timeoutsOrFailures.get());
    }
}
