```csharp
using System;
using System.Collections.Generic;
using System.Threading;
using System.Linq;

public class CustomRandom
{
    private int minValue;
    private int maxValue;
    private bool isLoggingEnabled = false;
    private static readonly Random random = new Random();
    private static readonly object syncLock = new object();

    public CustomRandom(int min, int max)
    {
        if (min > max) throw new ArgumentException("Minimum value cannot be greater than maximum");

        this.minValue = min;
        this.maxValue = max;
    }

    public void UpdateRange(int min, int max)
    {
        lock (syncLock)
        {
            if (min > max) throw new ArgumentException("Minimum value cannot be greater than maximum");

            this.minValue = min;
            this.maxValue = max;
        }
    }

    public int NextInt(bool inclusive = true)
    {
        lock (syncLock)
        {
            var result = random.Next(this.minValue, this.maxValue + Convert.ToInt32(inclusive));

            if (isLoggingEnabled) Log(result);

            return result;
        }
    }

    public float NextFloat()
    {
        lock (syncLock)
        {
            var result = minValue + random.NextDouble() * (maxValue - minValue);

            if (isLoggingEnabled) Log(result);

            return (float)result;
        }
    }

    public IEnumerable<int> SequenceInt(int length, bool inclusive = true)
    {
        lock (syncLock)
        {
            for (var i = 0; i < length; i++)
            {
                var result = random.Next(this.minValue, this.maxValue + Convert.ToInt32(inclusive));

                if (isLoggingEnabled) Log(result);

                yield return result;
            }
        }
    }

    public void ShuffleArrayInPlace(int[] array)
    {
        lock (syncLock)
        {
            int n = array.Length;

            while (n > 1) 
            {
                n--;

                int k = random.Next(n + 1);
                var value = array[k];

                if (isLoggingEnabled) Log(value);

                array[k] = array[n];
                array[n] = value;
            } 
        }
    }

    public void EnableLogging() => isLoggingEnabled = true;

    public void DisableLogging() => isLoggingEnabled = false;

    private void Log(object message)
    {
        // Implement logging here. This could be a console log, file log, or any other form of logging.
        Console.WriteLine(message);
    }

    public override string ToString() => $"Range: [{minValue}, {maxValue}]";
}
```
