#include <pthread.h>

typedef struct {
    int key;
} record_t;

typedef struct {
    pthread_mutex_t lock;
    size_t count;
    size_t capacity;
    record_t** records;
} array_t;

array_t* create_array(size_t max) {
    array_t* arr = malloc(sizeof(array_t));
    if (arr == NULL) return NULL;

    pthread_mutex_init(&arr->lock, NULL);
    arr->count = 0;
    arr->capacity = max;
    arr->records = malloc(sizeof(record_t*) * max);
    if (arr->records == NULL) {
        free(arr);
        return NULL;
    }

    return arr;
}

void destroy_array(array_t* arr) {
    for (size_t i = 0; i < arr->count; ++i) {
        free(arr->records[i]);
    }
    free(arr->records);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

int add_record(array_t* arr, record_t* rec) {
    if (pthread_mutex_lock(&arr->lock)) return -1;

    if (arr->count >= arr->capacity) {
        pthread_mutex_unlock(&arr->lock);
        return -2;
    }

    arr->records[arr->count++] = rec;

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

record_t* find_largest(array_t* arr) {
    if (pthread_mutex_lock(&arr->lock)) return NULL;

    record_t* largest = NULL;
    for (size_t i = 0; i < arr->count; ++i) {
        if (largest == NULL || arr->records[i]->key > largest->key) {
            largest = arr->records[i];
        }
    }

    pthread_mutex_unlock(&arr->lock);
    return largest;
}
