#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int id;
    void* metadata; // replace with actual metadata type
} Document;

typedef struct Node {
    Document doc;
    struct Node *prev, *next;
} Node;

typedef struct {
    pthread_mutex_t lock;
    sem_t capacity;
    int size;
    int limit;
    Node* head;
    Node* tail;
} Index;

Index* createIndex(int limit) {
    Index* index = malloc(sizeof(Index));
    pthread_mutex_init(&index->lock, NULL);
    sem_init(&index->capacity, 0, limit);
    index->size = 0;
    index->limit = limit;
    index->head = index->tail = NULL;
    return index;
}

void insertDocument(Index* index, Document doc) {
    sem_wait(&index->capacity); // wait for capacity

    pthread_mutex_lock(&index->lock);

    Node* node = malloc(sizeof(Node));
    node->doc = doc;
    node->prev = index->tail;
    node->next = NULL;

    if (index->head == NULL) { // empty list
        index->head = index->tail = node;
    } else {
        index->tail->next = node;
        index->tail = node;
    }

    pthread_mutex_unlock(&index->lock);
}

Document* getDocument(Index* index, int id) {
    pthread_mutex_lock(&index->lock);

    Node* curr = index->head;
    while (curr != NULL && curr->doc.id != id) {
        curr = curr->next;
    }

    pthread_mutex_unlock(&index->lock);

    return curr ? &(curr->doc) : NULL;
}

void deleteDocument(Index* index, int id) {
    pthread_mutex_lock(&index->lock);

    Node* curr = index->head;
    while (curr != NULL && curr->doc.id != id) {
        curr = curr->next;
    }

    if (curr != NULL) { // found
        if (curr == index->head) { // first node
            index->head = curr->next;
        } else {
            curr->prev->next = curr->next;
        }

        if (curr == index->tail) { // last node
            index->tail = curr->prev;
        } else {
            curr->next->prev = curr->prev;
        }

        free(curr);
    }

    pthread_mutex_unlock(&index->lock);
}
```
