        printf("Error: Number of nodes exceeds the maximum limit.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Validate location format according to ISO 3166-1 alpha-2 standard
    if (strlen(node.location) != 2 || !isalpha(node.location[0]) || !isalpha(node.location[1])) {
        printf("Error: Invalid location format.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Check if nodeID is unique within the list
    GList *iter = g_list_first(node_list);
    while (iter) {
        NetworkNode *existing_node = iter->data;
        if (existing_node->nodeID == node.nodeID) {
            printf("Error: Duplicate nodeID.\n");
            pthread_mutex_unlock(&lock);
            return;
        }
        iter = g_list_next(iter);
    }

    // Add the new node to the list
    node_list = g_list_append(node_list, &node);

    pthread_mutex_unlock(&lock);
}
```

