```C
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <curl/curl.h>
#include <json-c/json.h>
#include <glib.h>

// Global variables for configuration and locking
GHashTable* config_table;
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

void load_config(char* env) {
    char url[256];
    sprintf(url, "http://example.com/%s.json", env);

    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return;
    }

    // Set up the request
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);

    // Perform the request and handle errors
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to download configuration: %s\n", curl_easy_strerror(res));
        return;
    }

    // Parse the JSON response and handle errors
    json_object* jconfig = json_tokener_parse(curl_easy_getinfo(curl, CURLINFO_CONTENT));
    if (!jconfig) {
        fprintf(stderr, "Failed to parse configuration\n");
        return;
    }

    // Lock the config table and update it
    pthread_mutex_lock(&config_lock);
    json_object_object_foreach(jconfig, key, val) {
        g_hash_table_replace(config_table, (gpointer)key, (gpointer)val);
    }
    pthread_mutex_unlock(&config_lock);

    // Clean up
    curl_easy_cleanup(curl);
}
```

