    int status;
} NetworkNode;

typedef struct NodeList {
    pthread_mutex_t lock;
    size_t count;
    size_t capacity;
    NetworkNode** nodes;
} NodeList;

// Initialize the list with a certain capacity.
void init(NodeList* list, size_t initialCapacity) {
    list->count = 0;
    list->capacity = initialCapacity;
    list->nodes = malloc(sizeof(NetworkNode*) * initialCapacity);
    pthread_mutex_init(&list->lock, NULL);
}

// Add a node to the list.
void add(NodeList* list, NetworkNode* node) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        // Double the capacity when full.
        list->capacity *= 2;
        list->nodes = realloc(list->nodes, sizeof(NetworkNode*) * list->capacity);
    }

    list->nodes[list->count++] = node;

    pthread_mutex_unlock(&list->lock);
}

// Remove a node from the list.
void remove(NodeList* list, int nodeID) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->nodes[i]->nodeID == nodeID) {
            free(list->nodes[i]); // Free the memory.

            // Shift all elements after this one to fill the gap.
            for (size_t j = i; j < list->count - 1; ++j) {
                list->nodes[j] = list->nodes[j + 1];
            }

            --list->count;
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}
```
