#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct ResourceNode {
    int resourceID;
    char* resourceName;
    int status;
} ResourceNode;

typedef struct ResourceCollection {
    ResourceNode** nodes;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} ResourceCollection;

ResourceCollection* create_collection(size_t initialCapacity) {
    ResourceCollection* collection = malloc(sizeof(ResourceCollection));
    if (collection == NULL) return NULL;

    collection->nodes = calloc(initialCapacity, sizeof(ResourceNode*));
    if (collection->nodes == NULL) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initialCapacity;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_collection(ResourceCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->nodes[i]->resourceName);
        free(collection->nodes[i]);
    }

    free(collection->nodes);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int insert_node(ResourceCollection* collection, ResourceNode* node) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        ResourceNode** newNodes = realloc(collection->nodes, newCapacity * sizeof(ResourceNode*));

        if (newNodes == NULL) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Failed to allocate memory
        }

        collection->capacity = newCapacity;
        collection->nodes = newNodes;
    }

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->nodes[i]->resourceID == node->resourceID) {
            pthread_mutex_unlock(&collection->lock);
            return -2; // Duplicate resource ID
        }
    }

    collection->nodes[collection->count++] = node;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

ResourceNode* find_node(ResourceCollection* collection, int resourceID) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->nodes[i]->resourceID == resourceID) {
            pthread_mutex_unlock(&collection->lock);
            return collection->nodes[i];
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL; // Node not found
}

int delete_node(ResourceCollection* collection, int resourceID) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->nodes[i]->resourceID == resourceID) {
            free(collection->nodes[i]->resourceName);
            free(collection->nodes[i]);

            // Shift all nodes after the deleted one to fill the gap
            for (size_t j = i; j < collection->count - 1; ++j) {
                collection->nodes[j] = collection->nodes[j + 1];
            }

            --collection->count;
            pthread_mutex_unlock(&collection->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Node not found
}
```
This code provides a basic implementation of the `ResourceCollection` structure and functions for inserting, finding, and deleting nodes. It uses a mutex to ensure thread safety. The collection is implemented as an array with dynamic resizing when it reaches capacity. 

