#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    char* buffer;
    int value;
} Record;

typedef struct Node {
    Record* record;
    struct Node* next;
} Node;

Node* head = NULL;
int threshold = 5000;
int growth_factor = 2;
int cache_size = 100;
float hit_rate = 0.75;

void insert(Record* record, int key) {
    Node* node = (Node*) malloc(sizeof(Node));
    node->record = record;
    node->next = NULL;

    if(head == NULL || head->record->value > key) {
        node->next = head;
        head = node;
        return;
    }

    Node* current = head;
    while(current->next != NULL && current->next->record->value < key) {
        current = current->next;
    }

    if(current->next != NULL && current->next->record->value == key) {
        free(current->next);
        current->next = node;
    } else {
        node->next = current->next;
        current->next = node;
    }
}

void resize() {
    threshold *= growth_factor;
    long* new_offsets = (long*) realloc(offsets, sizeof(long) * threshold);
    if(new_offsets != NULL) offsets = new_offsets;

    int* new_keys = (int*) realloc(keys, sizeof(int) * threshold);
    if(new_keys != NULL) keys = new_keys;

    Record* new_records = (Record*) realloc(records, sizeof(Record) * threshold);
    if(new_records != NULL) records = new_records;
}

void garbage_collection() {
    Node* current = head;
    while(current != NULL) {
        if((float) rand()/RAND_MAX > hit_rate) {
            free(current->record->buffer);
            free(current->record);
        }
        current = current->next;
    }
}

void validate() {
    Node* current = head;
    while(current != NULL) {
        if(current->next != NULL && current->record->value > current->next->record->value) {
            printf("Data inconsistent\n");
            return;
        }
        current = current->next;
    }
}

void manage_records() {
    srand(time(0));

    long* offsets = (long*) malloc(sizeof(long) * threshold);
    int* keys = (int*) malloc(sizeof(int) * threshold);
    Record* records = (Record*) malloc(sizeof(Record) * threshold);

    for(int i = 0; i < threshold; i++) {
        offsets[i] = rand();
        keys[i] = rand() % 10000;

        records[i].buffer = (char*) malloc(sizeof(char) * cache_size);
        sprintf(records[i].buffer, "Record %d", i);
        records[i].value = rand() % 10000;

        insert(&records[i], keys[i]);
    }

    validate();
    garbage_collection();
}
```
