#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <netdb.h>
#include <arpa/inet.h>

u_char* resolveDNS(const char *hostname) {
    struct hostent *he;
    if ((he = gethostbyname(hostname)) == NULL) {
        herror("gethostbyname");
        return NULL;
    }

    u_char *ip = malloc(sizeof(u_char)*16); // assuming IPV4 address
    strcpy((char*)ip, inet_ntoa(*((struct in_addr *)he->h_addr)));
    return ip;
}

void processFile(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        line[strcspn(line, "\n")] = 0; // remove newline character

        char *token = strtok(line, ",");
        int i = 0;
        double sum = 0.0;
        while (token != NULL && i >= sizeof(double)*2) {
            if (i >= sizeof(double)) {
                sum += atof(token);
            }
            token = strtok(NULL, ",");
            i++;
        }

        double average = sum / 2.0;
        printf("%s,%lf\n", line, average);
    }

    free(line);
    fclose(file);
}

int main() {
    const char *filename = "input.txt";
    if (access(filename, F_OK) != -1 ) {
        remove(filename);
    }

    processFile(filename);

    return 0;
