class FileProcessor:
    def __init__(self, dao):
        self.dao = dao

    def process_file(self, filepath, user_id, new_password):
        if not os.path.isfile(filepath):
            return {"status": "failure", "message": f"File {filepath} does not exist"}

        md5 = hashlib.md5()
        sha256 = hashlib.sha256()

        with open(filepath, 'rb') as file:
            while True:
                data = file.read(4096)
                if not data:
                    break

                md5.update(data)
                sha256.update(data)

        hex_md5 = md5.hexdigest()
        hex_sha256 = sha256.hexdigest()

        if not self._validate_password(new_password):
            return {"status": "failure", "message": f"Password does not meet complexity requirements"}

        update_successful = self.dao.update_user(user_id, new_password)

        if update_successful:
            status = "success"
            message = "User password updated successfully"
        else:
            status = "failure"
            message = "Failed to update user password"

        return {"status": status, "message": message, "md5": hex_md5, "sha256": hex_sha256}

    def _validate_password(self, new_password):
        # Add your own complexity rules here
        if len(new_password) < 8:
            return False

        has_digit = any(char.isdigit() for char in new_password)
        has_uppercase = any(char.isupper() for char in new_password)
        has_lowercase = any(char.islower() for char in new_password)

        if not (has_digit and has_uppercase and has_lowercase):
            return False

        return True
