    if (records == NULL) {
        // Handle allocation failure
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize records
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = keys[i];
        records[i].key = &keys[i];
    }

