void *process_file(void *arg) {
    Arguments *args = (Arguments *) arg;

    if (args->enable_logging) logger_init();
    if (args->verbose_logging) logger_setLevel(LOGGER_LEVEL_TRACE);

    FILE *in = fopen(args->input_file, "r");
    if (!in) {
        if (args->enable_logging) LOG_ERROR("Failed to open input file: %s", args->input_file);
        return NULL;
    }

    FILE *out = fopen(args->output_file, "w");
    if (!out) {
        if (args->enable_logging) LOG_ERROR("Failed to open output file: %s", args->output_file);
        return NULL;
    }

    char buffer[1024]; // Adjust this size as needed for your JSON files
    fread(buffer, 1, sizeof(buffer), in);

    cJSON *root = cJSON_Parse(buffer);
    if (!root) {
        if (args->enable_logging) LOG_ERROR("Failed to parse JSON data");
        return NULL;
    }

    process_json(root, out, args->query);

    fclose(in);
    fclose(out);
    cJSON_Delete(root);

    if (args->enable_logging) logger_cleanup();

    return NULL;
}

int main(int argc, char *argv[]) {
    Arguments args = {0}; // Initialize all fields to 0 or NULL

    if (argc != 7) {
        printf("Usage: %s <input_file> <output_file> <query> <optimize_speed> <enable_logging> <verbose_logging>\n", argv[0]);
        return EXIT_FAILURE;
    }

    args.input_file = argv[1];
    args.output_file = argv[2];
    args.query = argv[3];
    args.optimize_speed = atoi(argv[4]);
    args.enable_logging = atoi(argv[5]);
    args.verbose_logging = atoi(argv[6]);

    pthread_t thread;
    if (pthread_create(&thread, NULL, process_file, &args)) {
        printf("Failed to create thread\n");
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    return EXIT_SUCCESS;
}
