```java
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import javax.xml.bind.DatatypeConverter;

public class FileHasher {
    private static final ExecutorService executor = Executors.newCachedThreadPool();
    private static final ConcurrentHashMap<String, String> fileHashes = new ConcurrentHashMap<>();
    private static final Map<String, Boolean> fileStatuses = new ConcurrentHashMap<>();

    public static void main(String[] args) {
        List<Path> files = getFilesFromDataFeed(); // Implement this method to fetch files from external data feed.

        for (Path file : files) {
            executor.execute(() -> processFile(file));
        }
    }

    private static void processFile(Path file) {
        if (!Files.isExecutable(file)) {
            System.out.println("Skipping non-executable file: " + file);
            return;
        }

        String hash = fileHashes.computeIfAbsent(file.toString(), k -> computeHash(file));
        if (hash != null) {
            System.out.println("File: " + file + ", Hash: " + hash);
            fileStatuses.put(file.toString(), true);
        } else {
            fileStatuses.put(file.toString(), false);
        }
    }

    private static String computeHash(Path file) {
        try (InputStream is = Files.newInputStream(file)) {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[8192];
            int bytesRead;

            while ((bytesRead = is.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }

            return DatatypeConverter.printHexBinary(md.digest());
        } catch (IOException | NoSuchFileException e) {
            System.out.println("Error processing file: " + file);
            e.printStackTrace();
            return null;
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e); // This should never happen.
        }
    }

    private static void reportProgress() {
        int total = fileStatuses.size();
        long successful = fileStatuses.values().stream().filter(Boolean::booleanValue).count();
        long failed = total - successful;

        System.out.println("Total files processed: " + total);
        System.out.println("Successfully hashed files: " + successful);
        System.out.println("Failed to hash files: " + failed);
    }
}
```
This code uses a `ConcurrentHashMap` to store the MD5 hashes of each file, and another map to track whether each file was successfully processed or not. It also uses an `ExecutorService` with a cached thread pool for concurrent processing of files. The `computeIfAbsent` method is used to ensure that each file is only processed once.

Please note that this code does not include the dynamic adjustment of the number of threads in the thread pool, deadlock detection and handling mechanisms, logging of progress periodically, queryable API endpoint for monitoring and analysis, or network connectivity issues recovery mechanism. You would need to implement these features yourself based on your specific requirements.
