```c
#include <stdlib.h>
#include <string.h>

typedef struct record {
    char* buffer;
    int value;
    int* metadata;
} Record;

typedef struct memory_manager {
    long* offsets;
    int* keys;
    Record** records;
    int* tempStorage;
    int capacity;
    int size;
} MemoryManager;

MemoryManager* createMemoryManager(int initialCapacity) {
    MemoryManager* manager = malloc(sizeof(MemoryManager));
    manager->offsets = calloc(initialCapacity, sizeof(long));
    manager->keys = calloc(initialCapacity, sizeof(int));
    manager->records = calloc(initialCapacity, sizeof(Record*));
    manager->tempStorage = calloc(initialCapacity, sizeof(int));
    manager->capacity = initialCapacity;
    manager->size = 0;
    return manager;
}

void insertRecord(MemoryManager* manager, Record* record) {
    if (manager->size == manager->capacity) {
        manager->offsets = realloc(manager->offsets, 2 * manager->capacity * sizeof(long));
        manager->keys = realloc(manager->keys, 2 * manager->capacity * sizeof(int));
        manager->records = realloc(manager->records, 2 * manager->capacity * sizeof(Record*));
        manager->tempStorage = realloc(manager->tempStorage, 2 * manager->capacity * sizeof(int));
        manager->capacity *= 2;
    }

    // Assuming keys are unique and sorted in ascending order
    int index = 0;
    while (index < manager->size && manager->keys[index] < record->value) {
        index++;
    }

    for (int i = manager->size - 1; i >= index; --i) {
        manager->offsets[i + 1] = manager->offsets[i];
        manager->keys[i + 1] = manager->keys[i];
        manager->records[i + 1] = manager->records[i];
    }

    manager->offsets[index] = (long)record;
    manager->keys[index] = record->value;
    manager->records[index] = record;
    manager->size++;
}

void deleteRecord(MemoryManager* manager, int key) {
    // Assuming keys are unique and sorted in ascending order
    int index = 0;
    while (index < manager->size && manager->keys[index] != key) {
        index++;
    }

    if (index == manager->size) {
        return; // Record not found
    }

    free(manager->records[index]->buffer);
    free(manager->records[index]);

    for (int i = index; i < manager->size - 1; ++i) {
        manager->offsets[i] = manager->offsets[i + 1];
        manager->keys[i] = manager->keys[i + 1];
        manager->records[i] = manager->records[i + 1];
    }

    manager->size--;
}

void cleanup(MemoryManager* manager) {
    for (int i = 0; i < manager->size; ++i) {
        free(manager->records[i]->buffer);
        free(manager->records[i]);
    }

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager->tempStorage);
    free(manager);
}
```
