using System;
using UnityEngine;

public class DynamicRangeGenerator
{
    private long seed;
    private Vector3 minBounds;
    private Vector3 maxBounds;
    private Random rand;

    public DynamicRangeGenerator(long seed)
    {
        this.seed = seed;
        rand = new Random((int)seed);
    }

    public void SetSeed(long seed)
    {
        this.seed = seed;
        rand = new Random((int)seed);
    }

    public int GetRandomInt(int min, int max, bool inclusive)
    {
        if (min > max) throw new ArgumentException("Min value cannot be greater than max value");
        return rand.Next(inclusive ? min : min + 1, inclusive ? max + 1 : max);
    }

    public float GetRandomFloat(float min, float max, bool inclusive)
    {
        if (min > max) throw new ArgumentException("Min value cannot be greater than max value");
        return (float)(rand.NextDouble() * (max - min) + min);
    }

    public Vector3 GetRandomVector3(bool xInclusive, bool yInclusive, bool zInclusive)
    {
        float x = GetRandomFloat(minBounds.x, maxBounds.x, xInclusive);
        float y = GetRandomFloat(minBounds.y, maxBounds.y, yInclusive);
        float z = GetRandomFloat(minBounds.z, maxBounds.z, zInclusive);
        return new Vector3(x, y, z);
    }

    public void SetBounds(Vector3 min, Vector3 max)
    {
        if (min.x > max.x || min.y > max.y || min.z > max.z) throw new ArgumentException("Invalid bounds");
        this.minBounds = min;
        this.maxBounds = max;
