    int key;
    Record* record;
    struct node* prev;
    struct node* next;
} Node;

Node* head = NULL;
Node* tail = NULL;
Record** records = NULL;
int* keys = NULL;
long* offsets = NULL;
void** metadata = NULL;
size_t size = 0;
size_t capacity = 10000;

void insert(int key, Record* record) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = key;
    node->record = record;
    node->prev = NULL;
    node->next = NULL;

    if (head == NULL) {
        head = tail = node;
    } else if (tail->key <= key) {
        tail->next = node;
        node->prev = tail;
        tail = node;
    } else {
        Node* current = head;
        while (current != NULL && current->key < key) {
            current = current->next;
        }

        if (current == head) {
            node->next = head;
            head->prev = node;
            head = node;
        } else {
            node->prev = current->prev;
            node->next = current;
            current->prev->next = node;
            current->prev = node;
        }
    }

    size++;
}

void allocate_memory() {
    records = (Record**)malloc(capacity * sizeof(Record*));
    keys = (int*)malloc(capacity * sizeof(int));
    offsets = (long*)malloc(capacity * sizeof(long));
