import org.apache.commons.codec.digest.*;

public class CloudStorageService {
    private CacheManager cacheManager;
    private LoadingCache<String, String> md5Cache;
    private Map<String, Boolean> processedFiles = new ConcurrentHashMap<>();

    public CloudStorageService() throws IOException {
        CachingProvider cachingProvider = Caching.getCachingProvider();
        cacheManager = cachingProvider.getCacheManager();
        MutableConfiguration<String, String> config = new MutableConfiguration<>();
        config.setTypes(String.class, String.class)
                .setStoreByValue(false)
                .setStatisticsEnabled(true);
        md5Cache = cacheManager.createCache("md5Cache", config);
    }

    public void processFiles(List<URL> fileUrls) {
        for (URL url : fileUrls) {
            String filePath = url.getFile();
            if (!processedFiles.containsKey(filePath)) {
                try {
                    String md5Hash = getMd5Hash(url);
                    md5Cache.put(filePath, md5Hash);
                    processedFiles.put(filePath, true);
                } catch (IOException e) {
                    // Handle exception
                }
            }
        }
    }

    private String getMd5Hash(URL url) throws IOException {
        byte[] data = Files.readAllBytes(Paths.get(url.getFile()));
        return DigestUtils.md5Hex(data);
    }
}
```
