class ResourceAllocator {
private:
    std::atomic<size_t> seed;
    std::mutex mtx;
    size_t maxMemorySize;
    std::vector<void*> allocatedResources;

public:
    enum class ResourceType {
        // Define your resource types here
    };

    ResourceAllocator(size_t seed, const std::string& configFile) : seed(seed), maxMemorySize(0) {
        loadConfigFromFile(configFile);
    }

    void* allocateResource(ResourceType type, size_t size) {
        if (maxMemorySize > 0 && allocatedResources.size() + size > maxMemorySize) {
            return nullptr; // Out of memory
        }

        std::lock_guard<std::mutex> lock(mtx);
        void* ptr = malloc(size);
        if (ptr != nullptr) {
            allocatedResources.push_back(ptr);
        }
        return ptr;
    }

    void deallocateResource(void* ptr) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = find(allocatedResources.begin(), allocatedResources.end(), ptr);
        if (it != allocatedResources.end()) {
            free(*it);
            allocatedResources.erase(it);
        }
    }

    std::string getMemoryStats() const {
