#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

Record** allocate_records(int count, int min, int max) {
    if (count > max - min + 1 && !unique) {
        fprintf(stderr, "Error: Cannot generate %d unique values in the range [%d, %d]\n", count, min, max);
        return NULL;
    }

    Record** records = malloc(count * sizeof(Record*));
    if (records == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int i;
    for (i = 0; i < count; ++i) {
        records[i] = malloc(sizeof(Record));
        if (records[i] == NULL) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        int value;
        do {
            value = rand() % (max - min + 1) + min;
        } while (unique && contains_value(records, i, value));

        records[i]->value = value;
    }

    return records;
}

int contains_value(Record** records, int count, int value) {
    for (int i = 0; i < count; ++i) {
        if (records[i]->value == value) {
            return 1;
        }
    }

    return 0;
}

void free_records(Record** records, int count) {
    for (int i = 0; i < count; ++i) {
        free(records[i]);
    }

    free(records);
}
