```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/sha.h>

typedef struct {
    int value;
} record;

void processData(int iterations, char* charset, size_t charsetSize, FILE *tempFile) {
    long *offsets = malloc(iterations * sizeof(long));
    if (offsets == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    int *keys = calloc(iterations, sizeof(int));
    if (keys == NULL) {
        free(offsets);
        printf("Memory allocation failed\n");
        return;
    }

    record *records = malloc(iterations * sizeof(record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        printf("Memory allocation failed\n");
        return;
    }

    srand((unsigned int) time(NULL));
    char* buffer = malloc(iterations + 1);
    if (buffer == NULL) {
        free(offsets);
        free(keys);
        free(records);
        printf("Memory allocation failed\n");
        return;
    }

    for (int i = 0; i < iterations; ++i) {
        buffer[i] = charset[rand() % charsetSize];
    }
    buffer[iterations] = '\0';

    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)buffer, strlen(buffer), hash);

    fprintf(tempFile, "%s", buffer);
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        fprintf(tempFile, "%02x", hash[i]);
    }

    free(offsets);
    free(keys);
    free(records);
    free(buffer);
}
```
