NodeList* createNodeList() {
    NodeList* list = malloc(sizeof(NodeList));
    list->nodes = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    sem_init(&list->semaphore, 0, 1);
    return list;
}

void destroyNodeList(NodeList* list) {
    free(list->nodes);
    pthread_mutex_destroy(&list->lock);
    sem_destroy(&list->semaphore);
    free(list);
}

NetworkNode* createNode() {
    NetworkNode* node = NULL;

    pthread_mutex_lock(&poolLock);
    if (memoryPool) {
        node = memoryPool;
        memoryPool = *((void**)memoryPool);
    }
    pthread_mutex_unlock(&poolLock);

    if (!node) {
        node = malloc(sizeof(NetworkNode));
    }

    return node;
}

void destroyNode(NetworkNode* node) {
    pthread_mutex_lock(&poolLock);
    *((void**)node) = memoryPool;
    memoryPool = node;
    pthread_mutex_unlock(&poolLock);
}

int addNodeToList(NodeList* list, NetworkNode* node) {
    sem_wait(&list->semaphore);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->nodes[i]->nodeID == node->nodeID) {
            sem_post(&list->semaphore);
            return -1;  // Node ID already exists
        }
    }

    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity ? list->capacity * 2 : 1;
        NetworkNode** newNodes = realloc(list->nodes, newCapacity * sizeof(NetworkNode*));

        if (!newNodes) {
            pthread_mutex_unlock(&list->lock);
            sem_post(&list->semaphore);
            return -2;  // Memory allocation failed
        }

        list->nodes = newNodes;
        list->capacity = newCapacity;
    }

    list->nodes[list->count++] = node;

    pthread_mutex_unlock(&list->lock);
    sem_post(&list->semaphore);

    return 0;  // Success
}
