['Here's an example of how you might implement this in C, using pthreads for thread safety and logging with syslog. Note that this code does not include all the features requested (like unique random integer generation, maximum number of records enforcement, etc.), but it should give you a good starting point. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <syslog.h>

typedef struct {
    int value;
} Record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int findMax(Record* records, size_t n) {
    if (n == 0) return -1; // error case

    int maxVal = records[0].value;
    for (size_t i = 1; i < n; ++i) {
        if (records[i].value > maxVal) {
            maxVal = records[i].value;
        }
    }

    return maxVal;
}

Record* readRecords(size_t *n, int enforceUniqueness) {
    pthread_mutex_lock(&lock); // lock for thread safety

    openlog("readRecords", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting read operation");

    Record *records = NULL;
    size_t capacity = 0;
    int value;
    while (scanf("%d", &value) == 1) {
        if (*n == capacity) { // need to resize array
            if ((capacity *= 2) == 0) capacity = 4; // start with capacity 4 if no initial size given

            Record* temp = realloc(records, capacity * sizeof(*records));
            if (temp == NULL) {
                syslog(LOG_ERR, "Memory allocation failed");
                pthread_mutex_unlock(&lock); // unlock on error
                return NULL; // return null to indicate failure
            }

            records = temp;
        }

        if (enforceUniqueness) {
            for (size_t i = 0; i < *n; ++i) {
                if (records[i].value == value) {
                    syslog(LOG_WARNING, "Duplicate value detected");
                    continue; // skip duplicates
                }
            }
        }

        records[(*n)++].value = value;
    }

    if (ferror(stdin)) {
        syslog(LOG_ERR, "Error reading from stdin");
        pthread_mutex_unlock(&lock); // unlock on error
        return NULL; // return null to indicate failure
    }

    closelog();
    pthread_mutex_unlock(&lock); // unlock after successful operation
    return records;
}
```
This code reads integers from standard input and stores them in a dynamically allocated array. It uses a mutex for thread safety, and logs operations using syslog. The `findMax` function is optimized to find the maximum value in an array of Records. 

Please note that this is just a basic example and does not include all the features requested such as unique random integer generation, maximum number of records enforcement, etc. You would need to add these features yourself based on your specific requirements. Also, error handling could be improved for production code.
