#include <unistd.h>

typedef struct {
    char **strings;
    size_t *lengths;
    int count;
} StringArray;

StringArray stringPool;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void addString(char *str) {
    pthread_mutex_lock(&mutex);

    if (stringPool.count == MAX_STRINGS) {
        // Reallocate memory for more strings
        stringPool.strings = realloc(stringPool.strings, sizeof(char *) * MAX_STRINGS * 2);
        stringPool.lengths = realloc(stringPool.lengths, sizeof(size_t) * MAX_STRINGS * 2);
    }

    // Add the new string and its length to the pool
    size_t len = strlen(str);
    stringPool.strings[stringPool.count] = malloc(len + 1);
    memcpy(stringPool.strings[stringPool.count], str, len + 1);
    stringPool.lengths[stringPool.count] = len;

    stringPool.count++;

    pthread_mutex_unlock(&mutex);
}

char *getLongestString() {
    size_t maxLen = 0;
    char *longestStr = NULL;

    for (int i = 0; i < stringPool.count; i++) {
        if (stringPool.lengths[i] > maxLen) {
            maxLen = stringPool.lengths[i];
            longestStr = stringPool.strings[i];
        }
    }

    return longestStr;
}

void freeStringPool() {
    for (int i = 0; i < stringPool.count; i++) {
        free(stringPool.strings[i]);
    }

    free(stringPool.strings);
    free(stringPool.lengths);
}
