#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/sha.h>

typedef struct record {
    int value;
    long* offset;
} record;

// Custom pseudo-random number generator
unsigned long xorshf96() {
    static unsigned long x = 123456789, y = 362436069, z = 521288629;
    unsigned long t;
    x ^= x << 16; x ^= x >> 5; x ^= x << 1;
    t = x; x = y; y = z; 
    z = t ^ x ^ y;
    return z;
}

// Custom hash-based solution to detect duplicate keys
unsigned long hash(int key) {
    unsigned long h = 0, high;
    for (size_t i = 0; i < sizeof(key); ++i) {
        h = (h << 4) + ((char*)&key)[i];
        high = h & 0xF0000000L;
        if (high != 0) h ^= high >> 24;
        h &= ~high;
    }
    return h;
}

// Function to compute the SHA-256 hash of a given string parameter
char* sha256(const char *string) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, string, strlen(string));
    SHA256_Final(hash, &sha256);

    char *outputBuffer = (char*)malloc(SHA256_DIGEST_LENGTH*2+1);
    for(int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        sprintf(outputBuffer + (i * 2), "%02x", hash[i]);
    }

    return outputBuffer;
}

// Function to handle dynamic memory allocation, initialization and lifecycle for multiple data structures
void* dataHandler(size_t size) {
    // Allocate memory in smaller chunks when the initial allocation fails
    int chunkSize = 1024 * 1024; // 1MB
    void* ptr = NULL;

    while (ptr == NULL && chunkSize > 0) {
        ptr = malloc(chunkSize);
        if (ptr == NULL) {
            chunkSize -= 1024 * 1024; // decrease the chunk size by 1MB
        }
    }

    if (ptr == NULL) {
        fprintf(stderr, "Out of memory!\n");
        exit(EXIT_FAILURE);
    }

    long* offsets = calloc(size, sizeof(long));
    int* keys = malloc(size * sizeof(int));
    record* records = calloc(size, sizeof(record));

    // Initialize arrays and populate with random numbers
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = xorshf96();
        keys[i] = hash((int)offsets[i]);
        records[i].value = rand() % 1000 + 1; // random number within a specified range
        records[i].offset = &offsets[i];
    }

    // Thread-safe operations for concurrent access to minimize contention and maintain data integrity across threads
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // ... perform operations on the arrays here ...

    pthread_mutex_unlock(&mutex);

    // Free memory upon abnormal termination
    atexit(free, offsets);
    atexit(free, keys);
    atexit(free, records);
}
