public class NetworkConnectionManager {
    private final ConcurrentHashMap<String, ConnectionInfo> connectionMap = new ConcurrentHashMap<>();
    private final AtomicLong totalDataSize = new AtomicLong(0);
    private static final long MAX_DATA_SIZE = 1024 * 1024; // 1MB

    public void processNetworkConnections(List<Connection> connections) {
        for (Connection connection : connections) {
            byte[] data = connection.getData();

            if (totalDataSize.addAndGet(data.length) > MAX_DATA_SIZE) {
                totalDataSize.addAndGet(-data.length); // Undo the addition
                System.err.println("Maximum data size limit exceeded!");
                continue;
            }

            ConnectionInfo info = connectionMap.get(connection.getLabel());

            if (info == null) {
                info = new ConnectionInfo();
                ConnectionInfo existing = connectionMap.putIfAbsent(connection.getLabel(), info);

                if (existing != null) { // Someone else beat us to it
                    info = existing;
                }
            }

            processDataAsync(info, data);
        }
    }

