    atomic_int count;
    pthread_mutex_t lock;
    record **records;
    int *keys;
    int maxRecords;
} RecordManager;

RecordManager* createRecordManager(int maxRecords) {
    RecordManager *manager = malloc(sizeof(RecordManager));
    if (manager == NULL) return NULL;

    manager->records = calloc(maxRecords, sizeof(record*));
    if (manager->records == NULL) {
        free(manager);
        return NULL;
    }

    manager->keys = malloc(sizeof(int) * maxRecords);
    if (manager->keys == NULL) {
        free(manager->records);
        free(manager);
        return NULL;
    }

    atomic_init(&manager->count, 0);
    pthread_mutex_init(&manager->lock, NULL);
    manager->maxRecords = maxRecords;

    return manager;
}

int addRecord(RecordManager *manager, int key, record *rec) {
    if (atomic_load(&manager->count) >= manager->maxRecords) {
        // Handle error: maximum records reached.
        return -1;
    }

    pthread_mutex_lock(&manager->lock);
    int index = atomic_fetch_add(&manager->count, 1);
    manager->records[index] = rec;
    manager->keys[index] = key;
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success.
}
```
