#include <netdb.h>
#include <time.h>

// Function to resolve DNS
int resolveDNS(char *hostname, u_char ip[INET6_ADDRSTRLEN]) {
    struct addrinfo hints, *res;
    int errcode;
    char addrstr[INET6_ADDRSTRLEN];
    void *ptr;

    memset (&hints, 0, sizeof (hints));
    hints.ai_family = PF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags |= AI_CANONNAME;

    errcode = getaddrinfo (hostname, NULL, &hints, &res);
    if (errcode != 0) {
        perror ("Error in resolving DNS");
        return -1;
    }

    while (res) {
        inet_ntop (res->ai_family, res->ai_addr->sa_data, addrstr, sizeof (addrstr));

        switch (res->ai_family) {
            case AF_INET:
                ptr = &((struct sockaddr_in *) res->ai_addr)->sin_addr;
                inet_ntop (res->ai_family, ptr, ip, sizeof(ip));
                break;
        } 

        res = res->ai_next;
    }

    freeaddrinfo(res);

    return 0;
}

// Function to read lines from a file and compute average of last two fields
double processFile(char *filename) {
    FILE *file = fopen (filename, "r");
    if (file == NULL) {
        perror ("Error opening file");
        return -1;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    double sum = 0.0, count = 0.0;

    while ((read = getline(&line, &len, file)) != -1) {
        char *token, *saveptr;
        for (int i = 0; i < 2; ++i) {
            token = strtok_r(line, " ", &saveptr);
            if (i == 3) sum += atof(token);
        }
        ++count;
    }

    free(line);
    fclose(file);

    return count ? sum / count : 0.0;
}

// Function to limit process capabilities
void limitProcessCapabilities() {
    struct rlimit lim;
    getrlimit(RLIMIT_NPROC, &lim);
    lim.rlim_cur = 10; // Set the limit here
    setrlimit(RLIMIT_NPROC, &lim);
}

int main() {
    u_char ip[INET6_ADDRSTRLEN];
    resolveDNS("www.google.com", ip);

    double avg = processFile("input.txt");

    limitProcessCapabilities();

    return 0;
}
```
