["Here is an example of how you might implement this using C programming language with POSIX threads for thread safety and a simple LRU cache for caching layer. This code does not include all the details such as reading from different types of files, handling concurrent access by multiple threads, or implementing a full-fledged caching system due to its complexity.

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    long timestamp;
    int key;
    double value;
} Record;

typedef struct Node {
    Record *record;
    struct Node *next, *prev;
} Node;

Node *head = NULL, *tail = NULL;
pthread_mutex_t lock;
int cacheSize = 100; // Adjust this value according to your needs.

void addToCache(Record *record) {
    pthread_mutex_lock(&lock);

    Node *node = (Node*) malloc(sizeof(Node));
    node->record = record;
    node->next = head;
    node->prev = NULL;

    if (head != NULL) {
        head->prev = node;
    }

    head = node;

    if (tail == NULL) {
        tail = head;
    }

    // If cache is full, remove the least recently used item.
    if(cacheSize > 0){
        Node *temp = head;

        while(temp->next != NULL){
            temp = temp->next;
        }

        tail = temp->prev;
        tail->next = NULL;
        free(temp);
    }

    pthread_mutex_unlock(&lock);
}

Record *getFromCache(int key) {
    pthread_mutex_lock(&lock);

    Node *temp = head;
    Record *record = NULL;

    while (temp != NULL) {
        if (temp->record->key == key) {
            record = temp->record;

            // Move the node to the front of the list.
            if(temp != head){
                if(temp == tail){
                    tail = tail->prev;
                }else{
                    temp->next->prev = temp->prev;
                }

                temp->prev->next = temp->next;

                temp->next = head;
                temp->prev = NULL;
                head = temp;
            }

            break;
        }

        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);

    return record;
}
```
This is a simple implementation of an LRU cache. It uses a doubly linked list to keep track of the order in which items were accessed, and a mutex lock for thread safety. When a new item is added to the cache, it's added to the front of the list. If the cache becomes full, the least recently used item (the one at the end of the list) is removed.

Please note that this code does not include error checking or handling for simplicity. In a real-world application, you would want to add checks and balances to ensure your program behaves correctly in all situations. Also, this code assumes that the records are being read from files and added to the cache as they're read. If you need to handle reading from different file types, you will need to implement additional logic for parsing those files and creating Record objects.
"]

["Here is a simplified version of how you might implement this in C. This code does not include all the details mentioned in your request, but it should give you an idea of what such a function could look like. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
} Item;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    Item* items;
} HashTable;

HashTable* create_hash_table(size_t initialCapacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    pthread_mutex_init(&table->lock, NULL);
    table->capacity = initialCapacity;
    table->count = 0;
    table->items = calloc(initialCapacity, sizeof(Item));
    if (table->items == NULL) {
        free(table);
        return NULL;
    }

    return table;
}

void destroy_hash_table(HashTable* table) {
    pthread_mutex_destroy(&table->lock);
    free(table->items);
    free(table);
}

int insert_item(HashTable* table, int key, Record record) {
    if (table == NULL || table->count >= table->capacity) return -1;

    pthread_mutex_lock(&table->lock);

    size_t index = key % table->capacity;
    while (table->items[index].key != 0) {
        if (++index >= table->capacity) index = 0;
    }

    table->items[index].key = key;
    table->items[index].record = record;
    table->count++;

    pthread_mutex_unlock(&table->lock);

    return 0;
}

Record* lookup_item(HashTable* table, int key) {
    if (table == NULL || table->count == 0) return NULL;

    pthread_mutex_lock(&table->lock);

    size_t index = key % table->capacity;
    while (table->items[index].key != key && table->items[index].key != 0) {
        if (++index >= table->capacity) index = 0;
    }

    Record* record = NULL;
    if (table->items[index].key == key) {
        record = &table->items[index].record;
    }

    pthread_mutex_unlock(&table->lock);

    return record;
}
```
