['This task requires a lot of code and setup which is beyond the scope of this platform. However, I can provide you with an example of how you might structure your application using Node.js, Express, MongoDB and Redis for locking mechanism. 

```javascript
const express = require('express');
const mongoose = require('mongoose');
const redis = require('redis');
const bodyParser = require('body-parser');
const rateLimit = require("express-rate-limit");

// Connect to MongoDB
mongoose.connect('mongodb://localhost/test', {useNewUrlParser: true, useUnifiedTopology: true});

// Connect to Redis
const client = redis.createClient();
client.on('error', function(err) {
  console.log('Redis error: ' + err);
});

const app = express();
app.use(bodyParser.json());

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Define a schema and model for your data
const Schema = mongoose.Schema;
const ResourceSchema = new Schema({
  id: String,
  data: Object
});
const ResourceModel = mongoose.model('Resource', ResourceSchema );

app.put('/resource/:id', async (req, res) => {
  const resourceId = req.params.id;

  // Acquire a lock for the resource
  const lockKey = `lock:${resourceId}`;
  const locked = await acquireLock(client, lockKey);
  if (!locked) {
    return res.status(503).send('Service Unavailable');
  }

  try {
    // Validate the request body
    if (!req.body || !req.body.data) {
      return res.status(400).send('Bad Request');
    }

    // Update the resource in MongoDB
    const updatedResource = await ResourceModel.findOneAndUpdate({id: resourceId}, req.body, {new: true});

    if (!updatedResource) {
      return res.status(404).send('Not Found');
    }

    // Release the lock
    client.del(lockKey);

    res.json(updatedResource);
  } catch (err) {
    console.error(err);
    res.status(500).send('Internal Server Error');
  }
});

async function acquireLock(client, lockKey) {
  return new Promise((resolve, reject) => {
    client.setnx(lockKey, '1', (err, reply) => {
      if (err) {
        console.error('Failed to acquire lock: ', err);
        resolve(false);
      } else {
        client.expire(lockKey, 60 * 5); // Lock expires after 5 minutes
        resolve(true);
      }
    });
  });
}

app.listen(3000, () => console.log('Server running on port 3000'));
```
This is a basic example and doesn't include all the features you requested such as logging, error handling, validation etc. Also, it uses MongoDB for data storage which might not be the best choice if your access patterns are more relational or complex than document-based. 

For production level code, consider using a mature framework like NestJS and TypeORM for better structure and robustness. For logging, use Winston or Bunyan libraries. For validation, you can use Joi library. For handling rate limiting, use express-rate-limit middleware. For backpressure handling, consider using techniques such as circuit breakers.
