```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    char* buffer;
    int value;
} Record;

typedef struct Node {
    long offset;
    int key;
    Record record;
    struct Node* next;
} Node;

Node* head = NULL;
int cacheSize = 1000; // Adjust this based on your system's memory capacity and usage patterns.
Node** cache = NULL;

void initCache() {
    cache = (Node**)malloc(cacheSize * sizeof(Node*));
    for (int i = 0; i < cacheSize; ++i) {
        cache[i] = NULL;
    }
}

unsigned long hash(int key) {
    return key % cacheSize; // Simple hashing function. Replace with a more sophisticated one if needed.
}

Node* findInCache(int key) {
    unsigned long index = hash(key);
    Node* node = cache[index];
    while (node != NULL && node->key != key) {
        node = node->next;
    }
    return node;
}

void insertIntoCache(Node* node) {
    unsigned long index = hash(node->key);
    node->next = cache[index];
    cache[index] = node;
}

void addRecordToList(int key, Record record) {
    Node* cachedNode = findInCache(key);
    if (cachedNode != NULL) { // Update existing entry.
        free(cachedNode->record.buffer);
        cachedNode->record = record;
        return;
    }

    Node* node = (Node*)malloc(sizeof(Node));
    node->key = key;
    node->record = record; // Assuming that the record's buffer is dynamically allocated.
    node->next = head;
    head = node;

    insertIntoCache(node);
}

void freeList() {
    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp->record.buffer);
        free(temp);
    }
    head = NULL;
}

void freeCache() {
    for (int i = 0; i < cacheSize; ++i) {
        Node* node = cache[i];
        while (node != NULL) {
            Node* temp = node;
            node = node->next;
