```java
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;

public class FileProcessor {
    private final ExecutorService executor;
    private final Map<String, String> cache = new ConcurrentHashMap<>();

    public FileProcessor(int threadPoolSize) {
        this.executor = Executors.newFixedThreadPool(threadPoolSize);
    }

    public Map<String, Future<String>> processFiles(List<Path> filePaths) {
        Map<String, Future<String>> futures = new HashMap<>();

        for (Path path : filePaths) {
            if (!cache.containsKey(path)) {
                FutureTask<String> task = new FutureTask<>(() -> computeMD5Hash(path));
                executor.execute(task);
                futures.put(path, task);
            }
        }

        return futures;
    }

    private String computeMD5Hash(Path path) {
        try (InputStream is = Files.newInputStream(path)) {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[8192];
            int bytesRead;

            while ((bytesRead = is.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }

            String hash = toHexString(md.digest());
            cache.putIfAbsent(path.toString(), hash);
            return hash;
        } catch (IOException | NoSuchFileException e) {
            // Handle exception
        } catch (NoSuchAlgorithmException e) {
            // This should never happen
        }

        return null;
    }

    private String toHexString(byte[] bytes) {
        Formatter formatter = new Formatter();

        for (byte b : bytes) {
            formatter.format("%02x", b);
        }

        return formatter.toString();
    }
}
```
This code creates a thread pool and uses it to process files concurrently. It also includes a simple cache to avoid recomputing hashes for the same file. The `computeMD5Hash` method computes the MD5 hash of a file, handling exceptions as necessary. 

