    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    char*** strings;
    pthread_mutex_t mutex;
} DataStructures;

DataStructures* init(int n, int m) {
    srand(time(NULL));

    DataStructures* ds = (DataStructures*)malloc(sizeof(DataStructures));
    if (!ds) return NULL;

    ds->offsets = (long*)calloc(n, sizeof(long));
    ds->keys = (int*)calloc(n, sizeof(int));
    ds->records = (Record**)malloc(sizeof(Record*) * n);
    if (!ds->records) return NULL;

    for (int i = 0; i < n; ++i) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) return NULL;

        record->value = rand() % 100 + 1; // random value between 1 and 100
        ds->records[i] = record;
    }

    ds->strings = (char***)malloc(sizeof(char**) * n);
    if (!ds->strings) return NULL;

    for (int i = 0; i < n; ++i) {
        ds->strings[i] = (char**)malloc(sizeof(char*) * m);
        if (!ds->strings[i]) return NULL;

        for (int j = 0; j < m; ++j) {
            ds->strings[i][j] = (char*)calloc(10, sizeof(char)); // 10 character strings
            if (!ds->strings[i][j]) return NULL;

            sprintf(ds->strings[i][j], "String %d", j);
        }
    }

    pthread_mutex_init(&ds->mutex, NULL);

    return ds;
}

void updateRecords(DataStructures* ds, int n, int m) {
    for (int i = 0; i < n; ++i) {
        pthread_mutex_lock(&ds->mutex);

        // Update record value based on formula
        ds->records[i]->value = ds->records[i]->value * i + strlen(ds->strings[i][m - 1]);

        pthread_mutex_unlock(&ds->mutex);
    }
}

void destroy(DataStructures* ds, int n, int m) {
    for (int i = 0; i < n; ++i) {
        free(ds->records[i]);

        for (int j = 0; j < m; ++j) {
            free(ds->strings[i][j]);
        }

        free(ds->strings[i]);
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds->strings);
    pthread_mutex_destroy(&ds->mutex);
    free(ds);
}
```
This code initializes the data structures and updates the records based on a formula. It uses mutexes to ensure thread safety. The `init` function allocates memory for all arrays, while the `updateRecords` function updates the record values. Finally, the `destroy` function frees all allocated memory.

