    while (collection->keys[hashedKey] != 0 && collection->records[hashedKey]->value != rec->value) {
        hashedKey = (hashedKey + 1) % collection->capacity; // Linear probing for collision resolution.
    }

    if (collection->keys[hashedKey] == 0) {
