function manageUserAccounts($request) {
    $response = [
        'status' => '',
        'message' => '',
        'data' => []
    ];

    // Validate request data
    if (!isset($request['name']) || !preg_match("/^[a-zA-Z ]*$/", $request['name'])) {
        $response['status'] = 'error';
        $response['message'] = 'Invalid name. Only alphabets and spaces are allowed.';
        return json_encode($response);
    }

    if (!isset($request['email']) || !filter_var($request['email'], FILTER_VALIDATE_EMAIL)) {
        $response['status'] = 'error';
        $response['message'] = 'Invalid email. Please provide a valid email address.';
        return json_encode($response);
    }

    if (!isset($request['password']) || strlen($request['password']) < 8) {
        $response['status'] = 'error';
        $response['message'] = 'Invalid password. Password must be at least 8 characters long.';
        return json_encode($response);
    }

    // Verify device credentials using third-party authentication service
    $deviceVerified = verifyDeviceCredentials();
    if (!$deviceVerified) {
        $response['status'] = 'error';
        $response['message'] = 'Unauthorized device. Please confirm your device to proceed.';
        return json_encode($response);
    }

    // Handle user requests based on sub-action
    $subAction = $request['sub_action'];
    switch ($subAction) {
        case 'create':
            createUserAccount();
            break;
        case 'update':
            updateUserAccount();
            break;
        case 'delete':
            deleteUserAccount();
            break;
        default:
            retrieveUserData();
    }

    $response['status'] = 'success';
    $response['message'] = 'Successfully processed the request.';
    $response['data'] = getUserData($request['id']);

    return json_encode($response);
}
