// JavaScript
import React, { useEffect, useState } from 'react';

function processAndTransformData(dataItems, filters, transformations) {
  const [processedData, setProcessedData] = useState({});

  useEffect(() => {
    let transformedData = dataItems;

    for (let filter of filters) {
      transformedData = transformedData.filter(filter);
    }

    for (let transform of transformations) {
      transformedData = transformedData.map(transform);
    }

    setProcessedData(transformedData);
  }, [dataItems, filters, transformations]);

  useEffect(() => {
    parent.postMessage({ data: processedData }, '*');
  }, [processedData]);
}
