```javascript
const EventEmitter = require('events');
const axios = require('axios');

class DataService extends EventEmitter {
    constructor(maxBatchSize, monitorUrl) {
        super();
        this.buffer = [];
        this.isPaused = false;
        this.maxBatchSize = maxBatchSize;
        this.monitorUrl = monitorUrl;
    }

    collectData(data) {
        if (this.isPaused || this.buffer.length >= this.maxBatchSize) {
            return Promise.resolve();
        }

        this.buffer.push(data);

        if (this.buffer.length === this.maxBatchSize) {
            return this.processData().then(() => this.pause());
        }
    }

    processData() {
        // Simulate data processing with a delay
        return new Promise(resolve => setTimeout(() => resolve(), 100));
    }

    pause() {
        this.isPaused = true;
    }

    resume() {
        this.isPaused = false;
    }

    startService(interval) {
        this.serviceIntervalId = setInterval(() => {
            if (this.buffer.length > 0) {
                this.processData().then(() => {
                    this.buffer = [];
                    axios.post(this.monitorUrl, { status: 'Service running' })
                        .catch(err => console.error('Error sending monitoring update', err));
                });
            } else {
                axios.post(this.monitorUrl, { status: 'Idle' })
                    .catch(err => console.error('Error sending monitoring update', err));
            }
        }, interval);
    }

    stopService() {
        clearInterval(this.serviceIntervalId);
        axios.post(this.monitorUrl, { status: 'Service stopped' })
            .catch(err => console.error('Error sending monitoring update', err));
    }
}
```

