```javascript
const { Transform } = require('stream');
const async = require('async');

class DataMerger extends Transform {
    constructor(options) {
        super(options);
        this._buffer = [];
        this._maxBufferSize = 1024; // default buffer size
    }

    _transform(chunk, encoding, callback) {
        if (this._buffer.length >= this._maxBufferSize) {
            return callback(new Error('Buffer overflow'));
        }

        this._buffer.push(chunk);
        callback();
    }

    _flush(callback) {
        async.eachSeries(this._buffer, (task, cb) => {
            // process each chunk asynchronously
            setImmediate(() => {
                this.push(task);
                cb();
            });
        }, err => callback(err));
    }
}
```
