const { exec } = require('child_process');
const fs = require('fs').promises;
const path = require('path');

async function compileCFunction(filename, sequence, fileType) {
  const cCode = `
    #include <stdio.h>
    void modifyExtension(char *filename) {
      char newFilename[256];
      sprintf(newFilename, "%s%d.%s", filename, ${sequence}, "${fileType}");
      rename(filename, newFilename);
    }
  `;

  const cFilePath = path.join(__dirname, 'temp.c');
  await fs.writeFile(cFilePath, cCode);

  return new Promise((resolve, reject) => {
    exec(`gcc -shared -fPIC -o libmodifyExtension.so ${cFilePath}`, (error) => {
      if (error) {
        console.log(`Compilation failed with error: ${error}`);
        reject(error);
      } else {
        console.log('Compilation succeeded');
        resolve();
      }
    });
  });
}

async function loadAndExecuteCFunction(filename, sequence, fileType) {
  try {
    await compileCFunction(filename, sequence, fileType);

    const libPath = path.join(__dirname, 'libmodifyExtension.so');
    const soFile = require(libPath);
    soFile.modifyExtension(filename);
  } catch (error) {
    console.log('Error occurred:', error);
  } finally {
    // Clean up the temporary C file
    await fs.unlink(path.join(__dirname, 'temp.c'));
  }
}
