["Here is a basic implementation of a hash table with open addressing for collision resolution using C. This does not include all the features you mentioned like logging, thread safety, integration with other services etc. It's just a starting point and can be extended according to your needs. 

```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
} Item;

typedef struct {
    size_t size;
    Item *items;
} HashTable;

HashTable* create_table(size_t size) {
    HashTable *ht = malloc(sizeof(HashTable));
    ht->size = size;
    ht->items = calloc(ht->size, sizeof(Item));
    return ht;
}

void free_table(HashTable *ht) {
    free(ht->items);
    free(ht);
}

int hash(int key, size_t size) {
    return key % size;
}

Item* create_item(long offset, int key, Record record) {
    Item *item = malloc(sizeof(Item));
    item->offset = offset;
    item->key = key;
    item->record = record;
    return item;
}

void insert_item(HashTable *ht, long offset, int key, Record record) {
    Item *item = create_item(offset, key, record);
    int index = hash(key, ht->size);

    while (ht->items[index].record.value != 0) {
        if (ht->items[index].key == key) {
            free(item);
            return;
        }

        index = (index + 1) % ht->size;
    }

    ht->items[index] = *item;
    free(item);
}

Record* lookup_item(HashTable *ht, int key) {
    int index = hash(key, ht->size);

    while (ht->items[index].record.value != 0) {
        if (ht->items[index].key == key) {
            return &(ht->items[index].record);
        }

        index = (index + 1) % ht->size;
    }

    return NULL;
}
```
This code creates a hash table with open addressing for collision resolution. It uses the modulo operation to calculate the hash of a key, and if there is a collision it moves to the next index until an empty slot is found. The insert_item function checks if the key already exists before inserting to avoid duplicates. The lookup_item function returns NULL if the item is not found.
"]

