#include <vector>
#include <memory>
#include <mutex>

struct Point {
    float x, y, z;
};

class OctreeNode {
public:
    std::unique_ptr<OctreeNode> children[8];
    bool isLeaf = true;
    std::vector<Point> points;
    std::mutex mtx;

    void insert(const Point& p) {
        if (isLeaf && points.size() < 100) { // max leaf size
            points.push_back(p);
        } else {
            if (!children[0]) {
                for (int i = 0; i < 8; ++i) {
                    children[i] = std::make_unique<OctreeNode>();
                }
            }
            isLeaf = false;
            int idx = ((p.x > 0 ? 1 : 0) << 2) | ((p.y > 0 ? 1 : 0) << 1) | (p.z > 0 ? 1 : 0);
            std::lock_guard<std::mutex> lock(children[idx]->mtx);
            children[idx]->insert(p);
        }
    }
};
```
