['Here is a simplified version of how you might implement this in C++ using std::mutex for thread safety, std::ofstream for logging, and std::chrono for timing. This code does not include the shared resource manager or the actual attack logic as those would be complex to implement without knowing more about your game's specific requirements.

```cpp
#include <fstream>
#include <vector>
#include <mutex>
#include <chrono>
#include <random>

struct Attack {
    std::string name;
    int cooldown;
    std::chrono::steady_clock::time_point lastUsedTime;
};

std::vector<Attack> attacks = {{"Rest", 0, std::chrono::steady_clock::now()}, {"Attack1", 5, std::chrono::steady_clock::now()}, {"Attack2", 7, std::chrono::steady_clock::now()}, {"Attack3", 9, std::chrono::steady_clock::now()}, {"Attack4", 15, std::chrono::steady_clock::now()}};
std::mutex mtx;
int totalAttacks = 0;

void selectAndPerformAttack(float& energyLevel) {
    static std::default_random_engine generator(std::chrono::system_clock::now().time_since_epoch().count());
    static std::uniform_real_distribution<double> distribution(0.1, 0.3);

    mtx.lock();
    if (totalAttacks >= 10) {
        // Wait until the next minute and reset attack count
        auto now = std::chrono::steady_clock::now();
        auto waitTime = 60 - ((now - attacks[0].lastUsedTime).count() % 60);
        std::this_thread::sleep_for(std::chrono::seconds(waitTime));
        totalAttacks = 1; // The current attack is not counted in the new minute
    } else {
        ++totalAttacks;
    }
    mtx.unlock();

    std::string selectedAttackName = "Rest";
    if (energyLevel < 20) {
        selectedAttackName = "Rest";
    } else {
        // Select a random attack that is not on cooldown and has enough energy to use
        std::uniform_int_distribution<int> attackDistribution(1, 4);
        do {
            int attackIndex = attackDistribution(generator);
            if (attacks[attackIndex].lastUsedTime + std::chrono::seconds(attacks[attackIndex].cooldown) <= std::chrono::steady_clock::now()) {
                selectedAttackName = attacks[attackIndex].name;
            }
        } while (selectedAttackName == "Rest");
    }

    // Perform the attack and update energy level
    if (selectedAttackName != "Rest") {
        float decreaseAmount = distribution(generator) * (energyLevel < 90 ? 1 : 0.5);
        energyLevel -= decreaseAmount;
    } else {
        energyLevel = 80;
    }

    // Update the last used time of the selected attack and log it
    std::ofstream logFile("combat_log.txt", std::ios_base::app);
    mtx.lock();
    for (auto& attack : attacks) {
        if (attack.name == selectedAttackName) {
            attack.lastUsedTime = std::chrono::steady_clock::now();
            logFile << "Performed " << selectedAttackName << ", cooldown: " << attack.cooldown << ", energy level: " << energyLevel << "\n";
        }
    }
    mtx.unlock();
}
```
This code is a simplified version and does not include the shared resource manager or the actual attack logic as those would be complex to implement without knowing more about your game's specific requirements. Also, it doesn't handle the case where energy level drops below zero after an attack. You should add appropriate error handling and edge cases according to your needs.
']

["Here is an example of how you might implement such a function in JavaScript using async/await syntax for asynchronous operations, along with some basic error handling and retry logic. This code does not include all the features mentioned in your request (like caching, rate limiting, logging configuration etc.), but it should give you a good starting point:

```javascript
const axios = require('axios'); // for external API calls
const { promisify } = require('util'); // for converting callbacks to promises
const redisClient = require('redis').createClient(); // for caching

// Convert the redis get and set methods to use promises
const getAsync = promisify(redisClient.get).bind(redisClient);
const setAsync = promisify(redisClient.set).bind(redisClient);

async function processTransactions(transactions, filterFn, config) {
  let processedTransactions = [];

  for (let transaction of transactions) {
    try {
      // Apply the customizable filter function
      if (!filterFn(transaction)) continue;

      // Check if we have this transaction in cache
      const cachedTransaction = await getAsync(`txn:${transaction.id}`);
      if (cachedTransaction) {
        processedTransactions.push(JSON.parse(cachedTransaction));
        continue;
      }

      // Validate the transaction with an external API
      const response = await axios.post('https://api.example.com/validate', transaction);

      if (response.status !== 200) {
        throw new Error(`Failed to validate transaction: ${transaction}`);
      }

      // Process the transaction...
      const processedTransaction = await processTransaction(transaction, config);

      // Cache the processed transaction
      await setAsync(`txn:${transaction.id}`, JSON.stringify(processedTransaction));

      processedTransactions.push(processedTransaction);
    } catch (error) {
      console.error(`Error processing transaction ${transaction}: ${error.message}`);
    }
  }

  return processedTransactions;
}

async function processTransaction(transaction, config) {
  // Process the transaction...
  let retries = 0;
  while (retries < MAX_RETRIES) {
    try {
      const response = await axios.post('https://api.example.com/process', transaction);

      if (response.status !== 200) {
        throw new Error(`Failed to process transaction: ${transaction}`);
      }

      return response.data;
    } catch (error) {
      console.warn(`Error processing transaction, retrying...`);
      await sleep(Math.pow(2, retries++) * 1000); // exponential backoff
    }
  }

  throw new Error(`Failed to process transaction after ${MAX_RETRIES} attempts: ${transaction}`);
