```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long* offset;
    int key;
} record;

record** create_records(long* offsets, int* keys, size_t count) {
    srand((unsigned int) time(NULL)); // Seed the random number generator

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Initialize a mutex for thread safety

    record** records = (record**) calloc(count, sizeof(record*)); // Allocate memory for the array of pointers to records
    if (!records) {
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        record* rec = (record*) malloc(sizeof(record)); // Allocate memory for each record
        if (!rec) {
            free(records);
            return NULL;
        }

        pthread_mutex_lock(&lock); // Lock the mutex before modifying shared data
        rec->offset = &offsets[i]; // Assign the offset value from the pre-existing array
        rec->key = rand() % 10 + 1; // Generate a random key within the specified range
        pthread_mutex_unlock(&lock); // Unlock the mutex after modifying shared data

        records[i] = rec; // Assign the record to its position in the array of pointers
    }

    return records;
}
```
This code creates a dynamic collection of 'record' structures from two pre-existing arrays: one containing 'long' offsets and the other 'int' keys. It uses a mutex for thread safety, ensuring that only one thread can modify shared data at a time to prevent race conditions. The random number generator is seeded with the current time to ensure consistent results across multiple invocations but varies between different runs of the program.

Please note that this code does not include any strategies for handling external data source changes or backward compatibility with legacy code, as these are complex topics that would require more detailed understanding of the existing application framework and its requirements.
