int validateSession(const char* jsonPayload, CURL *curl) {
    json_error_t error;
    json_t *root = json_loads(jsonPayload, 0, &error);

    if(!root) {
        fprintf(stderr, "Error: on line %d: %s\n", error.line, error.text);
        return -1;
    }

    json_t *session_id = json_object_get(root, "session_id");
    json_t *user_id = json_object_get(root, "user_id");
