public class DecryptionService
{
    private readonly byte[] key;
    private readonly byte[] iv;

    public DecryptionService(byte[] key, byte[] iv)
    {
        this.key = key;
        this.iv = iv;
    }

    public (string decryptedMessage, string hmacValue) ProcessAndDecrypt(string base64EncodedData, string hmacKey)
    {
        try
        {
            byte[] encryptedBytes = Convert.FromBase64String(base64EncodedData);

            using var tripleDes = TripleDES.Create();
            tripleDes.Mode = CipherMode.CBC;
            tripleDes.Padding = PaddingMode.PKCS7;
            tripleDes.KeySize = key.Length * 8; // Convert from bytes to bits

            using var decryptor = tripleDes.CreateDecryptor(key, iv);
            using var memoryStream = new MemoryStream();
            using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Write))
            {
                cryptoStream.Write(encryptedBytes, 0, encryptedBytes.Length);
            }

            byte[] decryptedBytes = memoryStream.ToArray();
            string decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);

            using var hmacsha256 = new HMACSHA256(Encoding.UTF8.GetBytes(hmacKey));
            byte[] hashValue = hmacsha256.ComputeHash(decryptedBytes);
            string hmacValue = BitConverter.ToString(hashValue).Replace("-", "");

            return (decryptedMessage, hmacValue);
        }
        catch (Exception ex)
        {
            // Handle exceptions appropriately for your use case
            Console.WriteLine($"Error processing and decrypting data: {ex}");
            throw;
        }
    }
}
```
