```c
#include <stdlib.h>
#include <pthread.h>
#include <omp.h>

typedef struct {
    int key;
    int value;
} Record;

typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

Node **hashTable;
int tableSize = 10007; // Prime number for better distribution
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
long *offsets;
int *keys;
Record **records;
int recordCount = 0;

void insert(Record* record) {
    pthread_mutex_lock(&lock);
    int index = abs(record->key % tableSize);
    Node *node = malloc(sizeof(Node));
    node->record = record;
    node->next = hashTable[index];
    hashTable[index] = node;
    pthread_mutex_unlock(&lock);
}

Record* get(int key) {
    int index = abs(key % tableSize);
    Node *node = hashTable[index];
    while (node != NULL) {
        if (node->record->key == key) {
            return node->record;
        }
        node = node->next;
    }
    return NULL;
}

void initHashTable() {
    hashTable = malloc(sizeof(Node*) * tableSize);
    for (int i = 0; i < tableSize; i++) {
        hashTable[i] = NULL;
    }
}

void initArrays(int maxRecords) {
    offsets = calloc(maxRecords, sizeof(long));
    keys = malloc(sizeof(int) * maxRecords);
    records = malloc(sizeof(Record*) * maxRecords);
}

void addRecord(int key, int value) {
    Record* record = malloc(sizeof(Record));
    record->key = key;
    record->value = value;
    records[recordCount] = record;
    keys[recordCount] = key;
    offsets[recordCount] = (long)record;
    insert(record);
    recordCount++;
}
```
