    char* key;
    AudioStream* value;
    struct CacheEntry* next;
} CacheEntry;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
CacheEntry* cache[1024]; // Simple hash table for caching

void addToCache(char* key, AudioStream* value) {
    pthread_mutex_lock(&lock);
    unsigned long index = djb2Hash(key) % 1024;
    CacheEntry* entry = malloc(sizeof(CacheEntry));
    if (entry == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&lock);
        return;
    }
    entry->key = key;
    entry->value = value;
    entry->next = cache[index];
    cache[index] = entry;
    pthread_mutex_unlock(&lock);
}

AudioStream* getFromCache(char* key) {
    unsigned long index = djb2Hash(key) % 1024;
    CacheEntry* current = cache[index];
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            return current->value;
        }
        current = current->next;
    }
    return NULL; // Not found in cache
}

unsigned long djb2Hash(char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash;
}
