public class UserActivitySummaryService
{
    private readonly ConcurrentDictionary<string, ConcurrentDictionary<DateTime, int>> _userActivities = new();
    private readonly object _lockObject = new();

    public async Task ProcessLogFileAsync(string filePath)
    {
        using var reader = new StreamReader(filePath);

        while (!reader.EndOfStream)
        {
            var line = await reader.ReadLineAsync().ConfigureAwait(false);

            if (line == null) continue;

            var parts = line.Split(' '); // Assuming the format is "timestamp userId eventType"

            if (!DateTime.TryParse(parts[0], out var timestamp)) 
                throw new FormatException("Invalid timestamp");

            var userId = parts[1];
            var eventType = parts[2];

            lock (_lockObject) // Lock to ensure thread safety while updating the dictionary
            {
                if (!_userActivities.TryGetValue(userId, out var activities))
                {
                    activities = new ConcurrentDictionary<DateTime, int>();
                    _userActivities[userId] = activities;
                }

                // Increment the count for this user and timestamp
                activities.AddOrUpdate(timestamp.Date, 1, (_, count) => count + 1);
            }
        }
    }

    public async Task SaveSummariesAsync()
    {
        foreach (var userActivities in _userActivities)
        {
            var userId = userActivities.Key;

            foreach (var activity in userActivities.Value)
            {
                var date = activity.Key;
                var count = activity.Value;

                // Save the summary to your database here
                await YourDatabaseApi.SaveUserActivityAsync(userId, date, count).ConfigureAwait(false);
            }
        }
    }
}
