async function executeCommand(command) {
    try {
        const response = await axios.get('/api/config'); // Replace with your API endpoint
        const config = response.data;

        if (config && config[command]) {
            const cmd = config[command];

            logger.info(`Executing command: ${cmd}`);

            const childProcess = exec(cmd, (error, stdout, stderr) => {
                if (error) {
                    logger.error(`Error executing command: ${error.message}`);
                    return;
                }

                if (stderr) {
                    logger.warn(`Command output: ${stderr}`);
                } else {
                    wss.clients.forEach((client) => {
                        if (client.readyState === WebSocket.OPEN) {
                            client.send(stdout);
                        }
                    });

                    logger.info('Command executed successfully');
                }
            });

            childProcess.on('error', (error) => {
                logger.error(`Error executing command: ${error.message}`);
            });
        } else {
            logger.warn('No configuration found for the command');
        }
    } catch (error) {
        logger.error(`Failed to fetch configuration: ${error.message}`);
    }
}

// Schedule commands execution with rate limiting
setInterval(() => {
    limiter.schedule(() => executeCommand('command1')); // Replace 'command1' with your command
}, 5000); // Adjust the interval as needed
