#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <resolv.h>

typedef struct record {
    long *offset;
    int key;
} Record;

Record* records = NULL;
int num_records = 0;
pthread_mutex_t lock;

void init(long offsets[], int keys[], int size) {
    srand((unsigned int)time(NULL));

    pthread_mutex_init(&lock, NULL);

    num_records = size;
    records = (Record*)malloc(sizeof(Record)*num_records);

    for(int i=0; i<num_records; ++i) {
        pthread_mutex_lock(&lock);

        records[i].offset = malloc(sizeof(long));
        *(records[i].offset) = offsets[i];
        records[i].key = keys[i];

        pthread_mutex_unlock(&lock);
    }
}

void destroy() {
    for(int i=0; i<num_records; ++i) {
        free(records[i].offset);
    }

    free(records);
    pthread_mutex_destroy(&lock);
}

u_char* resolve_hostname(const char *hostname) {
    static u_char ip[16]; // IPv4-mapped IPv6 address is 16 bytes long.

    struct __res_state res;
    if (res_ninit(&res) == -1) {
        return NULL;
    }

    int result = res_search(hostname, C_INET, T_A, ip, sizeof(ip));
    if (result < 0) {
        return NULL;
    }

    res_nclose(&res);

    return ip;
}
