            String filePath = scanner.nextLine();

            CompletableFuture.supplyAsync(() -> readFileFromCloudStorage(filePath))
                .thenApply(this::computeMD5)
                .thenAccept(md5Hash -> storeMetadata(filePath, md5Hash));
