pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int maxStringsPerNode = 1000; // Default value
char* uniqueStrings[MAX_UNIQUE_STRINGS]; // Array to store unique strings
int numUniqueStrings = 0;
