// Function prototypes
void* generateString(void* arg);
void handleMemoryAllocationFailure();
void handleInvalidInputs();
void setupLogging();
void garbageCollection();

int main(int argc, char** argv) {
    // Parse command-line arguments for configuration parameters
    if (argc > 1) {
        maxStringsPerNode = atoi(argv[1]);
    }

    setupLogging();

    pthread_t threads[maxStringsPerNode];
    int i;
    for (i = 0; i < maxStringsPerNode; i++) {
        if (pthread_create(&threads[i], NULL, generateString, NULL)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (i = 0; i < maxStringsPerNode; i++) {
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error joining thread\n");
            return 2;
        }
    }

    pthread_mutex_destroy(&lock);
    fclose(logFile);
    garbageCollection();

    return 0;
}

void* generateString(void* arg) {
    // Generate a random string and store it in the global array
    srand(time(NULL));
    size_t len = rand() % MAX_STRING_LEN + 1;
    char* str = malloc(len);

    if (str == NULL) {
        handleMemoryAllocationFailure();
        return NULL;
    }

    // Generate random content for the string
    int i;
    for (i = 0; i < len; i++) {
        str[i] = 'a' + rand() % 26;
    }

    pthread_mutex_lock(&lock);
    if (numUniqueStrings >= MAX_UNIQUE_STRINGS) {
        handleInvalidInputs();
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    uniqueStrings[numUniqueStrings] = str;
    numUniqueStrings++;
    fprintf(logFile, "Generated string: %s\n", str);
    pthread_mutex_unlock(&lock);

    return NULL;
}
