    static std::unordered_map<std::string, u_char*> cache; // Cache for DNS resolution results

    std::lock_guard<std::mutex> lock(mtx); // Lock the mutex to ensure thread safety

    auto it = hostnameList.begin();
    while (it != hostnameList.end()) {
        if (*it == targetHost) {
            u_char* ipAddress;

