                std::optional<u_char*> resolvedIp = dnsResolve(*it);

                // Retry mechanism for transient failures
                while(!resolvedIp && it != hostnameList.end()) {
                    std::this_thread::sleep_for(std::chrono::seconds(1));
                    resolvedIp = dnsResolve(*it);
                }

                if (!resolvedIp) {
                    throw std::runtime_error("DNS resolution failed");
                }

                ipAddress = *resolvedIp;
                cache[*it] = ipAddress; // Update the cache
            }

            it = hostnameList.insert_after(it, newHost); // Insert newHost after targetHost
            return;
        } else {
            ++it;
        }
    }

    // If targetHost is not found in the list, append newHost to the end of the list
    hostnameList.push_front(newHost);
