["Here is an example of how you might implement such a function in C using pthreads for thread safety and separate chaining to handle collisions. This code does not include the garbage collection mechanism as it would be quite complex to implement correctly and efficiently. 

```c
#include <pthread.h>
#include <stdlib.h>

typedef struct Record {
    int key;
    long offset;
    struct Record *next;
} Record;

typedef struct HashTable {
    pthread_rwlock_t lock;
    Record **records;
    size_t capacity;
    size_t count;
} HashTable;

HashTable* create_table(size_t initial_capacity) {
    HashTable *table = malloc(sizeof(HashTable));
    table->records = calloc(initial_capacity, sizeof(Record*));
    table->capacity = initial_capacity;
    table->count = 0;
    pthread_rwlock_init(&table->lock, NULL);
    return table;
}

size_t hash(int key, size_t capacity) {
    // A simple hash function for demonstration purposes. 
    // In a real application, you would want to use a good hash function.
    return (size_t)(key % capacity);
}

void insert(HashTable *table, int key, long offset) {
    pthread_rwlock_wrlock(&table->lock);

    if ((double)table->count / table->capacity > 0.75) {
        // Rehash when load factor exceeds 0.75
        Record **old_records = table->records;
        size_t old_capacity = table->capacity;

        table->capacity *= 2;
        table->count = 0;
        table->records = calloc(table->capacity, sizeof(Record*));

        for (size_t i = 0; i < old_capacity; ++i) {
            Record *record = old_records[i];
            while (record != NULL) {
                insert(table, record->key, record->offset);  // Recursive call to rehash
                Record *next = record->next;
                free(record);
                record = next;
            }
        }

        free(old_records);
    } else {
        size_t index = hash(key, table->capacity);
        Record *new_record = malloc(sizeof(Record));
        new_record->key = key;
        new_record->offset = offset;
        new_record->next = table->records[index];
        table->records[index] = new_record;
        ++table->count;
    }

    pthread_rwlock_unlock(&table->lock);
}

long get(HashTable *table, int key) {
    pthread_rwlock_rdlock(&table->lock);

    size_t index = hash(key, table->capacity);
    Record *record = table->records[index];
    while (record != NULL && record->key != key) {
        record = record->next;
    }

    long offset = record ? record->offset : -1;  // Return -1 if not found

    pthread_rwlock_unlock(&table->lock);

    return offset;
}
```
This code uses a simple hash function for demonstration purposes. In a real application, you would want to use a good hash function that distributes keys evenly across the table. The load factor is set at 0.75, but this can be adjusted based on your specific needs and requirements.

The `insert` function uses a recursive call to rehash when the load factor exceeds 0.75, which ensures that all records are properly hashed after the resize operation. This approach minimizes the impact of resizing on performance during high load.

This code also includes thread-safe operations using pthread's read-write locks. The `insert` function acquires a write lock to ensure exclusive access and prevent race conditions, while the `get` function acquires a read lock to allow concurrent reads without blocking writes or vice versa.
"]

