typedef struct record {
    int value;
    atomic_int refcount;
} Record;

Record** records = NULL;
long* offsets = NULL;
size_t size = 0, capacity = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void record_init(Record* rec) {
    atomic_init(&rec->refcount, 1);
}

void record_incr_ref(Record* rec) {
    pthread_mutex_lock(&lock);
    atomic_fetch_add(&rec->refcount, 1);
    pthread_mutex_unlock(&lock);
}

void record_decr_ref(Record* rec) {
    pthread_mutex_lock(&lock);
    if (atomic_fetch_sub(&rec->refcount, 1) == 1) {
        free(rec);
    }
    pthread_mutex_unlock(&lock);
}

void record_resize(size_t newCapacity) {
    Record** newRecords = realloc(records, sizeof(*newRecords) * newCapacity);
    if (newRecords == NULL && newCapacity != 0) {
        // Handle out of memory error
        return;
    }
    records = newRecords;
    capacity = newCapacity;
}

void record_add(int value) {
    pthread_mutex_lock(&lock);
    if (size == capacity) {
        record_resize(capacity * 2 + 1);
    }
    Record* rec = malloc(sizeof(*rec));
    record_init(rec);
    rec->value = value;
    records[size++] = rec;
    pthread_mutex_unlock(&lock);
}

Record* record_search(int value) {
    for (size_t i = 0; i < size; ++i) {
        if (records[i]->value == value) {
            return records[i];
        }
    }
    return NULL;
}
```
