```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    int ref_count;
    time_t last_accessed;
} record;

record **records = NULL;
int num_records = 0;
long *offsets = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void increment_ref(record *r) {
    pthread_mutex_lock(&lock);
    r->ref_count++;
    pthread_mutex_unlock(&lock);
}

void decrement_ref(record *r) {
    pthread_mutex_lock(&lock);
    if (--r->ref_count == 0) {
        free(r);
    }
    pthread_mutex_unlock(&lock);
}

int allocate_records(int size) {
    records = malloc(size * sizeof(record*));
    if (records == NULL) return -1;

    for (int i = 0; i < size; i++) {
        records[i] = malloc(sizeof(record));
        if (records[i] == NULL) return -1;

        records[i]->value = 0;
        records[i]->ref_count = 0;
        time(&records[i]->last_accessed);
    }

    num_records = size;
    offsets = malloc(num_records * sizeof(long));
    if (offsets == NULL) return -1;

    for (int i = 0; i < num_records; i++) {
        offsets[i] = (long) records[i];
    }

    return 0;
}

void free_records() {
    if (offsets != NULL) {
        free(offsets);
        offsets = NULL;
    }

    if (records != NULL) {
        for (int i = 0; i < num_records; i++) {
            if (records[i] != NULL) {
                free(records[i]);
                records[i] = NULL;
            }
        }

        free(records);
        records = NULL;
    }

    num_records = 0;
}
