#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    float x;
    float y;
} Point2D;

typedef struct {
    Point2D* points;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PointCollection;

PointCollection* create_collection(size_t initial_capacity) {
    PointCollection* collection = malloc(sizeof(PointCollection));
    if (collection == NULL) return NULL;

    collection->points = malloc(initial_capacity * sizeof(Point2D));
    if (collection->points == NULL) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);

    srand(time(NULL)); // seed the random number generator

    return collection;
}

void destroy_collection(PointCollection* collection) {
    free(collection->points);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_point(PointCollection* collection, Point2D point) {
    pthread_mutex_lock(&collection->lock);

    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity * 2; // double the capacity when full
        Point2D* new_points = realloc(collection->points, new_capacity * sizeof(Point2D));

        if (new_points == NULL) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // error: failed to allocate memory
        }

        collection->points = new_points;
        collection->capacity = new_capacity;
    }

    collection->points[collection->size++] = point;

    pthread_mutex_unlock(&collection->lock);

    return 0; // success
}

Point2D generate_point(float min, float max) {
    Point2D point;
    float range = max - min;

    point.x = ((float)rand() / RAND_MAX) * range + min;
    point.y = ((float)rand() / RAND_MAX) * range + min;

    return point;
}
```
