#include "keyvaluestore.h"
#include <stdlib.h>

typedef struct Node {
    KeyValuePair pair;
    struct Node* next;
} Node;

Node* store = NULL;

void init_store() {
    store = NULL;
}

KeyValuePair* insert(int key, long offset) {
    Node* node = malloc(sizeof(Node));
    if (node == NULL) return NULL;

    node->pair.key = key;
    node->pair.offset = offset;
    node->next = store;
    store = node;

    return &(node->pair);
}

KeyValuePair* lookup(int key) {
    Node* current = store;
    while (current != NULL) {
        if (current->pair.key == key) {
            return &(current->pair);
        }
        current = current->next;
    }

    return NULL;
}

void delete(int key) {
    Node* prev = NULL;
    Node* current = store;
    while (current != NULL) {
        if (current->pair.key == key) {
            if (prev == NULL) {
                store = current->next;
            } else {
                prev->next = current->next;
            }

            free(current);
            return;
        }

        prev = current;
        current = current->next;
    }
}
