    FILE *file = fopen(filepath, "r");
    if (file == NULL) {
        return -1; // Error opening file
    }

    // Load resource bundle from file
    size_t num_items = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        ++num_items;
    }
    rewind(file);

    if (num_records > num_items) {
        return -2; // Not enough records in the file
    }

    *records = malloc(sizeof(record) * num_records);
    if (*records == NULL) {
        return -3; // Error allocating memory for records
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        fgets(line, sizeof(line), file);

        // Initialize record value randomly within the specified range
        (*records)[i].value = rand() % (max - min + 1) + min;

        // Calculate offset based on key derived from resource bundle using bitwise operation and modulus operation
        size_t key = strlen(line);
        size_t offset = key & 0xFFF;
        if (offset >= num_records) {
            return -4; // Offset exceeds the bounds of the array
        }

        (*records)[i].offset = *records + offset;
    }

    fclose(file);

    return num_records;
}
