Database** initialize_and_secure_database(int maxRecords, int minValue, int maxValue) {
    if (maxRecords <= 0 || minValue >= maxValue) {
        return NULL; // Invalid input parameters
    }

    srand(time(NULL));

    Database** db = malloc(sizeof(Database*) * maxRecords);
    if (!db) {
        return NULL; // Memory allocation failure
    }

    for (int i = 0; i < maxRecords; ++i) {
        db[i] = malloc(sizeof(Database));
        if (!db[i]) {
            // Free previously allocated memory and return error
            for (--i; i >= 0; --i) {
                free(db[i]);
            }
            free(db);
            return NULL;
        }

        db[i]->offset = i;
        db[i]->key = rand() % (maxValue - minValue + 1) + minValue; // Unique key within range
        db[i]->record = malloc(sizeof(Record));
        if (!db[i]->record) {
            // Free previously allocated memory and return error
            free(db[i]);
            for (--i; i >= 0; --i) {
                free(db[i]);
            }
            free(db);
            return NULL;
        }

        db[i]->record->value = rand(); // Random value
        pthread_mutex_init(&db[i]->mutex, NULL); // Initialize mutex for concurrent access control
    }

    return db;
}
