#include <pthread.h>

typedef struct {
    size_t offset;
    const char* fileName;
    struct stat info;
} FileInfo;

FileInfo** files = NULL;
size_t numFiles = 0;
size_t totalSize = 0;
const size_t MAX_SIZE = 1024 * 1024 * 500; // 500MB
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* readFile(void* arg) {
    const char* fileName = (const char*)arg;

    int fd = open(fileName, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return NULL;
    }

    struct stat info;
    if (fstat(fd, &info) != 0) {
        perror("fstat");
        close(fd);
        return NULL;
    }

    char* buffer = malloc(info.st_size);
    if (!buffer) {
        perror("malloc");
        close(fd);
        return NULL;
    }

    ssize_t bytesRead = read(fd, buffer, info.st_size);
    if (bytesRead != info.st_size) {
        fprintf(stderr, "read: expected %ld bytes but got %ld\n", 
                (long)info.st_size, (long)bytesRead);
        free(buffer);
        close(fd);
        return NULL;
    }

    pthread_mutex_lock(&lock);
    if ((totalSize + info.st_size) > MAX_SIZE) {
        fprintf(stderr, "Total size limit exceeded\n");
        free(buffer);
        close(fd);
        return NULL;
    }

    FileInfo* file = malloc(sizeof(FileInfo));
    if (!file) {
        perror("malloc");
        free(buffer);
        close(fd);
        return NULL;
    }

    file->offset = totalSize;
    file->fileName = strdup(fileName);
    file->info = info;

    files = realloc(files, sizeof(FileInfo*) * (numFiles + 1));
    if (!files) {
        perror("realloc");
        free(buffer);
        close(fd);
        return NULL;
    }

    files[numFiles++] = file;
    totalSize += info.st_size;

    pthread_mutex_unlock(&lock);

    // Process the buffer as needed...

    close(fd);
    return NULL;
}
```
