#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct timestamp {
    int unix_timestamp;
    float* temperature;
} timestamp;

typedef struct data_struct {
    pthread_mutex_t lock;
    float* temperatures;
    timestamp* timestamps;
    size_t num_samples;
} data_struct;

data_struct* init_data(size_t num_samples, float initial_temp) {
    data_struct* ds = malloc(sizeof(data_struct));
    if (ds == NULL) return NULL;

    pthread_mutex_init(&ds->lock, NULL);

    ds->num_samples = num_samples;
    ds->temperatures = malloc(sizeof(float) * num_samples);
    if (ds->temperatures == NULL) {
        free(ds);
        return NULL;
    }

    for (size_t i = 0; i < num_samples; ++i) {
        ds->temperatures[i] = initial_temp;
    }

    ds->timestamps = malloc(sizeof(timestamp) * num_samples);
    if (ds->timestamps == NULL) {
        free(ds->temperatures);
        free(ds);
        return NULL;
    }

    for (size_t i = 0; i < num_samples; ++i) {
        ds->timestamps[i].unix_timestamp = time(NULL);
        ds->timestamps[i].temperature = &ds->temperatures[i];
    }

    return ds;
}

void update_temp(data_struct* ds, size_t index, float new_temp) {
    pthread_mutex_lock(&ds->lock);
    *ds->timestamps[index].temperature = new_temp;
    ds->timestamps[index].unix_timestamp = time(NULL);
    pthread_mutex_unlock(&ds->lock);
}

void free_data(data_struct* ds) {
    pthread_mutex_destroy(&ds->lock);
    free(ds->temperatures);
    free(ds->timestamps);
    free(ds);
}
```
