    }

    int *keys = malloc(maxRecords * sizeof(int));
    if (keys == NULL) {
        // Handle memory allocation failure
        free(offsets);
        return;
    }

    Record **records = malloc(maxRecords * sizeof(Record*));
    if (records == NULL) {
        // Handle memory allocation failure
        free(offsets);
        free(keys);
        return;
    }

    srand(time(NULL));  // Seed the random number generator

    for (int i = 0; i < maxRecords; i++) {
        int value = rand();

        if (enforceUnique) {
            for (int j = 0; j < i; j++) {
                if (keys[j] == value) {
                    // Handle duplicate value
                    free(offsets);
                    free(keys);
                    for (int k = 0; k < i; k++) {
                        free(records[k]);
                    }
                    free(records);
                    return;
                }
            }
        }

        keys[i] = value;

        Record *record = malloc(sizeof(Record));
        if (record == NULL) {
            // Handle memory allocation failure
            free(offsets);
            free(keys);
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            free(records);
            return;
        }

        record->value = value;
        records[i] = record;
    }

    // Use the allocated memory...

    for (int i = 0; i < maxRecords; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}
```
