import hashlib
import time
from concurrent.futures import ThreadPoolExecutor
from external_auth_service import ExternalAuthService
from local_file_storage import LocalFileStorage
from user_dao import UserDAO
from password_policy import PasswordPolicy

class UpdateUserProfile:
    def __init__(self, max_retries=5, backoff_factor=0.1):
        self.max_retries = max_retries
        self.backoff_factor = backoff_factor
        self.password_policy = PasswordPolicy()
        self.local_file_storage = LocalFileStorage()
        self.external_auth_service = ExternalAuthService()
        self.user_dao = UserDAO()

    def update_user_profile(self, user_id, new_password=None, new_email=None, mfa_enrollment=False):
        start_time = time.time()

        # Validate the strength of the new password using a configurable password policy.
        if new_password and not self.password_policy.validate(new_password):
            return {"status": "failure", "message": "Password does not meet requirements"}

        # Compute the MD5 and SHA-256 hashes of any attached documents in chunks to ensure efficient memory usage.
        document_hashes = self._compute_document_hashes()

        # Update the user's password, email, and any other profile details in the database through a Data Access Object (DAO) class.
        update_statuses = self._update_user_details(user_id, new_password, new_email)

        if mfa_enrollment:
            # If MFA is requested, enroll the user in the external authentication service.
            mfa_status = self._mfa_enrollment(user_id)
            update_statuses["MFA"] = mfa_status

        end_time = time.time()
        # Log detailed metrics about the operation, including document hash computation time, password validation time, and MFA enrollment status.
        self._log_metrics(start_time, end_time, document_hashes, update_statuses)

        return {"status": "success", "update_statuses": update_statuses}

    def _compute_document_hashes(self):
        documents = self.local_file_storage.get_documents()
        hashes = {}
        for doc in documents:
            md5, sha256 = hashlib.md5(), hashlib.sha256()
            with open(doc, 'rb') as f:
                while chunk := f.read(8192):
                    md5.update(chunk)
                    sha256.update(chunk)
            hashes[doc] = {"md5": md5.hexdigest(), "sha256": sha256.hexdigest()}
        return hashes

    def _update_user_details(self, user_id, new_password=None, new_email=None):
        with ThreadPoolExecutor() as executor:
            futures = []

            if new_password:
                future = executor.submit(self.user_dao.update_password, user_id, new_password)
                futures.append(("Password", future))

            if new_email:
                future = executor.submit(self.user_dao.update_email, user_id, new_email)
                futures.append(("Email", future))

            return {name: future.result() for name, future in futures}

    def _mfa_enrollment(self, user_id):
        for i in range(self.max_retries):
            try:
                code = self.external_auth_service.generate_code(user_id)
                if not self.external_auth_service.validate_code(user_id, code):
                    raise Exception("Invalid MFA code")
                return "success"
            except Exception as e:
                time.sleep((2 ** i) * self.backoff_factor)  # exponential backoff strategy
        return f"failure after {self.max_retries} retries"

    def _log_metrics(self, start_time, end_time, document_hashes, update_statuses):
        print("Document hashes:", document_hashes)
        print("Update statuses:", update_statuses)
        print("Operation time:", end_time - start_time)
