typedef struct {
    int value;
    long* offset_ptr;
    int* key_ptr;
} record;

record* manage_memory(size_t size, int* error) {
    if (size <= 0) {
        *error = -1; // Invalid size error code
        return NULL;
    }

    long* offsets = calloc(size, sizeof(long));
    if (!offsets) {
        *error = -2; // Memory allocation failure error code
        return NULL;
    }

    int* keys = malloc(size * sizeof(int));
    if (!keys) {
        free(offsets);
        *error = -2; // Memory allocation failure error code
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        keys[i] = i + 1;
    }

    record* records = malloc(size * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        *error = -2; // Memory allocation failure error code
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        records[i].value = 0;
        records[i].offset_ptr = &offsets[i];
        records[i].key_ptr = &keys[i];
    }

    // Set the value of each record's int field to a random value between 1 and 100.
    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % 100 + 1;
    }

    *error = 0; // Success error code
    return records;
}
```
