```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct record {
    char* buffer;
    int value;
    void* metadata;
} Record;

typedef struct node {
    long offset;
    int key;
    Record* record;
    struct node* prev;
    struct node* next;
} Node;

typedef struct list {
    pthread_mutex_t lock;
    Node* head;
    Node* tail;
    size_t count;
} List;

List* create_list() {
    // Initialize the list and its mutex
    List* list = malloc(sizeof(List));
    if (list == NULL) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;

    return list;
}

void destroy_list(List* list) {
    // Free all nodes and their records
    Node* node = list->head;
    while (node != NULL) {
        Node* next = node->next;

        free(node->record->buffer);
        free(node->record->metadata);
        free(node->record);
        free(node);

        node = next;
    }

    // Destroy the mutex and free the list
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_list(List* list, int key, Record* record) {
    Node* node = malloc(sizeof(Node));
    if (node == NULL) return -1;

    node->key = key;
    node->record = record;
    node->prev = NULL;
    node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        Node* current = list->head;

        while (current != NULL && key > current->key) {
            current = current->next;
        }

        if (current == NULL) {
            // Add to the end of the list
            node->prev = list->tail;
            list->tail->next = node;
            list->tail = node;
        } else if (key < current->key) {
            // Insert before 'current'
            node->prev = current->prev;
            node->next = current;

            if (current->prev != NULL) {
                current->prev->next = node;
            } else {
                list->head = node;
            }

            current->prev = node;
        } else {
            // Update existing record
            free(current->record->buffer);
            free(current->record->metadata);
            free(current->record);

            current->record = record;

            free(node);
        }
    }

    list->count++;

    pthread_mutex_unlock(&list->lock);

    return 0;
}
