    size_t count;
    size_t capacity;
} node_t;

node_t* create_node(size_t initial_capacity) {
    node_t* node = malloc(sizeof(node_t));
    pthread_mutex_init(&node->lock, NULL);
    node->offsets = malloc(initial_capacity * sizeof(long));
    node->keys = malloc(initial_capacity * sizeof(int));
    node->records = malloc(initial_capacity * sizeof(record_t*));
    node->count = 0;
    node->capacity = initial_capacity;
    return node;
}

void destroy_node(node_t* node) {
    for (size_t i = 0; i < node->count; ++i) {
        free(node->records[i]);
    }
    free(node->offsets);
    free(node->keys);
    free(node->records);
    pthread_mutex_destroy(&node->lock);
    free(node);
}

void add_record(node_t* node, long offset, int key) {
    pthread_mutex_lock(&node->lock);

    if (node->count == node->capacity) {
        // Reallocate memory for arrays with double capacity
        node->offsets = realloc(node->offsets, 2 * node->capacity * sizeof(long));
        node->keys = realloc(node->keys, 2 * node->capacity * sizeof(int));
        node->records = realloc(node->records, 2 * node->capacity * sizeof(record_t*));
        assert(node->offsets != NULL && node->keys != NULL && node->records != NULL);
        node->capacity *= 2;
    }

    // Add record to arrays
    node->offsets[node->count] = offset;
    node->keys[node->count] = key;
    node->records[node->count] = malloc(sizeof(record_t));
    RAND_bytes((unsigned char*)&node->records[node->count]->value, sizeof(int)); // Generate random value
    ++node->count;

    pthread_mutex_unlock(&node->lock);
}
