    size_t maxRecords;
    size_t numRecords;
} RecordManager;

RecordManager* createRecordManager(size_t initialSize) {
    RecordManager* manager = malloc(sizeof(RecordManager));
    pthread_mutex_init(&manager->lock, NULL);
    manager->records = calloc(initialSize, sizeof(Record));
    manager->maxRecords = initialSize;
    manager->numRecords = 0;
    return manager;
}

void addRecord(RecordManager* manager, int value) {
    pthread_mutex_lock(&manager->lock);

    if (manager->numRecords >= manager->maxRecords) {
        // Handle error: maximum number of records exceeded.
        return;
    }

    for (size_t i = 0; i < manager->numRecords; ++i) {
        if (manager->records[i].value == value) {
            // Handle error: duplicate record value detected.
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    manager->records[manager->numRecords++] = (Record){ .value = value };

    pthread_mutex_unlock(&manager->lock);
}

void destroyRecordManager(RecordManager* manager) {
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```
This code provides a basic structure for managing records with unique integer values. It uses a mutex to ensure thread safety, and checks for uniqueness before adding new records. 

