using System;
using System.Collections.Generic;
using System.Threading;
using Serilog; // External logging framework

public class CustomRandom
{
    private int minValue;
    private int maxValue;

    public CustomRandom(int min, int max)
    {
        this.minValue = min;
        this.maxValue = max;
    }

    public void UpdateRange(int newMin, int newMax)
    {
        if (newMin > newMax)
            throw new ArgumentException("Invalid range");

        Interlocked.Exchange(ref minValue, newMin);
        Interlocked.Exchange(ref maxValue, newMax);
    }

    public int NextInt()
    {
        return RandomNumberGenerator.Next(minValue, maxValue + 1);
    }

    public float NextFloat()
    {
        double sample = RandomNumberGenerator.NextDouble();
        double scaled = sample * (maxValue - minValue) + minValue;
        return (float)scaled;
    }

    public IEnumerable<int> Sequence(int count, bool inclusive)
    {
        for (int i = 0; i < count; i++)
            yield return NextInt();

        if (!inclusive)
            yield break;

        yield return maxValue;
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }
}
