    data->id = id;
    data->temperature = temperature;
    data->timestamp = timestamp;
    data->status = status;
    data->metadata = metadata;
}

void merge_data(sensor_data* active, sensor_data* inactive, int size) {
    for(int i = 0; i < size; i++) {
        if(inactive[i].status == 1 && active[i].id == inactive[i].id) {
            pthread_mutex_lock(&lock);

            // Swap the data from inactive to active
            sensor_data temp = active[i];
            active[i] = inactive[i];
            inactive[i] = temp;

            pthread_mutex_unlock(&lock);
        }
    }
}

void print_stats(sensor_data* data, int size) {
    int active = 0, inactive = 0;
    float sum = 0.0f;
    double min = data[0].timestamp, max = data[0].timestamp;

    for(int i = 0; i < size; i++) {
        if(data[i].status == 1) active++;
        else inactive++;

        sum += data[i].temperature;

        if(data[i].timestamp < min) min = data[i].timestamp;
        if(data[i].timestamp > max) max = data[i].timestamp;
    }

    printf("Active sensors: %d\n", active);
    printf("Inactive sensors: %d\n", inactive);
    printf("Average temperature: %.2f\n", sum/size);
