            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            // Parse JSON response and handle data
            json_t *root = json_loadf(curl, 0, &jsonError);

            if(!root) {
                fprintf(stderr, "error: on line %d: %s\n", jsonError.line, jsonError.text);
            } else {
                // Handle data...

                json_decref(root);
            }
        }

        curl_easy_cleanup(curl);
    }

    pthread_mutex_unlock(&lock); // Unlock after operation is complete
}
