        if (nodes[i].nodeID == id) {
            printf("Error: Duplicate nodeID\n");
            return;
        }
    }

    nodes = realloc(nodes, sizeof(NetworkNode) * (nodeCount + 1));
    NetworkNode newNode = {id, loc, stat};
    nodes[nodeCount] = newNode;
    ++nodeCount;
}
