#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Function to read integers from stdin and store them in a dynamically allocated array
int* read_integers(size_t *n) {
    size_t capacity = 10;
    int *arr = malloc(capacity * sizeof(*arr));
    if (arr == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    int num;
    while (scanf("%d", &num) == 1) {
        arr[*n] = num;
        ++(*n);

        if (*n == capacity) {
            capacity *= 2;
            arr = realloc(arr, capacity * sizeof(*arr));
            if (arr == NULL) {
                perror("Failed to reallocate memory");
                exit(EXIT_FAILURE);
            }
        }
    }

    return arr;
}

// Function to find the largest integer in an array
int find_largest(const int *arr, size_t n) {
    if (n == 0) {
        fprintf(stderr, "Array is empty\n");
        exit(EXIT_FAILURE);
    }

    int largest = arr[0];
    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    return largest;
}

// Function to generate a random string with custom character set
char* generate_random_string(size_t length, const char *charset) {
    size_t charset_len = strlen(charset);
    if (charset_len == 0) {
        fprintf(stderr, "Character set is empty\n");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int) time(NULL)); // seed the random number generator

    char *str = malloc((length + 1) * sizeof(*str));
    if (str == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < length; ++i) {
        str[i] = charset[rand() % charset_len]; // generate a random character from the set
    }
    str[length] = '\0'; // null-terminate the string

    return str;
