            break;
        }
        dataStore.values[dataStore.count] = value;
        time(&dataStore.measurements[dataStore.count]->timestamp);
        pthread_mutex_unlock(&dataStore.lock);
    }
    return NULL;
}

double findSmallest() {
    double smallest = dataStore.values[0];
    for (int i = 1; i < dataStore.count; ++i) {
        if (dataStore.values[i] < smallest) {
            smallest = dataStore.values[i];
        }
    }
    return smallest;
}

void initializeDataStore(int maxCount) {
