    long* offsets;
    int* keys;
    Record** records;
    size_t capacity;
    size_t count;
} Collection;

Collection* create_collection(size_t initial_capacity) {
    Collection* collection = malloc(sizeof(Collection));
    if (collection == NULL) return NULL;

    collection->offsets = malloc(initial_capacity * sizeof(long));
    collection->keys = malloc(initial_capacity * sizeof(int));
    collection->records = malloc(initial_capacity * sizeof(Record*));
    if (collection->offsets == NULL || collection->keys == NULL || collection->records == NULL) {
        free_collection(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;

    return collection;
}

void resize_collection(Collection* collection, size_t new_capacity) {
    collection->offsets = realloc(collection->offsets, new_capacity * sizeof(long));
    collection->keys = realloc(collection->keys, new_capacity * sizeof(int));
    collection->records = realloc(collection->records, new_capacity * sizeof(Record*));

    if (new_capacity > collection->capacity) {
        memset(collection->offsets + collection->capacity, 0, (new_capacity - collection->capacity) * sizeof(long));
        memset(collection->keys + collection->capacity, 0, (new_capacity - collection->capacity) * sizeof(int));
        memset(collection->records + collection->capacity, 0, (new_capacity - collection->capacity) * sizeof(Record*));
    }

    collection->capacity = new_capacity;
}

void add_record(Collection* collection, int key, char* buffer, size_t buffer_size) {
    if (collection->count == collection->capacity) {
        resize_collection(collection, collection->capacity * 2);
    }

    Record* record = malloc(sizeof(Record));
    record->buffer = malloc(buffer_size + 1);
    strncpy(record->buffer, buffer, buffer_size);
    record->buffer[buffer_size] = '\0';
    record->value = rand() % 100; // Pseudo-random number between 0 and 99

    collection->records[collection->count] = record;
    collection->keys[collection->count] = key;
    collection->offsets[collection->count] = (long)record;
    ++collection->count;
}

void free_collection(Collection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->buffer);
        free(collection->records[i]);
    }

    free(collection->offsets);
    free(collection->keys);
    free(collection->records);
    free(collection);
}
