typedef struct Record {
    int value;
} Record;

void logEvent(char* event) {
    time_t now = time(NULL);
    printf("[%ld] %s\n", now, event);
}

Record** allocateRecords(long* offsetArray, int* keyArray, size_t arraySize, size_t maxMemoryUsage) {
    if (arraySize * sizeof(int) > maxMemoryUsage) {
        logEvent("Error: Not enough memory for keys.");
        return NULL;
    }

    // Allocate memory for the key array
    int* keys = malloc(sizeof(int) * arraySize);
    if (keys == NULL) {
        logEvent("Error: Failed to allocate memory for keys.");
        return NULL;
    }

    // Initialize the key array with random values
    srand(time(NULL));
    for (size_t i = 0; i < arraySize; ++i) {
        keys[i] = rand();
    }

    // Allocate memory for the offset array
    long* offsets = malloc(sizeof(long) * arraySize);
    if (offsets == NULL) {
        logEvent("Error: Failed to allocate memory for offsets.");
        free(keys);
        return NULL;
    }

    // Initialize the offset array with random values
    for (size_t i = 0; i < arraySize; ++i) {
        offsets[i] = rand();
    }

    // Allocate memory for the record array
    Record** records = malloc(sizeof(Record*) * arraySize);
    if (records == NULL) {
        logEvent("Error: Failed to allocate memory for records.");
        free(keys);
        free(offsets);
        return NULL;
    }

    // Initialize the record array with random values
    for (size_t i = 0; i < arraySize; ++i) {
        Record* record = malloc(sizeof(Record));
        if (record == NULL) {
            logEvent("Error: Failed to allocate memory for a record.");
            // Free previously allocated records
            for (size_t j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(keys);
            free(offsets);
            return NULL;
        }

        record->value = rand();
        records[i] = record;
    }

    logEvent("Memory allocation successful.");
    *offsetArray = (long) offsets;
    *keyArray = (int) keys;
    return records;
}
```
