```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct record {
    int value;
} Record;

typedef struct list_node {
    Record *record;
    struct list_node *next;
} ListNode;

long *offsets = NULL;
int *keys = NULL;
ListNode *list_head = NULL;
pthread_mutex_t lock;
size_t max_memory = 1024*1024*1024; // 1GB
size_t used_memory = 0;

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    printf("[%s] %s\n", asctime(timeinfo), message);
}

int allocate_memory(size_t size) {
    pthread_mutex_lock(&lock);
    if (used_memory + size > max_memory) {
        log_event("Memory allocation failed: not enough space.");
        pthread_mutex_unlock(&lock);
        return -1;
    }
    used_memory += size;
    log_event("Memory allocated successfully.");
    pthread_mutex_unlock(&lock);
    return 0;
}

void deallocate_memory(size_t size) {
    pthread_mutex_lock(&lock);
    used_memory -= size;
    log_event("Memory deallocated successfully.");
    pthread_mutex_unlock(&lock);
}

int initialize() {
    srand(time(NULL));
    if (pthread_mutex_init(&lock, NULL) != 0) {
        printf("\n mutex init failed\n");
        return -1;
    }
    offsets = malloc(sizeof(long)*10); // Allocate initial space for 10 long values.
    if (offsets == NULL || allocate_memory(sizeof(long)*10) < 0) {
        log_event("Failed to initialize offsets.");
        return -1;
