        log_event("Failed to initialize keys.");
        return -1;
    }
    list_head = malloc(sizeof(ListNode)); // Allocate space for the head of linked list.
    if (list_head == NULL || allocate_memory(sizeof(ListNode)) < 0) {
        log_event("Failed to initialize list.");
        return -1;
    }
    list_head->next = NULL;
    return 0;
}

void add_record(int value) {
    ListNode *new_node = malloc(sizeof(ListNode));
    if (new_node == NULL || allocate_memory(sizeof(ListNode)) < 0) {
        log_event("Failed to add record.");
        return;
    }
    new_node->record = malloc(sizeof(Record));
    if (new_node->record == NULL || allocate_memory(sizeof(Record)) < 0) {
        log_event("Failed to add record.");
        free(new_node);
        deallocate_memory(sizeof(ListNode));
        return;
    }
    new_node->record->value = value;
    pthread_mutex_lock(&lock);
    new_node->next = list_head->next;
    list_head->next = new_node;
    pthread_mutex_unlock(&lock);
}
