['Here's an example of how you might implement this in C using POSIX threads (pthreads) for concurrency, and a simple binary file format for serialization. This code does not include all the features you requested, but it should give you a good starting point. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct NetworkNode {
    int nodeID;
    char location[3]; // ISO 3166-1 alpha-2 standard
    int status;
} NetworkNode;

typedef struct NodeList {
    pthread_mutex_t lock;
    NetworkNode* nodes;
    size_t count;
    size_t capacity;
} NodeList;

void init(NodeList* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->capacity = 1024; // Start with a reasonable default size
    list->nodes = malloc(sizeof(NetworkNode) * list->capacity);
}

void add_node(NodeList* list, NetworkNode node) {
    pthread_mutex_lock(&list->lock);

    // Check if the nodeID is unique
    for (int i = 0; i < list->count; ++i) {
        if (list->nodes[i].nodeID == node.nodeID) {
            printf("Error: Node ID already exists.\n");
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }

    // Check if the location is valid (assuming it's always 2 characters long)
    if (strlen(node.location) != 2) {
        printf("Error: Invalid location.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    // Check if we need to resize the array
    if (list->count == list->capacity) {
        list->capacity *= 2;
        list->nodes = realloc(list->nodes, sizeof(NetworkNode) * list->capacity);
    }

    // Add the node to the array
    list->nodes[list->count++] = node;

    pthread_mutex_unlock(&list->lock);
}

void save(NodeList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error: Could not open file for writing.\n");
        return;
    }

    pthread_mutex_lock(&list->lock);
    fwrite(list->nodes, sizeof(NetworkNode), list->count, file);
    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

void load(NodeList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error: Could not open file for reading.\n");
        return;
    }

    pthread_mutex_lock(&list->lock);
    list->count = 0;
    while (!feof(file)) {
        NetworkNode node;
        if (fread(&node, sizeof(NetworkNode), 1, file) == 1) {
            add_node(list, node); // This will validate the node
        } else {
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);

    fclose(file);
}
```
This code does not include incremental backups or non-blocking backup process. Also, it doesn't handle memory fragmentation and optimizes for performance under heavy load. For these features, you would need to use a more complex data structure like a balanced binary search tree or hash table, and implement your own memory management scheme that takes into account the specifics of your application.
