int init(size_t n, int min_value, int max_value) {
    if (n <= 0 || min_value >= max_value) {
        return -1; // Invalid input
    }

    offsets = malloc(n * sizeof(long));
    if (!offsets) {
        return -2; // Memory allocation failure
    }

    records = malloc(n * sizeof(record*));
    if (!records) {
        free(offsets);
        return -2; // Memory allocation failure
    }

    int range = max_value - min_value + 1;
    int last_val = -1;

    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < n; ++i) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            // Memory allocation failure, clean up and return error
            while (i-- > 0) {
                free(records[i]);
            }
            free(offsets);
            free(records);
            pthread_mutex_unlock(&lock);
            return -2; 
        }

        // Ensure unique values for consecutive records
        do {
            records[i]->value = (rand() % range) + min_value;
        } while(records[i]->value == last_val);

        last_val = records[i]->value;
    }
    pthread_mutex_unlock(&lock);

    return n; // Successfully initialized all records
}

void cleanup() {
    for (size_t i = 0; i < sizeof(records) / sizeof(record*); ++i) {
        free(records[i]);
