struct ImageInfo extractImageInfo(const char* filename) {
    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE * infile;
    JSAMPARRAY buffer;
    int row_stride;

    SHA_CTX ctx;
    unsigned char hash[SHA256_DIGEST_LENGTH];
    const int bufSize = 4096;
    unsigned char* buf = malloc(bufSize);

    struct ImageInfo info;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);

    if ((infile = fopen(filename, "rb")) == NULL) {
        // Handle error
    }

    jpeg_stdio_src(&cinfo, infile);
    (void)jpeg_read_header(&cinfo, TRUE);

    info.width = cinfo.image_width;
    info.height = cinfo.image_height;
    sprintf(info.orientation, "%d", cinfo.orientation);
    info.resolution_units = cinfo.density_unit;
    info.x_resolution = cinfo.X_density;
    info.y_resolution = cinfo.Y_density;

    SHA256_Init(&ctx);
    while (jpeg_read_scanlines(&cinfo, &buffer, 1) != 0) {
        int len = fread(buf, sizeof(unsigned char), bufSize, infile);
        SHA256_Update(&ctx, buf, len);
    }
    SHA256_Final(hash, &ctx);

    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        sprintf((char*)&info.sha256hash[i*2], "%02x", hash[i]);
    }

    jpeg_destroy_decompress(&cinfo);
    fclose(infile);

    return info;
}
