```cpp
#include <random>
#include <vector>
#include <mutex>
#include <stdexcept>

class DynamicRandomGenerator {
private:
    std::vector<std::mt19937> entropySources;
    std::mutex mtx;
public:
    void addEntropySource(std::mt19937 source) {
        std::lock_guard<std::mutex> lock(mtx);
        entropySources.push_back(source);
    }

    int generateRandomValue(int min, int max, bool inclusive = true) {
        if (entropySources.empty()) throw std::runtime_error("No entropy sources available");

        std::lock_guard<std::mutex> lock(mtx);
        std::uniform_int_distribution<> dist(min, max);
        return dist(entropySources[0]); // Use the first source for simplicity
    }

    void generateRandomSequence(int* arr, int size) {
        if (entropySources.empty()) throw std::runtime_error("No entropy sources available");

        std::lock_guard<std::mutex> lock(mtx);
        for (int i = 0; i < size; ++i) {
            arr[i] = generateRandomValue(0, 100); // Example usage
        }
    }
};
```
This class uses `std::mt19937` as an entropy source. You can replace it with any other random number generator you want to use. The `addEntropySource()` method allows adding new sources dynamically, and the `generateRandomValue()` and `generateRandomSequence()` methods generate random values or sequences using the first available source.

Please note that this is a very basic implementation and does not cover all your requirements. For example, it doesn't support different entropy sources, doesn't handle invalid input gracefully, doesn't integrate with an external resource manager to monitor and control memory usage, etc. You would need to extend this class according to your needs.
