typedef struct HashTable {
    pthread_mutex_t lock;
    int size;
    Object** objects;
} HashTable;

HashTable* create_hash_table(int size) {
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    table->objects = calloc(size, sizeof(Object*));
    if (table->objects == NULL) {
        free(table);
        return NULL;
    }

    pthread_mutex_init(&table->lock, NULL);
    table->size = size;

    return table;
}

void destroy_hash_table(HashTable* table) {
    for (int i = 0; i < table->size; ++i) {
        if (table->objects[i] != NULL) {
            free(table->objects[i]->id);
            free(table->objects[i]);
        }
    }

    pthread_mutex_destroy(&table->lock);
    free(table->objects);
    free(table);
}

int hash(char* id, int size) {
    unsigned long hash = 5381;
    int c;

    while ((c = *id++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % size;
}

Object* create_object(char* id, Point point, Object* ref) {
    Object* obj = malloc(sizeof(Object));
    if (obj == NULL) return NULL;

    obj->id = strdup(id);
    if (obj->id == NULL) {
        free(obj);
        return NULL;
    }

    obj->point = point;
    obj->ref = ref;

    return obj;
}

void insert_object(HashTable* table, Object* obj) {
    int index = hash(obj->id, table->size);

    pthread_mutex_lock(&table->lock);
    table->objects[index] = obj;
    pthread_mutex_unlock(&table->lock);
}
```
