#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    record* rec;
} pointer;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    char*** tags;
    pointer** pointers;
    pointer*** pointer_pointers;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager* create_manager(size_t initialCapacity) {
    // Initialize the manager and allocate memory for its components.
    MemoryManager* manager = malloc(sizeof(MemoryManager));
    if (manager == NULL) return NULL;

    manager->offsets = calloc(initialCapacity, sizeof(long));
    manager->keys = calloc(initialCapacity, sizeof(int));
    manager->records = calloc(initialCapacity, sizeof(record*));
    manager->tags = calloc(initialCapacity, sizeof(char**));
    manager->pointers = calloc(initialCapacity, sizeof(pointer*));
    manager->pointer_pointers = calloc(initialCapacity, sizeof(pointer**));

    if (manager->offsets == NULL || manager->keys == NULL || manager->records == NULL || 
        manager->tags == NULL || manager->pointers == NULL || manager->pointer_pointers == NULL) {
        // Handle memory allocation failure.
        free(manager);
        return NULL;
    }

    manager->capacity = initialCapacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void add_record(MemoryManager* manager, int key, record* rec, char** tags) {
    // Lock the manager to ensure thread safety.
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        // Handle maximum capacity exceeded error.
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    // Add the record to the manager's components.
    manager->keys[manager->count] = key;
    manager->records[manager->count] = rec;
    manager->tags[manager->count] = tags;

    pointer* ptr = malloc(sizeof(pointer));
    if (ptr == NULL) {
        // Handle memory allocation failure.
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    ptr->rec = rec;
    manager->pointers[manager->count] = ptr;

    pointer** ptrPtr = malloc(sizeof(pointer*));
    if (ptrPtr == NULL) {
        // Handle memory allocation failure.
        free(ptr);
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    *ptrPtr = ptr;
    manager->pointer_pointers[manager->count] = ptrPtr;

    manager->count++;

    // Unlock the manager.
    pthread_mutex_unlock(&manager->lock);
}
