typedef struct {
    const char* file_name;
    size_t offset;
    off_t size;
    time_t mod_time;
} file_info;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int total_size = 0;
const int MAX_SIZE = 1024 * 1024 * 500; // 500MB
void* (*error_callback)(char*) = NULL;

void* process_file(void* arg) {
    const char* file_name = (const char*)arg;

    int fd = open(file_name, O_RDONLY);
    if (fd == -1) {
        pthread_mutex_lock(&lock);
        if (error_callback != NULL) error_callback(strerror(errno));
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    struct stat st;
    fstat(fd, &st);

    // Check total size limit
    if (total_size + st.st_size > MAX_SIZE) {
        pthread_mutex_lock(&lock);
        if (error_callback != NULL) error_callback("Total file size exceeded maximum limit");
        pthread_mutex_unlock(&lock);
        close(fd);
        return NULL;
    }

    // Process the file...

    close(fd);
    return NULL;
}

void process_directory(const char* dir_path, const char* output_file) {
    DIR* dir = opendir(dir_path);
    if (dir == NULL) {
        pthread_mutex_lock(&lock);
        if (error_callback != NULL) error_callback(strerror(errno));
        pthread_mutex_unlock(&lock);
        return;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char file_path[1024];
        snprintf(file_path, sizeof(file_path), "%s/%s", dir_path, entry->d_name);

        pthread_t thread;
        if (pthread_create(&thread, NULL, process_file, file_path) != 0) {
            pthread_mutex_lock(&lock);
            if (error_callback != NULL) error_callback(strerror(errno));
            pthread_mutex_unlock(&lock);
        } else {
            pthread_detach(thread); // Detach the thread to prevent zombie threads
        }
    }

    closedir(dir);
}
