typedef struct Record {
    char* buffer;
    char* identifier;
    int value;
} Record;

typedef struct Node {
    int key;
    Record record;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int cacheSize = 1000;
long* offsets;
int* keys;
Record* records;
char** identifiers;

void insert(int key, Record record) {
    pthread_mutex_lock(&lock);

    Node* node = (Node*) malloc(sizeof(Node));
    node->key = key;
    node->record = record;
    node->next = NULL;

    if (head == NULL || head->key > key) {
        node->next = head;
        head = node;
    } else {
        Node* current = head;
        while (current->next != NULL && current->next->key < key) {
            current = current->next;
        }

        if (current->next != NULL && current->next->key == key) {
            free(node);
        } else {
            node->next = current->next;
            current->next = node;
        }
    }

    pthread_mutex_unlock(&lock);
}

void initialize() {
    offsets = (long*) malloc(cacheSize * sizeof(long));
    keys = (int*) malloc(cacheSize * sizeof(int));
    records = (Record*) malloc(cacheSize * sizeof(Record));
    identifiers = (char**) malloc(cacheSize * sizeof(char*));

    for (int i = 0; i < cacheSize; i++) {
        offsets[i] = -1;
        keys[i] = -1;
        records[i].buffer = NULL;
        identifiers[i] = NULL;
    }
}

void freeMemory() {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;

        if (temp->record.buffer != NULL) free(temp->record.buffer);
        if (temp->record.identifier != NULL) free(temp->record.identifier);
        free(temp);
    }

    for (int i = 0; i < cacheSize; i++) {
        if (records[i].buffer != NULL) free(records[i].buffer);
        if (identifiers[i] != NULL) free(identifiers[i]);
    }

    free(offsets);
    free(keys);
    free(records);
    free(identifiers);

    pthread_mutex_unlock(&lock);
}
```
