#include <pthread.h>
#include <stdlib.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node *head = NULL;
int count = 0;

void add(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);

    if (count >= 1000) {
        // Handle error, memory limit reached.
        return;
    }

    Node *newNode = malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = head;
    head = newNode;
    count++;

    pthread_mutex_unlock(&lock);
}

void removeAll() {
    pthread_mutex_lock(&lock);

    Node *current = head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
    head = NULL;
    count = 0;

    pthread_mutex_unlock(&lock);
}
```
This code provides a simple linked list with thread safety. It uses a mutex to ensure that only one thread can access the linked list at a time, preventing race conditions and memory leaks. The `add` function adds a new node to the beginning of the list, while the `removeAll` function frees all nodes in the list.

