void allocate_data(DataPoint **dataPoints, Status **statuses, int numPoints, long startTime, long interval, float minValue, float maxValue) {
    assert(numPoints > 0);

    *dataPoints = malloc(sizeof(DataPoint) * numPoints);
    if (*dataPoints == NULL) {
        return;
    }

    *statuses = calloc(numPoints, sizeof(Status));
    if (*statuses == NULL) {
        free(*dataPoints);
        *dataPoints = NULL;
