    }

    srand((unsigned int)time(NULL)); // seed the random number generator

    for (int i = 0; i < numPoints; ++i) {
        (*dataPoints)[i].timestamp = startTime + interval * i;
        float range = maxValue - minValue;
        float randNum = ((float)rand() / RAND_MAX) * range + minValue; // generate a random number within the given range
        (*dataPoints)[i].value = randNum;
    }
}

void deallocate_data(DataPoint **dataPoints, Status **statuses) {
    if (*dataPoints != NULL) {
        free(*dataPoints);
        *dataPoints = NULL;
    }

    if (*statuses != NULL) {
        free(*statuses);
        *statuses = NULL;
    }
}
