['Here is a basic implementation in C using pthreads for thread safety and a hash table (std::unordered_map) for quick access to records based on their keys. This code does not include error handling or batch updates/queries, as these would significantly increase the complexity of this example. 

```c
#include <pthread.h>
#include <unordered_map>
#include <stdexcept>

// Define a record structure
typedef struct {
    int key;
    long offset;
} Record;

class RecordManager {
private:
    std::unordered_map<int, Record*> records;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    size_t maxSizePerRecord; // Maximum allowed size per record in bytes
    size_t totalMemoryUsage = 0;

public:
    RecordManager(size_t maxSize) : maxSizePerRecord(maxSize) {}

    void addRecord(int key, long offset) {
        pthread_mutex_lock(&mutex);

        // Check if adding this record would exceed the memory limit
        size_t newMemoryUsage = totalMemoryUsage + sizeof(Record);
        if (newMemoryUsage > maxSizePerRecord) {
            pthread_mutex_unlock(&mutex);
            throw std::runtime_error("Adding this record would exceed the maximum allowed memory usage");
        }

        // Allocate memory for the new record and add it to the map
        Record* newRecord = (Record*)malloc(sizeof(Record));
        if (!newRecord) {
            pthread_mutex_unlock(&mutex);
            throw std::runtime_error("Failed to allocate memory for new record");
        }

        newRecord->key = key;
        newRecord->offset = offset;
        records[key] = newRecord;

        totalMemoryUsage = newMemoryUsage;
        pthread_mutex_unlock(&mutex);
    }

    Record* getRecord(int key) {
        pthread_mutex_lock(&mutex);
        auto it = records.find(key);
        if (it == records.end()) {
            pthread_mutex_unlock(&mutex);
            return nullptr;
        } else {
            Record* record = it->second;
            pthread_mutex_unlock(&mutex);
            return record;
        }
    }

    ~RecordManager() {
        // Free all allocated memory when the object is destroyed
        for (auto& pair : records) {
            free(pair.second);
        }
    }
};
```
This code uses a mutex to ensure that only one thread can modify the record collection at a time, preventing race conditions and ensuring thread safety. It also checks if adding a new record would exceed the maximum allowed memory usage before allocating memory for it. If an error occurs during allocation, all allocated resources are released promptly using the destructor of the RecordManager class.
']

