function manageResourceBundleAndAuthSession($oauthClient, $resourcePath, $randomRange) {
    // Authenticate user using OAuth 2.0 client
    $accessToken = $oauthClient->authenticate();

    if (empty($accessToken)) {
        return 1;
    }

    // Store access token in session variable
    if (!session_start()) {
        return 1;
    }

    $_SESSION['access_token'] = $accessToken;

    // Retrieve user information using the access token
    try {
        $userInfo = $oauthClient->getUserInfo($accessToken);
    } catch (Exception $e) {
        return 1;
    }

    // Load resource bundle from specified path
    $resourceBundle = file_get_contents($resourcePath);

    if ($resourceBundle === false) {
        return 1;
