#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct Project {
    char* name;
    int estimated_duration;
    float budget;
    char* status;
} Project;

typedef struct Node {
    Project* project;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* addProject(void* arg) {
    pthread_mutex_lock(&lock);

    Project* project = (Project*)arg;
    Node* node = malloc(sizeof(Node));
    if (!node) goto error;

    node->project = project;
    node->next = head;
    head = node;

    pthread_mutex_unlock(&lock);
    return NULL;

error:
    free(project->name);
    free(project->status);
    free(project);
    return NULL;
}

void* removeProject(void* arg) {
    pthread_mutex_lock(&lock);

    char* name = (char*)arg;
    Node** link = &head;

    while (*link) {
        if (!strcmp((*link)->project->name, name)) {
            Node* node = *link;
            *link = node->next;
            free(node->project->name);
            free(node->project->status);
            free(node->project);
            free(node);
            break;
        }
        link = &(*link)->next;
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}
```
