#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>

// Define a structure to hold request details
typedef struct {
    char* url;
    int payload_size;
} RequestDetails;

u_char* resolveDNS(const char *hostname) {
    static u_char ip[INET6_ADDRSTRLEN];
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // use IPv4 or IPv6, whichever
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        perror("Failed to resolve DNS");
        return NULL;
    }

    // Extract IP address from the first result
    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    addr = &(ipv4->sin_addr);
    inet_ntop(res->ai_family, addr, ip, sizeof ip);

    freeaddrinfo(res); // Free the linked list
    return ip;
}

RequestDetails* readFileAndAllocateMemory(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open file");
        return NULL;
    }

    RequestDetails *requests = malloc(sizeof(RequestDetails)); // Allocate memory for the first request
    int i = 0;
    char line[256];

    while (fgets(line, sizeof line, file)) {
        requests = realloc(requests, (i + 1) * sizeof(RequestDetails)); // Reallocate memory for each new request

        // Parse the line and store details in the allocated memory
        char *token = strtok(line, " ");
        while (token != NULL) {
            if (strcmp(token, "url") == 0) {
                token = strtok(NULL, " ");
                requests[i].url = malloc((strlen(token) + 1) * sizeof(char));
                strcpy(requests[i].url, token);
            } else if (strcmp(token, "payload_size") == 0) {
                token = strtok(NULL, " ");
                requests[i].payload_size = atoi(token);
            }

            token = strtok(NULL, " ");
        }

        i++;
    }

    fclose(file); // Close the file
    return requests;
}

int main() {
    const char *hostname = "www.example.com";
    u_char* ip = resolveDNS(hostname);
    if (ip != NULL) {
        printf("IP address: %s\n", ip);
    }

    const char *filename = "requests.txt";
    RequestDetails *requests = readFileAndAllocateMemory(filename);
    if (requests != NULL) {
        // Process requests...

        for (int i = 0; requests[i].url != NULL; i++) {
            free(requests[i].url); // Free allocated memory for each request's details
        }
        free(requests); // Free the main array of requests
    }

    return 0;
}
```
