        newNode->data = data;
        newNode->next = head;
        head = newNode;
        ++count;
    } else {
        printf("List is full!\n");
    }

    mtx_unlock(&lock);
}

void removeNode() {
    mtx_lock(&lock);

    if (head != NULL) {
        Node *temp = head;
        head = head->next;
        free(temp);
        --count;
    } else {
