    Record **records = malloc(max_records * sizeof(Record*));
    if (records == NULL) {
        free(offsets);
        free(keys);
        return NULL; // Handle memory allocation failure
    }

    for (size_t i = 0; i < max_records; ++i) {
        int value = rand() % (max_value - min_value + 1) + min_value;

        if (enforce_uniqueness) {
            // Check for duplicate values and regenerate if necessary
            for (size_t j = 0; j < i; ++j) {
                if (records[j]->value == value) {
                    --i;
                    continue;
                }
            }
        }

        Record *record = malloc(sizeof(Record));
        if (record == NULL) {
            // Handle memory allocation failure
            for (size_t j = 0; j <= i; ++j) {
                free(records[j]);
            }
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }

        record->value = value;
        records[i] = record;
    }

    // Return a struct containing all allocated memory for easy cleanup later
    void *result = malloc(3 * sizeof(void*) + max_records * sizeof(Record*));
    if (result == NULL) {
        // Handle memory allocation failure
        return NULL;
    }

    ((void**)result)[0] = offsets;
    ((void**)result)[1] = keys;
    memcpy(((void**)result)[2], records, max_records * sizeof(Record*));

    return result;
}
```

