#include <pthread.h>
#include <glib.h>
#include <stdlib.h>
#include <assert.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
GHashTable* hashTable;
Node* memoryPool;
int poolSize = 0;

void initMemoryPool(int size) {
    assert(size > 0);
    memoryPool = (Node*)calloc(size, sizeof(Node));
    for (int i = 0; i < size - 1; ++i) {
        memoryPool[i].next = &memoryPool[i + 1];
    }
    poolSize = size;
}

void initHashTable() {
    hashTable = g_hash_table_new(g_int_hash, g_int_equal);
}

NFAPI_CRC_INDICATION_PDU_T* allocateNode() {
    pthread_mutex_lock(&lock);
    if (memoryPool == NULL) {
        initMemoryPool(1024); // default size
    }
    Node* node = memoryPool;
    memoryPool = node->next;
    pthread_mutex_unlock(&lock);
    return &node->data;
}

void releaseNode(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = (Node*)data;
    pthread_mutex_lock(&lock);
    node->next = memoryPool;
    memoryPool = node;
    pthread_mutex_unlock(&lock);
}

void addToHashTable(int key, NFAPI_CRC_INDICATION_PDU_T* data) {
    g_hash_table_insert(hashTable, &key, data);
}

NFAPI_CRC_INDICATION_PDU_T* getFromHashTable(int key) {
    return (NFAPI_CRC_INDICATION_PDU_T*)g_hash_table_lookup(hashTable, &key);
}
```
