```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int state;
    time_t lastActivityTimestamp;
    pthread_mutex_t mutex;
} connection_info;

typedef struct {
    socklen_t* ids;
    const char** labels;
    connection_info** infos;
    size_t count;
    size_t capacity;
    void** labelToIndex;
    pthread_mutex_t mutex;
} ConnectionManager;

ConnectionManager* createConnectionManager() {
    ConnectionManager* manager = malloc(sizeof(ConnectionManager));
    if (manager == NULL) return NULL;

    manager->ids = NULL;
    manager->labels = NULL;
    manager->infos = NULL;
    manager->count = 0;
    manager->capacity = 0;
    manager->labelToIndex = NULL;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void addConnection(ConnectionManager* manager, socklen_t id, const char* label) {
    if (manager == NULL || label == NULL) return;

    pthread_mutex_lock(&manager->mutex);

    // Check if the connection already exists
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(label, manager->labels[i]) == 0) {
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
    }

    // Resize arrays if necessary
    if (manager->count == manager->capacity) {
        size_t newCapacity = manager->capacity == 0 ? 1 : manager->capacity * 2;

        manager->ids = realloc(manager->ids, sizeof(socklen_t) * newCapacity);
        manager->labels = realloc(manager->labels, sizeof(const char*) * newCapacity);
        manager->infos = realloc(manager->infos, sizeof(connection_info*) * newCapacity);

        if (manager->ids == NULL || manager->labels == NULL || manager->infos == NULL) {
            // Handle memory allocation failure gracefully
            pthread_mutex_unlock(&manager->mutex);
            return;
        }

        manager->capacity = newCapacity;
    }

    // Add the connection
    manager->ids[manager->count] = id;
    manager->labels[manager->count] = strdup(label);
    manager->infos[manager->count] = calloc(1, sizeof(connection_info));

    pthread_mutex_init(&manager->infos[manager->count]->mutex, NULL);
    ++manager->count;

    // Update the labelToIndex array
    manager->labelToIndex = realloc(manager->labelToIndex, sizeof(void*) * manager->count);
    if (manager->labelToIndex == NULL) {
        // Handle memory allocation failure gracefully
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    manager->labelToIndex[manager->count - 1] = &manager->infos[manager->count - 1]->state;

    pthread_mutex_unlock(&manager->mutex);
}
```
