#include <unistd.h>
#include <time.h>

typedef struct node {
    char* value;
    size_t length;
} Node;

Node** nodes = NULL;
size_t* lengths = NULL;
char** strings = NULL;
int count = 0;
pthread_mutex_t lock;

void* readStrings(void *arg) {
    char buffer[256];
    FILE *file = fopen((char*) arg, "r");

    if (file == NULL) {
        printf("Error opening file\n");
        return NULL;
    }

    while(fgets(buffer, sizeof(buffer), file)) {
        pthread_mutex_lock(&lock);

        strings = realloc(strings, (count + 1) * sizeof(char*));
        lengths = realloc(lengths, (count + 1) * sizeof(size_t));
        nodes = realloc(nodes, (count + 1) * sizeof(Node*));

        size_t len = strlen(buffer);
        strings[count] = malloc(len+1);
        strcpy(strings[count], buffer);
        lengths[count] = len;
        nodes[count] = malloc(sizeof(Node));
        nodes[count]->value = strings[count];
        nodes[count]->length = len;

        count++;

        pthread_mutex_unlock(&lock);
    }

    fclose(file);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (pthread_mutex_init(&lock, NULL) != 0) {
        printf("Mutex init failed\n");
        return 1;
    }

    pthread_t threads[argc-1];

    for(int i = 1; i < argc; i++) {
        if (pthread_create(&threads[i-1], NULL, readStrings, (void*) argv[i]) != 0) {
            printf("Thread creation failed\n");
            return 1;
        }
    }

    for(int i = 1; i < argc; i++) {
        if (pthread_join(threads[i-1], NULL) != 0) {
            printf("Thread join failed\n");
            return 1;
        }
    }

    pthread_mutex_destroy(&lock);

    for(int i = 0; i < count; i++) {
        free(strings[i]);
        free(nodes[i]);
    }

    free(strings);
    free(lengths);
    free(nodes);

    return 0;
}
```
This code reads strings from multiple files in parallel using threads. It uses a mutex to ensure thread safety when accessing shared data structures. The memory allocated for the strings is freed at the end of the program.

