```java
import java.util.*;
import java.util.concurrent.*;

public class ConfigService {
    private final ConcurrentHashMap<String, Config> configMap = new ConcurrentHashMap<>();

    public void addConfig(String key, Config config) {
        synchronized (configMap) {
            if (!configMap.containsKey(key)) {
                configMap.put(key, config);
            } else {
                throw new IllegalArgumentException("Configuration with this key already exists");
            }
        }
    }

    public void removeConfig(String key) {
        synchronized (configMap) {
            if (configMap.containsKey(key)) {
                configMap.remove(key);
            } else {
                throw new IllegalArgumentException("Configuration with this key does not exist");
            }
        }
    }

    public void updateConfig(String key, Config config) {
        synchronized (configMap) {
            if (configMap.containsKey(key)) {
                configMap.put(key, config);
            } else {
                throw new IllegalArgumentException("Configuration with this key does not exist");
            }
        }
    }

    public Config getConfigByKey(String key) {
        synchronized (configMap) {
            if (configMap.containsKey(key)) {
                return configMap.get(key);
            } else {
                throw new IllegalArgumentException("Configuration with this key does not exist");
            }
        }
    }

    public List<Config> getConfigByPriority(int priority) {
        synchronized (configMap) {
            List<Config> configs = new ArrayList<>();
            for (Config config : configMap.values()) {
                if (config.getPriority() == priority) {
                    configs.add(config);
                }
            }
            return configs;
        }
    }
}
