    int *keys = calloc(m, sizeof(int));
    if (!keys) {
        free(offsets);
        return -3; // memory allocation failure
    }

    record *records = malloc(k * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return -4; // memory allocation failure
    }
    memset(records, 0, k * sizeof(record));

    srand((unsigned int)time(NULL)); // seed the random number generator
    for (size_t i = 0; i < k; ++i) {
        records[i].value = rand() % m + 1; // generate a unique random value within range [1, m]
    }

    free(offsets);
    free(keys);
    free(records);

    return 0; // success
}
