    int status;
} NetworkNode;

GArray *networkNodes = NULL;
int maxNodeCount = 1000; // Maximum limit for the network nodes
pthread_mutex_t lock;

void initNetworkManager() {
    pthread_mutex_init(&lock, NULL);
    networkNodes = g_array_new(FALSE, FALSE, sizeof(NetworkNode));
}

int addNode(int nodeID, char* location, int status) {
    if (g_array_size(networkNodes) >= maxNodeCount) {
        printf("Error: Maximum node count exceeded.\n");
        return -1;
    }

    pthread_mutex_lock(&lock);
    for (int i = 0; i < g_array_size(networkNodes); ++i) {
        NetworkNode *node = &g_array_index(networkNodes, NetworkNode, i);
        if (node->nodeID == nodeID) {
            printf("Error: Duplicate node ID.\n");
            pthread_mutex_unlock(&lock);
            return -1;
        }
    }

    // Validate location using ISO 3161-1 alpha-2 standard (not implemented here)

    NetworkNode newNode = {nodeID, strdup(location), status};
    g_array_append_val(networkNodes, newNode);
    pthread_mutex_unlock(&lock);

    printf("Added node with ID: %d\n", nodeID);
    return 0;
}
