```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int fd;
    const char* event_type;
    void (*callback)(int);
} FileDescriptorEvent;

typedef struct {
    FileDescriptorEvent* events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} EventList;

void init_event_list(EventList* list, size_t initial_capacity) {
    list->events = malloc(initial_capacity * sizeof(FileDescriptorEvent));
    if (list->events == NULL) {
        // Handle memory allocation failure
        exit(1);
    }
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void add_event(EventList* list, int fd, const char* event_type, void (*callback)(int)) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        // Dynamically resize the array when full
        size_t new_capacity = list->capacity * 2;
        FileDescriptorEvent* new_events = realloc(list->events, new_capacity * sizeof(FileDescriptorEvent));
        if (new_events == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->events = new_events;
        list->capacity = new_capacity;
    }

    FileDescriptorEvent event = {fd, event_type, callback};
    list->events[list->count++] = event;

    pthread_mutex_unlock(&list->lock);
}

void process_event(FileDescriptorEvent* event) {
    // Process the file descriptor based on its event type and call the corresponding callback function
    if (strcmp(event->event_type, "read") == 0) {
        event->callback(event->fd);
    } else if (strcmp(event->event_type, "write") == 0) {
        // Handle write events...
    } else if (strcmp(event->event_type, "error") == 0) {
        // Handle error events...
    }
}

void process_events(EventList* list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        process_event(&list->events[i]);
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_event_list(EventList* list) {
    free(list->events);
    pthread_mutex_destroy(&list->lock);
}
```
