typedef struct {
    int value;
} record;

record *records = NULL;
int records_size = 0;
int records_capacity = 0;
pthread_mutex_t lock;

void handle_error(const char* msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

void resize_records() {
    if (records == NULL) {
        records = malloc(sizeof(record));
        if (records == NULL) handle_error("Memory allocation failed");
        records_capacity = 1;
    } else {
        record *temp = realloc(records, 2 * records_capacity * sizeof(record));
        if (temp == NULL) handle_error("Memory reallocation failed");
        records = temp;
        records_capacity *= 2;
    }
}

void add_record(int value) {
    pthread_mutex_lock(&lock);
    if (records_size == records_capacity) resize_records();
    records[records_size++].value = value;
    pthread_mutex_unlock(&lock);
}

int find_largest() {
    int largest = INT_MIN;
    for (int i = 0; i < records_size; ++i) 
        if (records[i].value > largest) largest = records[i].value;
    return largest;
}

void read_and_store() {
    int value;
    while (scanf("%d", &value) == 1) add_record(value);
    printf("Largest integer: %d\n", find_largest());
}

int main() {
    pthread_mutex_init(&lock, NULL);
    read_and_store();
    free(records);
    pthread_mutex_destroy(&lock);
    return 0;
