['Here is an example of how you might implement this in C. This code does not include all the features you requested (like logging memory allocation/deallocation events to file or detecting potential memory fragmentation issues), but it provides a basic structure for handling dynamic lists and thread safety. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

typedef struct List {
    Node *head;
    pthread_mutex_t lock;
    size_t maxSize;
    size_t currentSize;
} List;

List* createList(size_t maxSize) {
    List *list = malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->maxSize = maxSize;
    list->currentSize = 0;
    return list;
}

void addRecord(List *list, Record *record) {
    if (pthread_mutex_lock(&list->lock)) {
        perror("Failed to lock mutex");
        exit(EXIT_FAILURE);
    }

    if (list->currentSize >= list->maxSize) {
        fprintf(stderr, "List is full\n");
        return;
    }

    Node *node = malloc(sizeof(Node));
    node->record = record;
    node->next = list->head;
    list->head = node;
    list->currentSize++;

    if (pthread_mutex_unlock(&list->lock)) {
        perror("Failed to unlock mutex");
        exit(EXIT_FAILURE);
    }
}

void destroyList(List *list) {
    Node *node = list->head;
    while (node != NULL) {
        Node *nextNode = node->next;
        free(node->record);
        free(node);
        node = nextNode;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}
```
This code creates a linked list structure with thread safety. It uses a mutex to ensure that only one thread can modify the list at a time, preventing potential race conditions and ensuring data integrity across concurrent accesses. The `addRecord` function checks if the list is full before adding a new record, and it handles potential overflow conditions by printing an error message and returning early.
']

