// Custom pseudo-random number generator
class PRNG {
public:
    PRNG(unsigned long seed) : state(seed & 0xFFFFFFFFFFFFFFFFLL) {}

    unsigned long next() {
        state = (state * multiplier + increment) & modulus;
        return state >> 32;
    }
private:
    static constexpr unsigned long multiplier = 0x5DEECE66DL;
    static constexpr unsigned long increment = 0xBL;
    static constexpr unsigned long modulus = (1L << 48);

    unsigned long state;
};

// Custom memory pool
class MemoryPool {
public:
    void* allocate(size_t size) {
        std::lock_guard<std::mutex> lock(mutex);
        void* ptr = malloc(size);
        if (ptr == nullptr) throw std::bad_alloc();
        allocated.push_back(ptr);
        return ptr;
    }

    void deallocate(void* ptr) {
        std::lock_guard<std::mutex> lock(mutex);
        free(ptr);
        auto it = std::find(allocated.begin(), allocated.end(), ptr);
        if (it != allocated.end()) allocated.erase(it);
    }

    ~MemoryPool() {
        for (void* ptr : allocated) free(ptr);
    }
private:
    std::mutex mutex;
    std::vector<void*> allocated;
};

// Custom hash-based solution for detecting duplicate keys
class DuplicateKeyDetector {
public:
    bool add(int key) {
        std::lock_guard<std::mutex> lock(mutex);
        return keys.insert({key, true}).second;
    }
private:
    std::unordered_map<int, bool> keys;
    std::mutex mutex;
};

// Custom record structure
