    ~dataProcessor() = default;

    // Methods for managing arrays of 'long' integers, 'int' keys, and 'record' structures
    void manageOffsets(std::vector<long>& offsets) {
        std::lock_guard<boost::shared_mutex> lock(offsetMutex);
        this->offsets = offsets;
    }

    bool addKey(int key) {
        return detector.add(key);
    }

    void manageRecords(std::vector<Record>& records) {
        std::lock_guard<boost::shared_mutex> lock(recordMutex);
        this->records = records;
    }

    // Methods for populating 'int' values with random numbers and computing MD5 hash of each unique file
    int getRandomNumber() {
        std::lock_guard<std::mutex> lock(prngMutex);
        return prng.next();
    }

    std::string computeMD5HashOfFile(const std::string& filename) {
        unsigned char c[MD5_DIGEST_LENGTH];
        MD5_CTX mdContext;
        int bytes;
        unsigned char data[1024];

        FILE *inFile = fopen (filename.c_str(), "rb");
        if (inFile == NULL) throw std::runtime_error("Could not open file: " + filename);

        MD5_Init(&mdContext);
        while ((bytes = fread(data, 1, 1024, inFile)) != 0) {
            MD5_Update(&mdContext, data, bytes);
        }
        MD5_Final(c, &mdContext);

        std::ostringstream sout;
        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            sout << std::hex << std::setw(2) << std::setfill('0') << (int)c[i];
        }

        return sout.str();
    }

private:
    MemoryPool pool;
    DuplicateKeyDetector detector;
    PRNG prng;

    boost::shared_mutex offsetMutex, recordMutex;
    std::vector<long> offsets;
    std::vector<Record> records;

    std::mutex prngMutex;
};
