#include <openssl/sha.h>
#include <pthread.h>
#include <string.h>
#include <stdlib.h>
#include <unistd.h>

#define BUFSIZE 1024*1024 // 1MB buffer size for file processing

typedef struct {
    int value;
} Record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void process_file(char *filename, unsigned char md5[MD5_DIGEST_LENGTH], unsigned char sha256[SHA256_DIGEST_LENGTH]) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Failed to open file\n");
        return;
    }

    MD5_CTX md5Context;
    SHA256_CTX sha256Context;
    MD5_Init(&md5Context);
    SHA256_Init(&sha256Context);

    unsigned char buffer[BUFSIZE];
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, BUFSIZE, file)) > 0) {
        MD5_Update(&md5Context, buffer, bytesRead);
        SHA256_Update(&sha256Context, buffer, bytesRead);
    }

    MD5_Final(md5, &md5Context);
    SHA256_Final(sha256, &sha256Context);

    fclose(file);
}

void *process_and_update(void *arg) {
    char *filename = (char *) arg;
    unsigned char md5[MD5_DIGEST_LENGTH];
    unsigned char sha256[SHA256_DIGEST_LENGTH];

    pthread_mutex_lock(&lock);
    process_file(filename, md5, sha256);
    // Update the database here...
    pthread_mutex_unlock(&lock);
}

void process_files_and_update_user_records(char **filenames, int numFiles) {
    pthread_t threads[numFiles];

    for (int i = 0; i < numFiles; i++) {
        if (pthread_create(&threads[i], NULL, process_and_update, filenames[i]) != 0) {
            printf("Failed to create thread\n");
            return;
        }
    }

