#include <stdio.h>
#include <pthread.h>
#include <sys/syslog.h>

typedef struct {
    long offset;
    int key;
    char status;
} Record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static size_t memoryUsage = 0;

void processRecord(Record* record) {
    // Process the record here.
}

void handleBatch(Record** batch, int batchSize) {
    for (int i = 0; i < batchSize; ++i) {
        pthread_mutex_lock(&lock);
        processRecord(batch[i]);
        memoryUsage -= sizeof(Record);
        syslog(LOG_INFO, "Memory usage: %zu bytes", memoryUsage);
        pthread_mutex_unlock(&lock);
    }
}

void* handleStream(void* arg) {
    Record** batch = (Record**)arg;
    int batchSize = 0;

    while (batch[batchSize] != NULL) {
        ++batchSize;
    }

    if (memoryUsage + sizeof(Record)*batchSize > 1024*1024) {
        syslog(LOG_ERR, "Memory limit exceeded!");
        return NULL;
    }

    pthread_mutex_lock(&lock);
    for (int i = 0; i < batchSize; ++i) {
        memoryUsage += sizeof(Record);
    }
    syslog(LOG_INFO, "Memory usage: %zu bytes", memoryUsage);
    pthread_mutex_unlock(&lock);

    handleBatch(batch, batchSize);

    return NULL;
}

void processStream(Record** stream) {
    int i = 0;
    while (stream[i] != NULL) {
        Record* batch[101]; // 100 records plus the null terminator.
        for (int j = 0; j < 100 && stream[i] != NULL; ++j, ++i) {
            batch[j] = stream[i];
        }
        batch[i > 100 ? 100 : i] = NULL; // Null terminate the batch.

        pthread_t thread;
        if (pthread_create(&thread, NULL, handleStream, batch) != 0) {
            syslog(LOG_ERR, "Failed to create thread!");
            continue;
        }

        // Wait for 1 second before processing the next batch.
        struct timespec ts = {1, 0};
        nanosleep(&ts, NULL);
    }
}
```
