['Here is a basic implementation of your requirements in C++ using STL containers and mutexes for thread safety. This code does not include all the features you requested (like dynamic sensor intake rate adjustment based on system load or integration with an external data processing pipeline), but it should give you a good starting point:

```cpp
#include <vector>
#include <mutex>
#include <stdexcept>
#include <chrono>
#include <regex>

class SensorDevice {
public:
    std::string deviceID;
    std::string location;
    std::time_t lastSeenTimestamp;
    double sensorData;
};

class SensorManager {
private:
    std::vector<SensorDevice> sensors;
    std::mutex mtx;
    const std::regex geoConstraints = std::regex("^[A-Za-z]+, [A-Z]{2}$"); // Example regex for US locations
public:
    void addSensor(const SensorDevice& sensor) {
        std::lock_guard<std::mutex> lock(mtx);

        if (sensors.size() >= UINT16_MAX) {
            throw std::runtime_error("Too many sensors");
        }

        for (const auto& s : sensors) {
            if (sensor.deviceID == s.deviceID) {
                throw std::invalid_argument("Duplicate device ID: " + sensor.deviceID);
            }
        }

        if (!std::regex_match(sensor.location, geoConstraints)) {
            throw std::invalid_argument("Invalid location format");
        }

        sensors.push_back(sensor);
    }

    SensorDevice getSensor(const std::string& deviceID) {
        std::lock_guard<std::mutex> lock(mtx);

        for (const auto& sensor : sensors) {
            if (sensor.deviceID == deviceID) {
                return sensor;
            }
        }

        throw std::invalid_argument("No such device ID: " + deviceID);
    }

    void removeSensor(const std::string& deviceID) {
        std::lock_guard<std::mutex> lock(mtx);

        for (auto it = sensors.begin(); it != sensors.end(); ++it) {
            if (it->deviceID == deviceID) {
                sensors.erase(it);
                return;
            }
        }

        throw std::invalid_argument("No such device ID: " + deviceID);
    }
};
```
