typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    pthread_mutex_t mutex;
} DataStructure;

DataStructure* createDataStructure(size_t size) {
    srand((unsigned int)time(NULL));

    DataStructure* ds = malloc(sizeof(DataStructure));
    if (ds == NULL) return NULL;

    ds->offsets = malloc(size * sizeof(long));
    ds->keys = malloc(size * sizeof(int));
    ds->records = malloc(size * sizeof(Record*));

    if (ds->offsets == NULL || ds->keys == NULL || ds->records == NULL) {
        freeDataStructure(ds);
        return NULL;
    }

    pthread_mutex_init(&ds->mutex, NULL);

    for (size_t i = 0; i < size; ++i) {
        ds->offsets[i] = rand();
        ds->keys[i] = rand();

        Record* record = malloc(sizeof(Record));
        if (record == NULL) {
            freeDataStructure(ds);
            return NULL;
        }

        record->value = rand();
        ds->records[i] = record;
    }

    return ds;
}

void freeDataStructure(DataStructure* ds) {
    if (ds == NULL) return;

    pthread_mutex_destroy(&ds->mutex);

    for (size_t i = 0; i < size; ++i) {
        free(ds->records[i]);
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds);
}
