    int priority;
    int stock_quantity;
    float price;
    char category[20];
} item_info;

typedef struct transaction {
    time_t purchase_date;
    int customer_id;
    float transaction_amount;
} transaction;

typedef struct data_stream {
    pthread_mutex_t lock;
    char *buffer;
    size_t buffer_size;
    size_t buffer_used;
} data_stream;

data_stream* create_data_stream(size_t initial_size) {
    data_stream *ds = malloc(sizeof(data_stream));
    if (ds == NULL) return NULL;

    ds->buffer = malloc(initial_size);
    if (ds->buffer == NULL) {
        free(ds);
        return NULL;
    }

    ds->buffer_size = initial_size;
    ds->buffer_used = 0;
    pthread_mutex_init(&ds->lock, NULL);

    return ds;
}

void destroy_data_stream(data_stream *ds) {
    free(ds->buffer);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

int add_to_data_stream(data_stream *ds, void *data, size_t data_size) {
    pthread_mutex_lock(&ds->lock);

    if (ds->buffer_used + data_size > ds->buffer_size) {
        size_t new_size = ds->buffer_size * 2;
        while (new_size < ds->buffer_used + data_size)
            new_size *= 2;

        void *new_buffer = realloc(ds->buffer, new_size);
        if (new_buffer == NULL) {
            pthread_mutex_unlock(&ds->lock);
            return -1;
        }

        ds->buffer = new_buffer;
        ds->buffer_size = new_size;
    }

    memcpy(ds->buffer + ds->buffer_used, data, data_size);
    ds->buffer_used += data_size;

    pthread_mutex_unlock(&ds->lock);
    return 0;
}
```
