    if (taskMap.find(id) != taskMap.end()) {
        taskMap[id]->priority = newPriority;
    } else {
        // handle case where task with given id does not exist
    }
}

void cleanupTasks() {
    std::lock_guard<std::mutex> lock(mapMutex); // ensure thread safety

    for (auto& kv : taskMap) {
