["Here's an example of how you might implement this in C. This code does not include all the features mentioned, but it provides a starting point for implementing these features. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    double value;
    time_t timestamp;
    int sourceId;
} data_point;

typedef struct {
    data_point **buffer;
    size_t head;
    size_t tail;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} circular_buffer;

circular_buffer *create_buffer(size_t capacity) {
    circular_buffer *buf = malloc(sizeof(circular_buffer));
    if (buf == NULL) return NULL;

    buf->buffer = calloc(capacity, sizeof(data_point*));
    if (buf->buffer == NULL) {
        free(buf);
        return NULL;
    }

    buf->head = 0;
    buf->tail = 0;
    buf->count = 0;
    buf->capacity = capacity;
    pthread_mutex_init(&buf->lock, NULL);

    return buf;
}

void destroy_buffer(circular_buffer *buf) {
    for (size_t i = 0; i < buf->count; ++i) {
        free(buf->buffer[(buf->tail + i) % buf->capacity]);
    }

    pthread_mutex_destroy(&buf->lock);
    free(buf->buffer);
    free(buf);
}

void add_data_point(circular_buffer *buf, data_point *dp) {
    pthread_mutex_lock(&buf->lock);

    if (buf->count == buf->capacity) {
        // Buffer is full, remove oldest element
        free(buf->buffer[buf->tail]);
        buf->tail = (buf->tail + 1) % buf->capacity;
        --buf->count;
    }

    buf->buffer[buf->head] = dp;
    buf->head = (buf->head + 1) % buf->capacity;
    ++buf->count;

    pthread_mutex_unlock(&buf->lock);
}
```
This is a basic circular buffer implementation. It uses a mutex to ensure thread safety when adding data points. The `add_data_point` function will remove the oldest element if the buffer is full before adding a new one. 

