#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    time_t timestamp;
    int status;
} record;

record **records;
int *keys;
long *offsets;
int size = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* process(void* arg) {
    int value = *((int*)arg);

    pthread_mutex_lock(&lock);
    size++;
    records = realloc(records, sizeof(record*) * size);
    keys = realloc(keys, sizeof(int) * size);
    offsets = realloc(offsets, sizeof(long) * size);

    record* new_record = malloc(sizeof(record));
    if (new_record == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    new_record->value = value;
    new_record->timestamp = time(NULL);
    new_record->status = 0;

    records[size - 1] = new_record;
    keys[size - 1] = size - 1;
    offsets[size - 1] = (long)new_record;

    pthread_mutex_unlock(&lock);

    return NULL;
}

int main() {
    srand(time(NULL));

    int n = 10; // number of integers to read
    pthread_t threads[n];
    int values[n];

    for (int i = 0; i < n; i++) {
        values[i] = rand() % 100; // generate random integer within a specified range

        if (pthread_create(&threads[i], NULL, process, &values[i])) {
            printf("Thread creation failed\n");
            return 1;
        }
    }

    for (int i = 0; i < n; i++) {
        if (pthread_join(threads[i], NULL)) {
            printf("Thread join failed\n");
            return 1;
        }
    }

    // print records
    for (int i = 0; i < size; i++) {
        printf("Key: %d, Value: %d, Timestamp: %ld, Status: %d\n", keys[i], records[i]->value, offsets[i], records[i]->status);
    }

    // free memory
    for (int i = 0; i < size; i++) {
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);

    return 0;
}
```
