    float min, max, avg;
} stats;

typedef struct buffer {
    pthread_mutex_t lock;
    sensor_data *data;
    int size;
    int count;
    stats stat;
} buffer;

buffer* createBuffer(int size) {
    buffer *buf = malloc(sizeof(buffer));
    if (buf == NULL) return NULL;

    buf->data = malloc(sizeof(sensor_data) * size);
    if (buf->data == NULL) {
        free(buf);
        return NULL;
    }

    pthread_mutex_init(&buf->lock, NULL);
    buf->size = size;
    buf->count = 0;
    buf->stat.min = FLT_MAX;
    buf->stat.max = -FLT_MAX;
    buf->stat.avg = 0;

    return buf;
}

void addData(buffer *buf, sensor_data data) {
    pthread_mutex_lock(&buf->lock);

    if (buf->count == buf->size) {
        // handle buffer full scenario here
    } else {
        buf->data[buf->count++] = data;

        if (data.temp < buf->stat.min) buf->stat.min = data.temp;
        if (data.temp > buf->stat.max) buf->stat.max = data.temp;

        float sum = 0;
        for(int i=0; i<buf->count; i++) {
            sum += buf->data[i].temp;
        }
        buf->stat.avg = sum / buf->count;
    }

    pthread_mutex_unlock(&buf->lock);
}

void freeBuffer(buffer *buf) {
    pthread_mutex_destroy(&buf->lock);
    free(buf->data);
    free(buf);
}
```
