["Here is an example of how you could implement this task in C, using a lock-free approach with a resizing strategy that doubles the size of the hash table when it reaches 75% capacity to minimize rehashing overheads. This code does not include error checking for memory allocation failures or other potential issues, which would be necessary for a production environment:

```c
#include <stdlib.h>
#include <string.h>
#include <stdatomic.h>

typedef struct config {
    // Define your configuration structure here
} Config;

typedef struct data {
    char* string;
    double value;
    Config config;
    atomic_int identifier;
} Data;

typedef struct hash_table {
    Data** table;
    size_t capacity;
    size_t count;
    atomic_flag resize_lock;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* ht = malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->table = calloc(initial_capacity, sizeof(Data*));
    if (!ht->table) {
        free(ht);
        return NULL;
    }

    ht->capacity = initial_capacity;
    ht->count = 0;
    atomic_flag_clear(&ht->resize_lock);

    return ht;
}

void destroy_hash_table(HashTable* ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        if (ht->table[i]) free(ht->table[i]);
    }

    free(ht->table);
    free(ht);
}

int insert_data(HashTable* ht, Data* data) {
    if ((double) ht->count / ht->capacity > 0.75) {
        // Resize the hash table when it reaches 75% capacity
        atomic_flag_test_and_set(&ht->resize_lock);

        if ((double) ht->count / ht->capacity > 0.75) {
            size_t new_capacity = ht->capacity * 2;
            Data** new_table = calloc(new_capacity, sizeof(Data*));

            if (!new_table) return -1; // Memory allocation failure

            for (size_t i = 0; i < ht->count; ++i) {
                size_t index = hash(ht->table[i]->identifier) % new_capacity;

                while (new_table[index]) {
                    index = (index + 1) % new_capacity;
                }

                new_table[index] = ht->table[i];
            }

            free(ht->table);
            ht->table = new_table;
            ht->capacity = new_capacity;
        }

        atomic_flag_clear(&ht->resize_lock);
    }

    size_t index = hash(data->identifier) % ht->capacity;

    while (ht->table[index]) {
        index = (index + 1) % ht->capacity;
    }

    ht->table[index] = data;
    atomic_fetch_add(&ht->count, 1);

    return 0; // Success
}
```

This is a simplified example and does not include all the features you requested. For instance, it doesn't handle memory allocation failures or provide thread safety for concurrent access. You would need to add these features in a production environment. Also, this code assumes that `hash` function exists which maps an identifier to a hash value.
"]

