    net::io_context ioc;
    tcp::resolver resolver{ioc};
    websocket::stream<beast::tcp_stream> ws{ioc};

    auto const results = resolver.resolve(url, "80");
    beast::get_lowest_layer(ws).connect(results);
    ws.handshake(url, "/");

    while (true) {
        beast::flat_buffer buffer;
        ws.read(buffer);

        std::string receivedMessage = boost::beast::buffers_to_string(buffer.data());
        nlohmann::json messageJson = nlohmann::json::parse(receivedMessage);

        if (messageJson["topic"] == topic) {
            // Process the message here...

            std::unique_lock<std::mutex> lck(mtx);
            ready = true;
            cv.notify_all();
        }
    }
}

int main() {
    spdlog::info("Starting WebSocket client...");

    std::thread t1(subscribeToWebSocketEvents, "ws://example.com", "topic");

    // Wait for the thread to finish
    t1.join();

    return 0;
}
```
