Device* newNode(int item) {
    Device* temp = (Device*) malloc(sizeof(Device));
    if (!temp) {
        printf("Memory allocation failed.\n");
        exit(1);
    }

    temp->id = item;
    temp->voltage_reading = 0.0f;
    // initialize settings as needed
    temp->left = temp->right = NULL;
    return temp;
}

Device* insert(Device* node, int id) {
    if (node == NULL) 
        return newNode(id);

    if (id < node->id)
        node->left  = insert(node->left, id);
    else if (id > node->id)
        node->right = insert(node->right, id);

    return node;
}

Device* minValueNode(Device* node) {
    Device* current = node;
    while (current && current->left != NULL)
        current = current->left;

    return current;
}

Device* deleteNode(Device* root, int id) {
    if (root == NULL) 
        return root;

    if (id < root->id)
        root->left = deleteNode(root->left, id);
    else if(id > root->id)
        root->right = deleteNode(root->right, id);
    else {
        if (root->left == NULL) {
            Device* temp = root->right;
            free(root);
            return temp;
        } 
        else if (root->right == NULL) {
            Device* temp = root->left;
            free(root);
            return temp;
        }

        Device* temp = minValueNode(root->right);
        root->id = temp->id;
        root->right = deleteNode(root->right, temp->id);
    }

    return root;
}

Device* search(Device* root, int id) {
    if (root == NULL || root->id == id)
       return root;

    if (root->id < id)
       return search(root->right, id);

    return search(root->left, id);
}
```

