void allocate_and_initialize(long *offsets, int offsetSize, int *keys, int keySize, 
                             Record **records, int recordSize, char distributionType) {
    srand(time(0)); // seed the random number generator

    if (distributionType == 'u') {
        for (int i = 0; i < offsetSize; ++i) {
            offsets[i] = rand() % 1000; // uniform distribution between 0 and 999
        }

        for (int i = 0; i < keySize; ++i) {
            keys[i] = rand() % 1000 + 1; // uniform distribution between 1 and 1000
        }
    } else if (distributionType == 'w') {
        int totalWeight = 0;
        for (int i = 0; i < keySize; ++i) {
            keys[i] = rand() % 1000 + 1; // uniform distribution between 1 and 1000
            totalWeight += keys[i];
        }

        for (int i = 0; i < offsetSize; ++i) {
            int randomNum = rand() % totalWeight;
            int sum = 0;
            for (int j = 0; j < keySize; ++j) {
                sum += keys[j];
                if (sum > randomNum) {
                    offsets[i] = j; // weighted distribution based on keys
                    break;
                }
            }
        }
    } else {
        printf("Invalid distribution type. Please use 'u' for uniform or 'w' for weighted.\n");
        exit(1);
    }

    for (int i = 0; i < recordSize; ++i) {
        records[i] = malloc(sizeof(Record)); // allocate memory for each record
        records[i]->value = rand() % 1000 + 1; // initialize value with a random number between 1 and 1000
    }
}
