class DataProcessor {
public:
    DataProcessor() : nodeList(), nodeMap(), memPool(), updateQueue(), mutex(), condVar(), thread(&DataProcessor::updateThread, this) {}

    ~DataProcessor() {
        // Stop the update thread and join it
        stop = true;
        condVar.notify_all();
        thread.join();
    }

    void addNode(NetworkNode node) {
        std::unique_lock<std::shared_mutex> lock(mutex);

        // Check if the nodeID is unique and location format is valid
        if (nodeMap.find(node.nodeID) != nodeMap.end() || !validateLocationFormat(node.location)) {
            throw std::runtime_error("Invalid node");
        }

        // Add the node to the list and map
        nodeList.push_back(node);
        nodeMap[node.nodeID] = --nodeList.end();
    }

    void updateNodeStatus(int nodeID, bool status) {
        std::unique_lock<std::shared_mutex> lock(mutex);

        // Check if the node exists and add an update to the queue
        auto it = nodeMap.find(nodeID);
        if (it != nodeMap.end()) {
            (*it->second).status = status;
            updateQueue.push({nodeID, status});
            condVar.notify_one();
        } else {
            throw std::runtime_error("Node not found");
        }
    }

private:
    struct Update {
        int nodeID;
        bool status;
    };

    std::vector<NetworkNode> nodeList;
    std::unordered_map<int, decltype(nodeList)::iterator> nodeMap;
    MemoryPool memPool;
    boost::lockfree::queue<Update> updateQueue;
    std::shared_mutex mutex;
    std::condition_variable condVar;
    std::atomic<bool> stop{false};
    std::thread thread;

    void updateThread() {
        while (!stop) {
            Update update;

            // Wait for an update or a stop signal
            {
                std::unique_lock<std::shared_mutex> lock(mutex);
                condVar.wait(lock, [this] { return !updateQueue.empty() || stop; });

                if (stop) {
                    break;
                }

                updateQueue.pop(update);
            }

            // Update the node status and handle network failures
            try {
                (*nodeMap[update.nodeID]).status = update.status;
            } catch (const std::exception& e) {
                BOOST_LOG_TRIVIAL(error) << "Network failure: " << e.what();
            }
        }
    }

    bool validateLocationFormat(const std::string& location) {
