["Here's an example of how you might implement such a data structure in C using a hash table with open addressing (linear probing) as the collision resolution method. This approach minimizes memory usage by avoiding pointers and instead storing entries directly within the array. It also uses atomic operations for thread safety, ensuring that updates and inserts are performed without blocking other threads.

```c
#include <stdatomic.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* key;
    double value;
} Entry;

typedef struct {
    atomic_int count;
    atomic_int capacity;
    Entry* entries;
} HashTable;

HashTable* create_table(int initialCapacity) {
    HashTable* table = malloc(sizeof(HashTable));
    table->count = 0;
    table->capacity = initialCapacity;
    table->entries = calloc(initialCapacity, sizeof(Entry));
    return table;
}

void destroy_table(HashTable* table) {
    for (int i = 0; i < table->capacity; ++i) {
        free(table->entries[i].key);
    }
    free(table->entries);
    free(table);
}

unsigned long hash_function(const char* key, int capacity) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % capacity;
}

void insert(HashTable* table, const char* key, double value) {
    if (table->count >= table->capacity / 2) {
        resize_table(table);
    }

    unsigned long index = hash_function(key, table->capacity);
    while (1) {
        Entry* entry = &table->entries[index];

        if (!entry->key || strcmp(entry->key, key) == 0) {
            free(entry->key);
            entry->key = strdup(key);
            atomic_store(&entry->value, value);
            ++table->count;
            return;
        }

        index = (index + 1) % table->capacity;
    }
}

double* lookup(HashTable* table, const char* key) {
    unsigned long index = hash_function(key, table->capacity);

    for (int i = 0; i < table->capacity; ++i) {
        Entry* entry = &table->entries[index];

        if (!entry->key || strcmp(entry->key, key) == 0) {
            return &entry->value;
        }

        index = (index + 1) % table->capacity;
    }

    return NULL;
}

void resize_table(HashTable* table) {
    int newCapacity = table->capacity * 2;
    Entry* newEntries = calloc(newCapacity, sizeof(Entry));

    for (int i = 0; i < table->capacity; ++i) {
        Entry* entry = &table->entries[i];

        if (!entry->key) {
            continue;
        }

        unsigned long index = hash_function(entry->key, newCapacity);

        while (1) {
            Entry* newEntry = &newEntries[index];

            if (!newEntry->key) {
                newEntry->key = strdup(entry->key);
                atomic_store(&newEntry->value, entry->value);
                break;
            }

            index = (index + 1) % newCapacity;
        }
    }

    free(table->entries);
    table->entries = newEntries;
    table->capacity = newCapacity;
}
```
This is a basic implementation and may need to be adjusted based on specific requirements. For example, you might want to add error checking or handle edge cases such as when the hash table becomes full. Also, this code does not include any concurrency control mechanisms for thread safety, which would require additional work depending on your specific use case.
"]

