typedef struct {
    int value;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
} Metadata;

Metadata* allocate_memory(size_t arraySize, size_t recordSize, size_t budget) {
    assert(arraySize <= (budget / sizeof(long)) && "Array size exceeds memory budget");
    assert(recordSize <= (budget / sizeof(Record)) && "Record size exceeds memory budget");

    Metadata *metadata = malloc(sizeof(Metadata));
    if (!metadata) {
        return NULL; // Out of memory
    }

    metadata->offsets = calloc(arraySize, sizeof(long));
    if (!metadata->offsets) {
        free(metadata);
        return NULL; // Out of memory
    }

    metadata->keys = calloc(arraySize, sizeof(int));
    if (!metadata->keys) {
        free(metadata->offsets);
        free(metadata);
        return NULL; // Out of memory
    }

    metadata->records = malloc(recordSize * sizeof(Record*));
    if (!metadata->records) {
        free(metadata->keys);
        free(metadata->offsets);
        free(metadata);
        return NULL; // Out of memory
    }

    for (size_t i = 0; i < recordSize; ++i) {
        metadata->records[i] = malloc(sizeof(Record));
        if (!metadata->records[i]) {
            // Clean up previously allocated records
            while (i-- > 0) {
                free(metadata->records[i]);
            }

            free(metadata->keys);
            free(metadata->offsets);
            free(metadata);
            return NULL; // Out of memory
        }
    }

    return metadata;
}
```
