['Here is a basic implementation of a hash table in C with some of the features you mentioned. This code does not include all the features you asked for like concurrency control, resource management, scalability, performance optimization etc. These are complex topics and would require a lot more code to fully implement. 

```c
#include <stdlib.h>
#include <string.h>

typedef struct entry_t {
    char* key;
    double value;
    struct entry_t* next;
} entry_t;

typedef struct hashmap_t {
    int size;
    entry_t** table;
} hashmap_t;

hashmap_t* create_hashmap(int size) {
    hashmap_t* new_map = malloc(sizeof(hashmap_t));
    new_map->size = size;
    new_map->table = malloc(sizeof(entry_t*) * size);
    memset(new_map->table, 0, sizeof(entry_t*) * size);
    return new_map;
}

unsigned int hash(char* key) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % HASH_SIZE;
}

void put(hashmap_t* map, char* key, double value) {
    unsigned int index = hash(key);
    entry_t* new_entry = malloc(sizeof(entry_t));
    new_entry->key = strdup(key);
    new_entry->value = value;
    new_entry->next = map->table[index];
    map->table[index] = new_entry;
}

double get(hashmap_t* map, char* key) {
    unsigned int index = hash(key);
    entry_t* current = map->table[index];

    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            return current->value;
        }
        current = current->next;
    }

    return 0.0; // or throw an exception
}
```
This is a very basic hash table implementation and does not include many of the features you asked for like concurrency control, resource management, scalability, performance optimization etc. These are complex topics and would require a lot more code to fully implement.
