int add_measurement(char key, double value) {
    pthread_mutex_lock(&lock);
    ++num_measurements;
    measurements = realloc(measurements, num_measurements * sizeof(KeyMeasurementPair*));
    if (measurements == NULL) {
        --num_measurements;
        pthread_mutex_unlock(&lock);
        return -1; // Error: Memory allocation failed.
    }

    KeyMeasurementPair* pair = malloc(sizeof(KeyMeasurementPair));
    if (pair == NULL) {
        --num_measurements;
        pthread_mutex_unlock(&lock);
        return -1; // Error: Memory allocation failed.
    }

    Measurement* measurement = malloc(sizeof(Measurement));
    if (measurement == NULL) {
        free(pair);
        --num_measurements;
        pthread_mutex_unlock(&lock);
        return -1; // Error: Memory allocation failed.
    }

    pair->key = key;
    pair->measurement = measurement;
    measurements[num_measurements - 1] = pair;

    measurement->value = value;

    pthread_mutex_unlock(&lock);
    return 0; // Success.
}
