    if (ts == NULL) return NULL;

    ts->sensor_readings = calloc(num_sensors, sizeof(float));
    ts->event_types = calloc(num_types, sizeof(char));
    ts->event_logs = malloc(num_logs * sizeof(event_log));
    ts->handlers = malloc(num_handlers * sizeof(event_handler*));

    if (ts->sensor_readings == NULL || ts->event_types == NULL || 
        ts->event_logs == NULL || ts->handlers == NULL) {
        free_telemetry(ts);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num_logs; ++i) {
        ts->event_logs[i].timestamp = rand();
        ts->event_logs[i].type_index = rand() % num_types;
        ts->event_logs[i].payload_size = rand() % 1024;
    }

    for (int i = 0; i < num_handlers; ++i) {
        ts->handlers[i] = malloc(sizeof(event_handler));
        if (ts->handlers[i] == NULL) {
            free_telemetry(ts);
            return NULL;
        }
        pthread_mutex_init(&ts->handlers[i]->lock, NULL);
    }

    return ts;
}

void free_telemetry(telemetry_system *ts) {
    if (ts == NULL) return;

    for (int i = 0; i < num_handlers; ++i) {
        pthread_mutex_destroy(&ts->handlers[i]->lock);
        free(ts->handlers[i]);
    }

    free(ts->sensor_readings);
    free(ts->event_types);
    free(ts->event_logs);
    free(ts->handlers);
    free(ts);
}
```
