using log4net;

public class MyService
{
    private static readonly ILog Logger = LogManager.GetLogger(typeof(MyService));
    private static string _envVarPath;
    private static object _lockObject = new object();

    public void EnsureEnvironmentVariableSet()
    {
        if (string.IsNullOrEmpty(_envVarPath))
        {
            lock (_lockObject)
            {
                if (string.IsNullOrEmpty(_envVarPath))
                {
                    string appVersion = ConfigurationManager.AppSettings["appVersion"];
                    _envVarPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData), "MyService", appVersion);
                    Environment.SetEnvironmentVariable("MY_SERVICE_PATH", _envVarPath, EnvironmentVariableTarget.Machine);
                    Logger.InfoFormat("Created directory {0} and set environment variable MY_SERVICE_PATH to its path.", _envVarPath);
                }
            }
        }
    }

    public string GetConfigParameter(string paramName)
    {
        try
        {
            EnsureEnvironmentVariableSet();

            XDocument doc = XDocument.Load(Path.Combine(_envVarPath, "config.xml"));
            var element = doc.Descendants("configuration").Elements().FirstOrDefault(e => e.Name == paramName);

            if (element == null)
                throw new Exception(string.Format("No configuration parameter named {0} found.", paramName));

            return element.Value;
        }
        catch (Exception ex)
        {
            Logger.Error("Failed to parse XML configuration file", ex);
            throw;
        }
    }
}
```
