typedef struct Node {
    char data;
    struct Node* next;
} Node;

Node* create_node(char data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        exit(0);
    }

    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

Node* insert_node(Node* head, char data) {
    if (!head) {
        return create_node(data);
    } else {
        Node* temp = head;
        while (temp->next != NULL) {
            temp = temp->next;
        }

        temp->next = create_node(data);
        return head;
    }
}

void traverse_list(Node* head) {
    Node* temp = head;
    while (temp != NULL) {
        printf("%c ", temp->data);
        temp = temp->next;
    }
    printf("\n");
}

int main() {
    Node* head = NULL;

    // Insert nodes
    for(char c = 'a'; c <= 'z'; ++c) {
        head = insert_node(head, c);
    }

    traverse_list(head);

    return 0;
}
```
