clock_t start;
int requestCount = 0;

void rateLimit() {
    if (requestCount == 0) {
        start = clock();
    } else if (requestCount == MAX_REQUESTS) {
        double elapsedTime = ((double)clock() - start) / CLOCKS_PER_SEC;

        // If we've made the maximum requests in less than a second, sleep until next second
        if (elapsedTime < 1.0) {
