// Define the NetworkNode structure
typedef struct {
    int nodeID;
    char location[3]; // ISO 3166-1 alpha-2 standard
    int status;
} NetworkNode;

// Define a dynamic list of nodes
typedef struct {
    NetworkNode* nodes;
    size_t length;
    size_t capacity;
    pthread_mutex_t lock; // for thread safety
} NodeList;

// Initialize the node list
void init(NodeList* nl) {
    nl->nodes = malloc(sizeof(NetworkNode));
    nl->length = 0;
    nl->capacity = 1;
    pthread_mutex_init(&nl->lock, NULL); // initialize the lock
}

// Add a node to the list
void addNode(NodeList* nl, NetworkNode n) {
    pthread_mutex_lock(&nl->lock); // acquire the lock

    if (nl->length == nl->capacity) {
        nl->capacity *= 2;
        nl->nodes = realloc(nl->nodes, nl->capacity * sizeof(NetworkNode));
    }

    // Check for unique nodeID and valid location format (ISO 3166-1 alpha-2)
    if (!isalpha(n.location[0]) || !isalpha(n.location[1])) {
        printf("Invalid location format\n");
        return;
    }

    for (size_t i = 0; i < nl->length; ++i) {
        if (nl->nodes[i].nodeID == n.nodeID) {
            printf("Duplicate nodeID\n");
