#define MAX_DEPTH 10 // Maximum depth of nested logs

typedef struct {
    char *buffer;
    int depth;
} LogData;

void logMessage(char *format, ...) {
    va_list args;
    va_start(args, format);

    LogData *data = malloc(sizeof(LogData));
    data->buffer = malloc(1024); // Initial buffer size
    data->depth = 0;

    while (vsnprintf(data->buffer, 1024, format, args) >= 1024 && data->depth < MAX_DEPTH) {
        // Buffer was not large enough. Double the size and try again.
        free(data->buffer);
        data->buffer = malloc(strlen(data->buffer) * 2 + 1);
        data->depth++;
    }

    va_end(args);

    // Asynchronous logging using pthreads.
    pthread_t thread;
    if (pthread_create(&thread, NULL, logMessageAsync, data) != 0) {
        perror("Failed to create thread");
        free(data->buffer);
        free(data);
    } else {
        // Detach the thread so we don't have to join it.
        pthread_detach(thread);
    }
}

void *logMessageAsync(void *arg) {
    LogData *data = (LogData *) arg;

