["This task is quite complex and requires a deep understanding of C programming, concurrency, memory management, and data structures. Here's an outline of how you might approach this problem using pthreads for threading, OpenMP for parallelism, and a custom hash table implementation for efficient key-based access. 

Please note that the actual code would be much longer and more complex due to the many details involved in implementing such a system. This is just an outline of how you might approach it:

```c
#include <stdlib.h>
#include <pthread.h>
#include <omp.h>

typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

typedef struct HashTable {
    pthread_mutex_t lock;
    Record** records;
    size_t capacity;
    size_t count;
} HashTable;

HashTable* create_table(size_t initial_capacity) {
    // Initialize the hash table and its mutex.
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    table->records = calloc(initial_capacity, sizeof(Record*));
    if (table->records == NULL) {
        free(table);
        return NULL;
    }

    table->capacity = initial_capacity;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void destroy_table(HashTable* table) {
    // Free all records and the hash table itself.
    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->records[i] != NULL) free(table->records[i]);
    }

    pthread_mutex_destroy(&table->lock);
    free(table->records);
    free(table);
}

int insert_record(HashTable* table, Record* record) {
    // Acquire the lock and insert the record.
    pthread_mutex_lock(&table->lock);

    if (table->count >= table->capacity * 0.75) {
        // Resize the hash table when it's over 75% full.
        size_t new_capacity = table->capacity * 2;
        Record** new_records = calloc(new_capacity, sizeof(Record*));

        if (new_records == NULL) {
            pthread_mutex_unlock(&table->lock);
            return -1; // Error: Failed to allocate memory.
        }

        for (size_t i = 0; i < table->capacity; ++i) {
            if (table->records[i] != NULL) {
                size_t index = table->records[i]->key % new_capacity;

                while (new_records[index] != NULL) {
                    index = (index + 1) % new_capacity;
                }

                new_records[index] = table->records[i];
            }
        }

        free(table->records);
        table->records = new_records;
        table->capacity = new_capacity;
    }

    size_t index = record->key % table->capacity;

    while (table->records[index] != NULL) {
        if (table->records[index]->key == record->key) {
            pthread_mutex_unlock(&table->lock);
            return -2; // Error: Duplicate key.
        }

        index = (index + 1) % table->capacity;
    }

    table->records[index] = record;
    ++table->count;

    pthread_mutex_unlock(&table->lock);
    return 0; // Success.
}
```
This is just a basic outline and doesn't include all the details you requested, but it should give you a good starting point for implementing this kind of system in C. You would need to add more code to handle errors, manage memory usage, and implement concurrency control mechanisms such as atomic operations or lock-free data structures where appropriate.
