typedef struct {
    char* name;
    sem_t sem;
} Semaphore;

Semaphore** semaphores = NULL;
int num_semaphores = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void create_semaphore(char* name, int value) {
    pthread_mutex_lock(&lock);

    semaphores = realloc(semaphores, (num_semaphores + 1) * sizeof(Semaphore*));
    Semaphore* new_semaphore = malloc(sizeof(Semaphore));
    new_semaphore->name = name;
    sem_init(&new_semaphore->sem, 0, value);

    semaphores[num_semaphores++] = new_semaphore;

    pthread_mutex_unlock(&lock);
}

void delete_semaphore(char* name) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < num_semaphores; ++i) {
        if (strcmp(semaphores[i]->name, name) == 0) {
            sem_destroy(&semaphores[i]->sem);
            free(semaphores[i]);

            // Shift all elements after the deleted one to fill the gap.
            for (int j = i; j < num_semaphores - 1; ++j) {
                semaphores[j] = semaphores[j + 1];
            }

            --num_semaphores;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void modify_semaphore(char* name, int value) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < num_semaphores; ++i) {
        if (strcmp(semaphores[i]->name, name) == 0) {
            sem_destroy(&semaphores[i]->sem);
            sem_init(&semaphores[i]->sem, 0, value);
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}
