void batchUpdateWithValidationAndConcurrency(std::vector<int>& vec, const std::map<int, std::string>& updates) {
    std::lock_guard<std::mutex> lock(mtx); // acquire mutex

    for (const auto& update : updates) {
        int key = update.first;
        std::string value = update.second;

        if (key < 0) {
            key = 0;
        } else if (key >= vec.size()) {
            key = vec.size() - 1;
        }

        // Check cache first
        auto it = cache.find(key);
        if (it != cache.end() && it->second == value) {
            continue;
        }

        // Update vector and cache
        vec[key] = value;
        cache[key] = value;
    }

    blueslip = false; // reset mock object
    blueslip = true; // reinitialize mock object
}
