["This task is quite complex and requires a deep understanding of system architecture, concurrency, memory management, caching, logging, profiling, and advanced data structures. Here's an outline of how you might approach this problem in C:

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    unsigned long offset;
    int key;
    record* data;
    pthread_mutex_t lock;
    time_t lastAccessed;
    int accessFrequency;
    // Add more fields as needed
} metadata;

metadata** database = NULL;
pthread_rwlock_t dbLock = PTHREAD_RWLOCK_INITIALIZER;

void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        // Handle memory allocation failure gracefully
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initializeDatabase() {
    database = allocateMemory(100000 * sizeof(metadata*));
    for (int i = 0; i < 100000; ++i) {
        database[i] = NULL;
    }
}

record* createRecord(int value) {
    record* rec = allocateMemory(sizeof(record));
    rec->value = value;
    return rec;
}

metadata* createMetadata() {
    metadata* meta = allocateMemory(sizeof(metadata));
    // Initialize fields as needed
    pthread_mutex_init(&meta->lock, NULL);
    return meta;
}

void insertRecord(int key, int value) {
    if (database[key] != NULL) {
        // Handle duplicate keys gracefully
        return;
    }

    pthread_rwlock_wrlock(&dbLock);
    database[key] = createMetadata();
    database[key]->data = createRecord(value);
    pthread_rwlock_unlock(&dbLock);
}

record* getRecord(int key) {
    pthread_rwlock_rdlock(&dbLock);
    if (database[key] == NULL) {
        // Handle missing keys gracefully
        return NULL;
    }

    record* rec = database[key]->data;
    time_t now = time(NULL);
    pthread_mutex_lock(&database[key]->lock);
    database[key]->lastAccessed = now;
    database[key]->accessFrequency++;
    pthread_mutex_unlock(&database[key]->lock);

    pthread_rwlock_unlock(&dbLock);
    return rec;
}
```
This is a simplified example and does not include all the features you requested. Implementing such a system would require a deep understanding of concurrency, memory management, caching, logging, profiling, and advanced data structures. It's also important to note that this code doesn't handle errors or edge cases that might occur in a real-world distributed database system.
