            $startTime = microtime(true);
            $retries = 0;
            do {
                try {
                    $this->rateLimiter->limit(); // rate limiting

                    // database operation
                    $this->dao->updateUserPassword($userId, $newPassword); 

                    $elapsedTime = microtime(true) - $startTime;
                    $this->logger->info("Successfully updated password for user: " . $userId . ". Time taken: " . $elapsedTime);
