                } catch (Exception $e) {
                    $retries++;
                    $sleepTime = pow(2, $retries); // exponential backoff strategy

                    $this->logger->error("Failed to update password for user: " . $userId . ". Retry: " . $retries . ". Error: " . $e->getMessage());
                    sleep($sleepTime); // wait before retrying
                }
