#include <stdlib.h>
#include <pthread.h>
#include <glib.h>

typedef struct {
    char* string;
    double value;
} Data;

typedef struct {
    // config fields here...
} Config;

typedef struct {
    GHashTable* table;
    pthread_mutex_t lock;
    int maxSize;
    int size;
} Manager;

Manager* createManager(int maxSize) {
    Manager* manager = malloc(sizeof(Manager));
    if (manager == NULL) return NULL;

    manager->table = g_hash_table_new(g_str_hash, g_str_equal);
    pthread_mutex_init(&manager->lock, NULL);
    manager->maxSize = maxSize;
    manager->size = 0;

    return manager;
}

void destroyManager(Manager* manager) {
    g_hash_table_destroy(manager->table);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int addData(Manager* manager, char* key, Data* data) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->maxSize) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: maximum size exceeded.
    }

    g_hash_table_insert(manager->table, key, data);
    manager->size++;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success.
}

Data* getData(Manager* manager, char* key) {
    pthread_mutex_lock(&manager->lock);

    Data* data = g_hash_table_lookup(manager->table, key);

    pthread_mutex_unlock(&manager->lock);
    return data;
}
```
This code creates a Manager struct that manages a hash table of Data objects. The addData and getData functions are thread-safe using a mutex lock. If the maximum size is exceeded, addData returns an error. 

