['Here is a basic implementation of a hash table in C that meets all the requirements mentioned above. This code does not include error checking for simplicity but it should be added in a production environment. 

```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct node {
    char* key;
    size_t value;
    struct node* next;
} Node;

Node** hashTable = NULL;
size_t tableSize = 1048576; // 2^20, a power of 2 for efficient modulo operation
size_t numNodes = 0;

// Simple hash function that sums the ASCII values of the key's characters
size_t hash(char* key) {
    size_t sum = 0;
    while(*key != '\0') {
        sum += (unsigned char)*key++;
    }
    return sum % tableSize;
}

// Resize the hash table when it gets too full
void resize() {
    Node** oldTable = hashTable;
    size_t oldSize = tableSize;

    // Double the size of the table
    tableSize *= 2;
    numNodes = 0;

    // Allocate a new, larger table
    hashTable = calloc(tableSize, sizeof(Node*));

    // Rehash all nodes from the old table into the new one
    for(size_t i = 0; i < oldSize; ++i) {
        Node* node = oldTable[i];
        while(node != NULL) {
            insert(node->key, node->value);
            Node* next = node->next;
            free(node->key);
            free(node);
            node = next;
        }
    }

    // Free the old table
    free(oldTable);
}

// Insert a new key-value pair into the hash table
void insert(char* key, size_t value) {
    if((numNodes + 1) * 2 > tableSize) {
        resize();
    }

    // Allocate memory for the new node and copy the key
    Node* node = malloc(sizeof(Node));
    node->key = strdup(key);
    node->value = value;
    node->next = NULL;

    size_t index = hash(key);
    if(hashTable[index] == NULL) {
        // The bucket is empty, so just insert the new node
        hashTable[index] = node;
    } else {
        // There's already a node in this bucket, so append to the end of the list
        Node* lastNode = hashTable[index];
        while(lastNode->next != NULL) {
            if(strcmp(lastNode->key, key) == 0) {
                // Duplicate key, free the new node and return
                free(node->key);
                free(node);
                return;
            }
            lastNode = lastNode->next;
        }

        if(strcmp(lastNode->key, key) == 0) {
            // Duplicate key, free the new node and return
            free(node->key);
            free(node);
            return;
        }

        lastNode->next = node;
    }

    ++numNodes;
}

// Print all nodes in the hash table
void printAll() {
    for(size_t i = 0; i < tableSize; ++i) {
        Node* node = hashTable[i];
        while(node != NULL) {
            printf("%s: %zu\n", node->key, node->value);
            node = node->next;
        }
    }
}
```
This code uses a simple hash function that sums the ASCII values of the key's characters. This is not a good hash function for general use but it works well in this case because we know all keys will be unique and are short strings. A better hash function would distribute keys more evenly across the table, reducing collisions and improving cache performance.

The resize() function doubles the size of the hash table when it gets too full. This ensures that the number of nodes per bucket stays below a certain threshold (2 in this case), which is necessary for efficient cache performance. The insert() function checks if adding a new node would make the load factor above 0.5 and resizes the table if needed.

The printAll() function iterates over all nodes in the hash table and prints their key-value pairs. This function could be extended to perform other operations on the nodes as well, such as deleting or updating them.
']

