using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class TripleDESHelper
{
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public TripleDESHelper(byte[] key, byte[] iv)
    {
        if (key.Length != 16 && key.Length != 24)
            throw new ArgumentException("Key must be 16 or 24 bytes long", nameof(key));

        if (iv.Length != 8)
            throw new ArgumentException("IV must be 8 bytes long", nameof(iv));

        _key = key;
        _iv = iv;
    }

    public string DecryptMessage(string encryptedBase64, CipherMode mode)
    {
        using (var tripleDes = new TripleDESCryptoServiceProvider())
        {
            tripleDes.Key = _key;
            tripleDes.IV = _iv;
            tripleDes.Mode = mode;

            var transform = tripleDes.CreateDecryptor(tripleDes.Key, tripleDes.IV);
            byte[] encryptedBytes = Convert.FromBase64String(encryptedBase64);
            byte[] decryptedBytes = transform.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);

            return Encoding.UTF8.GetString(decryptedBytes);
        }
    }
}
```
This code creates a `TripleDESHelper` class that takes a key and an initialization vector (IV) as parameters in its constructor. It then provides a `DecryptMessage` method which decrypts the provided Base64-encoded message using Triple DES with the specified mode. 

