#include <iostream>
#include <fstream>
#include <string>
#include <openssl/sha.h>
#include <vector>
#include <thread>
#include <mutex>
#include <random>
#include <atomic>
#include <condition_variable>

struct Record {
    double value;
};

std::mutex mtx;
std::condition_variable cv;
std::vector<Record*> records;
std::atomic<bool> done(false);
int currentIndex = 0;

void processLine(const std::string& line, int index) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)line.c_str(), line.length(), hash);

    std::string transformedLine = line + " ";
    for(int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        transformedLine += hash[i];
    }

    records[index]->value = std::stod(transformedLine); // Assuming the line can be converted to double.
}

void workerThread() {
    while (true) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, []{ return done || currentIndex < records.size(); });

        if (done) break;

        int index = currentIndex++;
        lock.unlock();
        cv.notify_all();

        processLine("", index); // Assuming the line is read from a file.
    }
}

void processFile(const std::string& inputFileName, const std::string& outputFileName, int maxRecords) {
    std::ifstream inputFile(inputFileName);

    if (!inputFile.is_open()) {
        throw std::runtime_error("Failed to open the file");
    }

    records.reserve(maxRecords);
    for (int i = 0; i < maxRecords; ++i) {
        Record* record = new Record(); // Assuming memory allocation is successful.

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(0, 1);
        record->value = dis(gen);

        records.push_back(record);
    }

    int numThreads = std::thread::hardware_concurrency(); // Assuming we can use all available cores.
    std::vector<std::thread> threads;
    for (int i = 0; i < numThreads; ++i) {
        threads.push_back(std::thread(workerThread));
    }

    std::string line;
    while (std::getline(inputFile, line)) {
        processLine(line, currentIndex++); // Assuming the line is read from a file.

        if (currentIndex >= maxRecords) break;
    }

    done = true;
    cv.notify_all();

    for (auto& thread : threads) {
        if (thread.joinable()) {
            thread.join();
        }
    }

    std::ofstream outputFile(outputFileName);
    for (const auto record : records) {
        outputFile << record->value << "\n"; // Assuming the value can be written to a file.

        delete record;
    }
}
```
This code is simplified and does not cover all your requirements, but it should give you an idea of how to approach this problem. It uses OpenSSL for SHA-256 hashing, std::thread for multithreading, std::mutex and std::condition_variable for thread synchronization, std::vector for dynamic memory allocation, and std::atomic for atomic operations.
']

["This is a complex task that requires a deep understanding of Java programming, concurrency, and system design principles. Here's an outline of how you might approach this problem using the SLF4J logging framework for Java, which supports various logging targets including console, file, and Loggly or Splunk:

```java
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.AppenderBase;
import java.util.concurrent.*;

public class AsyncLogger extends AppenderBase<ILoggingEvent> {
    private static final Logger logger = LoggerFactory.getLogger(AsyncLogger.class);
    private BlockingQueue<ILoggingEvent> queue = new LinkedBlockingDeque<>();
    private ExecutorService executorService;

    public AsyncLogger() {
        int cores = Runtime.getRuntime().availableProcessors();
        executorService = Executors.newFixedThreadPool(cores);

        for (int i = 0; i < cores; ++i) {
            executorService.submit(() -> {
                while (!executorService.isShutdown()) {
                    try {
                        ILoggingEvent event = queue.take();
                        super.append(event);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
            });
        }
    }

    @Override
    protected void append(ILoggingEvent eventObject) {
        queue.add(eventObject);
    }

    public void stop() {
        executorService.shutdown();

        try {
            if (!executorService.awaitTermination(5, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}
```
This is a basic example of an asynchronous logger using SLF4J and Logback. It uses a `BlockingQueue` to hold log events, which are then processed by a pool of worker threads. The number of worker threads is determined by the number of available cores on the system.

For managing logging levels dynamically, you could use a configuration management tool like Apache ZooKeeper or etcd. These tools allow you to store and retrieve configuration data in real-time, which can be used to adjust logging levels at runtime.

To handle failures when log targets are unavailable or configuration updates fail, you should implement retry logic with exponential backoff and jitter for network errors, and fallback mechanisms for local storage if all sinks are down.

For memory management, consider using a disk-based data structure like an LSM tree or B-tree to efficiently manage log rotations without excessive disk usage. You could also use off-heap memory (e.g., with the Java NIO library) for large objects that don't need to be serialized and deserialized frequently, such as log events.

Finally, remember to evaluate your logging system under load and monitor its performance using tools like Prometheus or Grafana. This will help you identify bottlenecks and make necessary adjustments based on real-world constraints.
