typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    pthread_mutex_t lock;
} DataStructure;

DataStructure* createDataStructure(int maxRecords) {
    srand(time(NULL));

    DataStructure* ds = malloc(sizeof(DataStructure));
    if (ds == NULL) return NULL; // Handle memory allocation failure

    ds->offsets = calloc(maxRecords, sizeof(long));
    ds->keys = calloc(maxRecords, sizeof(int));
    ds->records = malloc(sizeof(Record*) * maxRecords);

    if (ds->offsets == NULL || ds->keys == NULL || ds->records == NULL) {
        // Handle memory allocation failure
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
        return NULL;
    }

    pthread_mutex_init(&ds->lock, NULL); // Initialize mutex for thread safety

    return ds;
}

void destroyDataStructure(DataStructure* ds) {
    if (ds == NULL) return;

    free(ds->offsets);
    free(ds->keys);

    // Free records and their values
    for (int i = 0; i < maxRecords; ++i) {
        if (ds->records[i] != NULL) {
            free(ds->records[i]);
        }
    }
    free(ds->records);

    pthread_mutex_destroy(&ds->lock); // Destroy mutex

    free(ds);
}
