        ds->offsets[i] = rand() % (maxValue - minValue + 1) + minValue;
        ds->keys[i] = i;

        Record* record = malloc(sizeof(Record));
        if (!record) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        record->value = rand() % (maxValue - minValue + 1) + minValue;
        ds->records[i] = record;

        Lookup** lookup = malloc(sizeof(Lookup*));
        if (!lookup) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        Lookup* lu = malloc(sizeof(Lookup));
        if (!lu) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        lu->key = i;
        lu->record = record;
        lookup[0] = lu;
        ds->lookups[i] = lookup;
    }

    pthread_mutex_init(&ds->mutex, NULL);
    ds->logFile = fopen("log.txt", "w");
    if (!ds->logFile) {
