#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>

// Define a structure for the record
typedef struct {
    int value;
} Record;

// Memory pool allocator
void* memory_pool = NULL;
size_t memory_pool_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* mem_alloc(size_t size) {
    pthread_mutex_lock(&mutex);

    if (memory_pool == NULL || memory_pool_size < size) {
        // Allocate a new pool if the current one is too small
        free(memory_pool);
        memory_pool = malloc(size);
        memory_pool_size = size;
    }

    void* ptr = memory_pool;
    memory_pool += size;
    memory_pool_size -= size;

    pthread_mutex_unlock(&mutex);

    return ptr;
}

// DNS resolution and IP address storage
u_char* resolve_hostname(const char* hostname) {
    struct addrinfo hints, *res;
    int errcode;
    char addrstr[100];
