#include <stdio.h>
#include <pthread.h>
#include <glib.h>

typedef struct {
    int transaction_id;
    int user_id;
    long timestamp;
    double amount;
} Transaction;

GHashTable* hash_table;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* process_transaction(void* arg) {
    Transaction* transaction = (Transaction*)arg;

    pthread_mutex_lock(&lock);
    g_hash_table_insert(hash_table, &transaction->transaction_id, transaction);
    pthread_mutex_unlock(&lock);

    return NULL;
}

void iterate_transactions() {
    GHashTableIter iter;
    gpointer key, value;

    pthread_mutex_lock(&lock);
    g_hash_table_iter_init (&iter, hash_table); 
    while (g_hash_table_iter_next (&iter, &key, &value)) {
        Transaction* transaction = (Transaction*)value;
        printf("Transaction ID: %d\n", transaction->transaction_id);
        // Process the transaction...
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    hash_table = g_hash_table_new(g_direct_hash, g_direct_equal);

    Transaction transactions[] = {{1, 100, 1625948732, 100.0}, {2, 200, 1625948733, 200.0}};
    int num_transactions = sizeof(transactions) / sizeof(Transaction);

    pthread_t threads[num_transactions];
    for (int i = 0; i < num_transactions; ++i) {
        pthread_create(&threads[i], NULL, process_transaction, &transactions[i]);
    }

    for (int i = 0; i < num_transactions; ++i) {
        pthread_join(threads[i], NULL);
    }

    iterate_transactions();

    g_hash_table_destroy(hash_table);

    return 0;
}
```
This code creates a separate thread for each transaction to process it concurrently. It uses a mutex lock to ensure that only one thread can access the hash table at a time, preventing race conditions and ensuring data integrity. The iterate_transactions function provides an example of how you might retrieve all transactions from the hash table.
