    long* offsets;
    int* keys;
    Record** records;
    pthread_rwlock_t lock;
    size_t maxRecords;
    size_t currentMemoryUsage;
    const size_t memoryBudget;
} MemoryManager;

int initMemoryManager(MemoryManager* manager, size_t maxRecords, size_t memoryBudget) {
    assert(manager != NULL);

    if ((manager->offsets = malloc(sizeof(long) * maxRecords)) == NULL ||
        (manager->keys = calloc(maxRecords, sizeof(int))) == NULL ||
        (manager->records = malloc(sizeof(Record*) * maxRecords)) == NULL) {
        return -1; // Memory allocation failed.
    }

    manager->maxRecords = maxRecords;
    manager->currentMemoryUsage = 0;
    manager->memoryBudget = memoryBudget;
    pthread_rwlock_init(&manager->lock, NULL);

    return 0; // Success.
}

void destroyMemoryManager(MemoryManager* manager) {
    assert(manager != NULL);

    for (size_t i = 0; i < manager->maxRecords; ++i) {
        free(manager->records[i]);
    }

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    pthread_rwlock_destroy(&manager->lock);
}

int createRecord(MemoryManager* manager, int value) {
    assert(manager != NULL);

    if (manager->currentMemoryUsage + sizeof(Record) > manager->memoryBudget) {
        return -1; // Memory budget exceeded.
    }

    pthread_rwlock_wrlock(&manager->lock);

    size_t i = 0;
    while (i < manager->maxRecords && manager->records[i] != NULL) {
        ++i;
    }

    if (i == manager->maxRecords) {
        pthread_rwlock_unlock(&manager->lock);
        return -2; // Maximum number of records reached.
    }

    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        pthread_rwlock_unlock(&manager->lock);
        return -3; // Memory allocation failed.
    }

    record->value = value;
    manager->records[i] = record;
    manager->currentMemoryUsage += sizeof(Record);

    pthread_rwlock_unlock(&manager->lock);

    return 0; // Success.
}
