typedef struct Record {
    long offset;
    int key;
    void* data;
} Record;

typedef struct RecordCollection {
    size_t maxRecords;
    atomic_size_t numRecords;
    pthread_mutex_t mutex;
    Record** records;
    long* offsets;
    int* keys;
} RecordCollection;

RecordCollection* createRecordCollection(size_t maxRecords) {
    RecordCollection* collection = malloc(sizeof(RecordCollection));
    if (collection == NULL) return NULL;

    collection->maxRecords = maxRecords;
    atomic_init(&collection->numRecords, 0);
    pthread_mutex_init(&collection->mutex, NULL);

    collection->records = malloc(sizeof(Record*) * maxRecords);
    if (collection->records == NULL) {
        free(collection);
        return NULL;
    }

    collection->offsets = malloc(sizeof(long) * maxRecords);
    if (collection->offsets == NULL) {
        free(collection->records);
        free(collection);
        return NULL;
    }

    collection->keys = malloc(sizeof(int) * maxRecords);
    if (collection->keys == NULL) {
        free(collection->offsets);
        free(collection->records);
        free(collection);
        return NULL;
    }

    for (size_t i = 0; i < maxRecords; ++i) {
        collection->records[i] = NULL;
    }

    return collection;
}

void destroyRecordCollection(RecordCollection* collection) {
    pthread_mutex_lock(&collection->mutex);

    for (size_t i = 0; i < collection->maxRecords; ++i) {
        if (collection->records[i] != NULL) {
            free(collection->records[i]->data);
            free(collection->records[i]);
        }
    }

    free(collection->keys);
    free(collection->offsets);
    free(collection->records);
    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int addRecord(RecordCollection* collection, int key, void* data) {
    size_t numRecords = atomic_load(&collection->numRecords);

    if (numRecords >= collection->maxRecords) return -1; // Error: Max records exceeded

    pthread_mutex_lock(&collection->mutex);

    size_t index = atomic_fetch_add(&collection->numRecords, 1);

    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        pthread_mutex_unlock(&collection->mutex);
        return -2; // Error: Memory allocation failed
    }

    record->key = key;
    record->data = data;
    collection->records[index] = record;

    pthread_mutex_unlock(&collection->mutex);

    return 0; // Success
}
```
