typedef struct item {
    int id;
    char* data;
} item_t;

typedef struct node {
    item_t* item;
    struct node* next;
} node_t;

typedef struct list {
    node_t* head;
    pthread_mutex_t lock;
    int max_items;
    int current_items;
    char** existing_payloads;
    int payload_length;
    int (*external_memory_management)(void*, size_t); // optional hook for external memory management functions
} list_t;

