    list_t* list = malloc(sizeof(list_t));
    assert(list != NULL);

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->max_items = max_items;
    list->current_items = 0;
    list->existing_payloads = malloc(sizeof(char*) * max_items);
    assert(list->existing_payloads != NULL);
    list->payload_length = payload_length;

    return list;
}

void add_item(list_t* list, item_t* item) {
    pthread_mutex_lock(&list->lock);

    if (list->current_items >= list->max_items) {
        // handle error: maximum number of items reached
        return;
    }

    for (int i = 0; i < list->current_items; ++i) {
        if (strcmp(list->existing_payloads[i], item->data) == 0) {
            // handle error: duplicate payload string detected
            return;
        }
    }

    node_t* new_node = malloc(sizeof(node_t));
    assert(new_node != NULL);
    new_node->item = item;
    new_node->next = list->head;
    list->head = new_node;

    list->existing_payloads[list->current_items] = item->data;
    ++list->current_items;

    pthread_mutex_unlock(&list->lock);
}
