    if (io_submit(ctx->ctx, 1, ctx->cbs) != 1) {
        return -1;
    }
    while (io_getevents(ctx->ctx, 0, 1, &event, NULL) == 0) {
        if (event.res == sizeof(*buf)) {
            *buf = ctx->buf;
            return 0;
        } else if (event.res < 0) {
            return -2;
        }
    }
    return -3;
}

void* read_file(void* arg) {
    file_manager* manager = (file_manager*)arg;
    async_read_context ctx;
    char* buf;
    int ret;

    pthread_mutex_lock(&manager->lock);
    manager->outstanding_requests++;
    pthread_mutex_unlock(&manager->lock);

    // Initialize async read context...

    for (int i = 0; i < manager->retry_limit; i++) {
        ret = async_read(&ctx, &buf);
        if (ret == 0) break;
    }

    pthread_mutex_lock(&manager->lock);
    manager->outstanding_requests--;
    pthread_mutex_unlock(&manager->lock);

    // Process file contents...

    return NULL;
}

void process_files(file_manager* manager, const char** filenames, size_t count) {
    pthread_attr_t attr;
    pthread_t threads[count];

    pthread_mutex_init(&manager->lock, NULL);

    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    for (size_t i = 0; i < count; i++) {
        if (pthread_create(&threads[i], &attr, read_file, manager)) {
            // Handle error...
        }
    }

    pthread_attr_destroy(&attr);

    for (size_t i = 0; i < count; i++) {
        if (pthread_join(threads[i], NULL)) {
            // Handle error...
        }
    }

    pthread_mutex_destroy(&manager->lock);
}
```
