    ~fileAnalyzer() {}

    void processFiles(const std::vector<fs::path>& files) {
        for (auto& file : files) {
            if (!isFileProcessed(file)) {
                // Process the file in a separate thread
                std::thread t(&fileAnalyzer::processFile, this, file);
                t.detach();  // Detach the thread to allow it to run independently
            }
        }
    }

private:
    struct Record {
        int value;
        long* offset;
    };

    std::unordered_map<int, Record> cache_;
    std::mutex mtx_;  // Mutex for thread-safe operations

    bool isFileProcessed(const fs::path& file) {
        std::lock_guard<std::mutex> lock(mtx_);
        return cache_.find(getMD5Hash(file)) != cache_.end();
    }

    void processFile(const fs::path& file) {
        // Implement your custom pseudo-random number generator here
        // ...

        // Hash-based solution to detect duplicate keys efficiently
        int key = getMD5Hash(file);

        std::lock_guard<std::mutex> lock(mtx_);
        if (cache_.find(key) == cache_.end()) {
            // Process the file and populate the data structures
            // ...

            // Store the processed file in the cache
            Record record;
            // Populate the record with your data
            // ...
            cache_[key] = record;
        }
    }

    int getMD5Hash(const fs::path& file) {
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5_CTX context;
        MD5_Init(&context);

        // Read the file and update the hash
        std::ifstream inputFile(file.string(), std::ios::binary);
        const int bufferSize = 1024;
        char buffer[bufferSize];
        while (!inputFile.eof()) {
            inputFile.read(buffer, bufferSize);
            MD5_Update(&context, buffer, inputFile.gcount());
        }

        // Finalize the hash and convert it to an integer
        unsigned char* p = MD5_Final(&context);
        int hash = 0;
        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            hash += static_cast<int>(p[i]);
        }

        return hash;
    }
};
