typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    Point** points;
    char** identifiers;
    Record** records;
} DataManager;

DataManager* create_data_manager(size_t initialCapacity) {
    DataManager* manager = malloc(sizeof(DataManager));
    if (manager == NULL) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = initialCapacity;
    manager->count = 0;
    manager->points = malloc(sizeof(Point*) * initialCapacity);
    manager->identifiers = malloc(sizeof(char*) * initialCapacity);
    manager->records = calloc(initialCapacity, sizeof(Record*));

    if (manager->points == NULL || manager->identifiers == NULL || manager->records == NULL) {
        free_data_manager(manager);
        return NULL;
    }

    return manager;
}

void add_point(DataManager* manager, Point* point, const char* identifier) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        manager->capacity *= 2;

        manager->points = realloc(manager->points, sizeof(Point*) * manager->capacity);
        assert(manager->points != NULL);

        manager->identifiers = realloc(manager->identifiers, sizeof(char*) * manager->capacity);
        assert(manager->identifiers != NULL);

        manager->records = realloc(manager->records, sizeof(Record*) * manager->capacity);
        assert(manager->records != NULL);
    }

    manager->points[manager->count] = point;
    manager->identifiers[manager->count] = strdup(identifier);

    pthread_mutex_unlock(&manager->lock);
}

void free_data_manager(DataManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->identifiers[i]);
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager->points);
    free(manager->identifiers);
    free(manager->records);
    free(manager);
}
```
