['This task is quite complex and involves multiple aspects of system programming such as memory management, concurrency control, synchronization, data structures, and logging. Here's an outline of how you might approach this problem in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>
#include <unistd.h>
#include <sys/mman.h>
#include <fcntl.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    int key;
    Record* record;
} OffsetKeyRecord;

typedef struct {
    sem_t mutex;
    OffsetKeyRecord** array;
    size_t size;
    size_t capacity;
} SharedMemoryRegion;

SharedMemoryRegion* shared_memory_region = NULL;

void error(char *msg) {
    perror(msg);
    exit(0);
}

int findLargestInteger(int* array, int size) {
    int max = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void* createSharedMemoryRegion(size_t capacity) {
    int fd = shm_open("/myregion", O_CREAT | O_RDWR, 0666);
    if (fd < 0) error("ERROR opening shared memory region");

    if (ftruncate(fd, sizeof(SharedMemoryRegion)) < 0) {
        error("ERROR resizing shared memory region");
    }

    SharedMemoryRegion* region = mmap(NULL, sizeof(SharedMemoryRegion), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (region == MAP_FAILED) {
        error("ERROR mapping shared memory region");
    }

    sem_init(&region->mutex, 1, 1);
    region->array = malloc(sizeof(OffsetKeyRecord*) * capacity);
    if (region->array == NULL) {
        error("ERROR allocating memory for array");
    }

    region->capacity = capacity;
    region->size = 0;

    return region;
}

void addToSharedMemoryRegion(OffsetKeyRecord* item) {
    sem_wait(&shared_memory_region->mutex);

    if (shared_memory_region->size == shared_memory_region->capacity) {
        error("ERROR: Shared memory region is full");
    }

    shared_memory_region->array[shared_memory_region->size++] = item;

    sem_post(&shared_memory_region->mutex);
}

void* threadFunction(void *arg) {
    int value = *((int*) arg);
    Record* record = malloc(sizeof(Record));
    if (record == NULL) error("ERROR allocating memory for record");

    srand(time(NULL));
    record->value = rand() % 100; // Generate a random integer between 0 and 99

    OffsetKeyRecord* item = malloc(sizeof(OffsetKeyRecord));
    if (item == NULL) error("ERROR allocating memory for item");

    item->offset = value;
    item->key = record->value;
    item->record = record;

    addToSharedMemoryRegion(item);

    return NULL;
}

int main() {
    shared_memory_region = createSharedMemoryRegion(100); // Create a shared memory region with capacity of 100 items

    pthread_t threads[5];
    int values[5] = {1, 2, 3, 4, 5};

    for (int i = 0; i < 5; ++i) {
        if (pthread_create(&threads[i], NULL, threadFunction, &values[i]) != 0) {
            error("ERROR creating thread");
        }
    }

    for (int i = 0; i < 5; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            error("ERROR joining thread");
        }
    }

    // Clean up shared memory region and threads here...

    return 0;
}
```
This is a simplified example and does not include all the features you requested. It creates a shared memory region, initializes it with a semaphore for thread safety, and then creates multiple threads that add items to the shared memory region. Each item contains an offset (which is just the input value), a key (which is a random integer between 0 and 99), and a record (which contains a single integer value).
