import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.*;

public class TransactionProcessor {
    private static final Logger logger = Logger.getLogger(TransactionProcessor.class.getName());

    // Map to store disjoint pairs of transactions
    private ConcurrentHashMap<String, AtomicInteger> disjointPairs;

    public TransactionProcessor() {
        this.disjointPairs = new ConcurrentHashMap<>();
    }

    public void processTransaction(Transaction transaction) {
        long startTime = System.currentTimeMillis();

        // Check if the transaction is already in a disjoint pair
        AtomicInteger count = disjointPairs.get(transaction.getId());
        if (count != null && count.decrementAndGet() > 0) {
            logger.info("Transaction " + transaction.getId() + " is part of an existing disjoint pair");
            return;
        }

        // Check for other transactions with the same ID and form a new disjoint pair if found
        count = disjointPairs.get(transaction.getId());
        if (count != null && count.decrementAndGet() > 0) {
            logger.info("Found another transaction with the same ID, forming a new disjoint pair");
            return;
        }

        // No other transactions found, add this one to the map
        disjointPairs.put(transaction.getId(), new AtomicInteger(1));

        long endTime = System.currentTimeMillis();
        logger.info("Disjointness check took " + (endTime - startTime) + " ms");
    }

    // Other methods for filtering, updating count, sliding window mechanism, adjusting threshold, etc.
}
