#include <stdatomic.h>

typedef struct {
    int value;
    long* offset;
    int key;
} record;

record** records = NULL;
long* offsets = NULL;
int* keys = NULL;
atomic_size_t totalRecords = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init(size_t maxRecords, int minValue, int maxValue) {
    records = malloc(maxRecords * sizeof(record*));
    offsets = malloc(maxRecords * sizeof(long));
    keys = malloc(maxRecords * sizeof(int));

    for (size_t i = 0; i < maxRecords; ++i) {
        records[i] = NULL;
        offsets[i] = -1L;
        keys[i] = -1;
    }
}

void addRecord(int value, long* offset, int key) {
    pthread_mutex_lock(&lock);

    size_t index = atomic_fetch_add(&totalRecords, 1L);
    if (index < maxRecords) {
        records[index] = malloc(sizeof(record));
        records[index]->value = value;
        records[index]->offset = offset;
        records[index]->key = key;

        *offset = index;
    } else {
        // Handle overflow here, e.g., by ignoring the new record or throwing an error
    }

    pthread_mutex_unlock(&lock);
}

void printRecord(size_t index) {
    if (index < maxRecords && records[index] != NULL) {
        printf("Offset: %ld, Key: %d, Value: %d\n", *records[index]->offset, records[index]->key, records[index]->value);
    } else {
        printf("Invalid record index.\n");
    }
}

void reset() {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < maxRecords; ++i) {
        if (records[i] != NULL) {
            free(records[i]);
            records[i] = NULL;
            offsets[i] = -1L;
            keys[i] = -1;
        }
    }

    atomic_store(&totalRecords, 0L);

    pthread_mutex_unlock(&lock);
}

void freeMemory() {
    reset();

    if (records != NULL) {
        free(records);
        records = NULL;
    }

    if (offsets != NULL) {
        free(offsets);
        offsets = NULL;
    }

    if (keys != NULL) {
        free(keys);
        keys = NULL;
    }
}
