        io::write(socket_, io::buffer("GET / HTTP/1.0\r\nHost: " + host_ + "\r\nAccept: */*\r\nConnection: close\r\n\r\n"), error);
    }

private:
    io::io_service ioService_;
    tcp::socket socket_;
};

class MemoryPool {
public:
    MemoryPool(size_t maxSize) : maxSize_(maxSize), mutex_(new boost::mutex()) {}

    void addRecord(int value, int offset, const std::string& key) {
        boost::lock_guard<boost::mutex> lock(*mutex_);
        if (records_.size() >= maxSize_) {
            BOOST_LOG_TRIVIAL(warning) << "Memory pool is full. Dropping record.";
            return;
        }
        records_.push_back({value, offset, key});
    }

private:
