typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    int key;
    Record* record;
} Item;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int totalAllocations = 0;
int totalDeallocations = 0;
size_t totalMemoryUsage = 0;

void* handleConnection(void* arg) {
    int clientSocket = *((int*)arg);
    // Read from the socket and process data...

    close(clientSocket);
    return NULL;
}

Record* createRecord() {
    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&lock);
    totalAllocations++;
    totalMemoryUsage += sizeof(Record);
    pthread_mutex_unlock(&lock);

    record->value = rand(); // Generate a random value for the record.
    return record;
}

void freeItem(Item* item) {
    if (item == NULL) {
        fprintf(stderr, "Null pointer dereference\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&lock);
    totalDeallocations++;
    totalMemoryUsage -= sizeof(Item);
    pthread_mutex_unlock(&lock);

    free(item->record);
    free(item);
}

int main() {
    int serverSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (serverSocket == -1) {
        perror("Failed to create socket");
        exit(EXIT_FAILURE);
    }

    // Bind the socket and listen for connections...

    while (1) {
        int clientSocket = accept(serverSocket, NULL, NULL);
        if (clientSocket == -1) {
            perror("Failed to accept connection");
            exit(EXIT_FAILURE);
        }

        pthread_t thread;
        if (pthread_create(&thread, NULL, handleConnection, &clientSocket) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    close(serverSocket);
    return 0;
}
```
