["Here is an example of how you might implement this in C. This code does not include all the considerations mentioned above as they are quite complex to implement and would require a more detailed understanding of your system's requirements. However, it provides a basic structure for dynamically managing memory for multiple types of data structures within a configurable data processing pipeline:

```c
#include <stdlib.h>
#include <time.h>

typedef int offset_t;
typedef int key_t;
typedef int value_t;

typedef struct record {
    value_t value;
} record_t;

typedef struct node {
    record_t *record;
    struct node *next;
} node_t;

int processData(size_t numRecords, size_t minValue, size_t maxValue) {
    offset_t *offsets = malloc(numRecords * sizeof(offset_t));
    if (offsets == NULL) return -1; // Out of memory error

    key_t *keys = calloc(numRecords, sizeof(key_t));
    if (keys == NULL) {
        free(offsets);
        return -1; // Out of memory error
    }

    record_t *records = malloc(numRecords * sizeof(record_t));
    if (records == NULL) {
        free(offsets);
        free(keys);
        return -1; // Out of memory error
    }

    node_t *head = NULL, *tail = NULL;
    size_t totalRecords = 0;
    value_t sumValue = 0;

    srand(time(NULL));
    for (size_t i = 0; i < numRecords; ++i) {
        offsets[i] = i * sizeof(record_t);
        keys[i] = i;

        records[i].value = minValue + rand() % ((maxValue + 1) - minValue);
        sumValue += records[i].value;

        node_t *node = malloc(sizeof(node_t));
        if (node == NULL) {
            // Free all previously allocated memory and return an error code
            free(offsets);
            free(keys);
            free(records);

            while (head != NULL) {
                node_t *next = head->next;
                free(head);
                head = next;
            }

            return -1; // Out of memory error
        }

        node->record = &records[i];
        node->next = NULL;

        if (tail == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
        }

        ++totalRecords;
    }

    // Continue processing...

    free(offsets);
    free(keys);
    free(records);

    while (head != NULL) {
        node_t *next = head->next;
        free(head);
        head = next;
    }

    return 0; // Success
}
```
This code creates and populates the arrays of `offset_t`, `key_t`, and `record_t` structures. It also maintains a linked list to track the total number of records and their cumulative sum. The function sets each record’s `value_t` to a random integer within a specified range. If there is insufficient memory available for allocation, it frees all previously allocated memory and returns an error code indicating insufficient resources.
"]

