#include <iostream>
#include <fstream>
#include <sstream>
#include <mutex>
#include <thread>
#include <chrono>

namespace Logging {
    enum class Level { DEBUG, INFO, WARNING, ERROR, CRITICAL };

    class Logger {
        public:
            static void init(Level level = Level::INFO) {
                getInstance().level_ = level;
            }

            static void log(Level level, const std::string& message) {
                if (level >= getInstance().level_) {
                    std::lock_guard<std::mutex> lock(getInstance().mtx_);

                    // Log to console
                    std::cout << "[" << getCurrentTime() << "] [" << levelToString(level) << "]: " << message << std::endl;

                    // Log to file
                    std::ofstream logFile("log.txt", std::ios_base::app);
                    if (logFile.is_open()) {
                        logFile << "[" << getCurrentTime() << "] [" << levelToString(level) << "]: " << message << std::endl;
                        logFile.close();
                    } else {
                        throw std::runtime_error("Unable to open log file");
                    }
                }
            }

        private:
            Logger() = default;
            ~Logger() = default;

            static Logger& getInstance() {
                static Logger instance;
                return instance;
            }

            static std::string levelToString(Level level) {
                switch (level) {
                    case Level::DEBUG:    return "DEBUG";
                    case Level::INFO:     return "INFO";
                    case Level::WARNING:  return "WARNING";
                    case Level::ERROR:    return "ERROR";
                    case Level::CRITICAL: return "CRITICAL";
                }
            }

            static std::string getCurrentTime() {
                auto now = std::chrono::system_clock::now();
                auto in_time_t = std::chrono::system_clock::to_time_t(now);

                std::stringstream ss;
                ss << std::put_time(std::localtime(&in_time_t), "%Y-%m-%d %X");
                return ss.str();
            }

            Level level_;
            std::mutex mtx_;
    };
}
```

This code creates a Logger class with static methods for initializing and logging messages. The log method checks if the message's level is high enough to be logged, then acquires a lock on a mutex before writing to both console and file. 

The `getInstance` function ensures that only one instance of the logger exists at any given time (a singleton pattern), which is thread-safe in C++11 and later. The mutex ensures that logging operations are atomic, preventing race conditions when multiple threads try to log simultaneously.

Please note that this code does not handle errors or edge cases such as file I/O failures, incorrect log levels, etc. It's a basic starting point for building a more robust logging framework. 

Also, remember to call `Logger::init()` before calling `Logger::log()` to initialize the logger with your desired log level.
