```javascript
const fs = require('fs').promises;
const path = require('path');

async function readFilesFromDirectory(dirPath, extensions, maxSize) {
    let files = await fs.readdir(dirPath);

    // Filter out files that don't match the specified extension and are too large
    files = files.filter((file) => {
        const fileExt = path.extname(file).toLowerCase();
        return extensions.includes(fileExt) && fs.statSync(path.join(dirPath, file)).size <= maxSize;
    });

    // Check for duplicate filenames and log a warning if found
    const filenameCounts = {};
    files.forEach((file) => {
        if (filenameCounts[file]) {
            console.warn(`Duplicate file name detected: ${file}`);
        } else {
            filenameCounts[file] = 1;
        }
    });

    // Read the contents of each file and return an object containing their names, sizes, and last modified timestamps
    const results = {};
    for (const file of files) {
        const stats = await fs.stat(path.join(dirPath, file));
        results[file] = {
            size: stats.size,
            mtime: stats.mtimeMs
        };
    }

    return results;
}
```

This function reads all files in the specified directory and filters them based on their extension and size. It then checks for duplicate filenames and logs a warning if any are found. Finally, it asynchronously reads the contents of each file and returns an object containing their names, sizes, and last modified timestamps.

Please note that this is a basic example and does not include error handling or concurrency control. For production use, you would need to add appropriate error handling and potentially use a queue-based system for processing files asynchronously to prevent memory exhaustion. You might also want to consider using a database or other form of persistent storage if the directory contains millions of files.
