    time_t timestamp;
} FileDescriptorEntry;

typedef struct {
    pthread_mutex_t lock;
    size_t maxSize;
    size_t currentSize;
    FileDescriptorEntry* entries;
} FDManager;

void fdmanager_init(FDManager* manager, size_t maxSize) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->maxSize = maxSize;
    manager->currentSize = 0;
    manager->entries = malloc(sizeof(FileDescriptorEntry) * maxSize);
}

void fdmanager_add(FDManager* manager, int fd) {
    pthread_mutex_lock(&manager->lock);

    if (manager->currentSize >= manager->maxSize) {
        printf("Maximum limit reached. Rejecting connection.\n");
        return;
    }

    FileDescriptorEntry* entry = &manager->entries[manager->currentSize++];
    entry->fd = fd;
    entry->timestamp = time(NULL);

    pthread_mutex_unlock(&manager->lock);
}

void fdmanager_destroy(FDManager* manager) {
    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
}
```
