import java.net.*;
import java.util.*;
import java.nio.ByteBuffer;
import java.lang.reflect.Array;
import java.util.concurrent.*;

public class ConnectionManager {
    private static final int MAX_CONNECTIONS = 10000;
    private static final int MAX_BUFFER_SIZE = 4096; // 4KB buffer size

    private ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private ConcurrentHashMap<Socket, ConnectionInfo> connections = new ConcurrentHashMap<>();

    public void manageDynamicConnectionPool() {
        try (ServerSocket serverSocket = new ServerSocket(8080)) {
            while (true) {
                Socket socket = serverSocket.accept();

                if (connections.size() < MAX_CONNECTIONS) {
                    ConnectionInfo connectionInfo = new ConnectionInfo(socket);
                    connections.put(socket, connectionInfo);

                    executor.execute(() -> handleConnection(connectionInfo));
                } else {
                    socket.close(); // reject the connection if pool is full
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void handleConnection(ConnectionInfo connectionInfo) {
        try {
            ByteBuffer buffer = ByteBuffer.allocateDirect(MAX_BUFFER_SIZE);

            while (connectionInfo.getSocket().isConnected()) {
                int bytesRead = connectionInfo.getSocket().getInputStream().read(buffer.array());

                if (bytesRead == -1) break; // end of stream

                buffer.limit(bytesRead);

                processData(connectionInfo, buffer);
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            connections.remove(connectionInfo.getSocket());
        }
    }

    private void processData(ConnectionInfo connectionInfo, ByteBuffer data) {
        // Process incoming data here...
    }
}

class ConnectionInfo {
    private Socket socket;
    private long lastActivityTimestamp;

    public ConnectionInfo(Socket socket) {
        this.socket = socket;
        this.lastActivityTimestamp = System.currentTimeMillis();
    }

    // getters and setters...
}
