typedef struct {
    size_t fileSize;
    time_t modificationTime;
} FileInfo;

GHashTable* hashMap = NULL;
FileInfo** fileInfos = NULL;
const char** fileNames = NULL;
size_t* offsets = NULL;
int numFiles = 0;
pthread_mutex_t lock;

void* readFile(void* arg) {
    const char* fileName = (const char*)arg;

    FILE* fp = fopen(fileName, "r");
    if (!fp) {
        printf("Failed to open %s\n", fileName);
        return NULL;
    }

    struct stat st;
    stat(fileName, &st);
    size_t fileSize = st.st_size;

    char* buffer = malloc(fileSize + 1);
    if (!buffer) {
        printf("Failed to allocate memory for %s\n", fileName);
        fclose(fp);
        return NULL;
    }

    size_t bytesRead = fread(buffer, 1, fileSize, fp);
    if (bytesRead != fileSize) {
        printf("Failed to read %s\n", fileName);
        free(buffer);
        fclose(fp);
        return NULL;
    }

    buffer[fileSize] = '\0';  // Null-terminate the string

    FileInfo* fileInfo = malloc(sizeof(FileInfo));
    if (!fileInfo) {
        printf("Failed to allocate memory for %s's metadata\n", fileName);
        free(buffer);
        fclose(fp);
        return NULL;
    }

    fileInfo->fileSize = fileSize;
    fileInfo->modificationTime = st.st_mtime;

    pthread_mutex_lock(&lock);
    g_hash_table_insert(hashMap, (gpointer)fileName, fileInfo);
    numFiles++;
    fileInfos = realloc(fileInfos, sizeof(FileInfo*) * numFiles);
    fileNames = realloc(fileNames, sizeof(char*) * numFiles);
    offsets = realloc(offsets, sizeof(size_t) * numFiles);

