class WebSocketConnection {
public:
    WebSocketConnection(const std::string& host, const std::string& port) : host_(host), port_(port) {}
    ~WebSocketConnection() { if (socket_.is_open()) socket_.close(); }

    void connect() {
        tcp::resolver resolver(io_service_);
        tcp::resolver::query query(host_, port_);
