['Here is an example of how you might implement this in C using POSIX threads (pthreads). This code does not include all the features mentioned, but it should give you a good starting point for your task. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record_t;

typedef struct {
    size_t count;
    size_t max_records;
    pthread_mutex_t lock;
    record_t **records;
} record_array_t;

record_array_t *create_record_array(size_t max_records) {
    record_array_t *arr = malloc(sizeof(record_array_t));
    if (arr == NULL) return NULL;

    arr->count = 0;
    arr->max_records = max_records;
    pthread_mutex_init(&arr->lock, NULL);
    arr->records = malloc(sizeof(record_t *) * max_records);

    if (arr->records == NULL) {
        free(arr);
        return NULL;
    }

    for (size_t i = 0; i < max_records; ++i) {
        arr->records[i] = NULL;
    }

    return arr;
}

int add_record(record_array_t *arr, int value) {
    pthread_mutex_lock(&arr->lock);

    if (arr->count >= arr->max_records) {
        pthread_mutex_unlock(&arr->lock);
        return -1; // Error: Max records reached.
    }

    record_t *record = malloc(sizeof(record_t));
    if (record == NULL) {
        pthread_mutex_unlock(&arr->lock);
        return -2; // Error: Memory allocation failed.
    }

    record->value = value;
    arr->records[arr->count++] = record;

    pthread_mutex_unlock(&arr->lock);
    return 0; // Success.
}

int get_record(record_array_t *arr, size_t index) {
    if (index >= arr->max_records) {
        return -1; // Error: Index out of bounds.
    }

    pthread_mutex_lock(&arr->lock);
    record_t *record = arr->records[index];
    pthread_mutex_unlock(&arr->lock);

    if (record == NULL) {
        return -2; // Error: Record not found.
    }

    return record->value;
}
```
This code creates a thread-safe array of records that can be dynamically allocated and accessed in a multi-threaded environment. It uses a mutex to ensure that only one thread can modify the array at a time, preventing data corruption. 

