['Here is an example of how you might implement this in C with POSIX threads (pthreads) and Linux-specific APIs. This code does not include all features mentioned, but it provides a starting point for your requirements. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <openssl/md5.h>

typedef struct {
    char *file_path;
    size_t max_size;
} FileInfo;

void* processFile(void *arg) {
    FileInfo *info = (FileInfo*) arg;

    int fd = open(info->file_path, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return NULL;
    }

    struct stat st;
    if (fstat(fd, &st) != 0) {
        perror("fstat");
        close(fd);
        return NULL;
    }

    if (st.st_size > info->max_size) {
        fprintf(stderr, "File %s is too large\n", info->file_path);
        close(fd);
        return NULL;
    }

    unsigned char *buffer = malloc(info->max_size);
    if (buffer == NULL) {
        perror("malloc");
        close(fd);
        return NULL;
    }

    ssize_t bytesRead = read(fd, buffer, info->max_size);
    if (bytesRead == -1) {
        perror("read");
        free(buffer);
        close(fd);
        return NULL;
    }

    unsigned char md5[MD5_DIGEST_LENGTH];
    MD5(buffer, bytesRead, md5);

    printf("File: %s\n", info->file_path);
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        printf("%02x", md5[i]);
    }
    printf("\n");

    free(buffer);
    close(fd);

    return NULL;
}

int main() {
    char filePath[1024];
    size_t maxSize = 1024 * 1024; // 1MB

    while (fgets(filePath, sizeof(filePath), stdin) != NULL) {
        FileInfo *info = malloc(sizeof(FileInfo));
        if (info == NULL) {
            perror("malloc");
            continue;
        }

        info->file_path = strdup(filePath);
        if (info->file_path == NULL) {
            perror("strdup");
            free(info);
            continue;
        }

        // Remove trailing newline character
        info->file_path[strcspn(info->file_path, "\n")] = 0;

        info->max_size = maxSize;

        pthread_t thread;
        if (pthread_create(&thread, NULL, processFile, info) != 0) {
            perror("pthread_create");
            free(info->file_path);
            free(info);
            continue;
        }

        pthread_detach(thread);
    }

    return 0;
}
```
This code reads file paths from standard input, opens each file in a separate thread, and computes the MD5 hash of its contents. It uses `pthreads` for concurrency and `OpenSSL` for MD5 computation. The maximum size of files is set to 1MB, but you can adjust this as needed.
']

