#include <vector>
#include <string>
#include <atomic>
#include <mutex>

struct SensorData {
    int sensorId;
    std::string deviceIdentifier;
    double geographicalTag;
};

class MemoryManager {
public:
    MemoryManager(size_t maxSize) : maxSize_(maxSize), currentSize_(0) {}

    void* allocate(size_t size) {
        std::lock_guard<std::mutex> lock(mutex_);

        if (currentSize_ + size > maxSize_) {
            throw std::bad_alloc();
        }

        currentSize_ += size;
        return malloc(size);
    }

    void deallocate(void* ptr, size_t size) {
        std::lock_guard<std::mutex> lock(mutex_);

        if (currentSize_ < size) {
            throw std::runtime_error("Invalid memory deallocation");
        }

        currentSize_ -= size;
        free(ptr);
    }

private:
    std::mutex mutex_;
    size_t maxSize_;
    std::atomic<size_t> currentSize_;
};
```
