#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    // Add fields for connection metadata here
} connection_info;

typedef struct {
    int value;
} record;

typedef struct {
    socklen_t* ids;
    const char** labels;
    connection_info* infos;
    record* records;
    size_t capacity;
    atomic_size_t count;
    pthread_rwlock_t lock;
} ConnectionManager;

ConnectionManager* create_manager(size_t initial_capacity) {
    ConnectionManager* manager = malloc(sizeof(ConnectionManager));
    if (!manager) return NULL;

    manager->ids = malloc(initial_capacity * sizeof(socklen_t));
    manager->labels = malloc(initial_capacity * sizeof(const char*));
    manager->infos = calloc(initial_capacity, sizeof(connection_info));
    manager->records = malloc(initial_capacity * sizeof(record));

    if (!manager->ids || !manager->labels || !manager->infos || !manager->records) {
        free_manager(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    atomic_init(&manager->count, 0);
    pthread_rwlock_init(&manager->lock, NULL);

    return manager;
}

void free_manager(ConnectionManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < atomic_load(&manager->count); ++i) {
        free((char*)manager->labels[i]);
    }

    pthread_rwlock_destroy(&manager->lock);
    free(manager->ids);
    free(manager->labels);
    free(manager->infos);
    free(manager->records);
    free(manager);
}
```
