    if (he == NULL) {
        herror("gethostbyname");
        return NULL;
    }
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].ip[0] == 0 && cache[i].hostname[0] == 0) {
            strncpy(cache[i].hostname, hostname, MAX_LINE);
            memcpy(cache[i].ip, he->h_addr_list[0], INET6_ADDRSTRLEN);
            pthread_mutex_unlock(&cacheLock);
            return cache[i].ip;
        }
    }
    pthread_mutex_unlock(&cacheLock);
    return NULL;
}

void processFile(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("fopen");
        return;
    }
    MD5_CTX mdContext;
    unsigned char data[1024];
    int bytes;
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Init(&mdContext);
    while ((bytes = fread(data, 1, 1024, file)) != 0) {
        MD5_Update(&mdContext, data, bytes);
    }
    unsigned char *charDigest = MD5_Final(&mdContext);
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(digest, "%02x", charDigest[i]);
    }
    printf("MD5 digest: %s\n", digest);
}

void *threadFunction(void *arg) {
    const char *filename = (const char *) arg;
    processFile(filename);
    return NULL;
}

int main() {
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, threadFunction, "test.txt");
    }
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
```
