```c
#include <stdio.h>
#include <stdlib.h>

typedef struct settings {
    // Define the fields of the 'settings' object here
} Settings;

typedef struct device {
    int id;
    float voltage_reading;
    Settings settings;
} Device;

typedef struct node {
    Device *device;
    struct node *left;
    struct node *right;
} Node;

Node* newNode(Device *device) {
    Node* temp = (Node*)malloc(sizeof(Node));
    if (!temp) {
        printf("Memory allocation failed. Please check system resources.\n");
        // Send notification to the system administrator for persistent issues
        exit(0);
    }

    temp->device = device;
    temp->left = temp->right = NULL;
    return temp;
}

Node* insert(Node* node, Device *device) {
    if (node == NULL) 
        return newNode(device);

    if (device->id < node->device->id)
        node->left = insert(node->left, device);
    else if (device->id > node->device->id)
        node->right = insert(node->right, device);

    return node;
}

// Implement other BST operations like delete, search etc. here...

void free_tree(Node *root) {
    if (root != NULL) {
        free_tree(root->left);
        free_tree(root->right);

        // Free the device and node memory
        free(root->device);
        free(root);
    }
}
```
This is a basic BST implementation with insertion operation. The `newNode` function allocates memory for a new node, checks if allocation was successful, and returns the newly created node. If allocation fails, it prints an error message and exits the program. 

The `insert` function recursively traverses the tree to find the correct position to insert a new device. It creates a new node with the given device data and assigns it as the left or right child of its parent node based on the comparison between the IDs. If the BST is empty, it simply returns the newly created node.

The `free_tree` function recursively frees all nodes in the tree by traversing to each leaf node and freeing them up one by one. 

