```java
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.WebSecurityConfigurerAdapter;
import org.springframework.security.oauth2.client.OAuth2AuthorizedClientManager;
import org.springframework.security.oauth2.client.OAuth2AuthorizedClientProviderBuilder;
import org.springframework.security.oauth2.client.registration.ClientRegistrationRepository;
import com.netflix.hystrix.contrib.javanica.annotation.HystrixCommand;

@SpringBootApplication
public class WebAppModule extends WebSecurityConfigurerAdapter {
    @Override
    protected void configure(HttpSecurity http) throws Exception {
        http.authorizeRequests()
            .anyRequest().authenticated()
            .and()
            .oauth2Login();
    }

    @Bean
    public OAuth2AuthorizedClientManager authorizedClientManager(
      ClientRegistrationRepository clientRegistrationRepository,
      OAuth2AuthorizedClientRepository authorizedClientRepository) {

        OAuth2AuthorizedClientProvider authorizedClientProvider =
            OAuth2AuthorizedClientProviderBuilder.builder()
                .authorizationCode()
                .refreshToken()
                .build();

        DefaultOAuth2AuthorizedClientManager authorizedClientManager =
            new DefaultOAuth2AuthorizedClientManager(
                clientRegistrationRepository, authorizedClientRepository);
        authorizedClientManager.setAuthorizedClientProvider(authorizedClientProvider);

        return authorizedClientManager;
    }

    @HystrixCommand(fallbackMethod = "fallback")
    public void authenticate() {
        // Authentication logic here
    }

    public void fallback() {
        // Fallback authentication mechanism when OAuth service is unavailable
    }
}
```
This code provides a basic structure for your web application module. It uses Spring Boot to create a standalone, production-grade Spring based Application and the `WebSecurityConfigurerAdapter` to configure HTTP security. The `OAuth2AuthorizedClientManager` bean is used to manage OAuth 2.0 clients and their authorized tokens.

The `@HystrixCommand` annotation is used with a fallback method to handle transient service outages. When the OAuth service is unavailable, the `authenticate()` method will call the `fallback()` method instead.

