int initializeSystem(size_t size, int rangeMin, int rangeMax) {
    srand(time(NULL)); // Seed the random number generator

    long* offsets = malloc(size * sizeof(long));
    if (offsets == NULL) return -1; // Allocation failed

    int* keys = malloc(size * sizeof(int));
    if (keys == NULL) {
        free(offsets);
