['This is quite an extensive task and implementing such a system would require a lot of code. Here's a simplified version of how you might start with this in C. Note that this doesn't include all the features mentioned above but it should give you a good starting point. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct node {
    char* str;
    size_t len;
} node;

typedef struct stringPool {
    pthread_mutex_t lock;
    int maxStrings;
    int currentStrings;
    node** pool;
} stringPool;

stringPool* createStringPool(int maxStrings) {
    stringPool* sp = malloc(sizeof(stringPool));
    if (sp == NULL) return NULL;

    pthread_mutex_init(&sp->lock, NULL);
    sp->maxStrings = maxStrings;
    sp->currentStrings = 0;
    sp->pool = malloc(sizeof(node*) * maxStrings);
    if (sp->pool == NULL) {
        free(sp);
        return NULL;
    }

    for (int i = 0; i < maxStrings; ++i) {
        sp->pool[i] = NULL;
    }

    return sp;
}

void addStringToPool(stringPool* sp, char* str) {
    pthread_mutex_lock(&sp->lock);
    if (sp->currentStrings < sp->maxStrings) {
        node* newNode = malloc(sizeof(node));
        if (newNode != NULL) {
            newNode->str = strdup(str);
            newNode->len = strlen(str);
            sp->pool[sp->currentStrings++] = newNode;
        } else {
            printf("Failed to allocate memory for string\n");
        }
    } else {
        printf("Pool is full, cannot add more strings\n");
    }
    pthread_mutex_unlock(&sp->lock);
}

void freeStringPool(stringPool* sp) {
    pthread_mutex_lock(&sp->lock);
    for (int i = 0; i < sp->currentStrings; ++i) {
        if (sp->pool[i] != NULL) {
            free(sp->pool[i]->str);
            free(sp->pool[i]);
        }
    }
    pthread_mutex_unlock(&sp->lock);

    free(sp->pool);
    pthread_mutex_destroy(&sp->lock);
    free(sp);
}
