    void* handle;
    int (*processFile)(const char*, char**, size_t*);
    void (*freeBuffer)(char*);
} plugin;

plugin plugins[10];
int numPlugins = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void loadPlugin(const char* path) {
    void *handle = dlopen(path, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Failed to load plugin: %s\n", dlerror());
        return;
    }

    char* (*getName)() = dlsym(handle, "getName");
    int (*processFile)(const char*, char**, size_t*) = dlsym(handle, "processFile");
    void (*freeBuffer)(char*) = dlsym(handle, "freeBuffer");

    if (!getName || !processFile || !freeBuffer) {
        fprintf(stderr, "Invalid plugin: %s\n", path);
        return;
    }

    pthread_mutex_lock(&mutex);
    plugins[numPlugins].name = getName();
    plugins[numPlugins].handle = handle;
    plugins[numPlugins].processFile = processFile;
    plugins[numPlugins].freeBuffer = freeBuffer;
    numPlugins++;
    pthread_mutex_unlock(&mutex);
}

void* readFiles(void* arg) {
    const char** filePaths = (const char**)arg;

    for (int i = 0; filePaths[i] != NULL; i++) {
        int fd = open(filePaths[i], O_RDONLY);
        if (fd == -1) {
            perror("Failed to open file");
            continue;
        }

        struct stat st;
        if (fstat(fd, &st) == -1) {
            perror("Failed to get file status");
            close(fd);
            continue;
        }

        size_t size = st.st_size;
        char* buffer = malloc(size);
        if (!buffer) {
            perror("Failed to allocate memory for buffer");
            close(fd);
            continue;
        }

        ssize_t bytesRead = read(fd, buffer, size);
        if (bytesRead == -1) {
            perror("Failed to read file");
            free(buffer);
            close(fd);
            continue;
        } else if ((size_t)bytesRead != size) {
            fprintf(stderr, "Short read: expected %zu bytes, got %zd\n", size, bytesRead);
            free(buffer);
            close(fd);
            continue;
        }

        // Process file using plugins...

        for (int j = 0; j < numPlugins; j++) {
            char* processedBuffer = NULL;
            size_t processedSize = 0;

            if (!plugins[j].processFile(buffer, &processedBuffer, &processedSize)) {
                // Processing failed...

                plugins[j].freeBuffer(processedBuffer);
                free(buffer);
                close(fd);
                continue;
            }

            // Use processed buffer...

            plugins[j].freeBuffer(processedBuffer);
        }

        free(buffer);
        close(fd);
    }

    return NULL;
}

int main() {
    const char* filePaths[] = {"file1.txt", "file2.txt", /*...*/, NULL};

    // Load plugins...

    pthread_t thread;
    if (pthread_create(&thread, NULL, readFiles, filePaths) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        return 1;
    }

    // Unload plugins...

    return 0;
}
