    MyStruct* newElem = malloc(sizeof(MyStruct));
    if (newElem == NULL || arr->count >= arr->maxCount) {
        free(newElem);
        pthread_mutex_unlock(&arr->lock);
        return NULL;
    }

    newElem->num = num;
