['Here is a simplified example of how you might implement an in-memory cache system using C. This code does not include thread safety, advanced querying capabilities or error handling which are crucial for a production level system. 

```c
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* key;
    void* value;
} Entry;

typedef struct {
    int capacity;
    int size;
    Entry** entries;
} Cache;

Cache* create_cache(int capacity) {
    Cache* cache = malloc(sizeof(Cache));
    cache->capacity = capacity;
    cache->size = 0;
    cache->entries = malloc(sizeof(Entry*) * capacity);
    return cache;
}

void insert_entry(Cache* cache, const char* key, void* value) {
    if (cache->size == cache->capacity) {
        // Handle error: Cache is full
        return;
    }

    Entry* entry = malloc(sizeof(Entry));
    entry->key = strdup(key);
    entry->value = value;

    cache->entries[cache->size++] = entry;
}

void* get_entry(Cache* cache, const char* key) {
    for (int i = 0; i < cache->size; ++i) {
        if (strcmp(cache->entries[i]->key, key) == 0) {
            return cache->entries[i]->value;
        }
    }

    // Handle error: Key not found
    return NULL;
}

void delete_entry(Cache* cache, const char* key) {
    for (int i = 0; i < cache->size; ++i) {
        if (strcmp(cache->entries[i]->key, key) == 0) {
            free(cache->entries[i]->key);
            free(cache->entries[i]);

            cache->entries[i] = cache->entries[--cache->size];
            return;
        }
    }

    // Handle error: Key not found
}
```
