}

void addRecord(Collection* collection, Record record, long offset, int key) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->currentSize < collection->maxRecords) {
        // Check for duplicate values
        for (size_t i = 0; i < collection->currentSize; ++i) {
            if (collection->records[i].value == record.value) {
                pthread_mutex_unlock(&collection->mutex);
                return;
            }
        }

        // Add the new record
        collection->records[collection->currentSize] = record;
        collection->offsets[collection->currentSize] = offset;
        collection->keys[collection->currentSize] = key;
        ++collection->currentSize;
    }

    pthread_mutex_unlock(&collection->mutex);
}
```
This code creates a `Collection` structure that manages an array of records, offsets and keys. The `addRecord` function checks for duplicate values before adding a new record to the collection. It uses a mutex to ensure thread safety when adding records. 

