class DynamicRandomGenerator {
private:
    std::mt19937 mt; // Mersenne Twister is a popular random number generator algorithm
    std::uniform_real_distribution<double> dist;
    std::mutex mutex;

public:
    DynamicRandomGenerator() : dist(0.0, 1.0) {
        std::random_device rd; // obtain a seed for the random number engine
        mt = std::mt19937(rd()); // initialize Mersenne Twister with this seed
    }

    double generateUniformRandom() {
        std::lock_guard<std::mutex> lock(mutex);
        return dist(mt);
    }

    double generateNormalRandom(double mean, double stddev) {
        if (stddev <= 0.0) throw std::invalid_argument("Standard deviation must be positive.");

        std::normal_distribution<double> normalDist(mean, stddev);
        std::lock_guard<std::mutex> lock(mutex);
        return normalDist(mt);
    }

    double generateExponentialRandom(double lambda) {
        if (lambda <= 0.0) throw std::invalid_argument("Lambda must be positive.");

        std::exponential_distribution<double> expDist(lambda);
        std::lock_guard<std::mutex> lock(mutex);
        return expDist(mt);
    }

    // Add more methods as per your requirements...
};
```
This class uses the Mersenne Twister random number generator algorithm, which is a high-quality pseudo-random number generator. It generates numbers that pass statistical tests of randomness and has a period of 2^19937−1. The `std::uniform_real_distribution` is used to generate uniform real numbers in the range [0, 1).

The methods are thread-safe because they lock a mutex before accessing the Mersenne Twister and distribution objects. This ensures that only one thread can access these objects at a time, preventing race conditions.

