data_struct* init(size_t max, int enforce_uniqueness) {
    srand(time(NULL));
    data_struct* ds = malloc(sizeof(data_struct));
    if (ds == NULL) return NULL;

    ds->offsets = calloc(max, sizeof(long));
    ds->keys = calloc(max, sizeof(int));
    ds->records = calloc(max, sizeof(record*));
    ds->lookup = calloc(max, sizeof(record**));

    if (ds->offsets == NULL || ds->keys == NULL || ds->records == NULL || ds->lookup == NULL) {
        free_data_struct(ds);
        return NULL;
    }

    for (size_t i = 0; i < max; ++i) {
        int value = rand();

        if (enforce_uniqueness) {
            while (lookup[value % max] != NULL) {
                value = rand();
            }
        }

        ds->records[i] = malloc(sizeof(record));
        if (ds->records[i] == NULL) {
            free_data_struct(ds);
            return NULL;
        }

        ds->records[i]->value = value;
        ds->keys[i] = value % max;
        ds->lookup[value % max] = &ds->records[i];
    }

    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

void free_data_struct(data_struct* ds) {
