    pthread_mutex_t lock;
    size_t max_entries;
    size_t current_entries;
    data_entry_t **data_entries;
} data_manager_t;

int init_data_manager(data_manager_t *dm, size_t max_entries) {
    dm->max_entries = max_entries;
    dm->current_entries = 0;
    dm->data_entries = malloc(sizeof(data_entry_t *) * max_entries);
    if (dm->data_entries == NULL) {
        return -1;
    }
    pthread_mutex_init(&dm->lock, NULL);
    return 0;
}

int add_data_entry(data_manager_t *dm, data_entry_t *de) {
    if (pthread_mutex_lock(&dm->lock)) {
        return -1;
    }
    if (dm->current_entries >= dm->max_entries) {
        pthread_mutex_unlock(&dm->lock);
        return -2;
    }
    de->key = dm->current_entries++;
    dm->data_entries[de->key] = de;
    pthread_mutex_unlock(&dm->lock);
    return 0;
}

int find_largest_key(data_manager_t *dm) {
    if (pthread_mutex_lock(&dm->lock)) {
        return -1;
    }
    int largest = -1;
    for (size_t i = 0; i < dm->current_entries; ++i) {
        if (dm->data_entries[i]->key > largest) {
            largest = dm->data_entries[i]->key;
        }
    }
    pthread_mutex_unlock(&dm->lock);
    return largest;
}

void free_data_manager(data_manager_t *dm) {
    for (size_t i = 0; i < dm->current_entries; ++i) {
        free(dm->data_entries[i]->metadata);
        free(dm->data_entries[i]->payload->identifier);
        free(dm->data_entries[i]->payload);
        free(dm->data_entries[i]);
    }
    pthread_mutex_destroy(&dm->lock);
    free(dm->data_entries);
}
