public Dictionary<string, string> ProcessFilePaths(List<string> filePaths)
{
    // Check if environment variable is set and create directory if not
    var envVar = Environment.GetEnvironmentVariable("MyEnvVar");
    if (envVar == null)
    {
        var dirPath = Path.Combine(AppContext.BaseDirectory, "Resources");
        Directory.CreateDirectory(dirPath);
        Environment.SetEnvironmentVariable("MyEnvVar", dirPath);
    }

    // Initialize logging mechanism
    Logger logger = new Logger();
    logger.Configure("logfile.txt");

    Dictionary<string, string> fileHashes = new Dictionary<string, string>();
    foreach (var path in filePaths)
    {
        try
        {
            // Parse XML using XPath to find first element matching a given name
            var doc = new XmlDocument();
            doc.Load(path);
            var navigator = doc.CreateNavigator();
            var expression = navigator.Compile("//elementName");
            var iterator = navigator.Select(expression);

            // Check if element exists and throw exception if not or multiple elements are found
            int count = 0;
            while (iterator.MoveNext())
                count++;

            if (count != 1)
                throw new Exception("Element not found or multiple elements found");

            // Calculate MD5 hash of file content
            var md5 = MD5.Create();
            using (var stream = File.OpenRead(path))
            {
                var hashBytes = md5.ComputeHash(stream);
                var hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
                fileHashes[Path.GetFileName(path)] = hashString;
            }
        }
        catch (Exception ex)
        {
            logger.LogError(ex.Message);
        }
    }

    // Log total files processed, successfully hashed, and those skipped
    logger.LogInfo($"Total files: {filePaths.Count}, Successfully Hashed: {fileHashes.Count}, Skipped: {filePaths.Count - fileHashes.Count}");

    return fileHashes;
}
```
