    private static final int MAX_CONCURRENT_COMMANDS = 15;
    private static final long TIMEOUT = 60 * 1000; // 1 minute

    private AmazonS3 s3Client;
    private Storage gcsClient;
    private MinioClient minioClient;

    private Map<String, String> md5Cache = new HashMap<>();
    private List<Process> childProcesses = new ArrayList<>();

    public CloudStorageService() {
        // Initialize cloud storage clients here
    }

    public void processFile(String filePath) throws Exception {
        if (filePath.length() > MAX_FILE_SIZE) {
            throw new IllegalArgumentException("File size exceeds limit");
        }

        String md5 = DigestUtils.md5Hex(new FileInputStream(filePath));
        if (md5Cache.containsKey(md5)) {
            System.out.println("Skipping file, already processed: " + filePath);
            return;
        }

        md5Cache.put(md5, filePath);

        // Process the file here
    }

    public void executeCommand(String command) throws Exception {
        if (childProcesses.size() >= MAX_CONCURRENT_COMMANDS) {
            throw new IllegalStateException("Too many concurrent commands");
        }

        ProcessBuilder pb = new ProcessBuilder(command);
        Process child = pb.start();
        childProcesses.add(child);

        // Start a background thread to kill the process if it takes too long
        Thread timeoutThread = new Thread(() -> {
            try {
                Thread.sleep(TIMEOUT);
                child.destroy();
            } catch (InterruptedException e) {
                // Ignore
            }
        });
        timeoutThread.start();

        // Wait for the process to finish and remove it from the list of child processes
        int exitCode = child.waitFor();
        childProcesses.remove(child);

        if (exitCode != 0) {
            throw new Exception("Command failed with exit code " + exitCode);
        }
    }

