const blueslip = require('blueslip');
const axios = require('axios').default;

class TestRunner {
  constructor(moduleName) {
    this.moduleName = moduleName;
    this.tests = [];
    this.mockConfigsCache = {};
  }

  addTest(testFn, mockConfig) {
    this.tests.push({ testFn, mockConfig });
  }

  async runTests() {
    const startTime = Date.now();
    let totalDuration = 0;

    for (let i = 0; i < Math.min(this.tests.length, 5); i++) {
      const testData = this.tests[i];
      const mockConfigCacheKey = JSON.stringify(testData.mockConfig);
      let mockConfig = this.mockConfigsCache[mockConfigCacheKey];

      if (!mockConfig) {
        mockConfig = blueslip.createMockConfig(testData.mockConfig);
        this.mockConfigsCache[mockConfigCacheKey] = mockConfig;
      }

      const testStartTime = Date.now();
      console.log(`Running test ${i + 1} for module ${this.moduleName}...`);

      try {
        await testData.testFn(mockConfig);
        console.log('Test passed');
      } catch (error) {
        console.error('Test failed', error);
      } finally {
        const duration = Date.now() - testStartTime;
        totalDuration += duration;
        console.log(`Test ${i + 1} took ${duration}ms to complete`);
      }
    }

    const endTime = Date.now();
    const totalExecutionTime = endTime - startTime;
    console.log(`Total execution time: ${totalExecutionTime}ms, Total test duration: ${totalDuration}ms`);
  }

  async fetchTestsAndDependencies() {
    try {
      const response = await axios.get('http://test-config-service/tests');
      this.tests = response.data.tests;
      // Fetch dependencies and cache them for subsequent test runs
    } catch (error) {
      console.error('Failed to fetch tests', error);
      throw error;
    }
  }
}
