app.factory('dataFetchingService', ['$http', '$q', 'cacheService', 'messageService', function($http, $q, cacheService, messageService) {
    return {
        refreshFields: function(resourceId, config) {
            var promises = [];

            // Iterate over each field in the configuration object
            for (var fieldName in config) {
                if (config.hasOwnProperty(fieldName)) {
                    var url = config[fieldName];

                    // Check cache before making a request
                    var cachedData = cacheService.getCachedData(url);
                    if (cachedData) {
                        messageService.sendMessage({
                            resourceId: resourceId,
                            fieldName: fieldName,
                            data: cachedData
                        });
                    } else {
                        $http.get(url).then(function(response) {
                            cacheService.cacheData(url, response.data);
                            messageService.sendMessage({
                                resourceId: resourceId,
                                fieldName: fieldName,
                                data: response.data
                            });
                        }, function() {
                            // Fallback mechanism for failed fetch attempts
                            messageService.sendMessage({
                                resourceId: resourceId,
                                fieldName: fieldName,
                                data: 'Fetch failed'
                            });
                        });
                    }
                }
            }

            $q.all(promises).then(function() {
                // All fields have been updated
            }, function() {
                // Some or all fields failed to update
            });
        }
    };
}]);
```
