void process_sensor_stream(FILE *input) {
    sensor_metadata metadata;
    sensor_data data;

    while (fread(&metadata, sizeof(sensor_metadata), 1, input)) {
        if (fread(&data, sizeof(sensor_data), 1, input) != 1) {
            fprintf(stderr, "Error reading sensor data\n");
            return;
        }

        pthread_mutex_lock(&metadata_lock);
        if (sensors[metadata.id].metadata == NULL) {
            sensors[metadata.id].metadata = malloc(sizeof(sensor_metadata));
            *sensors[metadata.id].metadata = metadata;

            // Initialize sliding window for sensor data
            sensors[metadata.id].window_size = 1024;
            sensors[metadata.id].current_index = 0;
            sensors[metadata.id].window = calloc(sensors[metadata.id].window_size, sizeof(sensor_data *));

            pthread_mutex_init(&sensors[metadata.id].lock, NULL);
        }
        pthread_mutex_unlock(&metadata_lock);

        pthread_mutex_lock(&sensors[metadata.id].lock);
        if (total_data_size + sizeof(sensor_data) > MAX_DATA_SIZE) {
            fprintf(stderr, "Maximum data size limit exceeded\n");
            return;
        }

        // Add sensor data to sliding window and update total data size
        if (sensors[metadata.id].window[sensors[metadata.id].current_index] != NULL) {
            free(sensors[metadata.id].window[sensors[metadata.id].current_index]);
            total_data_size -= sizeof(sensor_data);
        }

        sensors[metadata.id].window[sensors[metadata.id].current_index] = malloc(sizeof(sensor_data));
        *sensors[metadata.id].window[sensors[metadata.id].current_index] = data;
        total_data_size += sizeof(sensor_data);

        sensors[metadata.id].current_index = (sensors[metadata.id].current_index + 1) % sensors[metadata.id].window_size;
        pthread_mutex_unlock(&sensors[metadata.id].lock);
    }
}
