#include <pthread.h>

typedef struct point {
    float x;
    float y;
} Point;

typedef struct map {
    size_t capacity;
    size_t size;
    Point* points;
    pthread_mutex_t lock;
} Map;

Map* create_map(size_t initial_capacity) {
    Map* map = malloc(sizeof(Map));
    if (map == NULL) return NULL;

    map->points = malloc(initial_capacity * sizeof(Point));
    if (map->points == NULL) {
        free(map);
        return NULL;
    }

    map->size = 0;
    map->capacity = initial_capacity;
    pthread_mutex_init(&map->lock, NULL);

    return map;
}

void resize_map(Map* map, size_t new_capacity) {
    Point* new_points = realloc(map->points, new_capacity * sizeof(Point));
    if (new_points != NULL) {
        map->points = new_points;
        map->capacity = new_capacity;
    }
}

void add_point(Map* map, Point p) {
    pthread_mutex_lock(&map->lock);

    if (map->size == map->capacity) {
        resize_map(map, map->capacity * 2);
    }

    map->points[map->size++] = p;

    pthread_mutex_unlock(&map->lock);
}

void remove_point(Map* map, Point p) {
    pthread_mutex_lock(&map->lock);

    for (int i = 0; i < map->size; ++i) {
        if (map->points[i].x == p.x && map->points[i].y == p.y) {
            map->points[i] = map->points[--map->size];
            break;
        }
    }

    if (map->size > 0 && map->size < map->capacity / 4) {
        resize_map(map, map->capacity / 2);
    }

    pthread_mutex_unlock(&map->lock);
}

Point* get_points_in_radius(Map* map, Point center, float radius) {
    Point* result = malloc(sizeof(Point));
    int count = 0;

    for (int i = 0; i < map->size; ++i) {
        float dx = map->points[i].x - center.x;
        float dy = map->points[i].y - center.y;

        if (sqrt(dx * dx + dy * dy) <= radius) {
            result[count++] = map->points[i];
            result = realloc(result, (count + 1) * sizeof(Point));
        }
    }

    return result;
}
```
