// Define a custom data structure for events
typedef struct Event {
    time_t timestamp;
    char* message;
} Event;

// Define a circular buffer to store events
#define MAX_EVENTS 1000
Event eventBuffer[MAX_EVENTS];
int eventCount = 0;
pthread_mutex_t eventMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add an event to the buffer
void addEvent(char* message) {
    pthread_mutex_lock(&eventMutex);

    // Remove oldest event if maximum reached
    if (eventCount == MAX_EVENTS) {
        free(eventBuffer[0].message);
        for (int i = 1; i < MAX_EVENTS; ++i) {
            eventBuffer[i - 1] = eventBuffer[i];
        }
        --eventCount;
    }

    // Add new event
    Event e;
    e.timestamp = time(NULL);
    e.message = strdup(message);
    eventBuffer[(eventCount++) % MAX_EVENTS] = e;

    pthread_mutex_unlock(&eventMutex);
}

// Function to get events from the buffer
Event* getEvents() {
    Event* result = malloc(sizeof(Event) * eventCount);
    pthread_mutex_lock(&eventMutex);

    for (int i = 0; i < eventCount; ++i) {
        result[i] = eventBuffer[(i + eventCount - eventCount) % MAX_EVENTS];
    }

    pthread_mutex_unlock(&eventMutex);
    return result;
}

// Function to create a directory and set an environment variable
void createDirectory(char* dirName, char* envVar) {
    if (getenv(envVar)) {
        printf("Environment variable %s already set\n", envVar);
        return;
    }

    int result = mkdir(dirName, 0755);
    if (result == -1 && errno != EEXIST) {
        perror("Error creating directory");
        return;
    }

    char* command = malloc(strlen(envVar) + strlen(dirName) + 2);
    sprintf(command, "%s=%s", envVar, dirName);
    putenv(command);
}

