    pthread_mutex_lock(&array->lock);
    array->offsets[array->size] = offset;
    array->keys[array->size] = key;
    array->records[array->size] = record;
    array->size++;
    pthread_mutex_unlock(&array->lock);
}

Record* get_record(Array* array, int key) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->keys[i] == key) {
            return array->records[i];
        }
    }

    return NULL;
}

void free_array(Array* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->records[i]);
    }

    free(array->offsets);
    free(array->keys);
    free(array->records);
    pthread_mutex_destroy(&array->lock);
    free(array);
}
```
