void add_record(int value) {
    if (record_count >= max_record_count) {
        fprintf(stderr, "Maximum number of records reached\n");
        exit(EXIT_FAILURE);
    }

    Record *record = create_record(value);
    records[record_count++] = record;
}

void* manage_records() {
    pthread_mutex_init(&lock, NULL);
    records = allocate_memory(max_record_count * sizeof(Record*));

