#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct item {
    int key;
    char* string;
    size_t length;
} Item;

typedef struct array {
    pthread_mutex_t lock;
    Item* items;
    size_t capacity;
    size_t count;
} Array;

Array* create_array(size_t initial_capacity) {
    Array* arr = malloc(sizeof(Array));
    if (arr == NULL) return NULL;

    pthread_mutex_init(&arr->lock, NULL);

    arr->items = calloc(initial_capacity, sizeof(Item));
    if (arr->items == NULL) {
        free(arr);
        return NULL;
    }

    arr->capacity = initial_capacity;
    arr->count = 0;

    return arr;
}

int add_item(Array* arr, int key, size_t length) {
    pthread_mutex_lock(&arr->lock);

    if (arr->count >= arr->capacity) {
        Item* new_items = realloc(arr->items, 2 * arr->capacity * sizeof(Item));
        if (new_items == NULL) {
            pthread_mutex_unlock(&arr->lock);
            return -1; // Allocation failed
        }

        arr->items = new_items;
        arr->capacity *= 2;
    }

    Item* item = &arr->items[arr->count];
    item->key = key;
    item->length = length;
    item->string = malloc(item->length + 1); // +1 for null terminator
    if (item->string == NULL) {
        pthread_mutex_unlock(&arr->lock);
        return -1; // Allocation failed
    }

    sprintf(item->string, "Item%d", key);

    arr->count++;

    pthread_mutex_unlock(&arr->lock);

    return 0; // Success
}
```
