```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <assert.h>

typedef struct {
    int key;
    char* string;
    size_t length;
} item;

typedef struct record {
    int value;
    struct record *next;
} record;

typedef struct hash_table {
    pthread_mutex_t lock;
    size_t size;
    size_t count;
    record **records;
} hash_table;

hash_table* create_hash_table(size_t size) {
    hash_table *ht = malloc(sizeof(hash_table));
    if (ht == NULL) return NULL;

    ht->size = size;
    ht->count = 0;
    ht->records = calloc(size, sizeof(record*));
    if (ht->records == NULL) {
        free(ht);
        return NULL;
    }

    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void destroy_hash_table(hash_table *ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        record *r = ht->records[i];
        while (r != NULL) {
            record *next = r->next;
            free(r);
            r = next;
        }
    }

    pthread_mutex_destroy(&ht->lock);
    free(ht->records);
    free(ht);
}

void insert_record(hash_table *ht, int key, record *r) {
    size_t index = key % ht->size;

    pthread_mutex_lock(&ht->lock);
    r->next = ht->records[index];
    ht->records[index] = r;
    ht->count++;
    pthread_mutex_unlock(&ht->lock);
}

record* find_record(hash_table *ht, int key) {
    size_t index = key % ht->size;

    pthread_mutex_lock(&ht->lock);
    record *r = ht->records[index];
    while (r != NULL && r->value != key) {
        r = r->next;
    }
    pthread_mutex_unlock(&ht->lock);

    return r;
}
```
