    if ((startNode->id && strcmp(selector, startNode->id) == 0) ||
        (startNode->class && strcmp(selector, startNode->class) == 0)) {

        int length = strlen(currentPath);
        currentPath = realloc(currentPath, (length + strlen(startNode->id ? startNode->id : startNode->class) + 2) * sizeof(char));
        strcat(currentPath, "/");
        strcat(currentPath, startNode->id ? startNode->id : startNode->class);
    }

    for (int i = 0; startNode->children[i] != NULL; ++i) {
        if (nodeIndices == NULL || (nodeIndices[0] <= i && i <= nodeIndices[1])) {
            buildPathString(currentPath, maxDepth, startNode->children[i], selector, nodeIndices);
        }
    }

    return currentPath;
}
