        return;
    }

    new_node->data = strdup(data);
    if (new_node->data == NULL) {
        free(new_node);
        // Handle memory allocation failure gracefully.
        return;
    }

    new_node->priority = priority;
    pthread_mutex_lock(&lock);
    Node** indirect = &head;

    while (*indirect != NULL && comparator(new_node, *indirect) <= 0) {
        indirect = &(*indirect)->next;
    }

    new_node->next = *indirect;
    *indirect = new_node;
    pthread_mutex_unlock(&lock);
}

char* getHighestPriorityData() {
    pthread_mutex_lock(&lock);
    char* data = head != NULL ? strdup(head->data) : NULL;
    pthread_mutex_unlock(&lock);

    return data;
}

void clearList() {
    pthread_mutex_lock(&lock);
    while (head != NULL) {
        Node* next = head->next;
        free(head->data);
        free(head);
        head = next;
    }

    pthread_mutex_unlock(&lock);
}
```
