['Here is a basic outline of how you might approach this task in C++ using libtiff for parsing the image file and OpenSSL for calculating the MD5 hash. This code does not include error handling, RAII principles or streaming large images as these would significantly increase the complexity of the solution. 

```cpp
#include <openssl/md5.h>
#include <tiffio.h>
#include <string>
#include <vector>

struct ImageMetadata {
    uint32_t width;
    uint32_t height;
    uint16_t bitsPerSample;
    uint16_t samplesPerPixel;
    uint16_t compressionType;
    std::string colorInterpretation;
    std::vector<unsigned char> md5Hash;
};

ImageMetadata parseTiff(const std::string& filename) {
    TIFF* tif = TIFFOpen(filename.c_str(), "r");
    if (tif == nullptr) {
        throw std::runtime_error("Failed to open TIFF file.");
    }

    ImageMetadata metadata;
    TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &metadata.width);
    TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &metadata.height);
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &metadata.bitsPerSample);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &metadata.samplesPerPixel);
    TIFFGetField(tif, TIFFTAG_COMPRESSION, &metadata.compressionType);

    char* colorInterpretation;
    if (TIFFGetField(tif, TIFFTAG_PHOTOMETRIC, &colorInterpretation) == 1) {
        metadata.colorInterpretation = colorInterpretation;
    }

    MD5_CTX mdContext;
    MD5_Init(&mdContext);

    uint32_t width = TIFFScanlineSize(tif);
    std::vector<unsigned char> buffer(width);
    for (uint32_t row = 0; row < metadata.height; ++row) {
        if (TIFFReadScanline(tif, &buffer[0], row) <= 0) {
            throw std::runtime_error("Failed to read scanline from TIFF file.");
        }

        MD5_Update(&mdContext, &buffer[0], width);
    }

    metadata.md5Hash.resize(MD5_DIGEST_LENGTH);
    MD5_Final(&metadata.md5Hash[0], &mdContext);

    TIFFClose(tif);

    return metadata;
}
```
This code does not handle images with multiple pages or components, each potentially containing different metadata and compression types. It also doesn't support non-standard TIFF variants or streaming large images. You would need to add these features yourself based on your specific requirements. 

