#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

int process_batch(long size) {
    if (size <= 0 || size > 1000) return 0;

    long* offsets = malloc(size * sizeof(long));
    if (!offsets) return -1; // Memory allocation failed.

    int keys[100];
    for (int i = 0; i < size && i < 100; ++i) {
        keys[i] = rand();
    }

    Record* records = malloc(size * sizeof(Record));
    if (!records) { // Memory allocation failed.
        free(offsets);
        return -1;
    }

    int last_value = 0;
    for (int i = 0; i < size; ++i) {
        do {
            records[i].value = rand();
        } while (records[i].value == last_value);
        last_value = records[i].value;
    }

    free(offsets);
    free(records);

    return size; // Return the number of successfully initialized records.
}
```
This function first checks if the provided size is valid (greater than 0 and less than or equal to 1000). If it's not, it returns 0 without allocating any memory. It then dynamically allocates memory for the offsets array and keys array. If either of these allocations fail, it frees the already allocated memory (if any) and returns -1 to indicate a failure.

Next, it fills the keys array with random values. Since the size of the keys array is fixed at 100, if the provided size exceeds this limit, it truncates the input by only filling the first 100 elements.

Then, it dynamically allocates memory for an array of Record structures and checks if the allocation was successful. If not, it frees the already allocated memory (if any) and returns -1 to indicate a failure.

Finally, it fills each record with a random value that is different from the previous one. After filling all records, it frees both the offsets array and the records array and returns the number of successfully initialized records.
