```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    size_t id;
    const char* address;
    time_t lastActiveTime;
    int messageCount;
} connection_info;

typedef struct {
    pthread_mutex_t lock;
    size_t maxSize;
    size_t currentSize;
    connection_info** connections;
    char** messages;
} ConnectionManager;

ConnectionManager* createConnectionManager(size_t maxSize) {
    ConnectionManager* manager = malloc(sizeof(ConnectionManager));
    if (manager == NULL) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->maxSize = maxSize;
    manager->currentSize = 0;
    manager->connections = malloc(sizeof(connection_info*) * maxSize);
    if (manager->connections == NULL) {
        free(manager);
        return NULL;
    }

    manager->messages = malloc(sizeof(char*) * maxSize);
    if (manager->messages == NULL) {
        free(manager->connections);
        free(manager);
        return NULL;
    }

    return manager;
}

void addConnection(ConnectionManager* manager, size_t id, const char* address) {
    pthread_mutex_lock(&manager->lock);
    if (manager->currentSize >= manager->maxSize) {
        // Handle error: max connections reached.
        return;
    }

    connection_info* info = malloc(sizeof(connection_info));
    if (info == NULL) {
        // Handle error: memory allocation failed.
        return;
    }

    info->id = id;
    info->address = address;
    info->lastActiveTime = 0;
    info->messageCount = 0;

    manager->connections[manager->currentSize] = info;
    manager->messages[manager->currentSize] = NULL;
    manager->currentSize++;

    pthread_mutex_unlock(&manager->lock);
}

void processMessage(ConnectionManager* manager, size_t id, const char* message) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->currentSize; ++i) {
        if (manager->connections[i]->id == id) {
            size_t newMessageLength = strlen(message);
            if (newMessageLength + manager->connections[i]->messageCount > manager->maxSize) {
                // Handle error: message exceeds max size.
                return;
            }

            char* newBuffer = realloc(manager->messages[i], 
                                      manager->connections[i]->messageCount + newMessageLength);
            if (newBuffer == NULL) {
                // Handle error: memory allocation failed.
                return;
            }

            strcat(newBuffer, message);
            manager->messages[i] = newBuffer;
            manager->connections[i]->messageCount += newMessageLength;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void destroyConnectionManager(ConnectionManager* manager) {
    for (size_t i = 0; i < manager->currentSize; ++i) {
        free(manager->connections[i]);
        free(manager->messages[i]);
    }

    free(manager->connections);
    free(manager->messages);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```
