```java
import java.util.*;
import java.util.concurrent.*;
import java.nio.ByteBuffer;
import java.net.*;
import java.lang.management.ManagementFactory;

public class NetworkConnectionManager {
    private static final int MAX_DATA_SIZE = 1024 * 1024; // 1MB
    private ConcurrentHashMap<String, ConnectionInfo> connectionPool = new ConcurrentHashMap<>();
    private CopyOnWriteArrayList<ConnectionInfo> activeConnections = new CopyOnWriteArrayList<>();
    private ExecutorService executorService = Executors.newCachedThreadPool();

    public void manageNetworkConnections(String label, socklen_t id) {
        ConnectionInfo connectionInfo = new ConnectionInfo(label, id);

        if (connectionPool.putIfAbsent(label, connectionInfo) != null) {
            // handle duplicate connection labels
        } else {
            activeConnections.add(connectionInfo);

            executorService.submit(() -> {
                try {
                    processIncomingData(connectionInfo);
                } catch (Exception e) {
                    // handle exceptions
                } finally {
                    activeConnections.remove(connectionInfo);
                }
            });
        }
    }

    private void processIncomingData(ConnectionInfo connectionInfo) throws Exception {
        DatagramSocket socket = new DatagramSocket();

        while (true) {
            byte[] buffer = new byte[4096];
            DatagramPacket packet = new DatagramPacket(buffer, buffer.length);

            socket.receive(packet);

            int dataSize = packet.getLength();

            if (dataSize + connectionInfo.totalDataSize > MAX_DATA_SIZE) {
                // handle error: total data size limit exceeded
            } else {
                ByteBuffer byteBuffer = ByteBuffer.allocate(connectionInfo.totalDataSize + dataSize);

                byteBuffer.put(connectionInfo.dataBuffer);
                byteBuffer.put(buffer, 0, dataSize);

                connectionInfo.dataBuffer = byteBuffer.array();
                connectionInfo.totalDataSize += dataSize;
            }
        }
    }

    private class ConnectionInfo {
        String label;
        socklen_t id;
        Object mutex = new Object();

        int totalDataSize = 0;
        byte[] dataBuffer = new byte[0];

        ConnectionInfo(String label, socklen_t id) {
            this.label = label;
            this.id = id;
        }
    }
}
```
This code uses a `ConcurrentHashMap` to store the connection pool and a `CopyOnWriteArrayList` for active connections. It creates a new thread for each incoming connection, which processes incoming data asynchronously. The total size of processed data is tracked in each `ConnectionInfo` object. If the total size exceeds the limit, an error is thrown.

