["This is quite an extensive task that would require a lot of code to fully implement all these features. Here's a simplified version of what such a function might look like in C. This does not include all the features you requested, but it should give you a good starting point for building your own logging system. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* timestamp;
    int severity_level;
    char** custom_fields;
    char* message;
} LogEntry;

typedef struct {
    LogEntry* entries;
    size_t max_entries;
    size_t current_index;
    pthread_mutex_t lock;
} Logger;

Logger* create_logger(size_t max_entries) {
    Logger* logger = malloc(sizeof(Logger));
    if (logger == NULL) {
        return NULL;
    }

    logger->max_entries = max_entries;
    logger->current_index = 0;
    logger->entries = calloc(max_entries, sizeof(LogEntry));
    if (logger->entries == NULL) {
        free(logger);
        return NULL;
    }

    pthread_mutex_init(&logger->lock, NULL);

    return logger;
}

void log_entry(Logger* logger, LogEntry entry) {
    pthread_mutex_lock(&logger->lock);

    if (logger->current_index >= logger->max_entries) {
        // Discard oldest entry and shift all others down.
        memmove(logger->entries, logger->entries + 1, sizeof(LogEntry) * (logger->max_entries - 1));
        logger->current_index--;
    }

    // Add new entry to the end of the array.
    logger->entries[logger->current_index] = entry;
    logger->current_index++;

    pthread_mutex_unlock(&logger->lock);
}
```
This code creates a simple logging system that stores log entries in memory and discards the oldest ones when the maximum number of entries is exceeded. It uses a mutex to ensure thread safety, which means only one thread can access or modify the logger at any given time. 

