Record* loadDataFromCSV(const char* filename, size_t maxMemoryUsage, Metadata* metadata) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open file %s\n", filename);
        return NULL;
    }

    // Initialize random number generator
    srand(time(NULL));

    Record* records = malloc(maxMemoryUsage);
    if (records == NULL) {
        printf("Failed to allocate memory\n");
        fclose(file);
        return NULL;
    }

    char line[256];
    size_t recordCount = 0;
    while (fgets(line, sizeof(line), file)) {
        metadata->entriesProcessed++;

        // Parse CSV line
        long offset;
        int key;
        double measurement;
        if (sscanf(line, "%ld,%d,%lf", &offset, &key, &measurement) != 3) {
            metadata->errorsEncountered++;
            continue;
        }

        // Set random values within specified ranges
        offset = rand() % 1000 + 1;  // Random number between 1 and 1000
        key = rand() % 100 + 1;      // Random number between 1 and 100
        measurement = ((double)rand() / (double)(RAND_MAX)) * 10.0;  // Random double between 0 and 10

        // Check if we have enough memory for the new record
        if (recordCount + 1 > maxMemoryUsage / sizeof(Record)) {
            printf("Not enough memory to allocate a new record\n");
            break;
        }

        records[recordCount].offset = offset;
        records[recordCount].key = key;
        records[recordCount].measurement = measurement;
        recordCount++;
    }

    fclose(file);
    return records;
}
