void* process_packet_stream(void *arg) {
    int id = *((int*) arg);
    free(arg);

    while (1) {
        // Simulate packet processing
        long offset = rand() % 100;
        int key = rand() % 100;
        double timestamp = ((double)rand() / (double)(RAND_MAX)) * 10.0;

        pthread_mutex_lock(&lock);
        records[id].offset = offset;
        records[id].key = key;
        records[id].timestamp = timestamp;
        fprintf(log_file, "Processed packet with id %d\n", id);
        fflush(log_file);
        pthread_mutex_unlock(&lock);

        // Simulate delay to simulate concurrent access
        usleep(1000);
    }

    return NULL;
}

int main() {
    signal(SIGINT, sigint_handler);
    init();

    pthread_t threads[num_records];
    for (int i = 0; i < num_records; i++) {
