#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct VideoSequence {
    int frameCount;
    // Other metadata fields...
} VideoSequence;

// Global variables for thread safety and memory management
VideoSequence* videoSequences = NULL;
int sequenceCount = 0;
int maxSequences = 1000;  // Maximum number of sequences
pthread_mutex_t lock;

void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Failed to allocate memory.\n");
        exit(1);  // Exit the program on failure
    }
    return ptr;
}

void initializeVideoSequence(int index, int frameCount) {
    pthread_mutex_lock(&lock);

    if (index >= maxSequences) {
        printf("Index out of bounds.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Reuse memory blocks when possible
    if (videoSequences == NULL || index > sequenceCount) {
        videoSequences = realloc(videoSequences, sizeof(VideoSequence) * maxSequences);

        if (videoSequences == NULL) {
            printf("Failed to allocate memory.\n");
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    videoSequences[index].frameCount = frameCount;
    // Initialize other fields...

    if (index >= sequenceCount) {
        sequenceCount = index + 1;
    }

    pthread_mutex_unlock(&lock);
}

void freeMemory() {
    pthread_mutex_lock(&lock);
    free(videoSequences);
    videoSequences = NULL;
    sequenceCount = 0;
    pthread_mutex_unlock(&lock);
}
```
