#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct node {
    char* value;
    size_t length;
} node;

node** nodes = NULL;
size_t totalSize = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* createStrings(void* arg) {
    int maxStrings = *((int*)arg);
    if (maxStrings > 100) {
        fprintf(stderr, "Error: Maximum number of strings exceeded.\n");
        return NULL;
    }

    char** strings = malloc(sizeof(char*) * maxStrings);
    size_t* lengths = malloc(sizeof(size_t) * maxStrings);
    nodes = malloc(sizeof(node*) * maxStrings);

    if (strings == NULL || lengths == NULL || nodes == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < maxStrings; i++) {
        size_t length = rand() % 10 + 1; // Generate a random string length between 1 and 10.

        strings[i] = malloc(length);
        if (strings[i] == NULL) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return NULL;
        }

        for (size_t j = 0; j < length - 1; j++) { // Generate a random string.
            strings[i][j] = 'a' + rand() % ('z' - 'a');
        }
        strings[i][length - 1] = '\0';

        lengths[i] = length;
    }

    for (int i = 0; i < maxStrings; i++) { // Create nodes.
        pthread_mutex_lock(&lock);
        totalSize += lengths[i];
        if (totalSize > 1024 * 1024) { // Check memory threshold.
            fprintf(stderr, "Error: Memory threshold exceeded.\n");
            return NULL;
        }

        nodes[i] = malloc(sizeof(node));
        if (nodes[i] == NULL) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return NULL;
        }

        nodes[i]->value = strings[i];
        nodes[i]->length = lengths[i];
        pthread_mutex_unlock(&lock);
    }

    free(strings);
    free(lengths);

    return NULL;
}
```
This code creates a separate thread for each string creation. It uses a mutex to ensure that the total size of all strings is updated safely and atomically, preventing race conditions. The memory threshold is checked after updating the total size, ensuring that no more than 1MB of memory is used by all threads combined.
