#include <unistd.h>

#define MAX_THREADS 5
#define LOGFILE "/tmp/logfile"

int threadCount = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void *resolveDNS(void *hostname) {
    struct hostent *he;
    if ((he=gethostbyname((char*)hostname)) == NULL) {
        herror("gethostbyname");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    threadCount--;
    pthread_mutex_unlock(&mutex);

    return he->h_addr_list[0];
}

void executeCommand(char *file) {
    struct stat st;
    if (stat(file, &st) == 0 && S_ISREG(st.st_mode)) {
        char command[256];
        snprintf(command, sizeof(command), "rm %s", file);
        system(command);

        FILE *log = fopen(LOGFILE, "a");
        if (log != NULL) {
            fprintf(log, "Executed command: %s\n", command);
            fclose(log);
        }
    }
}

int main() {
