    if (file == NULL) {
        perror("fopen");
        return 1;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        char *token, *saveptr;
        double sum = 0.0, count = 0.0;

        for (token = strtok_r(line, ",", &saveptr); 
             token && count < 2; 
             token = strtok_r(NULL, ",", &saveptr)) {
            sum += atof(token);
            count++;
        }

        double average = (count > 0) ? (sum / count) : 0.0;

        printf("%s, %f\n", line, average);
    }

    free(line);
    fclose(file);

    pthread_t threads[MAX_THREADS];
    char *hostnames[] = {"www.google.com", "www.facebook.com"}; // replace with actual hostnames
    for (int i = 0; i < sizeof(hostnames) / sizeof(char*); ++i) {
        while (threadCount >= MAX_THREADS) {
            sleep(1);
        }

        pthread_create(&threads[i], NULL, resolveDNS, hostnames[i]);
        threadCount++;
    }

    for (int i = 0; i < sizeof(hostnames) / sizeof(char*); ++i) {
        u_char *ip;
        pthread_join(threads[i], (void**)&ip);

        if (ip != NULL) {
            printf("IP address: %s\n", inet_ntoa(*((struct in_addr*) ip)));
        }
    }

    char *fileToDelete = "/path/to/file"; // replace with actual file path
    executeCommand(fileToDelete);

    return 0;
}
```
