#include <string.h>

typedef struct file_info {
    char *name;
    int size;
} file_info;

void* readFile(void* arg) {
    char* path = (char*)arg;
    FILE* fp = fopen(path, "r");

    if (fp == NULL) {
        printf("Failed to open %s\n", path);
        return NULL;
    }

    // Get file size
    fseek(fp, 0L, SEEK_END);
    int sz = ftell(fp);
    rewind(fp);

    // Allocate memory for buffer and read file content
    char* buffer = malloc(sz + 1);
    if (buffer == NULL) {
        printf("Failed to allocate memory\n");
        fclose(fp);
        return NULL;
    }

    size_t bytesRead = fread(buffer, 1, sz, fp);
    buffer[bytesRead] = '\0'; // Null-terminate the string

    file_info* info = malloc(sizeof(file_info));
    if (info == NULL) {
        printf("Failed to allocate memory\n");
        free(buffer);
        fclose(fp);
        return NULL;
    }

    // Store file information in the structure
    info->name = strdup(path);
    if (info->name == NULL) {
        printf("Failed to allocate memory\n");
        free(buffer);
        fclose(fp);
        return NULL;
    }

    info->size = sz;

    // Close the file and return the structure
    fclose(fp);
    return info;
}

void processFiles(char** paths, int count) {
    pthread_t threads[count];
    void* results[count];

    for (int i = 0; i < count; ++i) {
        if (pthread_create(&threads[i], NULL, readFile, paths[i]) != 0) {
            printf("Failed to create thread\n");
            return;
