```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    socklen_t id;
    const char* label;
    connection_info info; // Assuming this is a defined type
} connection;

typedef struct {
    size_t maxSize;
    size_t currentSize;
    pthread_mutex_t lock;
    socklen_t* ids;
    const char** labels;
    connection_info* infos;
    record* records;
} ConnectionManager;

ConnectionManager* createConnectionManager(size_t maxSize) {
    ConnectionManager* manager = malloc(sizeof(ConnectionManager));
    if (manager == NULL) return NULL;

    manager->maxSize = maxSize;
    manager->currentSize = 0;
    pthread_mutex_init(&manager->lock, NULL);

    manager->ids = malloc(sizeof(socklen_t) * maxSize);
    manager->labels = malloc(sizeof(const char*) * maxSize);
    manager->infos = malloc(sizeof(connection_info) * maxSize);
    manager->records = calloc(maxSize, sizeof(record)); // Initialize to 0

    return manager;
}

void addConnection(ConnectionManager* manager, socklen_t id, const char* label, connection_info info) {
    pthread_mutex_lock(&manager->lock);

    if (manager->currentSize < manager->maxSize) {
        size_t index = manager->currentSize++;

        manager->ids[index] = id;
        manager->labels[index] = strdup(label); // Allocate new memory for the label
        manager->infos[index] = info;
    }

    pthread_mutex_unlock(&manager->lock);
}

void removeConnection(ConnectionManager* manager, socklen_t id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->currentSize; ++i) {
        if (manager->ids[i] == id) {
            free((void*)manager->labels[i]); // Free the label memory

            // Shift all elements after this one to fill the gap
            for (size_t j = i; j < manager->currentSize - 1; ++j) {
                manager->ids[j] = manager->ids[j + 1];
                manager->labels[j] = manager->labels[j + 1];
                manager->infos[j] = manager->infos[j + 1];
            }

            --manager->currentSize;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void destroyConnectionManager(ConnectionManager* manager) {
    for (size_t i = 0; i < manager->currentSize; ++i) {
        free((void*)manager->labels[i]); // Free the label memory
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager->ids);
    free(manager->labels);
    free(manager->infos);
    free(manager->records);
    free(manager);
}
```
