#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int value;
} Record;

typedef struct Set {
    pthread_mutex_t lock;
    Record **records;
    size_t count;
    size_t capacity;
} Set;

Set *create_set() {
    Set *set = malloc(sizeof(Set));
    set->count = 0;
    set->capacity = 10;
    set->records = malloc(sizeof(Record *) * set->capacity);
    pthread_mutex_init(&set->lock, NULL);
    return set;
}

void insert_record(Set *set, Record *record) {
    pthread_mutex_lock(&set->lock);
    if (set->count == set->capacity) {
        set->capacity *= 2;
        set->records = realloc(set->records, sizeof(Record *) * set->capacity);
    }
    set->records[set->count++] = record;
    pthread_mutex_unlock(&set->lock);
}

void delete_record(Set *set, size_t index) {
    pthread_mutex_lock(&set->lock);
    if (index < set->count - 1) {
        free(set->records[index]);
        for (size_t i = index; i < set->count - 1; ++i) {
            set->records[i] = set->records[i + 1];
        }
    } else if (index == set->count - 1) {
        free(set->records[index]);
    }
    --set->count;
    pthread_mutex_unlock(&set->lock);
}

Record *find_record(Set *set, int value) {
    pthread_mutex_lock(&set->lock);
    for (size_t i = 0; i < set->count; ++i) {
        if (set->records[i]->value == value) {
            pthread_mutex_unlock(&set->lock);
            return set->records[i];
        }
    }
    pthread_mutex_unlock(&set->lock);
    return NULL;
}

void destroy_set(Set *set) {
    for (size_t i = 0; i < set->count; ++i) {
        free(set->records[i]);
    }
    free(set->records);
    pthread_mutex_destroy(&set->lock);
    free(set);
}
