#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    char* name;
    int age;
    struct Record *next;
} Record;

Record* create_record(char* name, int age) {
    Record* new_record = (Record*) malloc(sizeof(Record));
    if (!new_record) {
        printf("Memory allocation failed.\n");
        exit(0);
    }

    new_record->name = strdup(name);
    new_record->age = age;
    new_record->next = NULL;

    return new_record;
}

void add_record(Record** head, char* name, int age) {
    Record* new_node = create_record(name, age);
    new_node->next = *head;
    *head = new_node;
}

void print_list(Record* node) {
    while (node != NULL) {
        printf("Name: %s  Age: %d\n", node->name, node->age);
        node = node->next;
    }
}

int main() {
    srand(time(0)); // seed the random number generator

    Record* head = NULL;
    char* names[] = {"Alice", "Bob", "Charlie", "David"};
    int num_names = sizeof(names) / sizeof(char*);

    for (int i = 0; i < 10; ++i) { // add 10 records to the list
        char* random_name = names[rand() % num_names];
        int random_age = rand() % 50 + 1; // age between 1 and 50

        add_record(&head, random_name, random_age);
    }

    print_list(head);

    return 0;
}
```
