```c
#include <pthread.h>
#include <time.h>
#include <stdlib.h>
#include <string.h>

typedef struct Session {
    char* username;
    int sessionID;
    time_t startTime;
    time_t lastActivity;
    struct Session *next;
} Session;

Session *head = NULL;
pthread_mutex_t lock;

void addSession(char* username, int sessionID) {
    pthread_mutex_lock(&lock);

    Session *newSession = malloc(sizeof(Session));
    newSession->username = strdup(username);
    newSession->sessionID = sessionID;
    time(&newSession->startTime);
    newSession->lastActivity = newSession->startTime;

    if (head == NULL) {
        head = newSession;
    } else {
        Session *current = head;
        while(current->next != NULL) {
            current = current->next;
        }
        current->next = newSession;
    }

    pthread_mutex_unlock(&lock);
}

void updateLastActivity(int sessionID) {
    pthread_mutex_lock(&lock);

    Session *current = head;
    while (current != NULL) {
        if (current->sessionID == sessionID) {
            time(&current->lastActivity);
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

Session* findLongestActiveSession() {
    pthread_mutex_lock(&lock);

    Session *longestActiveSession = NULL;
    time_t longestDuration = 0;

    Session *current = head;
    while (current != NULL) {
        time_t duration = time(NULL) - current->lastActivity;
        if (duration > longestDuration) {
            longestActiveSession = current;
            longestDuration = duration;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);

    return longestActiveSession;
}

void removeInactiveSessions(time_t expirationTime) {
    pthread_mutex_lock(&lock);

    Session *current = head;
    Session *previous = NULL;

    while (current != NULL) {
        if (difftime(expirationTime, current->lastActivity) > 0) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }

            free(current->username);
            free(current);

            if (previous != NULL) {
                current = previous->next;
            } else {
                current = head;
            }
        } else {
            previous = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&lock);
}
```
This code is a basic implementation and does not include all the features you requested. It's also missing error checking, logging, and other important aspects of a production system. You would need to add these in a real-world scenario. 

