typedef struct Record {
    char* name;
    int age;
    struct Record *next;
} Record;

Record* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addRecord(char* name, int age) {
    pthread_mutex_lock(&lock);

    Record *newRecord = (Record*) malloc(sizeof(Record));
    newRecord->name = strdup(name);
    newRecord->age = age;
    newRecord->next = NULL;

    if(head == NULL) {
        head = newRecord;
    } else {
        Record *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newRecord;
    }

    pthread_mutex_unlock(&lock);
}

void serializeList() {
    FILE *file = fopen("records.txt", "w");
    if (file == NULL) {
        printf("Error opening file!\n");
        exit(1);
    }

    Record *current = head;
    while (current != NULL) {
        fprintf(file, "%s %d\n", current->name, current->age);
        current = current->next;
    }

    fclose(file);
}

void deserializeList() {
    FILE *file = fopen("records.txt", "r");
    if (file == NULL) {
        printf("Error opening file!\n");
        exit(1);
    }

    char name[256];
    int age;
    while (fscanf(file, "%s %d\n", name, &age) == 2) {
        addRecord(name, age);
    }

    fclose(file);
}

