typedef struct Record {
    int id;
    int value;
    struct Record *next;
} Record;

Record* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

long* offsets;
int* keys;
size_t size = 0;

void add_record(int value) {
    Record *newRecord = malloc(sizeof(Record));

    if (newRecord == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    newRecord->id = keys[value] ^ time(NULL);
    newRecord->value = value;
    newRecord->next = head;

    pthread_mutex_lock(&lock);
    head = newRecord;
    pthread_mutex_unlock(&lock);
}

int get_record(int id) {
    Record *current = head;

    while (current != NULL) {
        if (current->id == id) {
            return current->value;
        }

        current = current->next;
    }

    printf("Record not found\n");
    return -1;
}

void manage_memory(long* offsets, int* keys, size_t size) {
    // Allocate memory for the arrays
    long* newOffsets = malloc(size * sizeof(long));
    if (newOffsets == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    int* newKeys = malloc(size * sizeof(int));
    if (newKeys == NULL) {
        free(newOffsets);
        printf("Memory allocation failed\n");
        return;
    }

    // Copy the data from the input arrays to the newly allocated memory
    for (size_t i = 0; i < size; ++i) {
        newOffsets[i] = offsets[i];
        newKeys[i] = keys[i];
    }

    // Free the old memory and update the pointers to point to the new arrays
    free(offsets);
    free(keys);
    offsets = newOffsets;
    keys = newKeys;
}

void cleanup() {
    Record *current = head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    free(offsets);
    free(keys);
}
