["Here is an example of how you might implement such a function using C with POSIX threads for concurrency control and synchronization. This code does not include the logging framework integration or external data sources handling, as these would require additional context and specifics about your system's architecture and requirements. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>

typedef struct {
    double **data;
    size_t rows, cols;
    pthread_mutex_t lock;
} Grid;

Grid *grid_create(size_t rows, size_t cols) {
    Grid *g = malloc(sizeof(Grid));
    if (!g) return NULL;

    g->data = calloc(rows, sizeof(double*));
    if (!g->data) { free(g); return NULL; }

    for (size_t i = 0; i < rows; ++i) {
        g->data[i] = calloc(cols, sizeof(double));
        if (!g->data[i]) {
            grid_destroy(g);
            errno = ENOMEM;
            return NULL;
        }
    }

    g->rows = rows;
    g->cols = cols;
    pthread_mutex_init(&g->lock, NULL);

    return g;
}

void grid_destroy(Grid *g) {
    if (!g) return;

    for (size_t i = 0; i < g->rows; ++i) free(g->data[i]);
    free(g->data);
    pthread_mutex_destroy(&g->lock);
    free(g);
}

double grid_average(Grid *g) {
    double sum = 0.0;

    pthread_mutex_lock(&g->lock);
    for (size_t i = 0; i < g->rows; ++i) 
        for (size_t j = 0; j < g->cols; ++j) 
            sum += g->data[i][j];
    pthread_mutex_unlock(&g->lock);

    return sum / (g->rows * g->cols);
}

int grid_resize(Grid *g, size_t newRows, size_t newCols) {
    double **newData = calloc(newRows, sizeof(double*));
    if (!newData) return -1;

    for (size_t i = 0; i < newRows; ++i) {
        newData[i] = calloc(newCols, sizeof(double));
        if (!newData[i]) {
            free(newData);
            return -1;
        }
    }

    pthread_mutex_lock(&g->lock);
    for (size_t i = 0; i < newRows && i < g->rows; ++i) 
        for (size_t j = 0; j < newCols && j < g->cols; ++j) 
            newData[i][j] = g->data[i][j];

    grid_destroy(g);
    g->data = newData;
    g->rows = newRows;
    g->cols = newCols;
    pthread_mutex_unlock(&g->lock);

    return 0;
}
```
This code provides a basic grid structure with dynamic resizing and average computation. It uses a mutex to ensure thread safety during concurrent read/write operations, but does not handle asynchronous updates or integrate with an external logging framework. For these features, additional error checking and synchronization mechanisms would be required. 

Please note that this is a simplified example and may need adjustments based on your specific requirements and constraints.
"]

