public class LogEventProcessor {
    private static final int MAX_THREADS = Runtime.getRuntime().availableProcessors();
    private ExecutorService executorService = Executors.newFixedThreadPool(MAX_THREADS);
    private ConcurrentHashMap<String, Boolean> eventCache = new ConcurrentHashMap<>();
    private Properties properties;

    public LogEventProcessor() {
        try (InputStream inputStream = new FileInputStream("config.properties")) {
            properties = new Properties();
            properties.load(inputStream);
        } catch (IOException e) {
            System.out.println("Error loading properties file: " + ExceptionUtils.getStackTrace(e));
        }
    }

    public void processLogEvents(List<String> logEventPaths) {
        CountDownLatch latch = new CountDownLatch(logEventPaths.size());

        for (String path : logEventPaths) {
            executorService.execute(() -> {
                try {
                    String eventData = Files.readString(Path.of(path));

                    if (!eventCache.containsKey(eventData)) {
                        eventCache.put(eventData, true);

                        // Process the log event here...

                        System.out.println("Processed event: " + path);
                    } else {
                        System.out.println("Skipped duplicate event: " + path);
                    }
                } catch (IOException e) {
                    System.out.println("Error reading log event file: " + ExceptionUtils.getStackTrace(e));
                } finally {
                    latch.countDown();
                }
            });
        }

        try {
            latch.await();
        } catch (InterruptedException e) {
            System.out.println("Error waiting for log events to process: " + ExceptionUtils.getStackTrace(e));
        }
    }

