```java
import org.apache.http.HttpEntity;
import org.apache.http.client.methods.*;
import org.apache.http.entity.StringEntity;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;
import com.google.common.util.concurrent.RateLimiter;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.*;

public class RESTfulService {
    private static final Logger logger = LogManager.getLogger(RESTfulService.class);
    private final CloseableHttpClient httpclient = HttpClients.createDefault();
    private final RateLimiter rateLimiter = RateLimiter.create(10.0); // 10 requests per second
    private ExecutorService executorService = Executors.newFixedThreadPool(50);

    public void invokeRESTfulService(String url, String method, String jsonPayload) {
        HttpUriRequest request;
        switch (method) {
            case "GET":
                request = new HttpGet(url);
                break;
            case "POST":
                request = new HttpPost(url);
                ((HttpEntityEnclosingRequestBase) request).setEntity(new StringEntity(jsonPayload, StandardCharsets.UTF_8));
                break;
            // Similar cases for PUT and DELETE...
            default:
                throw new IllegalArgumentException("Unsupported HTTP method");
        }

        executorService.submit(() -> {
            rateLimiter.acquire();
            try (CloseableHttpResponse response = httpclient.execute(request)) {
                HttpEntity entity = response.getEntity();
                logger.info("Received HTTP response: {}", EntityUtils.toString(entity));
            } catch (IOException e) {
                logger.error("Failed to execute HTTP request", e);
            }
        });
    }
}
```
