#include <pthread.h>
#include <glib.h>

typedef struct {
    char* name;
    int priority;
    char* status;
} Task;

GHashTable *task_table = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void createTask(char* name, int priority, char* status) {
    pthread_mutex_lock(&lock);

    if (g_hash_table_contains(task_table, name)) {
        printf("Error: Task with the same name already exists.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    Task* task = malloc(sizeof(Task));
    task->name = strdup(name);
    task->priority = priority;
    task->status = strdup(status);

    g_hash_table_insert(task_table, task->name, task);

    pthread_mutex_unlock(&lock);
}

void updateTaskStatus(char* name, char* status) {
    pthread_mutex_lock(&lock);

    Task* task = g_hash_table_lookup(task_table, name);
    if (task == NULL) {
        printf("Error: No such task exists.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    free(task->status);
    task->status = strdup(status);

    pthread_mutex_unlock(&lock);
}
```
