#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define ITEM_CHAR_LEN 1024

typedef struct {
    unsigned int counter;
    char data[ITEM_CHAR_LEN];
} Item;

typedef struct {
    pthread_mutex_t lock;
    size_t maxItems;
    size_t itemCount;
    Item* items;
} ItemCollection;

ItemCollection* createItemCollection(size_t maxItems) {
    ItemCollection* collection = malloc(sizeof(ItemCollection));
    if (collection == NULL) return NULL;

    pthread_mutex_init(&collection->lock, NULL);
    collection->maxItems = maxItems;
    collection->itemCount = 0;
    collection->items = malloc(sizeof(Item) * maxItems);
    if (collection->items == NULL) {
        free(collection);
        return NULL;
    }

    return collection;
}

void destroyItemCollection(ItemCollection* collection) {
    pthread_mutex_destroy(&collection->lock);
    free(collection->items);
    free(collection);
}

int addItemToCollection(ItemCollection* collection, Item item) {
    if (pthread_mutex_lock(&collection->lock)) return -1;

    if (collection->itemCount >= collection->maxItems) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    collection->items[collection->itemCount++] = item;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}
```
This code creates a `ItemCollection` struct that holds an array of `Item`s and a mutex for thread safety. The `createItemCollection` function allocates memory for the collection and initializes it, while `destroyItemCollection` frees all allocated memory. The `addItemToCollection` function adds an item to the collection, ensuring thread safety with a lock.

