```c
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    int *key;
} record;

int is_prime(int num) {
    if (num <= 1) return 0;
    if (num % 2 == 0 && num > 2) return 0;
    for(int i = 3; i < sqrt(num) + 1; i += 2) {
        if (num % i == 0) {
            return 0;
        }
    }
    return 1;
}

void *allocate_memory(size_t size, int num_offsets) {
    void *ptr = malloc(size * num_offsets);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

record* initialize_data_structures(int num_offsets) {
    long *offsets = allocate_memory(sizeof(long), num_offsets);
    int *keys = allocate_memory(sizeof(int), num_offsets);
    record *records = allocate_memory(sizeof(record), num_offsets);

    int count = 0;
    for (int i = 0; count < num_offsets; i++) {
        if (is_prime(i)) {
            keys[count] = i;
            records[count].key = &keys[count];
            count++;
        }
    }

