['Here is a basic implementation of your requirements in C using pthreads for thread safety and a simple LRU cache for optimization. Note that this is a simplified version and does not include all the features you requested, such as logging or integration with external systems. 

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    int value;
} Record;

typedef struct cache_entry {
    long offset;
    Record* record;
    struct cache_entry *prev, *next;
} CacheEntry;

typedef struct cache {
    pthread_mutex_t lock;
    size_t max_size;
    size_t current_size;
    CacheEntry *head, *tail;
} Cache;

Cache* create_cache(size_t max_size) {
    Cache* cache = malloc(sizeof(Cache));
    if (!cache) return NULL;

    pthread_mutex_init(&cache->lock, NULL);
    cache->max_size = max_size ? max_size : 100;
    cache->current_size = 0;
    cache->head = cache->tail = NULL;

    return cache;
}

void destroy_cache(Cache* cache) {
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

Record* get_record(Cache* cache, long offset) {
    if (!cache || offset < 0) return NULL;

    pthread_mutex_lock(&cache->lock);

    for (CacheEntry *entry = cache->head; entry != NULL; entry = entry->next) {
        if (entry->offset == offset) {
            // Move to head of list
            if (entry != cache->head) {
                if (entry->prev) entry->prev->next = entry->next;
                if (entry->next) entry->next->prev = entry->prev;

                entry->next = cache->head;
                cache->head->prev = entry;
                cache->head = entry;
            }

            pthread_mutex_unlock(&cache->lock);
            return entry->record;
        }
    }

    // Not in cache, try to allocate new record
    Record* record = malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&cache->lock);
        return NULL;
    }

    CacheEntry *entry = malloc(sizeof(CacheEntry));
    if (!entry) {
        free(record);
        pthread_mutex_unlock(&cache->lock);
        return NULL;
    }

    entry->offset = offset;
    entry->record = record;
    entry->prev = NULL;
    entry->next = cache->head;

    if (cache->head) cache->head->prev = entry;
    cache->head = entry;
    if (!cache->tail) cache->tail = entry;

    // If cache is full, remove least recently used entry
    if (++cache->current_size > cache->max_size) {
        CacheEntry *oldest = cache->tail;

        oldest->prev->next = NULL;
        cache->tail = oldest->prev;

        free(oldest->record);
        free(oldest);
    }

    pthread_mutex_unlock(&cache->lock);
    return record;
}
```
This code creates a simple LRU cache with a fixed size. When the cache is full, it removes the least recently used entry (the oldest one). It uses a linked list to keep track of the order of entries and a mutex for thread safety. 

Please note that this is a basic implementation and does not include all the features you requested, such as logging or integration with external systems. You would need to add these features yourself based on your specific requirements.
']

