["Here's an example of how you might implement this in C using pthread mutexes for thread safety and separate chaining to handle collisions. This is just a basic implementation and doesn't include all the features mentioned, but it should give you a good starting point. 

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Session {
    char *user_id;
    time_t last_activity;
    int status; // 0 for inactive, 1 for active
    struct Session *next;
} Session;

typedef struct HashTable {
    pthread_mutex_t lock;
    Session **sessions;
    size_t capacity;
    size_t size;
} HashTable;

HashTable* create_table(size_t initial_capacity) {
    HashTable *ht = malloc(sizeof(HashTable));
    ht->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    ht->sessions = calloc(initial_capacity, sizeof(Session*));
    ht->capacity = initial_capacity;
    ht->size = 0;
    return ht;
}

void destroy_table(HashTable *ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        Session *session = ht->sessions[i];
        while (session != NULL) {
            Session *next = session->next;
            free(session->user_id);
            free(session);
            session = next;
        }
    }
    free(ht->sessions);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

size_t hash(const char *user_id, size_t capacity) {
    size_t hash = 5381;
    int c;
    while ((c = *user_id++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % capacity;
}

void resize(HashTable *ht, size_t new_capacity) {
    Session **new_sessions = calloc(new_capacity, sizeof(Session*));
    for (size_t i = 0; i < ht->capacity; ++i) {
        Session *session = ht->sessions[i];
        while (session != NULL) {
            size_t index = hash(session->user_id, new_capacity);
            session->next = new_sessions[index];
            new_sessions[index] = session;
            session = session->next;
        }
    }
    free(ht->sessions);
    ht->sessions = new_sessions;
    ht->capacity = new_capacity;
}

void add_session(HashTable *ht, const char *user_id) {
    pthread_mutex_lock(&ht->lock);
    if (ht->size / (double)ht->capacity > 0.7) {
        resize(ht, ht->capacity * 2);
    }
    size_t index = hash(user_id, ht->capacity);
    Session *session = malloc(sizeof(Session));
    session->user_id = strdup(user_id);
    session->last_activity = time(NULL);
    session->status = 1;
    session->next = ht->sessions[index];
    ht->sessions[index] = session;
    ++ht->size;
    pthread_mutex_unlock(&ht->lock);
}

Session* get_session(HashTable *ht, const char *user_id) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash(user_id, ht->capacity);
    Session *session = ht->sessions[index];
    while (session != NULL && strcmp(session->user_id, user_id) != 0) {
        session = session->next;
    }
    pthread_mutex_unlock(&ht->lock);
    return session;
}
```
