Cache* createCache(size_t cacheSize) {
    Cache* cache = malloc(sizeof(Cache));
    if (cache == NULL) return NULL;

    pthread_mutex_init(&cache->lock, NULL);
    cache->nodes = calloc(cacheSize, sizeof(Node*));
    if (cache->nodes == NULL) {
        free(cache);
        return NULL;
    }
    cache->cacheSize = cacheSize;
    cache->numNodes = 0;

    return cache;
}

void destroyCache(Cache* cache) {
    pthread_mutex_destroy(&cache->lock);
    for (size_t i = 0; i < cache->numNodes; ++i) {
        free(cache->nodes[i]);
    }
    free(cache->nodes);
    free(cache);
}

void addToCache(Cache* cache, Node* node) {
    pthread_mutex_lock(&cache->lock);

    if (cache->numNodes == cache->cacheSize) {
        // Cache is full, evict the oldest entry.
        free(cache->nodes[0]);

        for (size_t i = 1; i < cache->numNodes; ++i) {
            cache->nodes[i - 1] = cache->nodes[i];
        }
    } else {
        ++cache->numNodes;
    }

    cache->nodes[cache->numNodes - 1] = node;

    pthread_mutex_unlock(&cache->lock);
}
```
This code creates a basic cache with a fixed size. When the cache is full, it evicts the oldest entry when adding a new one. It uses a mutex to ensure thread safety during concurrent accesses. 

