Task createTask(char* name, int priority, int status) {
    Task task;
    strncpy(task.name, name, sizeof(task.name));
    task.priority = priority;
    task.status = status;
    return task;
}

void addTask(Task task) {
    Node* temp = (Node*) malloc(sizeof(Node));
    if (temp == NULL) error("Error: Out of memory");

    pthread_mutex_lock(&lock);
    if (listLength() >= capacity) {
        pthread_mutex_unlock(&lock);
        error("Error: Maximum tasks limit reached");
    }

    temp->task = task;
    temp->next = head;
    head = temp;
    pthread_mutex_unlock(&lock);
}

Task* getTask(char* name) {
    Node* temp = head;
    while (temp != NULL) {
        if (strcmp(temp->task.name, name) == 0) return &(temp->task);
        temp = temp->next;
    }
    return NULL; // Task not found
}

void updateTask(char* name, int priority, int status) {
    pthread_mutex_lock(&lock);
    Node* temp = head;
    while (temp != NULL) {
        if (strcmp(temp->task.name, name) == 0) {
            temp->task.priority = priority;
            temp->task.status = status;
            break;
        }
        temp = temp->next;
    }
    pthread_mutex_unlock(&lock);
}

void markTaskCompleted(char* name) {
    pthread_mutex_lock(&lock);
    Node* temp = head;
    while (temp != NULL) {
        if (strcmp(temp->task.name, name) == 0) {
            temp->task.status = 1; // Mark as completed
            break;
        }
        temp = temp->next;
    }
    pthread_mutex_unlock(&lock);
}

int listLength() {
    int count = 0;
    Node* current = head;

    while (current != NULL) {
        count++;
        current = current->next;
    }
    return count;
}

void cleanupTasks() {
    pthread_mutex_lock(&lock);
    Node* current = head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    head = NULL;
    pthread_mutex_unlock(&lock);
}
```
