#define MAX_RECORDS 1000
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static record_info_t **records = NULL;
static int num_records = 0;

void init_record(record_t *record, int value) {
    record->value = value;
    memset(record->buffer, 0, sizeof(record->buffer));
}

int add_record(long offset, int key, int value) {
    pthread_mutex_lock(&lock);

    if (num_records >= MAX_RECORDS) {
        pthread_mutex_unlock(&lock);
        return -1; // Error: Maximum number of records exceeded.
    }

    record_t *record = malloc(sizeof(record_t));
    if (record == NULL) {
        pthread_mutex_unlock(&lock);
        return -2; // Error: Memory allocation failed.
    }

    init_record(record, value);

    record_info_t *info = malloc(sizeof(record_info_t));
    if (info == NULL) {
        free(record);
        pthread_mutex_unlock(&lock);
        return -2; // Error: Memory allocation failed.
    }

    info->offset = offset;
    info->key = key;
    info->record = record;

    records[num_records++] = info;

    pthread_mutex_unlock(&lock);

    return 0; // Success.
}

void free_all() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < num_records; ++i) {
        free(records[i]->record);
        free(records[i]);
    }

    free(records);
    records = NULL;
    num_records = 0;

    pthread_mutex_unlock(&lock);
}
