// Function to calculate MD5 hash of a file
unsigned char* md5HashOfFile(FILE* fp, int chunkSize, unsigned long long* totalBytesRead) {
    MD5_CTX ctx;
    MD5_Init(&ctx);

    unsigned char buffer[chunkSize];
    size_t bytesRead;
    *totalBytesRead = 0;

    while((bytesRead = fread(buffer, 1, chunkSize, fp)) > 0) {
        MD5_Update(&ctx, buffer, bytesRead);
        *totalBytesRead += bytesRead;
    }

    unsigned char* md5Digest = (unsigned char*)malloc(MD5_DIGEST_LENGTH);
    MD5_Final(md5Digest, &ctx);

    return md5Digest;
}

// Function to build path string and calculate hash of a file
char* buildPathStringHasher(const char* currentPath, int maxDepth, DOMElement* startNode, const char* selector, int minIndex, int maxIndex) {
    // Allocate memory for the path string
    char* path = allocatePathString(strlen(currentPath));

    // Copy the current path to the new allocated memory
    strcpy(path, currentPath);

    // Traverse the DOM tree and build the path string
    traverseDOMTree(startNode, selector, minIndex, maxIndex, maxDepth, path);

    // Calculate MD5 hash of a file
    FILE* fp = fopen(path, "rb");
    if (fp == NULL) {
        printf("Failed to open the file.\n");
        return NULL;
    }

    unsigned long long totalBytesRead = 0;
    int chunkSize = 1024; // Adjust this value based on your needs
    unsigned char* md5Digest = md5HashOfFile(fp, chunkSize, &totalBytesRead);

    fclose(fp);

    // Convert MD5 digest to hexadecimal string
    char mdString[MD5_DIGEST_LENGTH * 2 + 1];
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&mdString[i*2], "%02x", (unsigned int)md5Digest[i]);
    }

    // Free the memory allocated for md5 digest
    free(md5Digest);

    return mdString;
}
