        if (offsets && offset_size > 0) {
            int offset_index = i % offset_size; // Wrap around if necessary
            records[i].offset = &offsets[offset_index];
        } else {
            records[i].offset = NULL;
        }

        if (keys && key_size > 0) {
            int key_index = i % key_size; // Wrap around if necessary
            records[i].key = &keys[key_index];
        } else {
            records[i].key = NULL;
        }
