```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>

// Define the structure for a node in the graph
typedef struct Node {
    int value;
    char* string;
} Node;

// Define the structure for a record in the graph
typedef struct Record {
    long offset;
    int key;
    Node* node;
} Record;

// Define the structure for a memory pool
typedef struct MemoryPool {
    void** blocks;
    size_t blockSize;
    size_t numBlocks;
} MemoryPool;

// Initialize a new memory pool with a given block size and number of blocks
MemoryPool* initMemoryPool(size_t blockSize, size_t numBlocks) {
    // Allocate memory for the memory pool structure
    MemoryPool* pool = malloc(sizeof(MemoryPool));

    // Initialize the fields of the memory pool structure
    pool->blockSize = blockSize;
    pool->numBlocks = numBlocks;

    // Allocate memory for the blocks in the memory pool
    pool->blocks = malloc(sizeof(void*) * numBlocks);

    return pool;
}

// Function to allocate a block from the memory pool
void* allocBlock(MemoryPool* pool) {
    // Iterate over all blocks in the memory pool
    for (int i = 0; i < pool->numBlocks; ++i) {
        // If the current block is not allocated, allocate it and return its address
        if (!pool->blocks[i]) {
            pool->blocks[i] = malloc(pool->blockSize);
            return pool->blocks[i];
        }
    }

    // If no free blocks are found, return NULL
    return NULL;
}

// Function to deallocate a block from the memory pool
void deallocBlock(MemoryPool* pool, void* block) {
    // Iterate over all blocks in the memory pool
    for (int i = 0; i < pool->numBlocks; ++i) {
        // If the current block is the one to be deallocated, deallocate it and return
        if (pool->blocks[i] == block) {
            free(block);
            pool->blocks[i] = NULL;
            return;
        }
    }
}

// Function to initialize a new node with a given value and string length
Node* initNode(int value, size_t strLen) {
    // Allocate memory for the node structure
    Node* node = malloc(sizeof(Node));

    // Initialize the fields of the node structure
    node->value = value;
    node->string = malloc(strLen + 1);

    return node;
}

// Function to initialize a new record with a given offset, key, and node
Record* initRecord(long offset, int key, Node* node) {
    // Allocate memory for the record structure
    Record* record = malloc(sizeof(Record));

    // Initialize the fields of the record structure
    record->offset = offset;
    record->key = key;
    record->node = node;

    return record;
}

// Function to add a new node to the graph
void addNode(Record** records, size_t* numRecords, Node* node) {
    // Allocate memory for the new record and initialize it with the given node
    Record* record = initRecord(*numRecords, (*numRecords) * 2, node);

    // Increase the number of records in the graph
    (*numRecords)++;

    // Reallocate memory for the records array to accommodate the new record
    records = realloc(records, sizeof(Record*) * (*numRecords));

    // Add the new record to the end of the records array
    records[(*numRecords) - 1] = record;
}

// Function to delete a node from the graph
void deleteNode(Record** records, size_t* numRecords, Node* node) {
    // Iterate over all records in the graph
    for (int i = 0; i < *numRecords; ++i) {
        // If the current record's node is the one to be deleted, delete it and return
        if (records[i]->node == node) {
            free(records[i]);

            // Shift all subsequent records back by one position
            for (int j = i; j < *numRecords - 1; ++j) {
                records[j] = records[j + 1];
            }

            // Decrease the number of records in the graph
            (*numRecords)--;

            return;
        }
    }
}

// Function to modify a node in the graph
void modifyNode(Record** records, size_t* numRecords, Node* oldNode, Node* newNode) {
    // Iterate over all records in the graph
    for (int i = 0; i < *numRecords; ++i) {
        // If the current record's node is the one to be modified, modify it and return
        if (records[i]->node == oldNode) {
            free(oldNode);
            records[i]->node = newNode;

            return;
        }
    }
}
