#include <stdlib.h>
#include <pthread.h>
#include <assert.h>

typedef struct {
    float x;
    float y;
} Point;

typedef struct Path {
    int id;
    Point* points;
    size_t numPoints;
    struct Path* next;
} Path;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static Path* paths = NULL;

Path* createPath(int id, size_t maxPoints) {
    assert(maxPoints > 0);

    Path* path = malloc(sizeof(Path));
    if (path == NULL) return NULL;

    path->id = id;
    path->points = calloc(maxPoints, sizeof(Point));
    if (path->points == NULL) {
        free(path);
        return NULL;
    }

    path->numPoints = 0;
    path->next = NULL;

    pthread_mutex_lock(&lock);
    Path** pp = &paths;
    while (*pp != NULL) {
        if ((*pp)->id == id) return NULL; // ID already exists
        pp = &((*pp)->next);
    }

    *pp = path;
    pthread_mutex_unlock(&lock);

    return path;
}

void addPoint(Path* path, Point point) {
    assert(path != NULL && path->numPoints < MAX_POINTS); // MAX_POINTS should be defined elsewhere

    pthread_mutex_lock(&lock);
    path->points[path->numPoints++] = point;
    pthread_mutex_unlock(&lock);
}

void destroyPath(int id) {
    pthread_mutex_lock(&lock);

    Path** pp = &paths;
    while (*pp != NULL && (*pp)->id != id) 
