        pthread_mutex_unlock(&lock);
        return;
    }

    newSession->session_id = session_id;
    newSession->last_active_time = last_active_time;
    strcpy(newSession->connection_status, connection_status);

    sessions = realloc(sessions, (numSessions + 1) * sizeof(Session*));
    if (sessions == NULL) {
        printf("Memory allocation failed. Unable to add session.\n");
        free(newSession);
        pthread_mutex_unlock(&lock);
        return;
    }

    sessions[numSessions] = newSession;
    numSessions++;

    pthread_mutex_unlock(&lock);
}
