typedef enum {
    SUCCESS,
    CACHE_DIR_ERROR,
    CACHE_FILE_ERROR,
    NETWORK_ERROR,
    PARSE_ERROR,
    MEMORY_ERROR,
    CONCURRENCY_ERROR,
    INTEGRATION_ERROR
} status_code;

typedef struct node {
    json_t *data;
    struct node *next;
    struct node *prev;
} Node;

status_code initialize_and_load_data_source(int *records_count, void **records_list) {
    status_code status = SUCCESS;
    CURL *curl;
    FILE *fp;
    struct stat st = {0};

    if (stat("/var/cache/myapp", &st) == -1) {
        mkdir("/var/cache/myapp", 0700);
    }

    fp = fopen("/var/cache/myapp/data.json", "r");
    if(fp != NULL && (time(NULL) - st.st_mtime < 86400)) { // cache is valid
        char buffer[1024];
        size_t bytes_read;

        while((bytes_read = fread(buffer, 1, sizeof(buffer), fp)) > 0) {
            json_error_t error;
            json_t *root = json_loadb(buffer, bytes_read, 0, &error);

            if(!root) {
                status = PARSE_ERROR;
                break;
            }

            Node *node = malloc(sizeof(Node));
            node->data = root;
            node->next = NULL;
            node->prev = NULL;

            if(*records_list == NULL) {
                *records_list = node;
            } else {
                Node *last = *records_list;

                while(last->next != NULL) {
                    last = last->next;
                }

                last->next = node;
                node->prev = last;
            }

            (*records_count)++;
        }

        fclose(fp);
    } else { // fetch fresh data
        curl = curl_easy_init();
        if(curl) {
            FILE *fp = fopen("/var/cache/myapp/data.json", "w");

            curl_easy_setopt(curl, CURLOPT_URL, "https://api.example.com/data");
