            CURLcode res = curl_easy_perform(curl);

            if(res != CURLE_OK) {
                status = NETWORK_ERROR;
            }

            fclose(fp);
            curl_easy_cleanup(curl);
        } else {
            status = INTEGRATION_ERROR;
        }
    }

    return status;
}
```
