            memset(collection->records + collection->capacity, 0, (new_capacity - collection->capacity) * sizeof(record*));

            collection->capacity = new_capacity;
        }
    }

    collection->offsets[collection->count] = offset;
    collection->keys[collection->count] = key;
    collection->records[collection->count] = rec;
    collection->count++;

    pthread_mutex_unlock(&collection->lock);
}

void remove_entity(entity_collection* collection, size_t index) {
