typedef struct {
    int value;
} Record;

typedef struct {
    int min, max;
} Range;

typedef struct {
    Range range;
    void (*updateRange)(struct CustomRandom*, int, int);
    float (*nextFloat)(struct CustomRandom*);
    int (*nextInt)(struct CustomRandom*);
    void (*shuffleArray)(int*, size_t);
} CustomRandom;

void updateRange(CustomRandom *cr, int min, int max) {
    cr->range.min = min;
    cr->range.max = max;
}

float nextFloat(CustomRandom *cr) {
    return (float)rand() / (float)RAND_MAX * (cr->range.max - cr->range.min) + cr->range.min;
}

int nextInt(CustomRandom *cr) {
    return rand() % (cr->range.max - cr->range.min + 1) + cr->range.min;
}

void shuffleArray(int* array, size_t n) {
    if (n > 1) {
        for (size_t i = 0; i < n - 1; ++i) {
            size_t j = i + rand() / (RAND_MAX / (n - i) + 1);
            int t = array[j];
            array[j] = array[i];
            array[i] = t;
        }
    }
}

CustomRandom* createCustomRandom(int min, int max) {
    CustomRandom *cr = malloc(sizeof(CustomRandom));
    cr->range.min = min;
    cr->range.max = max;
    cr->updateRange = &updateRange;
    cr->nextFloat = &nextFloat;
    cr->nextInt = &nextInt;
    cr->shuffleArray = &shuffleArray;
    return cr;
}

void CustomRandomRecordInitializer(CustomRandom *cr, long* offsets, int* keys, Record* records, size_t n) {
    srand((unsigned int)time(NULL));

