    int* keys;
    data_entry* entries;
    size_t capacity;
    size_t count;
} data_store;

data_store* create_store(size_t initial_capacity) {
    data_store* store = malloc(sizeof(data_store));
    if (store == NULL) return NULL;

    store->offsets = malloc(initial_capacity * sizeof(long));
    store->keys = malloc(initial_capacity * sizeof(int));
    store->entries = malloc(initial_capacity * sizeof(data_entry));
    if (store->offsets == NULL || store->keys == NULL || store->entries == NULL) {
        free(store->offsets);
        free(store->keys);
        free(store->entries);
        free(store);
        return NULL;
    }

    store->capacity = initial_capacity;
    store->count = 0;

    return store;
}

void destroy_store(data_store* store) {
    if (store == NULL) return;

    free(store->offsets);
    free(store->keys);
    free(store->entries);
    free(store);
}

int insert_entry(data_store* store, int key, data_entry entry) {
    if (store == NULL || store->count >= store->capacity) return -1;

    size_t index = store->count++;
    store->keys[index] = key;
    store->entries[index] = entry;

    return 0;
}

data_entry* get_entry(data_store* store, int key) {
    if (store == NULL || store->count == 0) return NULL;

    for (size_t i = 0; i < store->count; ++i) {
        if (store->keys[i] == key) return &(store->entries[i]);
    }

    return NULL;
}
