#include <assert.h>
#include <stdatomic.h>

typedef struct {
    _Atomic(int) min;
    _Atomic(int) max;
} CustomRandom;

void CustomRandomRecordInitializer() {
    srand((unsigned int)time(NULL));
}

int CustomRandomInt(CustomRandom* rand, int exclusiveMax) {
    assert(exclusiveMax > atomic_load(&rand->min));
    return (rand() % (exclusiveMax - atomic_load(&rand->min))) + atomic_load(&rand->min);
}

float CustomRandomFloat(CustomRandom* rand, float exclusiveMax) {
    assert(exclusiveMax > atomic_load(&rand->min));
    return ((float)rand() / (float)(RAND_MAX)) * (exclusiveMax - atomic_load(&rand->min)) + atomic_load(&rand->min);
}

void CustomRandomUpdateRange(CustomRandom* rand, int newMin, int newMax) {
    atomic_store(&rand->min, newMin);
    atomic_store(&rand->max, newMax);
}
