For the cache system, you can use a combination of a hash table and doubly linked list to implement LRU eviction policy. Here is a simplified version:

```c
#include <stdlib.h>
#include <pthread.h>
#include <assert.h>

typedef struct CacheNode {
    int key;
    void* value;
    struct CacheNode *prev, *next;
} CacheNode;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    CacheNode *head, *tail;
    CacheNode **nodes;
} LRUCache;

LRUCache* CreateCache(size_t capacity) {
    LRUCache* cache = malloc(sizeof(LRUCache));
    assert(cache != NULL);

    cache->capacity = capacity;
    cache->size = 0;
    cache->head = cache->tail = NULL;
    cache->nodes = calloc(capacity, sizeof(CacheNode*));
    assert(cache->nodes != NULL);

    pthread_mutex_init(&cache->lock, NULL);

    return cache;
}

void DestroyCache(LRUCache* cache) {
    CacheNode *node = cache->head, *next;
    while (node != NULL) {
        next = node->next;
        free(node);
        node = next;
    }

    pthread_mutex_destroy(&cache->lock);
    free(cache->nodes);
    free(cache);
}
```
