    LOW, MEDIUM, HIGH
} Priority;

typedef struct log_entry {
    Timestamp timestamp;
    Priority priority;
    char* message;
} LogEntry;

LogEntry* create_log_entries(int num_entries, const Timestamp* timestamps, 
                             const Priority* priorities, const char** messages) {

    assert(num_entries > 0);
    assert(timestamps != NULL);
    assert(priorities != NULL);
    assert(messages != NULL);

    LogEntry* log_buffer = (LogEntry*)malloc(sizeof(LogEntry) * num_entries);

    if (log_buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for log entries\n");
        return NULL;
    }

    for (int i = 0; i < num_entries; ++i) {
        log_buffer[i].timestamp = timestamps[i];
        log_buffer[i].priority = priorities[i];

        size_t message_len = strlen(messages[i]);
        log_buffer[i].message = (char*)malloc(sizeof(char) * (message_len + 1));

        if (log_buffer[i].message == NULL) {
            fprintf(stderr, "Failed to allocate memory for message\n");

            // Clean up previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(log_buffer[j].message);
            }
            free(log_buffer);

            return NULL;
        }

        strncpy(log_buffer[i].message, messages[i], message_len + 1);
    }

    return log_buffer;
}

void clear_log_entries(LogEntry* log_buffer, int num_entries) {
    assert(num_entries > 0);
    assert(log_buffer != NULL);

    for (int i = 0; i < num_entries; ++i) {
        free(log_buffer[i].message);
    }

    free(log_buffer);
}
