#include <forward_list>
#include <string>
#include <algorithm>

void insertAfterInForwardList(std::forward_list<std::string>& flist, const std::string& searchStr, const std::string& insertionStr) {
    auto it = std::find(flist.begin(), flist.end(), searchStr);

    if (it != flist.end()) {
        // If the search string is found, insert the insertion string after it
        flist.insert_after(it, insertionStr);
    } else {
        // If the search string is not found, append the insertion string to the end of the list
        flist.push_front(insertionStr);
    }
}
