```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <sys/stat.h>

typedef struct {
    size_t offset;
    const char* fileName;
} FileInfo;

void* processFile(void *arg) {
    FileInfo *file = (FileInfo*) arg;

    int fd = open(file->fileName, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return NULL;
    }

    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("fstat");
        close(fd);
        return NULL;
    }

    file->offset = st.st_size;

    void *map = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (map == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return NULL;
    }

    // Process the file here...

    munmap(map, st.st_size);
    close(fd);

    return NULL;
}

void consolidateFiles(const char** fileNames, size_t numFiles) {
    pthread_t threads[numFiles];
    FileInfo files[numFiles];

    for (size_t i = 0; i < numFiles; ++i) {
        files[i].fileName = fileNames[i];

        if (pthread_create(&threads[i], NULL, processFile, &files[i]) != 0) {
            perror("pthread_create");
            return;
        }
    }

    for (size_t i = 0; i < numFiles; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("pthread_join");
            return;
        }

        // Consolidate the file here...
    }

    free(files);
}
```
