    pthread_mutex_lock(&lock);
    if (file_count >= MAX_SIZE) {
        pthread_mutex_unlock(&lock);
        return -1; // Maximum limit reached
    }

    files[file_count] = malloc(sizeof(file_info));
    if (!files[file_count]) {
        pthread_mutex_unlock(&lock);
        return -2; // Memory allocation failed
    }

    files[file_count]->offset = offset;
    files[file_count]->filename = filename;
    file_count++;

