```c
#include <pthread.h>
#include <stdlib.h>

typedef struct {
    int log_level;
    int rotation_interval;
    int retention_period;
    char* tags;
    void* context;
} Configuration;

typedef struct {
    pthread_mutex_t lock;
    Configuration** configurations;
    size_t count;
    size_t capacity;
} Configurations;

Configurations* create_configurations(size_t initial_capacity) {
    Configurations* configs = malloc(sizeof(Configurations));
    if (configs == NULL) return NULL;

    pthread_mutex_init(&configs->lock, NULL);
    configs->count = 0;
    configs->capacity = initial_capacity;
    configs->configurations = malloc(initial_capacity * sizeof(Configuration*));

    if (configs->configurations == NULL) {
        free(configs);
        return NULL;
    }

    return configs;
}

void add_configuration(Configurations* configs, Configuration* new_config) {
    pthread_mutex_lock(&configs->lock);

    if (configs->count == configs->capacity) {
        // Double the capacity when full
        configs->capacity *= 2;
        configs->configurations = realloc(configs->configurations, configs->capacity * sizeof(Configuration*));
    }

    configs->configurations[configs->count++] = new_config;

    pthread_mutex_unlock(&configs->lock);
}

void free_configuration(Configuration* config) {
    // Free any dynamically allocated fields in the configuration
    free(config->tags);
    free(config->context);
    free(config);
}

void destroy_configurations(Configurations* configs) {
    pthread_mutex_lock(&configs->lock);

    for (size_t i = 0; i < configs->count; ++i) {
        free_configuration(configs->configurations[i]);
    }

    free(configs->configurations);
    pthread_mutex_unlock(&configs->lock);
    pthread_mutex_destroy(&configs->lock);
    free(configs);
}
```
This code provides a basic structure for storing configurations in a thread-safe way. It uses a mutex to ensure that only one thread can modify the configuration at a time, preventing race conditions and deadlocks. The `add_configuration` function doubles the capacity of the array when it is full, ensuring efficient memory usage under high concurrency scenarios.

