typedef struct {
    double value;
    int index;
    char* str;
} processed_data;

processed_data* dataArray = NULL;
int arraySize = 0;
pthread_mutex_t lock;

void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void addDataToArray(double value, int index, char* str) {
    pthread_mutex_lock(&lock);
    ++arraySize;
    dataArray = realloc(dataArray, arraySize * sizeof(processed_data));
    if (dataArray == NULL) {
        fprintf(stderr, "Failed to reallocate memory\n");
        exit(EXIT_FAILURE);
    }
    processed_data* newData = &dataArray[arraySize - 1];
    newData->value = value;
    newData->index = index;
    newData->str = allocateMemory((strlen(str) + 1) * sizeof(char));
    strcpy(newData->str, str);
    pthread_mutex_unlock(&lock);
}

double computeWeightedAverage() {
    double sum = 0.0;
    int totalIndex = 0;
    for (int i = 0; i < arraySize; ++i) {
        sum += dataArray[i].value * dataArray[i].index;
        totalIndex += dataArray[i].index;
    }
    return totalIndex != 0 ? sum / totalIndex : 0.0;
}

void freeMemory() {
    for (int i = 0; i < arraySize; ++i) {
        free(dataArray[i].str);
    }
    free(dataArray);
}

int main() {
    // Initialize mutex
    if (pthread_mutex_init(&lock, NULL) != 0) {
        fprintf(stderr, "Failed to initialize mutex\n");
        return EXIT_FAILURE;
    }

    // Add data to array
    addDataToArray(1.5, 2, "Hello");
    addDataToArray(2.0, 3, "World");

    // Compute weighted average
    double avg = computeWeightedAverage();
    printf("Weighted Average: %f\n", avg);

    // Free memory
    freeMemory();

    // Destroy mutex
    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}
