    arr->size = 0;
    arr->data = malloc(arr->capacity * sizeof(record));
    if (arr->data == NULL) {
        free(arr);
        return NULL;
    }

    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void destroy_dynamic_array(dynamic_array* arr) {
    if (arr == NULL) return;

    free(arr->data);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

int add_record(dynamic_array* arr, record rec) {
    if (arr == NULL) return -1;

    pthread_mutex_lock(&arr->lock);

    // Resize array if necessary
    if (arr->size >= arr->capacity) {
        arr->capacity *= 2;
        record* new_data = realloc(arr->data, arr->capacity * sizeof(record));
        if (new_data == NULL) {
            pthread_mutex_unlock(&arr->lock);
            return -1;
        }

        arr->data = new_data;
    }

    // Add record to array
    arr->data[arr->size++] = rec;

    pthread_mutex_unlock(&arr->lock);
    return 0;
}
```
