    Connection* connection;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int maxConnections = 100; // Maximum number of connections

void addConnection(int fd, int status) {
    pthread_mutex_lock(&lock);

    if (head == NULL || head->connection->key > maxConnections) {
        printf("Maximum connections reached\n");
        return;
    }

    Node* newNode = malloc(sizeof(Node));
    newNode->connection = malloc(sizeof(Connection));
    newNode->connection->fd = fd;
    newNode->connection->status = status;
    newNode->connection->timestamp = time(NULL);

    srand(time(NULL)); // Seed the random number generator
    int key;
    do {
        key = rand() % maxConnections + 1; // Generate a unique key within range
    } while (!isUniqueKey(key));
    newNode->connection->key = key;

    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

int isUniqueKey(int key) {
    Node* current = head;
    while (current != NULL) {
        if (current->connection->key == key) {
            return 0; // Key already exists, not unique
        }
        current = current->next;
    }
    return 1; // Key is unique
}
```
This code creates a linked list where each node contains a `Connection` structure. The `addConnection()` function adds new connections to the head of the list, ensuring that they are processed in the order they were received. It also ensures that the key for each connection is unique by generating random keys and checking them against existing ones.

