['Here is a basic implementation of such function in C using pthreads for thread safety and glib's GHashTable for hash table operations. This code does not include all the features you mentioned due to complexity but it gives an idea about how to implement them. 

```c
#include <stdio.h>
#include <pthread.h>
#include <glib.h>

typedef struct {
    int key;
    int value;
} Record;

GHashTable* hash_table = NULL;
int max_records = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init(int max) {
    if (hash_table != NULL) return; // Already initialized

    hash_table = g_hash_table_new(g_direct_hash, g_direct_equal);
    max_records = max;
}

void cleanup() {
    pthread_mutex_lock(&lock);
    if (hash_table != NULL) {
        g_hash_table_destroy(hash_table);
        hash_table = NULL;
    }
    pthread_mutex_unlock(&lock);
}

void addRecord(int key, int value) {
    pthread_mutex_lock(&lock);

    if (g_hash_table_size(hash_table) >= max_records) {
        printf("Warning: Maximum number of records reached.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        printf("Error: Memory allocation failed for key %d\n", key);
        pthread_mutex_unlock(&lock);
        return;
    }

    record->key = key;
    record->value = value;

    gpointer oldRecord = g_hash_table_insert(hash_table, &record->key, record);
    if (oldRecord != NULL) {
        printf("Warning: Overwriting existing record for key %d\n", key);
        free(oldRecord);
    } else {
        printf("Successfully added record for key %d\n", key);
    }

    pthread_mutex_unlock(&lock);
}
```
This code provides a basic implementation of the requested features. It uses a hash table to store records, ensuring efficient insertion, deletion, and lookup operations. The `init` function initializes the hash table and sets the maximum number of records allowed. The `cleanup` function frees all allocated memory when the function exits. The `addRecord` function adds a new record to the hash table, handling memory allocation failures and checking if the maximum number of records has been reached.
']

