    for (size_t i = 0; i < count; ++i) {
        newOffsets[i] = offsets[keys[i]];
        newRecords[i] = records[keys[i]];
    }

    memcpy(offsets, newOffsets, count * sizeof(long));
    memcpy(records, newRecords, count * sizeof(Record));

    safe_free(&newOffsets);
    safe_free(&newRecords);
}
