["Here is a basic implementation of such a hash table in C using pthreads for thread safety. This code does not include all the features you requested (like unique keys generation, invalidation based on specific condition etc.) but it provides a good starting point. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct entry {
    double key;
    char* value;
    atomic_int refcount;
} Entry;

typedef struct hashTable {
    Entry** entries;
    size_t capacity;
    pthread_mutex_t lock;
} HashTable;

HashTable* createHashTable(size_t capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    table->entries = calloc(capacity, sizeof(Entry*));
    if (table->entries == NULL) {
        free(table);
        return NULL;
    }

    table->capacity = capacity;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void destroyHashTable(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Entry* entry = table->entries[i];
        if (entry != NULL && atomic_load(&entry->refcount) == 1) {
            free(entry->value);
            free(entry);
        }
    }

    free(table->entries);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

void insertEntry(HashTable* table, double key, char* value) {
    size_t index = (size_t)key % table->capacity;

    pthread_mutex_lock(&table->lock);

    Entry* entry = malloc(sizeof(Entry));
    if (entry == NULL) return;

    entry->key = key;
    entry->value = value;
    atomic_init(&entry->refcount, 1);

    table->entries[index] = entry;

    pthread_mutex_unlock(&table->lock);
}

char* getValue(HashTable* table, double key) {
    size_t index = (size_t)key % table->capacity;

    pthread_mutex_lock(&table->lock);

    Entry* entry = table->entries[index];
    if (entry != NULL && atomic_load(&entry->refcount) > 0) {
        char* value = entry->value;
        ++atomic_int(entry->refcount);
        pthread_mutex_unlock(&table->lock);
        return value;
    } else {
        pthread_mutex_unlock(&table->lock);
        return NULL;
    }
