```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    atomic_int nextKey;
    pthread_mutex_t mutex;
    Record **records;
    size_t maxRecords;
    size_t numRecords;
} RecordManager;

RecordManager *createRecordManager(size_t maxRecords) {
    RecordManager *manager = malloc(sizeof(RecordManager));
    if (manager == NULL) return NULL;

    manager->records = calloc(maxRecords, sizeof(Record*));
    if (manager->records == NULL) {
        free(manager);
        return NULL;
    }

    manager->nextKey = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->maxRecords = maxRecords;
    manager->numRecords = 0;

    return manager;
}

int generateUniqueKey(RecordManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    int key = atomic_fetch_add(&manager->nextKey, 1);
    pthread_mutex_unlock(&manager->mutex);

    return key;
}

Record *createRecord(int key, long offset) {
    Record *record = malloc(sizeof(Record));
    if (record == NULL) return NULL;

    record->key = key;
    record->offset = offset;

    return record;
}

void addRecord(RecordManager *manager, int key, long offset) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->numRecords < manager->maxRecords) {
        Record *record = createRecord(key, offset);

        if (record != NULL) {
            manager->records[manager->numRecords++] = record;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}
```
