#include <unistd.h>

// Define a struct to hold the data for each line of text
typedef struct {
    char* content;
    size_t length;
} LineData;

// Define a struct to hold the cache and its associated mutex
typedef struct {
    LineData** lines;
    int capacity;
    int count;
    pthread_mutex_t mutex;
} Cache;

// Function prototypes
Cache* create_cache(int capacity);
void destroy_cache(Cache* cache);
LineData* read_line(FILE* file);
void process_file(char* filename, Cache* cache);
void* thread_function(void* arg);

int main() {
    // Initialize the cache with a certain capacity
    Cache* cache = create_cache(1024);

    // Read multiple text files concurrently using threads
    pthread_t threads[3];
    char* filenames[] = {"file1.txt", "file2.txt", "file3.txt"};
    for (int i = 0; i < 3; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, filenames[i]) != 0) {
            perror("Failed to create thread");
            return 1;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < 3; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            return 1;
        }
    }

    // Clean up the cache
    destroy_cache(cache);

    return 0;
}

// Function definitions
Cache* create_cache(int capacity) {
    Cache* cache = malloc(sizeof(Cache));
    if (cache == NULL) {
        perror("Failed to allocate memory for cache");
        exit(1);
    }

    cache->lines = calloc(capacity, sizeof(LineData*));
    if (cache->lines == NULL) {
        perror("Failed to allocate memory for lines array");
        free(cache);
        exit(1);
    }

    cache->capacity = capacity;
    cache->count = 0;
    pthread_mutex_init(&cache->mutex, NULL);

    return cache;
}

void destroy_cache(Cache* cache) {
    for (int i = 0; i < cache->count; ++i) {
        free(cache->lines[i]->content);
        free(cache->lines[i]);
    }

    free(cache->lines);
    pthread_mutex_destroy(&cache->mutex);
    free(cache);
}

LineData* read_line(FILE* file) {
    LineData* line = malloc(sizeof(LineData));
    if (line == NULL) {
        perror("Failed to allocate memory for line");
        exit(1);
    }

    size_t length = 0;
    ssize_t read = getline(&line->content, &length, file);
    if (read == -1) {
        free(line);
        return NULL;
    }

    line->length = read;
    return line;
}

void process_file(char* filename, Cache* cache) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open file");
        exit(1);
    }

    while (!feof(file)) {
        LineData* line = read_line(file);
        if (line != NULL) {
            pthread_mutex_lock(&cache->mutex);

            // Add the line to the cache
            cache->lines[cache->count++] = line;

            pthread_mutex_unlock(&cache->mutex);
        }
    }

    fclose(file);
}

void* thread_function(void* arg) {
    char* filename = (char*)arg;
    process_file(filename, cache);
    return NULL;
}
```
