    pthread_mutex_init(&ds->mutex, NULL);
    return ds;
}

void destroy_data_structure(data_structure_t *ds) {
    free(ds->keys);
    for (int i = 0; i < ds->max_records; i++) {
        if (ds->records[i].value != NULL) {
            free(ds->records[i].value);
        }
    }
    free(ds->records);
    pthread_mutex_destroy(&ds->mutex);
    free(ds);
}

int add_record(data_structure_t *ds, int key, record_t record) {
    pthread_mutex_lock(&ds->mutex);
    if (ds->offset >= ds->max_records) {
        pthread_mutex_unlock(&ds->mutex);
        return -1; // Error: Max records exceeded
    }
    for (int i = 0; i < ds->offset; i++) {
        if (ds->keys[i] == key && !memcmp(ds->records[i].value, record.value, sizeof(int))) {
            pthread_mutex_unlock(&ds->mutex);
            return -2; // Error: Duplicate key and value
        }
    }
    ds->keys[ds->offset] = key;
    memcpy(&ds->records[ds->offset], &record, sizeof(record_t));
    ds->offset++;
    pthread_mutex_unlock(&ds->mutex);
    return 0; // Success
}
