#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <sys/stat.h>
#include <openssl/md5.h> // for MD5 checksum

typedef struct {
    size_t size;
    time_t modificationTime;
    unsigned char md5[MD5_DIGEST_LENGTH];
} file_info;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* processFile(void *filePath) {
    const char* path = (const char*)filePath;

    FILE *fp = fopen(path, "rb");
    if (!fp) {
        pthread_mutex_lock(&lock);
        printf("Error opening file: %s\n", path);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    struct stat st;
    stat(path, &st);
    size_t size = st.st_size;
    time_t modificationTime = st.st_mtime;

    unsigned char *buffer = malloc(size);
    if (!buffer) {
        pthread_mutex_lock(&lock);
        printf("Error allocating memory for file: %s\n", path);
        pthread_mutex_unlock(&lock);
        fclose(fp);
        return NULL;
    }

    if (fread(buffer, size, 1, fp) != 1) {
        pthread_mutex_lock(&lock);
        printf("Error reading file: %s\n", path);
        pthread_mutex_unlock(&lock);
        free(buffer);
        fclose(fp);
        return NULL;
    }

    unsigned char md5[MD5_DIGEST_LENGTH];
    MD5(buffer, size, md5);

    file_info *info = malloc(sizeof(file_info));
    if (!info) {
        pthread_mutex_lock(&lock);
        printf("Error allocating memory for file info: %s\n", path);
        pthread_mutex_unlock(&lock);
        free(buffer);
        fclose(fp);
        return NULL;
    }

    info->size = size;
    info->modificationTime = modificationTime;
    memcpy(info->md5, md5, MD5_DIGEST_LENGTH);

    pthread_mutex_lock(&lock);
    printf("Processed file: %s\n", path);
    pthread_mutex_unlock(&lock);

    free(buffer);
    fclose(fp);

    return info;
}
```
This function reads a file, calculates its size and modification time, computes an MD5 checksum of the content, and returns a `file_info` structure. It uses mutex to ensure thread safety when printing messages to console. 

