#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct StorageDevice {
    int deviceID;
    double capacity;
    char location[3]; // ISO 3166-1 alpha-2 standard
    char status[50];
} StorageDevice;

typedef struct Node {
    StorageDevice *data;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock;
int totalCapacity = 1000; // predefined maximum limit

void addStorageDevice(int deviceID, double capacity, char* location, char* status) {
    pthread_mutex_lock(&lock);

    if (totalCapacity < capacity) {
        printf("Error: Total storage capacity exceeds the specified maximum limit.\n");
        return;
    }

    Node *newNode = malloc(sizeof(Node));
    newNode->data = malloc(sizeof(StorageDevice));
    newNode->next = NULL;

    newNode->data->deviceID = deviceID;
    newNode->data->capacity = capacity;
    strcpy(newNode->data->location, location);
    strcpy(newNode->data->status, status);

    if (head == NULL) {
        head = newNode;
    } else {
        Node *temp = head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }

    totalCapacity -= capacity;

    printf("Storage device added successfully.\n");

    pthread_mutex_unlock(&lock);
}
