    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Add a node to the linked list
void add_node(Node **head, void *data) {
    Node *newNode = create_node(data);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
}

// Render points on a 2D canvas with transformations
void render_points(Node **points, float rotationAngle, Point2D scaleFactor) {
    Node *current = *points;
    while (current != NULL) {
        PointColor *pointColor = (PointColor*) current->data;

        // Apply transformations
        pointColor->point->x *= scaleFactor.x;
        pointColor->point->y *= scaleFactor.y;

        float x_old = pointColor->point->x;
        pointColor->point->x = pointColor->point->x * cos(rotationAngle) - pointColor->point->y * sin(rotationAngle);
        pointColor->point->y = x_old * sin(rotationAngle) + pointColor->point->y * cos(rotationAngle);

        // Render on canvas
        // ...

        current = current->next;
    }
}
```
For the 3D rendering part, you would need to define a `Vertex` structure and a `Face` structure. Each face would contain references to its vertices and each vertex would have a list of adjacent faces. You would also need to implement methods for inserting, deleting, and modifying vertices while ensuring that all normals remain consistent.

