} Record;

int processRecords(int* keys, int numKeys, int maxThreshold, int** offsetsPtr, int** keysPtr, Record*** recordsPtr) {
    srand((unsigned int)time(NULL)); // seed the random number generator

    *offsetsPtr = (int*)malloc(numKeys * sizeof(int));
    *keysPtr = (int*)malloc(numKeys * sizeof(int));
    *recordsPtr = (Record**)malloc(numKeys * sizeof(Record*));

    int totalValue = 0;
    for (int i = 0; i < numKeys; ++i) {
        (*offsetsPtr)[i] = i;
        (*keysPtr)[i] = keys[i];

        // Generate a random number within the range of 1 to maxThreshold - totalValue.
        int value = 1 + rand() % (maxThreshold - totalValue);
        Record* record = (Record*)malloc(sizeof(Record));
        record->key = keys[i];
        record->value = value;

        (*recordsPtr)[i] = record;
        totalValue += value;
    }

    // If the sum of all values exceeds maxThreshold, redistribute excess values.
    if (totalValue > maxThreshold) {
        int excessValue = totalValue - maxThreshold;

        for (int i = 0; i < numKeys && excessValue > 0; ++i) {
            // Reduce the value of each record by 1 until there's no more excess value.
            if ((*recordsPtr)[i]->value > excessValue) {
                (*recordsPtr)[i]->value -= excessValue;
                excessValue = 0;
            } else {
                excessValue -= (*recordsPtr)[i]->value - 1;
                (*recordsPtr)[i]->value = 1;
            }
        }
    }

    return numKeys; // Return the total number of records processed.
}
```
