void manageMemory(int size) {
    if (size <= 0) {
        printf("Invalid input size.\n");
        return;
    }

    double* doubles = malloc(size * sizeof(double));
    if (!doubles) {
        printf("Out of memory error.\n");
        return;
    }

    char* chars = malloc(size * sizeof(char));
    if (!chars) {
        free(doubles);
        printf("Out of memory error.\n");
        return;
    }

    Element* elements = malloc(size * sizeof(Element));
    if (!elements) {
        free(doubles);
        free(chars);
        printf("Out of memory error.\n");
        return;
    }

    srand((unsigned int) time(NULL)); // seed the random number generator

    for (int i = 0; i < size; ++i) {
        doubles[i] = rand() / (double) RAND_MAX; // generate a double precision floating-point number between 0 and 1

        chars[i] = 'a' + rand() % ('z' - 'a'); // generate an ASCII character between 'a' and 'z'

        int stringLength = 1 + rand() % 10; // generate a random length for the string between 1 and 10
        elements[i].string = malloc(stringLength + 1); // allocate memory for the string, including space for null terminator
        if (!elements[i].string) {
            printf("Out of memory error.\n");
            return;
        }

        for (int j = 0; j < stringLength; ++j) {
            elements[i].string[j] = 'a' + rand() % ('z' - 'a'); // generate a random ASCII character between 'a' and 'z'
        }
        elements[i].string[stringLength] = '\0'; // null terminate the string

        elements[i].integer = rand(); // generate an integer
    }

    free(doubles);
    free(chars);
    for (int i = 0; i < size; ++i) {
        free(elements[i].string);
    }
    free(elements);
}
