public class FileProcessingService {
    private final ExecutorService executor;
    private final int maxThreads;
    private final long upperLimit;
    private final Random random;
    private final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private AtomicLong totalRecordsProcessed = new AtomicLong(0);

    public FileProcessingService(int maxThreads, long upperLimit, int seed) {
        this.maxThreads = maxThreads;
        this.upperLimit = upperLimit;
        this.random = new Random(seed);
        this.executor = Executors.newFixedThreadPool(maxThreads);
    }

    public void processFiles(List<String> filePaths) {
        for (String path : filePaths) {
            executor.submit(() -> {
                try {
                    String md5 = cache.computeIfAbsent(path, this::calculateMD5);
                    int value = calculateValue(md5);

                    // handle sum exceeding upper limit and redistribution of excess values
                    if (totalRecordsProcessed.addAndGet(value) > upperLimit) {
                        totalRecordsProcessed.addAndGet(-value);
                        // redistribute the value among other files
                    }
                } catch (IOException e) {
                    e.printStackTrace();
                }
            });
        }
    }

    private String calculateMD5(String path) throws IOException {
        MessageDigest md = null;
        try {
            md = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }

        byte[] fileBytes = Files.readAllBytes(Paths.get(path));
        return Base64.getEncoder().encodeToString(md.digest(fileBytes));
    }

    private int calculateValue(String md5) {
        // Calculate a unique integer value for each file based on its metadata and the random seed
        return Math.abs(random.nextInt()) % Integer.MAX_VALUE;
    }
}
```
