['Here is a basic implementation of `DynamicRandomGenerator` in C++. This code does not cover all your requirements but it gives you an idea about how to start implementing such a class. 

```cpp
#include <random>
#include <vector>
#include <mutex>
#include <stdexcept>

class DynamicRandomGenerator {
public:
    enum DistributionType {
        UNIFORM, NORMAL, EXPONENTIAL
    };

    DynamicRandomGenerator(DistributionType type = UNIFORM) : distribution_type_(type), generator_(std::random_device{}()) {}

    void setDistributionType(DistributionType type) {
        std::lock_guard<std::mutex> lock(mtx_);
        distribution_type_ = type;
    }

    double getRandomNumber() {
        std::lock_guard<std::mutex> lock(mtx_);

        switch (distribution_type_) {
            case UNIFORM:
                return uniformDistribution_(generator_);
            case NORMAL:
                return normalDistribution_(generator_);
            case EXPONENTIAL:
                return exponentialDistribution_(generator_);
            default:
                throw std::runtime_error("Unknown distribution type");
        }
    }

private:
    DistributionType distribution_type_;
    std::mt19937 generator_;
    std::uniform_real_distribution<double> uniformDistribution_{0.0, 1.0};
    std::normal_distribution<double> normalDistribution_{0.0, 1.0};
    std::exponential_distribution<double> exponentialDistribution_{1.0};

    std::mutex mtx_; // for thread safety
};
```
This class uses the C++ Standard Library's random number generation facilities to generate random numbers according to a specified distribution type (uniform, normal, or exponential). The `getRandomNumber` method is thread-safe because it locks a mutex before accessing shared data. 

