```python
from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
import uuid

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:////tmp/test.db'
db = SQLAlchemy(app)

class Resource(db.Model):
    id = db.Column(db.String, primary_key=True)
    metadata = db.Column(db.JSON)
    dependencies = db.relationship('Dependency', backref='resource', lazy=True)

class Dependency(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    resource_id = db.Column(db.String, db.ForeignKey('resource.id'))
    dependency_id = db.Column(db.String)

@app.route('/resources/<uuid:resource_id>', methods=['PUT'])
def updateResource(resource_id):
    resource = Resource.query.get(str(resource_id))
    if not resource:
        return jsonify({'error': 'Resource not found'}), 404

    data = request.json
    if 'metadata' in data and isinstance(data['metadata'], dict):
        resource.metadata = data['metadata']
    else:
        return jsonify({'error': 'Invalid metadata'}), 400

    db.session.commit()
    return jsonify({'message': 'Resource updated successfully'})

@app.route('/resources/<uuid:resource_id>', methods=['DELETE'])
def deleteResource(resource_id):
    resource = Resource.query.get(str(resource_id))
    if not resource:
        return jsonify({'error': 'Resource not found'}), 404

    db.session.delete(resource)
    db.session.commit()
    return jsonify({'message': 'Resource deleted successfully'})
```
