import org.apache.commons.codec.digest.*;
import org.apache.log4j.*;

public class CloudStorageService {
    private static final int MAX_FILES = 100;
    private static final long MAX_SIZE = 1024 * 1024 * 1024L; // 1GB
    private static final int MAX_COMMANDS = 15;
    private static final int HIGH_PRIORITY_COUNT = 4;

    private AmazonS3 s3Client;
    private ExecutorService executorService;
    private ConcurrentHashMap<String, Future> fileHandles = new ConcurrentHashMap<>();
    private MessageDigest md5Digest;
    private Logger logger = Logger.getLogger(CloudStorageService.class);

    public CloudStorageService() {
        s3Client = AmazonS3ClientBuilder.defaultClient();
        executorService = Executors.newFixedThreadPool(MAX_COMMANDS + HIGH_PRIORITY_COUNT);

        try {
            md5Digest = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            logger.error("Failed to initialize MD5 digest", e);
        }
    }

    public void processFile(String filePath) {
        if (fileHandles.size() >= MAX_FILES) {
            logger.warn("Too many files open, cannot process " + filePath);
            return;
        }

        Future<?> future = executorService.submit(() -> {
            try {
                S3Object s3Object = s3Client.getObject(new GetObjectRequest("bucketName", filePath));

                if (s3Object.getObjectMetadata().getContentLength() > MAX_SIZE) {
                    logger.warn("File too large, cannot process " + filePath);
                    return;
                }

                try (InputStream inputStream = s3Object.getObjectContent()) {
                    byte[] buffer = new byte[8192];
                    int bytesRead;

                    while ((bytesRead = inputStream.read(buffer)) != -1) {
                        md5Digest.update(buffer, 0, bytesRead);

                        // Process file contents here...
                    }
                }

                byte[] digest = md5Digest.digest();
                String hash = DatatypeConverter.printHexBinary(digest).toLowerCase();

                logger.info("Processed " + filePath + ", MD5: " + hash);
            } catch (Exception e) {
                logger.error("Failed to process " + filePath, e);
            } finally {
                fileHandles.remove(filePath);
            }
        });

        fileHandles.put(filePath, future);
    }

    // Implement other methods as needed...
}
```
