['Here is a basic implementation of your requirements in C#. This code does not cover all aspects you mentioned due to complexity and size limitations. It's just a starting point for you to build upon. 

```csharp
using System;
using System.Collections.Generic;
using System.Net.Mail;
using System.Text.RegularExpressions;

public class UserSession
{
    public string sessionToken { get; set; }
    public string username { get; set; }
    public string email { get; set; }
    public Action<string> callbackFunction { get; set; }
}

public interface IUserService
{
    bool Validate(string token, out string userId);
}

public class UserSessionProcessor
{
    private readonly Dictionary<string, DateTime> _recentTokens = new Dictionary<string, DateTime>();
    private const int MaxTokenLength = 128;
    private const int MinTokenLength = 32;
    private static Regex ValidEmailRegex = CreateValidEmailRegex();
    private readonly IUserService _userService;

    public UserSessionProcessor(IUserService userService)
    {
        _userService = userService;
    }

    public string ProcessSession(UserSession session, out int errorCode)
    {
        if (!IsValidToken(session.sessionToken))
        {
            errorCode = 100; // Invalid token code
            return null;
        }

        if (!IsValidUsername(session.username))
        {
            errorCode = 200; // Invalid username code
            return null;
        }

        if (!IsValidEmail(session.email))
        {
            errorCode = 300; // Invalid email code
            return null;
        }

        string userId;
        bool isAuthenticated = _userService.Validate(session.sessionToken, out userId);

        if (!isAuthenticated)
        {
            errorCode = 400; // Authentication failed code
            session.callbackFunction?.Invoke("Authentication failed");
            return null;
        }

        errorCode = 0; // No error code
        return userId;
    }

    private bool IsValidToken(string token)
    {
        if (token == null || token.Length < MinTokenLength || token.Length > MaxTokenLength)
            return false;

        DateTime lastUsedTime;
        if (_recentTokens.TryGetValue(token, out lastUsedTime))
        {
            if ((DateTime.UtcNow - lastUsedTime).TotalMinutes < 60)
                return false;

            _recentTokens[token] = DateTime.UtcNow;
        }
        else
        {
            _recentTokens.Add(token, DateTime.UtcNow);
        }

        return true;
    }

    private bool IsValidUsername(string username)
    {
        if (username == null || username.Length > MaxTokenLength)
            return false;

        return true;
    }

    private bool IsValidEmail(string email)
    {
        try
        {
            MailAddress m = new MailAddress(email);
            return m.Address == email && Regex.IsMatch(email, ValidEmailRegex.ToString());
        }
        catch (FormatException)
        {
            return false;
        }
    }

    private static Regex CreateValidEmailRegex()
    {
        string validEmailPattern = @"^(?!\.)(""([^""\r\\]|\\[""\r\\])*""|" + @"([\w\!\#\$\%\&\'\*\+\-\/\=\?\^\`\{\|\}\~]|\.(?!\.))*)@\.";
        return new Regex(validEmailPattern, RegexOptions.IgnoreCase);
    }
}
```
This code assumes that you have an `IUserService` interface with a `Validate` method that takes a session token and returns whether the user is authenticated and their ID if so. The actual implementation of this service would depend on your specific authentication mechanism. 

