    int status_flag;
} Record;

Record** records = NULL;
size_t record_count = 0;
size_t max_records;

void init(size_t max) {
    max_records = max;
    records = (Record**) malloc(max * sizeof(Record*));
}

int add_record() {
    if (record_count >= max_records) return -1; // Error: Maximum limit reached

    Record* new_record = (Record*) malloc(sizeof(Record));
    new_record->primary_key = rand(); // Assign a unique primary key
    new_record->timestamp = time(NULL); // Current timestamp
    new_record->status_flag = rand() % 2; // Random status flag

    size_t string_length = (rand() % 100) + 1; // Random length between 1 and 100
    new_record->string_field = (char*) malloc(string_length * sizeof(char));
    for (size_t i = 0; i < string_length - 1; ++i) {
        int randomChar = rand() % (26 + 26 + 10); // Random alphanumeric character
        if (randomChar < 26) new_record->string_field[i] = 'a' + randomChar;
        else if (randomChar < 52) new_record->string_field[i] = 'A' + randomChar - 26;
        else new_record->string_field[i] = '0' + randomChar - 52;
    }
    new_record->string_field[string_length - 1] = 0; // Null terminator

    records[record_count++] = new_record;
    return 0; // Success
}

int update_record(unsigned long primary_key, const char* string_field) {
    for (size_t i = 0; i < record_count; ++i) {
        if (records[i]->primary_key == primary_key) {
            free(records[i]->string_field); // Free old string field

            size_t new_length = strlen(string_field);
            records[i]->string_field = (char*) malloc((new_length + 1) * sizeof(char));
            strcpy(records[i]->string_field, string_field); // Update string field

            return 0; // Success
        }
    }

    return -2; // Error: Record not found
}

int remove_record(unsigned long primary_key) {
    for (size_t i = 0; i < record_count; ++i) {
        if (records[i]->primary_key == primary_key) {
            free(records[i]->string_field); // Free string field
            free(records[i]); // Free record

            records[i] = records[--record_count]; // Move last record to the removed position
            return 0; // Success
        }
    }

    return -2; // Error: Record not found
}
```
