Record* initialize(int num_records, long lower_bound, long upper_bound, float buffer_percentage) {
    srand((unsigned int) time(NULL));

    // Calculate the size of offset array with a buffer percentage
    int offset_size = (float)num_records * (1 + buffer_percentage);

    long* offsets = malloc(offset_size * sizeof(long));
    if (!offsets) {
        return NULL; // Handle memory allocation failure
    }

    int* keys = malloc(num_records * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL; // Handle memory allocation failure
    }

    Record* records = malloc(num_records * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < num_records; ++i) {
        int key, value;

        do {
            key = rand() % (upper_bound - lower_bound + 1) + lower_bound;
        } while (!isUnique(key, keys, i)); // Check if the generated key is unique

        keys[i] = key;

        value = rand() % (upper_bound - lower_bound + 1) + lower_bound;
        records[i].value = value;
    }

    free(offsets); // Free the offset array as it's not used in this example

    return records;
}

int isUnique(int key, int* keys, int size) {
    for (int i = 0; i < size; ++i) {
        if (keys[i] == key) {
            return 0; // Key already exists in the array
        }
    }

    return 1; // Key is unique
}
```
