Record** records = NULL;
int recordCount = 0;
pthread_mutex_t lock;

void initializeRecords(int count) {
    pthread_mutex_lock(&lock);

    if (records != NULL) {
        for (int i = 0; i < recordCount; ++i) {
            free(records[i]->userID);
            free(records[i]);
        }

        free(records);
    }

