        record->userID = malloc(20);
        sprintf(record->userID, "User%d", record->key);

        records[i] = record;
    }

    recordCount = count;

    pthread_mutex_unlock(&lock);
}

void printRecords() {
    for (int i = 0; i < recordCount; ++i) {
        printf("Key: %d, UserID: %s\n", records[i]->key, records[i]->userID);
    }
}

void* threadFunction(void* arg) {
    int count = *((int*)arg);

    initializeRecords(count);

    printRecords();

    return NULL;
}

int main() {
