    if (pthread_mutex_init(&lock, NULL) != 0) {
        printf("Failed to initialize mutex\n");
        return 1;
    }

    int counts[] = {5, 10}; // Example record counts for different threads
    pthread_t threads[2];

    for (int i = 0; i < 2; ++i) {
        if(pthread_create(&threads[i], NULL, threadFunction, &counts[i]) != 0) {
            printf("Failed to create thread\n");
            return 1;
        }
    }

    for (int i = 0; i < 2; ++i) {
        if(pthread_join(threads[i], NULL) != 0) {
            printf("Failed to join thread\n");
            return 1;
        }
    }

    pthread_mutex_destroy(&lock);

    return 0;
}
