import java.util.*;

class Config implements Comparable<Config> {
    private String key;
    private Object value;
    private int priorityLevel;
    private long lastAccessedTimestamp;

    // Implement getters and setters for the fields

    @Override
    public int compareTo(Config other) {
        return Integer.compare(this.priorityLevel, other.priorityLevel);
    }
}

class ConfigManager {
    private static final int MAX_CONFIGS = 100; // Define the maximum limit on configurations
    private TreeMap<String, Config> configs = new TreeMap<>();
    private PriorityQueue<Config> priorityQueue = new PriorityQueue<>();

    public void addConfig(Config config) {
        if (configs.size() >= MAX_CONFIGS) {
            // Handle error: maximum configurations reached
        } else {
            configs.put(config.getKey(), config);
            priorityQueue.add(config);
        }
    }

    public void removeConfig(String key) {
        Config removed = configs.remove(key);
        if (removed != null) {
            priorityQueue.remove(removed);
        } else {
            // Handle error: configuration not found
        }
    }

    public void updateConfig(String key, Object newValue) {
        Config config = configs.get(key);
        if (config != null) {
            priorityQueue.remove(config);
            config.setValue(newValue);
            priorityQueue.add(config);
        } else {
            // Handle error: configuration not found
        }
    }

    public Config getConfigByKey(String key) {
        return configs.get(key);
    }

    public List<Config> getConfigsByPriorityLevel(int priorityLevel) {
        List<Config> result = new ArrayList<>();
        for (Config config : priorityQueue) {
            if (config.getPriorityLevel() == priorityLevel) {
                result.add(config);
            }
        }
        return result;
    }
}
