```csharp
using System;
using Newtonsoft.Json;

public class DynamicValueGenerator
{
    private Random _random = new Random();
    public int Min { get; set; }
    public int Max { get; set; }

    public DynamicValueGenerator(int min, int max)
    {
        if (min > max) throw new ArgumentException("Minimum value cannot be greater than maximum");

        this.Min = min;
        this.Max = max;
    }

    public int GenerateRandomInteger()
    {
        lock (_random) // thread-safe
        {
            return _random.Next(this.Min, this.Max + 1);
        }
    }

    public float GenerateRandomFloat()
    {
        lock (_random) // thread-safe
        {
            double sample = _random.NextDouble();
            double scaled = sample * (double)(this.Max - this.Min) + this.Min;
            return (float)scaled;
        }
    }

    public bool GenerateRandomBoolean(int probability)
    {
        lock (_random) // thread-safe
        {
            if (probability < 0 || probability > 100) throw new ArgumentException("Probability must be between 0 and 100");

            return _random.NextDouble() < probability / 100.0;
        }
    }

    public string SerializeToJson()
    {
        return JsonConvert.SerializeObject(this);
    }
}
```
This class uses the `Random` class for generating random values, which is thread-safe and suitable for high concurrency environments. The `GenerateRandomInteger` method generates a random integer within the specified range, while the `GenerateRandomFloat` method generates a float value within that range. 

