['This task is quite complex and involves a lot of details that would require a significant amount of code. Here's a simplified version of how you might start implementing this in C using libtiff to parse the TIFF file and OpenSSL for MD5 hashing. This does not include all the features mentioned, but it should give you a good starting point:

```c
#include <stdio.h>
#include <string.h>
#include <openssl/md5.h>
#include <tiffio.h>

typedef struct {
    uint32_t width;
    uint32_t height;
    uint16_t bitsPerSample;
    uint16_t samplesPerPixel;
    uint16_t compressionType;
    char colorInterpretation[50];
    unsigned char md5Hash[MD5_DIGEST_LENGTH];
} ImageMetadata;

ImageMetadata extractMetadata(const char* filename) {
    TIFF* tiff = TIFFOpen(filename, "r");
    if (tiff == NULL) {
        fprintf(stderr, "Failed to open file %s\n", filename);
        exit(1);
    }

    ImageMetadata metadata;
    TIFFGetField(tiff, TIFFTAG_IMAGEWIDTH, &metadata.width);
    TIFFGetField(tiff, TIFFTAG_IMAGELENGTH, &metadata.height);
    TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &metadata.bitsPerSample);
    TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &metadata.samplesPerPixel);
    TIFFGetField(tiff, TIFFTAG_COMPRESSION, &metadata.compressionType);

    char* colorInterpretation;
    if (TIFFGetField(tiff, TIFFTAG_PHOTOMETRIC, &colorInterpretation) == 1) {
        strncpy(metadata.colorInterpretation, colorInterpretation, sizeof(metadata.colorInterpretation));
    } else {
        metadata.colorInterpretation[0] = '\0';
    }

    MD5_CTX mdContext;
    unsigned char buffer[8192];
    size_t bytesRead;
    unsigned char digest[MD5_DIGEST_LENGTH];

    MD5_Init(&mdContext);
    while ((bytesRead = TIFFReadRawStrip(tiff, 0, buffer, sizeof(buffer))) > 0) {
        MD5_Update(&mdContext, buffer, bytesRead);
    }
    MD5_Final(digest, &mdContext);

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf((char*)&metadata.md5Hash[i*2], "%02x", digest[i]);
    }

    TIFFClose(tiff);

    return metadata;
}
```
This code opens a TIFF file, extracts the width and height of the image, bits per sample, samples per pixel, compression type, and color interpretation. It then calculates an MD5 hash of the image data using OpenSSL's MD5 functions. 

