void generate_data(int num_records, int lower_bound, int upper_bound, 
                   long offset_size, int enable_logging) {

    srand(time(NULL)); // seed the random number generator

    // allocate memory for arrays
    long* offsets = malloc(offset_size * sizeof(long));
    assert(offsets != NULL);

    int* keys = calloc(upper_bound - lower_bound + 1, sizeof(int));
    assert(keys != NULL);

    Record* records = malloc(num_records * sizeof(Record));
    assert(records != NULL);

    Metadata* metadata = malloc(num_records * sizeof(Metadata));
    assert(metadata != NULL);

    // populate keys and records with random values
    for (int i = 0; i < num_records; i++) {
        int key, value;

        do {
            key = rand() % (upper_bound - lower_bound + 1) + lower_bound;
        } while(keys[key] != 0);

        keys[key] = 1;

        if (enable_logging) {
            printf("Generated unique key: %d\n", key);
        }

        value = rand() % (upper_bound - lower_bound + 1) + lower_bound;

        if (enable_logging && (value == upper_bound || value == lower_bound)) {
            printf("Generated extreme value: %d\n", value);
        }

        records[i].value = value;
    }

    // populate metadata with pointers to corresponding record and log message
    for (int i = 0; i < num_records; i++) {
        metadata[i].record = &(records[i]);

        if (enable_logging) {
            sprintf(metadata[i].log, "Successfully generated record with key: %d and value: %d", 
                    keys[i], records[i].value);
        } else {
            strcpy(metadata[i].log, "Operation successful");
        }
    }

    // calculate sum of all record values
    long sum = 0;
    for (int i = 0; i < num_records; i++) {
        if (__builtin_add_overflow(sum, records[i].value, &sum)) {
            printf("Overflow detected while calculating sum of all record values\n");
            break;
        }
    }

    // free memory
    free(offsets);
    free(keys);
    free(records);
    free(metadata);
}
