['Here is an example implementation in C using pthreads for concurrency control and a linked list with locks to ensure thread-safe operations. This code does not include the error handling mechanism you requested, but it provides a basic structure that can be expanded upon as needed. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct data_point {
    float value;
    double weight;
    unsigned int id;
    struct data_point *next;
} DataPoint;

typedef struct list {
    pthread_mutex_t lock;
    DataPoint *head;
    size_t max_size;
    size_t current_size;
} List;

List* create_list(size_t max_size) {
    List *list = malloc(sizeof(List));
    if (list == NULL) return NULL;

    list->head = NULL;
    list->max_size = max_size;
    list->current_size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int add_data_point(List *list, float value, double weight, unsigned int id) {
    if (list == NULL || list->current_size >= list->max_size) return -1;

    DataPoint *new_dp = malloc(sizeof(DataPoint));
    if (new_dp == NULL) return -2;

    new_dp->value = value;
    new_dp->weight = weight;
    new_dp->id = id;
    new_dp->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = new_dp;
    } else {
        DataPoint *current = list->head;
        while (current->next != NULL) {
            if (current->id == id) {
                free(new_dp);
                pthread_mutex_unlock(&list->lock);
                return -3;
            }
            current = current->next;
        }
        current->next = new_dp;
    }
    ++list->current_size;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

double calculate_average(List *list) {
    if (list == NULL || list->head == NULL) return -1.0;

    double sum = 0.0;
    size_t count = 0;

    pthread_mutex_lock(&list->lock);
    DataPoint *current = list->head;
    while (current != NULL) {
        sum += current->value * current->weight;
        ++count;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    return count > 0 ? sum / count : 0.0;
}
```
This code provides a basic structure for handling concurrent data point updates and calculating the average of the dataset. It uses a linked list with locks to ensure thread safety, but it does not include error handling or memory management optimizations that would be needed in a production environment.
']

