    time_t modificationTime;
    char checksum[32]; // Assuming a 32-byte checksum for simplicity
} file_info;

typedef struct {
    const char* filename;
    file_info* info;
    pthread_mutex_t mutex;
} FileEntry;

FileEntry** files = NULL;
size_t numFiles = 0;
sem_t semaphore;
pthread_mutex_t filesMutex = PTHREAD_MUTEX_INITIALIZER;

void* readFile(void* arg) {
    const char* filename = (const char*)arg;

    // Open file, read contents, etc.

    sem_post(&semaphore); // Signal that we're done reading
}

int main() {
    if (sem_init(&semaphore, 0, MAX_CONCURRENT_READS) == -1) {
        perror("Failed to initialize semaphore");
        return EXIT_FAILURE;
    }

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        // Remove trailing newline character
        buffer[strcspn(buffer, "\n")] = 0;

        if (sem_wait(&semaphore) == -1) {
            perror("Failed to wait on semaphore");
            return EXIT_FAILURE;
        }

        pthread_t thread;
        if (pthread_create(&thread, NULL, readFile, buffer) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }

        // Add file entry and allocate memory for its info
        pthread_mutex_lock(&filesMutex);
        files = realloc(files, (numFiles + 1) * sizeof(FileEntry*));
        if (!files) {
            perror("Failed to allocate memory");
            return EXIT_FAILURE;
        }

        FileEntry* entry = malloc(sizeof(FileEntry));
        if (!entry) {
            perror("Failed to allocate memory");
            return EXIT_FAILURE;
        }

        entry->filename = strdup(buffer);
        if (!entry->filename) {
            perror("Failed to duplicate string");
            return EXIT_FAILURE;
        }

        entry->info = malloc(sizeof(file_info));
        if (!entry->info) {
            perror("Failed to allocate memory");
            return EXIT_FAILURE;
        }

        pthread_mutex_init(&entry->mutex, NULL);

        files[numFiles++] = entry;
        pthread_mutex_unlock(&filesMutex);
    }

    // Wait for all threads to finish
    while (sem_wait(&semaphore) == 0);

    // Cleanup code omitted for brevity
}
