["Here is an example implementation of your request using C11 threads and POSIX mutexes for synchronization. This code does not include all the features you requested (like unique value generation within a specified range), but it should give you a good starting point. 

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    pthread_mutex_t mutex;
    size_t capacity;
    size_t count;
} HashTable;

HashTable* create_hash_table(size_t initialCapacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    table->offsets = calloc(initialCapacity, sizeof(long));
    table->keys = calloc(initialCapacity, sizeof(int));
    table->records = calloc(initialCapacity, sizeof(record*));
    if (table->offsets == NULL || table->keys == NULL || table->records == NULL) {
        free_hash_table(table);
        return NULL;
    }

    pthread_mutex_init(&table->mutex, NULL);
    table->capacity = initialCapacity;
    table->count = 0;

    return table;
}

void free_hash_table(HashTable* table) {
    if (table == NULL) return;

    for (size_t i = 0; i < table->capacity; ++i) {
        free(table->records[i]);
    }

    free(table->offsets);
    free(table->keys);
    free(table->records);
    pthread_mutex_destroy(&table->mutex);
    free(table);
}

void resize_hash_table(HashTable* table, size_t newCapacity) {
    long* newOffsets = calloc(newCapacity, sizeof(long));
    int* newKeys = calloc(newCapacity, sizeof(int));
    record** newRecords = calloc(newCapacity, sizeof(record*));

    if (newOffsets == NULL || newKeys == NULL || newRecords == NULL) {
        free(newOffsets);
        free(newKeys);
        free(newRecords);
        return;
    }

    for (size_t i = 0; i < table->capacity; ++i) {
        size_t index = table->keys[i] % newCapacity;

        while (newKeys[index] != 0) {
            index = (index + 1) % newCapacity;
        }

        newOffsets[index] = table->offsets[i];
        newKeys[index] = table->keys[i];
        newRecords[index] = table->records[i];
    }

    free(table->offsets);
    free(table->keys);
    for (size_t i = 0; i < table->capacity; ++i) {
        free(table->records[i]);
    }
    free(table->records);

    table->offsets = newOffsets;
    table->keys = newKeys;
    table->records = newRecords;
    table->capacity = newCapacity;
}

void insert_record(HashTable* table, int key, record* rec) {
    pthread_mutex_lock(&table->mutex);

    if (table->count == table->capacity) {
        resize_hash_table(table, table->capacity * 2);
    }

    size_t index = key % table->capacity;

    while (table->keys[index] != 0) {
        index = (index + 1) % table->capacity;
    }

    table->offsets[index] = (long)(rec - table->records);
    table->keys[index] = key;
    table->records[index] = rec;
    ++table->count;

    pthread_mutex_unlock(&table->mutex);
}
```
This code creates a hash table that uses linear probing to handle collisions. It resizes the table when it becomes full, doubling its capacity each time. The `insert_record` function is thread-safe and locks the mutex before modifying the table. 

