        free(product);
        perror("strdup failed");
        return NULL;
    }

    product->price = price;
    product->stock = stock;
    return product;
}

void destroyProduct(Product* product) {
    if (product) {
        free(product->name);
        free(product);
    }
}

int addProduct(ProductList* list, Product* product) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        fprintf(stderr, "Maximum capacity reached\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->products[list->count++] = product;
    list->totalValue += product->price * product->stock;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

