['Here is an example implementation of a doubly-linked list with thread safety using pthreads in C. This code does not include error handling or graceful degradation of performance when system resources are constrained as it would be quite complex and beyond the scope of this task. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Node {
    char* buffer;
    int key;
    struct Node* prev;
    struct Node* next;
} Node;

Node* head = NULL;
Node* tail = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insert(char* buffer, int key) {
    pthread_mutex_lock(&lock);

    Node* node = (Node*)malloc(sizeof(Node));
    node->buffer = strdup(buffer);
    node->key = key;
    node->prev = NULL;
    node->next = head;

    if (head != NULL) {
        head->prev = node;
    } else {
        tail = node;
    }

    head = node;

    pthread_mutex_unlock(&lock);
}

void delete(int key) {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        if (current->key == key) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                head = current->next;
            }

            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                tail = current->prev;
            }

            free(current->buffer);
            free(current);
            break;
        }

        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

void traverse() {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        // Process node data here...

        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}
```
This code uses a mutex to ensure that only one thread can modify the list at a time, which is necessary for thread safety. It also uses dynamic memory allocation and deallocation to minimize fragmentation and optimize performance under high load. However, it does not include error handling or graceful degradation of performance when system resources are constrained as these would be quite complex and beyond the scope of this task.
']

['Here is an example of how you might implement such a function in C using pthreads for thread safety and glib for data structures. This code does not include all the features mentioned in your request due to complexity and size limitations. However, it provides a good starting point for building a scalable, concurrent network node management system:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <glib.h>

typedef struct {
    int nodeID;
    char* location;
    int status;
} NetworkNode;

GHashTable *node_table = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int max_nodes = 1000; // Maximum number of nodes

void init() {
    node_table = g_hash_table_new(g_direct_hash, g_direct_equal);
}

NetworkNode* create_node(int id, char* location, int status) {
    NetworkNode *node = malloc(sizeof(NetworkNode));
    if (node == NULL) return NULL;

    node->nodeID = id;
    node->location = strdup(location);
    node->status = status;

    return node;
}

void add_node(int id, char* location, int status) {
    pthread_mutex_lock(&lock);
    if (g_hash_table_size(node_table) >= max_nodes) {
        printf("Error: Maximum number of nodes reached.\n");
        return;
    }

    NetworkNode *node = create_node(id, location, status);
    gpointer existing = g_hash_table_lookup(node_table, &node->nodeID);
    if (existing != NULL) {
        printf("Error: Node ID already exists.\n");
        free(node->location);
        free(node);
        return;
    }

    g_hash_table_insert(node_table, &node->nodeID, node);
    pthread_mutex_unlock(&lock);
}

NetworkNode* get_node(int id) {
    pthread_mutex_lock(&lock);
    NetworkNode *node = g_hash_table_lookup(node_table, &id);
    if (node == NULL) {
        printf("Error: Node not found.\n");
    }
    pthread_mutex_unlock(&lock);

    return node;
}

void remove_node(int id) {
    pthread_mutex_lock(&lock);
    NetworkNode *node = g_hash_table_lookup(node_table, &id);
    if (node == NULL) {
        printf("Error: Node not found.\n");
        return;
    }

    g_hash_table_remove(node_table, &id);
    free(node->location);
    free(node);
    pthread_mutex_unlock(&lock);
}
```
This code uses a hash table to store the nodes. The `add_node` function checks if the maximum number of nodes has been reached and whether a node with the same ID already exists before adding it. Similarly, the `get_node` function retrieves a node by its ID. The `remove_node` function removes a node from the table and frees its memory.

