    point* pt = malloc(sizeof(point));
    pt->x = xCoord;
    pt->y = yCoord;

    // Add the key, coordinate values and point to the record
    rec->value = key;
    rec->pt = pt;

    // Lock-free synchronization using atomic operations and spinlock
    pthread_spin_lock(&spinlock);
    offsetValues[offset] = 0; // Replace with your own logic for generating offset values
    keys[offset] = key;
