# Develop a Java method that calculates the Fibonacci sequence using memoization
class Fibonacci {
    private Map<Integer, BigInteger> memoizeTable;

    public Fibonacci() {
        this.memoizeTable = new HashMap<>();
        this.memoizeTable.put(0, BigInteger.ZERO);
        this.memoizeTable.put(1, BigInteger.ONE);
    }

    public BigInteger fibonacci(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must not be less than zero");
        }
        return this.fibonacciMemoize(n).get();
    }

    private Optional<BigInteger> fibonacciMemoize(int n) {
        if (!this.memoizeTable.containsKey(n)) {
            Optional<BigInteger> fibNMinus1 = this.fibonacciMemoize(n - 1);
            Optional<BigInteger> fibNMinus2 = this.fibonacciMemoize(n - 2);

            if (fibNMinus1.isPresent() && fibNMinus2.isPresent()) {
                BigInteger result = fibNMinus1.get().add(fibNMinus2.get());
                this.memoizeTable.put(n, result);
            }
        }

        return Optional.ofNullable(this.memoizeTable.get(n));
    }
}
