```c
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>

typedef struct point {
    float x;
    float y;
} Point;

typedef struct geometry {
    float area;
    float perimeter;
    char* type;
} Geometry;

typedef struct data_model {
    long* offsets;
    int* keys;
    Point** points;
    Geometry** geometries;
    size_t max_records;
    size_t record_count;
    pthread_mutex_t lock;
} DataModel;

DataModel* create_data_model(size_t max_records) {
    DataModel* model = malloc(sizeof(DataModel));
    if (model == NULL) {
        return NULL;
    }

    model->offsets = calloc(max_records, sizeof(long));
    model->keys = calloc(max_records, sizeof(int));
    model->points = calloc(max_records, sizeof(Point*));
    model->geometries = calloc(max_records, sizeof(Geometry*));

    if (model->offsets == NULL || model->keys == NULL || 
        model->points == NULL || model->geometries == NULL) {

        free(model->offsets);
        free(model->keys);
        free(model->points);
        free(model->geometries);
        free(model);
        return NULL;
    }

    model->max_records = max_records;
    model->record_count = 0;
    pthread_mutex_init(&model->lock, NULL);

    return model;
}

int add_record(DataModel* model, long offset, int key, Point* point, Geometry* geometry) {
    if (pthread_mutex_lock(&model->lock)) {
        return -1;
    }

    if (model->record_count >= model->max_records) {
        pthread_mutex_unlock(&model->lock);
        errno = ENOMEM;
        return -1;
    }

    model->offsets[model->record_count] = offset;
    model->keys[model->record_count] = key;
    model->points[model->record_count] = point;
    model->geometries[model->record_count] = geometry;
    ++model->record_count;

    pthread_mutex_unlock(&model->lock);
    return 0;
}

void free_data_model(DataModel* model) {
    for (size_t i = 0; i < model->record_count; ++i) {
        free(model->points[i]);
        free(model->geometries[i]);
    }

    pthread_mutex_destroy(&model->lock);
    free(model->offsets);
    free(model->keys);
    free(model->points);
    free(model->geometries);
    free(model);
}
```
This code creates a data model with the specified maximum number of records. The `add_record` function adds a new record to the model, checking if there is enough space and locking the model for thread safety. The `free_data_model` function frees all allocated memory when the model is no longer needed.
