    char** strings;
    size_t* lengths;
    node** nodes;
    int* usageStatus;
    // Add other structures as needed.
} dataStructures;

dataStructures* initDataStructures(size_t maxStrings) {
    dataStructures* ds = malloc(sizeof(dataStructures));
    if (ds == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    ds->strings = calloc(maxStrings, sizeof(char*));
    ds->lengths = calloc(maxStrings, sizeof(size_t));
    ds->nodes = calloc(maxStrings, sizeof(node*));
    ds->usageStatus = calloc(maxStrings, sizeof(int));

    if (ds->strings == NULL || ds->lengths == NULL || ds->nodes == NULL || ds->usageStatus == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&ds->lock, NULL);

    return ds;
}

void generateString(dataStructures* ds, size_t index) {
    clock_t start = clock();

    // Generate a string here.
    char* str = "Generated String";  // Replace with actual generation logic.
    size_t len = strlen(str);

    pthread_mutex_lock(&ds->lock);
    ds->strings[index] = malloc(len + 1);
    if (ds->strings[index] == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    strcpy(ds->strings[index], str);
    ds->lengths[index] = len;
    pthread_mutex_unlock(&ds->lock);

    clock_t end = clock();
    double timeSpent = (double)(end - start) / CLOCKS_PER_SEC;
    printf("String generation and memory allocation took %f seconds.\n", timeSpent);
}

void* threadFunc(void* arg) {
    dataStructures* ds = (dataStructures*)arg;

    // Generate a string for each index.
    for (size_t i = 0; i < /* maxStrings */; ++i) {
        generateString(ds, i);
    }

    return NULL;
}

int main() {
    size_t maxStrings = /* user input or default value */;
    dataStructures* ds = initDataStructures(maxStrings);

    // Create threads.
    pthread_t threads[/* number of threads */];
    for (size_t i = 0; i < /* number of threads */; ++i) {
        if (pthread_create(&threads[i], NULL, threadFunc, ds)) {
            fprintf(stderr, "Thread creation failed.\n");
