void processFiles(size_t maxFileSize) {
    const char** fileNames = malloc(5 * sizeof(const char*));
    if (fileNames == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    size_t* offsets = calloc(5, sizeof(size_t));
    if (offsets == NULL) {
        printf("Memory allocation failed\n");
        free(fileNames);
        return;
    }

    file_info** fileInfos = malloc(5 * sizeof(file_info*));
    if (fileInfos == NULL) {
        printf("Memory allocation failed\n");
        free(fileNames);
        free(offsets);
        return;
    }

    int* errorCodes = calloc(5, sizeof(int));
    if (errorCodes == NULL) {
        printf("Memory allocation failed\n");
        free(fileNames);
        free(offsets);
        free(fileInfos);
        return;
    }

    size_t totalSize = 0;
    for (int i = 0; i < 5; ++i) {
        char filePath[256];
        scanf("%s", filePath);

        FILE* file = fopen(filePath, "r");
        if (file == NULL) {
            errorCodes[i] = 1; // Error code for file open failure
            continue;
        }

        size_t fileSize;
        fseek(file, 0L, SEEK_END);
        fileSize = ftell(file);
        rewind(file);

        if (totalSize + fileSize > maxFileSize) {
            errorCodes[i] = 2; // Error code for exceeding maximum size limit
            fclose(file);
            continue;
        }

        totalSize += fileSize;

        fileNames[i] = strdup(filePath);
        offsets[i] = totalSize - fileSize;

        file_info* info = malloc(sizeof(file_info));
        if (info == NULL) {
            errorCodes[i] = 3; // Error code for memory allocation failure
            fclose(file);
            continue;
        }

        info->fileSize = fileSize;
        // Set other fields of the file_info struct...

        fileInfos[i] = info;

        fclose(file);
    }

    // Process files and consolidate their contents into a single output stream...

    for (int i = 0; i < 5; ++i) {
        free((void*)fileNames[i]);
        free(fileInfos[i]);
    }

    free(fileNames);
    free(offsets);
    free(fileInfos);
    free(errorCodes);
}
```
