        }

        doubleArray[i] = minValue + ((double)rand() / RAND_MAX) * (maxValue - minValue);

        char* label = malloc(strlen(prefix) + strlen(suffix) + 20); // 20 is for the identifier and '\0'
        if (!label) {
            // handle error: memory allocation failed
            free(dataArray[i]);
            continue;
        }

        sprintf(label, "%s%d%s", prefix, i, suffix);
        dataArray[i]->identifier = i;
        dataArray[i]->value = doubleArray[i];
        dataArray[i]->label = label;

        statusFlags[i] = 1; // mark as initialized

        pthread_mutex_unlock(&lock);
    }
}
```
