```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordArray;

RecordArray createRecordArray(size_t initialCapacity) {
    RecordArray array = {
        .records = malloc(initialCapacity * sizeof(Record)),
        .capacity = initialCapacity,
        .count = 0,
        .lock = PTHREAD_MUTEX_INITIALIZER
    };

    if (array.records == NULL) {
        // Handle memory allocation failure
        exit(1);
    }

    return array;
}

void addRecord(RecordArray* array, long offset, int key) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity * 0.8) {
        // Resize the array by a factor of 2 when it reaches 80% capacity
        size_t newCapacity = array->capacity * 2;
        Record* newRecords = realloc(array->records, newCapacity * sizeof(Record));

        if (newRecords == NULL) {
            // Handle memory allocation failure during resizing
            exit(1);
        }

        array->records = newRecords;
        array->capacity = newCapacity;
    }

    array->records[array->count].offset = offset;
    array->records[array->count].key = key;
    array->count++;

    pthread_mutex_unlock(&array->lock);
}

void generateRecords(RecordArray* array, size_t count, int seed) {
    srand(seed);

    for (size_t i = 0; i < count; ++i) {
        long offset = rand();
        int key = rand();

        addRecord(array, offset, key);

        // Log the creation of each record
        printf("Created record with offset %ld and key %d\n", offset, key);
    }
}
```
