```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

typedef struct DataStructure {
    long* offsets;
    int* keys;
    Record** records;
    pthread_mutex_t mutex;
} DataStructure;

DataStructure* initializeDataStructure(int numRecords, int maxValue) {
    srand(time(NULL)); // seed the random number generator

    if (numRecords > maxValue + 1) {
        fprintf(stderr, "Error: Cannot generate unique values for %d records with a maximum value of %d\n", numRecords, maxValue);
        return NULL;
    }

    DataStructure* ds = malloc(sizeof(DataStructure));
    if (ds == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for data structure\n");
        return NULL;
    }

    ds->offsets = calloc(numRecords, sizeof(long));
    ds->keys = malloc(numRecords * sizeof(int));
    ds->records = malloc(numRecords * sizeof(Record*));

    if (ds->offsets == NULL || ds->keys == NULL || ds->records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for data structure components\n");
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
        return NULL;
    }

    pthread_mutex_init(&ds->mutex, NULL);

    int* usedKeys = calloc(maxValue + 1, sizeof(int));
    if (usedKeys == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for key tracking\n");
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        pthread_mutex_destroy(&ds->mutex);
        free(ds);
        return NULL;
    }

    for (int i = 0; i < numRecords; ++i) {
        int value;
        do {
            value = rand() % maxValue + 1; // generate a random number between 1 and maxValue
        } while (usedKeys[value]);

        usedKeys[value] = 1;

        ds->keys[i] = value;
        ds->records[i] = malloc(sizeof(Record));
        if (ds->records[i] == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for record %d\n", i);
            free(usedKeys);
            // clean up previously allocated records and keys
            for (int j = 0; j < i; ++j) {
                free(ds->records[j]);
            }
            free(ds->offsets);
            free(ds->keys);
            free(ds->records);
            pthread_mutex_destroy(&ds->mutex);
            free(ds);
            return NULL;
        }

        ds->records[i]->value = value;
    }

    free(usedKeys);

    return ds;
}
```
This code initializes a `DataStructure` with the specified number of records, each with a unique random integer value within the range 1 to `maxValue`. It uses a mutex for thread safety and checks memory allocation failures. However, it does not include features like periodic memory usage logging or handling concurrent access from multiple threads.
