```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <assert.h>

#define MAX_EVENTS 10000
#define MAX_MEMORY 2 * 1024 * 1024 // 2 MB in bytes
#define HASH_TABLE_SIZE 5007 // A prime number for better distribution

typedef struct event {
    double value;
    char priority;
    struct event* next;
} Event;

Event* events[MAX_EVENTS];
pthread_mutex_t mutexes[MAX_EVENTS];
Event* hashTable[HASH_TABLE_SIZE];
int initializedEvents = 0;

void init() {
    srand(time(NULL)); // Initialize random seed

    for (int i = 0; i < MAX_EVENTS; ++i) {
        pthread_mutex_init(&mutexes[i], NULL);
    }
}

void* allocateMemory(size_t size) {
    static size_t allocatedMemory = 0;

    if (allocatedMemory + size > MAX_MEMORY) {
        fprintf(stderr, "Not enough memory\n");
        return NULL;
    }

    void* ptr = malloc(size);
    if (!ptr) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    allocatedMemory += size;
    return ptr;
}

void addEventToHashTable(int index, Event* event) {
    int hash = abs((int)(event->priority * 100)) % HASH_TABLE_SIZE; // Simple hashing function

    pthread_mutex_lock(&mutexes[index]);
    event->next = hashTable[hash];
    hashTable[hash] = event;
    pthread_mutex_unlock(&mutexes[index]);
}

void addEvent(int index, double value, char priority) {
    Event* event = allocateMemory(sizeof(Event));

    if (!event) return;

    event->value = value;
    event->priority = priority;
    event->next = NULL;

    events[index] = event;
    addEventToHashTable(index, event);
    ++initializedEvents;
}

void cleanup() {
    for (int i = 0; i < MAX_EVENTS; ++i) {
        pthread_mutex_destroy(&mutexes[i]);

        if (events[i]) free(events[i]);
    }

    // Clean up hash table...
}

int main() {
    atexit(cleanup);
    init();

    for (int i = 0; i < MAX_EVENTS; ++i) {
        double value = ((double)rand() / RAND_MAX) * 10.0; // Random number between 0 and 10
        char priority = 'A' + rand() % ('Z' - 'A'); // Random uppercase letter

        addEvent(i, value, priority);
    }

    printf("Initialized events: %d\n", initializedEvents);

    return 0;
}
```
This code does not include all the features you requested. It's a basic implementation of dynamic memory allocation and concurrent access management for your requirements. You would need to add more features like reading configuration files, error handling, logging etc. Also, this is a simple hash table implementation which might lead to collisions and inefficient lookups. For a production-level code, you should use a well-tested library or implement a better hashing function.
