['Here is an example implementation in C that meets all the requirements you've specified. This code uses a hash table (implemented as a linked list array) for storing strings, with each node containing a string and its length. The helper function `find_longest` iterates over the nodes to find the longest string.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRINGS 10000
#define HASH_TABLE_SIZE 256

typedef struct node {
    char *str;
    int len;
    struct node *next;
} Node;

Node *hashTable[HASH_TABLE_SIZE];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int count = 0;

unsigned long hash(char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % HASH_TABLE_SIZE;
}

Node* find(char *str) {
    unsigned long index = hash(str);
    Node *node = hashTable[index];

    while (node != NULL) {
        if (strcmp(node->str, str) == 0)
            return node;

        node = node->next;
    }

    return NULL;
}

void insert(char *str) {
    pthread_mutex_lock(&mutex);

    if (count >= MAX_STRINGS) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    Node *node = find(str);

    if (node != NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    unsigned long index = hash(str);
    node = malloc(sizeof(Node));
    node->str = strdup(str);
    node->len = strlen(str);
    node->next = hashTable[index];
    hashTable[index] = node;

    count++;

    pthread_mutex_unlock(&mutex);
}

char* find_longest() {
    char *longestStr = NULL;
    int longestLen = 0;

    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        Node *node = hashTable[i];

        while (node != NULL) {
            if (node->len > longestLen) {
                longestStr = node->str;
                longestLen = node->len;
            }

            node = node->next;
        }
    }

    return longestStr;
}

void* read_strings(void *arg) {
    char buffer[1024];

    while (fgets(buffer, sizeof(buffer), stdin)) {
        buffer[strcspn(buffer, "\n")] = 0; // Remove trailing newline
        insert(buffer);
    }

    return NULL;
}

int main() {
    pthread_t thread1, thread2;

    pthread_create(&thread1, NULL, read_strings, NULL);
    pthread_create(&thread2, NULL, read_strings, NULL);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    char *longestStr = find_longest();

    if (longestStr != NULL) {
        printf("Longest string: %s\n", longestStr);
    } else {
        printf("No strings found.\n");
    }

    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        Node *node = hashTable[i];

        while (node != NULL) {
            Node *temp = node;
            node = node->next;

            free(temp->str);
            free(temp);
        }
    }

    return 0;
}
```
This code uses a hash table for storing strings, with each node containing a string and its length. The helper function `find_longest` iterates over the nodes to find the longest string. It's designed to handle concurrent access from multiple threads using mutex locks. Memory is freed upon exit to prevent memory leaks.
']

