["Here is an example implementation in C using pthread library for thread safety and error handling mechanism. This code does not include logging mechanism as it would be quite complex to implement here. However, you can use libraries like log4c or glib's GLog for this purpose. 

```C
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    pthread_mutex_t lock;
    Record* records;
    size_t capacity;
    size_t count;
} RecordsManager;

RecordsManager* create_records(size_t initialCapacity) {
    RecordsManager* manager = malloc(sizeof(RecordsManager));
    if (manager == NULL) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = initialCapacity;
    manager->count = 0;
    manager->records = malloc(initialCapacity * sizeof(Record));
    if (manager->records == NULL) {
        free(manager);
        return NULL;
    }

    srand(time(NULL)); // seed the random number generator
    for (size_t i = 0; i < initialCapacity; ++i) {
        manager->records[i].value = rand();
    }

    return manager;
}

void resize_records(RecordsManager* manager, size_t newCapacity) {
    pthread_mutex_lock(&manager->lock);
    Record* newRecords = realloc(manager->records, newCapacity * sizeof(Record));
    if (newRecords != NULL) {
        manager->records = newRecords;
        manager->capacity = newCapacity;
    } else {
        // handle memory allocation failure here
    }
    pthread_mutex_unlock(&manager->lock);
}

void add_record(RecordsManager* manager, int value) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        resize_records(manager, manager->capacity * 2); // double the capacity when full
    }

    manager->records[manager->count].value = value;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
}

void destroy_records(RecordsManager* manager) {
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```

This code provides a basic implementation of the requirements. It uses a mutex to ensure thread safety, and resizes the array when it's full. However, this is a very simple example and doesn't include many features that would be necessary in a real-world application, such as error handling, logging, unit tests, or concurrency control for multiple threads.
