    if (*keys == NULL) {
        free(*offsets);
        fprintf(stderr, "Memory allocation error for keys.\n");
        exit(EXIT_FAILURE);
    }

    *records = (record**) malloc(num_records * sizeof(record*));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        fprintf(stderr, "Memory allocation error for records.\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // seed the random number generator
    int min = 1; 
    int max = 100; // define your range here

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i] = (record*) malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            fprintf(stderr, "Memory allocation error for record %zu.\n", i);
            // free previously allocated records
            for (--i; i >= 0; --i) 
                free((*records)[i]);
            free(*offsets);
            free(*keys);
            exit(EXIT_FAILURE);
        }

        (*records)[i]->id = rand() % (max - min + 1) + min; // generate random number in range [min, max]
        (*records)[i]->filename = strdup("default.txt"); // allocate and initialize filename
    }
}
```
