['Here is an example of how you might implement this in C using pthreads for threading, a custom memory pool allocator, and serialization/deserialization with fwrite() and fread(). This code does not include error handling or checking for NULL pointers, which would be necessary in a production environment.

```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int value;
} Record;

typedef struct {
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    Record* records;
} Collection;

Collection* create_collection() {
    Collection* collection = malloc(sizeof(Collection));
    if (collection == NULL) return NULL;

    collection->capacity = 100;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    collection->records = malloc(sizeof(Record) * collection->capacity);
    if (collection->records == NULL) {
        free(collection);
        return NULL;
    }

    return collection;
}

void add_record(Collection* collection, Record record) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        Record* newRecords = realloc(collection->records, sizeof(Record) * newCapacity);
        if (newRecords != NULL) {
            collection->records = newRecords;
            collection->capacity = newCapacity;
        } else {
            pthread_mutex_unlock(&collection->lock);
            return;
        }
    }

    collection->records[collection->count++] = record;

    pthread_mutex_unlock(&collection->lock);
}

void serialize(Collection* collection, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) return;

    fwrite(&collection->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < collection->count; ++i) {
        fwrite(&collection->records[i], sizeof(Record), 1, file);
    }

    fclose(file);
}

Collection* deserialize(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) return NULL;

    Collection* collection = create_collection();
    if (collection == NULL) return NULL;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < count; ++i) {
        Record record;
        fread(&record, sizeof(Record), 1, file);
        add_record(collection, record);
    }

    fclose(file);

    return collection;
}
```
This code uses a simple lock to ensure that only one thread can modify the collection at a time. It also doubles the capacity of the collection whenever it is full, which reduces the number of reallocations needed and thus minimizes memory overhead. The serialization/deserialization functions use fwrite() and fread(), which are binary-safe and should be efficient for large amounts of data.
']

