    if (entries == NULL) return NULL;

    entries->capacity = 1024; // Start with a small initial capacity
    entries->count = 0;

    entries->offsets = malloc(entries->capacity * sizeof(long));
    if (entries->offsets == NULL) {
        free(entries);
