}

void add_entry(DataEntries* entries, long offset, int key, Record* record) {
    if (entries->count >= entries->capacity) {
        // Resize the arrays by doubling their capacity
        size_t newCapacity = entries->capacity * 2;

        entries->offsets = realloc(entries->offsets, newCapacity * sizeof(long));
        if (entries->offsets == NULL) return;

        entries->keys = realloc(entries->keys, newCapacity * sizeof(int));
        if (entries->keys == NULL) return;

        entries->records = realloc(entries->records, newCapacity * sizeof(Record*));
        if (entries->records == NULL) return;

        entries->capacity = newCapacity;
