#include <stdlib.h>
#include <pthread.h>

typedef struct Node {
    int id;
    double bandwidth;
    double latency;
    struct Node** connections;
} Node;

Node* create_node(int id, double bandwidth, double latency) {
    Node* node = malloc(sizeof(Node));
    if (node == NULL) return NULL;

    node->id = id;
    node->bandwidth = bandwidth;
    node->latency = latency;
    node->connections = calloc(1, sizeof(Node*)); // Start with 1 connection slot
    if (node->connections == NULL) {
        free(node);
        return NULL;
    }

    return node;
}

void add_connection(Node* node, Node* connection) {
    size_t num_slots = sizeof(node->connections) / sizeof(Node*);
    for (size_t i = 0; i < num_slots; ++i) {
        if (node->connections[i] == NULL) {
            node->connections[i] = connection;
            return;
        }
    }

    // If we're here, there was no free slot. Add a new one.
    size_t new_size = num_slots * 2 * sizeof(Node*);
    Node** new_connections = realloc(node->connections, new_size);
    if (new_connections == NULL) return; // Could not allocate more memory.

    node->connections = new_connections;
    add_connection(node, connection); // Try again with the larger array.
}

void free_node(Node* node) {
    if (node == NULL) return;

    for (size_t i = 0; i < sizeof(node->connections) / sizeof(Node*); ++i) {
        if (node->connections[i] != NULL) free_node(node->connections[i]);
    }

    free(node->connections);
    free(node);
}
```
This code creates a simple node structure with an id, bandwidth and latency. It also includes functions to create nodes dynamically and add connections between them. The `free_node` function recursively frees all connected nodes before freeing the current one. 

