#include <stdlib.h>
#include <pthread.h>
#include <glib.h>

typedef struct {
    int value;
} Record;

GHashTable* hash_table;
long* offsets;
int* keys;
Record** records;
size_t max_memory;
size_t current_memory = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate(size_t size) {
    pthread_mutex_lock(&lock);
    if (current_memory + size > max_memory) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    current_memory += size;
    void* memory = malloc(size);
    pthread_mutex_unlock(&lock);
    return memory;
}

void deallocate(void* memory, size_t size) {
    free(memory);
    pthread_mutex_lock(&lock);
    current_memory -= size;
    pthread_mutex_unlock(&lock);
}

int assign_key() {
    static int next_key = 0;
    pthread_mutex_lock(&lock);
    int key = ++next_key;
    while (g_hash_table_contains(hash_table, &key)) {
        ++key;
    }
    g_hash_table_insert(hash_table, &key, NULL);
    pthread_mutex_unlock(&lock);
    return key;
}

void initialize() {
    hash_table = g_hash_table_new(g_int_hash, g_int_equal);
    max_memory = 1024 * 1024; // 1MB
}

Record* create_record(int value) {
    Record* record = allocate(sizeof(Record));
    if (record == NULL) return NULL;
    record->value = value;
    int key = assign_key();
    keys = realloc(keys, sizeof(int) * (key + 1));
    keys[key] = key;
    records = realloc(records, sizeof(Record*) * (key + 1));
    records[key] = record;
    return record;
}
