    long* array = allocateMemory(size * sizeof(long));
    // Initialize the array with offsets
    for (int i = 0; i < size; ++i) {
        array[i] = rand() % 1000;
    }
    return array;
}

unsigned int hashFunction(const char* str, unsigned int length) {
    unsigned long hash = 5381;
    for (unsigned int i = 0; i < length; ++i) {
        hash = ((hash << 5) + hash) + str[i]; /* hash * 33 + c */
    }
    return hash % length;
}

int* createKeyArray(int size, const char** keys) {
    int* array = allocateMemory(size * sizeof(int));
    // Initialize the array with hashed keys
    for (int i = 0; i < size; ++i) {
        unsigned int hash = hashFunction(keys[i], strlen(keys[i]));
        array[hash % size] = hash;
    }
    return array;
}

Metadata* createMetadataArray(int size) {
