#include <chrono>

// Define a custom hash table entry
struct Entry {
    std::string id;
    std::time_t timestamp;
    std::vector<std::string> tags;
};

class HashTable {
public:
    // Constructor and destructor
    HashTable(size_t capacity) : maxCapacity_(capacity), size_(0) {}
    ~HashTable() = default;

    // Thread-safe read operation
    Entry getEntry(const std::string& id) {
        std::shared_lock<std::shared_mutex> lock(mutex_);
        auto it = table_.find(id);
        if (it != table_.end()) {
            return it->second;
        } else {
            throw std::runtime_error("Entry not found");
        }
    }

    // Thread-safe write operation
    void addEntry(const Entry& entry) {
        std::unique_lock<std::shared_mutex> lock(mutex_);
        if (size_ >= maxCapacity_) {
            resize();
        }
        table_[entry.id] = entry;
        ++size_;
    }

private:
    // Resize the hash table
    void resize() {
        std::unique_lock<std::shared_mutex> lock(mutex_);
        maxCapacity_ *= 2;  // Simple strategy for resizing, can be optimized
        size_ = 0;
    }

    std::unordered_map<std::string, Entry> table_;
    mutable std::shared_mutex mutex_;
    std::atomic<size_t> maxCapacity_;
    std::atomic<size_t> size_;
};
