void resizeRecords(size_t newSize) {
    Record* newArray = realloc(records, sizeof(Record) * newSize);
    if (newArray == NULL && newSize != 0) {
        fprintf(stderr, "Failed to allocate memory: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    records = newArray;
