void addRecord(int value, long timestamp, int priority, const char* source) {
    pthread_mutex_lock(&lock);

    if (recordCount == recordCapacity) {
        size_t newSize = recordCapacity * 2;
        if (newSize > 5000) {
            fprintf(stderr, "Maximum capacity reached\n");
            pthread_mutex_unlock(&lock);
            return;
        }
        resizeRecords(newSize);
    }

    Record* record = &records[recordCount++];
    record->value = value;
    record->timestamp = timestamp;
    record->priority = priority;
    strncpy(record->source, source, sizeof(record->source) - 1);
    record->source[sizeof(record->source) - 1] = '\0';

    pthread_mutex_unlock(&lock);
}

Record* getHighestPriorityRecord() {
    pthread_mutex_lock(&lock);

    Record* highestPriorityRecord = NULL;
    int highestPriority = -1;

    for (size_t i = 0; i < recordCount; ++i) {
        if (records[i].priority > highestPriority) {
            highestPriority = records[i].priority;
            highestPriorityRecord = &records[i];
        }
    }

    pthread_mutex_unlock(&lock);

    return highestPriorityRecord;
}
