#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
    void* data;
} Record;

typedef struct Node {
    Record* record;
    struct Node* next;
} Node;

typedef struct {
    pthread_mutex_t lock;
    Node** table;
    size_t size;
    int enforceUniqueKeys;
} HashTable;

HashTable* createHashTable(size_t size, int enforceUniqueKeys) {
    HashTable* hashTable = malloc(sizeof(HashTable));
    if (hashTable == NULL) return NULL;

    pthread_mutex_init(&hashTable->lock, NULL);
    hashTable->table = calloc(size, sizeof(Node*));
    if (hashTable->table == NULL) {
        free(hashTable);
        return NULL;
    }

    hashTable->size = size;
    hashTable->enforceUniqueKeys = enforceUniqueKeys;
    return hashTable;
}

void destroyHashTable(HashTable* hashTable) {
    pthread_mutex_destroy(&hashTable->lock);

    for (size_t i = 0; i < hashTable->size; ++i) {
        Node* node = hashTable->table[i];
        while (node != NULL) {
            Node* next = node->next;
            free(node->record);
            free(node);
            node = next;
        }
    }

    free(hashTable->table);
    free(hashTable);
}

int insertRecord(HashTable* hashTable, Record* record) {
    pthread_mutex_lock(&hashTable->lock);

    if (hashTable->enforceUniqueKeys) {
        Node* node = hashTable->table[record->key % hashTable->size];
        while (node != NULL) {
            if (node->record->key == record->key) {
                pthread_mutex_unlock(&hashTable->lock);
                return 0; // Key already exists
            }
            node = node->next;
        }
    }

    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        pthread_mutex_unlock(&hashTable->lock);
        return 0; // Memory allocation failed
    }

    newNode->record = record;
    newNode->next = hashTable->table[record->key % hashTable->size];
    hashTable->table[record->key % hashTable->size] = newNode;

    pthread_mutex_unlock(&hashTable->lock);
    return 1; // Success
}
```
