typedef struct Record {
    int key;
    int value;
    int *ptr_to_key;
} Record;

Record* createRecords(int num, int minVal, int maxVal) {
    srand(time(NULL)); // seed the random number generator

    // allocate memory for records and keys
    Record* records = (Record*) malloc(num * sizeof(Record));
    if (!records) {
        printf("Failed to allocate memory for records\n");
        return NULL;
    }

    int* keys = (int*) malloc(num * sizeof(int));
    if (!keys) {
        printf("Failed to allocate memory for keys\n");
        free(records);
        return NULL;
    }

    // initialize records and keys
    for (int i = 0; i < num; ++i) {
        int value = rand() % (maxVal - minVal + 1) + minVal;

        // ensure uniqueness of values
        for (int j = 0; j < i; ++j) {
            if (records[j].value == value) {
                --i;
                break;
            }
        }

        records[i].key = keys[i] = i + 1; // assign key and pointer to it
        records[i].value = value;
        records[i].ptr_to_key = &keys[i];
    }

    return records;
}
