#include <stdlib.h>
#include <pthread.h>

typedef enum {PENDING, COMPLETED, FAILED} Status;

typedef struct Transaction {
    uint64_t id;
    Status status;
    uint64_t timestamp;
    struct Transaction *prev;
    struct Transaction *next;
} Transaction;

typedef struct TransactionList {
    pthread_mutex_t lock;
    Transaction **transactions;
    size_t capacity;
    size_t count;
    Transaction *head;
    Transaction *tail;
} TransactionList;

TransactionList* createTransactionList(size_t initialCapacity) {
    TransactionList *list = malloc(sizeof(TransactionList));
    if (list == NULL) return NULL;

    list->transactions = calloc(initialCapacity, sizeof(Transaction*));
    if (list->transactions == NULL) {
        free(list);
        return NULL;
    }

    list->capacity = initialCapacity;
    list->count = 0;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void insertTransaction(TransactionList *list, Transaction *transaction) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        Transaction **newTransactions = realloc(list->transactions, newCapacity * sizeof(Transaction*));

        if (newTransactions != NULL) {
            list->transactions = newTransactions;
            list->capacity = newCapacity;
        } else {
            pthread_mutex_unlock(&list->lock);
            return; // Handle memory allocation failure
        }
    }

    list->transactions[list->count] = transaction;
    if (list->head == NULL) {
        list->head = transaction;
        list->tail = transaction;
    } else {
        list->tail->next = transaction;
        transaction->prev = list->tail;
        list->tail = transaction;
    }
    ++list->count;

    pthread_mutex_unlock(&list->lock);
}

// Implement other functions as needed...
```

