typedef struct HashTable {
    Node **buckets;
    size_t numBuckets;
    pthread_mutex_t lock;
} HashTable;

HashTable* createHashTable(size_t numBuckets) {
    HashTable *table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    table->buckets = calloc(numBuckets, sizeof(Node*));
    if (table->buckets == NULL) {
        free(table);
        return NULL;
    }

    table->numBuckets = numBuckets;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void destroyHashTable(HashTable *table) {
    for (size_t i = 0; i < table->numBuckets; ++i) {
        Node *node = table->buckets[i];
        while (node != NULL) {
            Node *next = node->next;
            free(node);
            node = next;
        }
    }

    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}

void insertIntoHashTable(HashTable *table, int key, Record *record) {
    size_t bucket = key % table->numBuckets;

    pthread_mutex_lock(&table->lock);

    Node *node = malloc(sizeof(Node));
    node->key = key;
    node->record = record;
    node->next = table->buckets[bucket];
    table->buckets[bucket] = node;

    pthread_mutex_unlock(&table->lock);
}
```
