    int size;
    int count;
    int* keys;
    Record** records;
} HashTable;

HashTable* create_hash_table(int size) {
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }

    table->keys = calloc(size, sizeof(int));
    if (table->keys == NULL) {
        printf("Memory allocation failed\n");
        free(table);
        exit(1);
    }

    table->records = malloc(size * sizeof(Record*));
    if (table->records == NULL) {
        printf("Memory allocation failed\n");
        free(table->keys);
        free(table);
        exit(1);
    }

    table->size = size;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void insert(HashTable* table, int key, Record* record) {
    if (table->count == table->size) {
        printf("Hash table is full\n");
        free(record);
        return;
    }

    pthread_mutex_lock(&table->lock);

    int index = key % table->size;
    while (table->keys[index] != 0) {
        if (++index == table->size) {
            index = 0;
        }
    }

    table->keys[index] = key;
    table->records[index] = record;
    table->count++;

    pthread_mutex_unlock(&table->lock);
}

Record* search(HashTable* table, int key) {
    int index = key % table->size;

    pthread_mutex_lock(&table->lock);

    while (table->keys[index] != key) {
        if (++index == table->size) {
            index = 0;
        }

        if (index == key % table->size) {
            pthread_mutex_unlock(&table->lock);
            return NULL;
        }
    }

    Record* record = table->records[index];

    pthread_mutex_unlock(&table->lock);

    return record;
}
